INSERT INTO public.deep_cases (id, market_id, day, slot, content, tags) VALUES
($ml$f44d3b4f-b5fd-5d50-9e4a-8fc88238032c$ml$::uuid, $ml$ai$ml$, 1, 1, $ml${"id": "ai-d1-c1", "title": "One point for a right answer", "lessonTitle": "Three ways a machine learns", "slot": 1, "type": "apply", "brief": {"headline": "DeepSeek's R1 learned to reason largely by trial and error: a reward of 1 for a correct answer, 0 otherwise. Nature published the work in September 2025, with R1's training put at $294,000.", "kicker": "Apply day 1: which way of learning taught R1 to reason?", "fullText": "DeepSeek built R1 on its V3 Base model, which had been trained with conventional methods on web data. The reasoning came next, through reinforcement learning. The model got a reward of 1 for a correct answer and 0 otherwise. Math answers were checked against the right answer, and code against test cases. It was not trained on thousands of human-labeled worked solutions.\n\nThe peer-reviewed paper appeared in Nature on September 17, 2025. Supplementary material put R1's training at the equivalent of $294,000, on top of about $6 million for the base model. R1 has been downloaded 10.9 million times on Hugging Face.\n\nCritics note that the base model's conventional start may explain part of the result. Still, the reasoning stage learned from rewards, not from answers written by people.", "sources": [{"url": "https://www.scientificamerican.com/article/secrets-of-chinese-ai-model-deepseek-revealed-in-landmark-paper", "label": "Scientific American, Secrets of DeepSeek AI model revealed, Sep 2025"}, {"url": "https://sciencenews.org/article/ai-model-deepseek-answers-training", "label": "Science News, A look under the hood of DeepSeek's AI models, Dec 2025"}]}, "evidence": {"kind": "spotFake", "prompt": "One of these is false about how R1 learned to reason. Tap it.", "statements": ["It got a reward of 1 for a correct answer, 0 otherwise.", "It learned from thousands of human-labeled worked solutions.", "Its code answers were checked against test cases."], "fakeIndex": 1, "explanation": "R1 was rewarded only for outcomes. No one showed it step-by-step human solutions, which is what makes this reinforcement learning."}, "numbers": {"kind": "numberSense", "prompt": "R1's reasoning stage cost $294,000; its base model about $6 million. How many times more did the base cost?", "min": 0, "max": 60, "value": 20, "unit": "x", "explanation": "About 20 times. The cheap headline figure sits on top of a base model that cost far more."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "You're interviewing for a machine learning role. They ask what R1's reasoning stage learned from.", "prompt": "Which answer shows you know how it works?", "options": ["Worked solutions labeled by human experts", "Patterns it found in unlabeled text alone", "Rewards for answers a program could check"], "correctIndex": 2, "consequences": ["That would be supervised learning, which this stage avoided.", "Pattern-finding describes unsupervised learning, not this stage.", "Right: 1 for a correct answer, 0 otherwise, checked automatically."], "explanation": "Naming what a model learns from, here a checkable reward, shows you know what it needs to work."}, "proReasoning": "Strong candidates name the raw material: labels, patterns or rewards. For R1, the reward was an automatic check of each answer.", "commonMistake": "Saying it \"taught itself\" without naming the reward that did the teaching.", "mentalModel": "Name what the model learns from."}, "invest": {"call": {"kind": "theCall", "situation": "Headlines say DeepSeek trained R1 for $294,000. You're judging what that means for AI costs.", "prompt": "What should you keep in mind?", "options": ["It leaves out the base model, so the total was higher", "Frontier AI now costs under $300,000 to build in total", "Reinforcement learning means no chips were needed at all"], "correctIndex": 0, "consequences": ["The base model alone cost about $6 million.", "The $294,000 covers only the reasoning stage on top.", "R1 still trained on NVIDIA chips; rewards replace labels, not compute."], "explanation": "A cost figure is only useful once you know what it covers. This one leaves out the base model."}, "proReasoning": "Investors ask what a training cost includes before comparing it. A stage cost and a full cost are different numbers.", "commonMistake": "Comparing one stage of training with the full cost of a rival model.", "mentalModel": "Ask what the cost figure covers."}, "build_startup": {"call": {"kind": "theCall", "situation": "You want to train a model to fill in tax forms, using rewards the way R1 did.", "prompt": "What must you have before you start?", "options": ["A model bigger than anyone else has", "A way to check each answer automatically", "Millions of worked examples written by people"], "correctIndex": 1, "consequences": ["Size was not the point; the checkable reward was.", "Without an automatic check, there is no reward to learn from.", "Worked examples are what this approach tries to avoid."], "explanation": "Reinforcement learning needs a reward you can measure. R1 worked because math and code answers can be checked."}, "proReasoning": "Founders check the raw material first. Rewards need an answer a program can grade; labels need people to write them.", "commonMistake": "Copying the method without asking whether your task can be graded automatically.", "mentalModel": "No checkable answer, no reward."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend says DeepSeek built an AI that taught itself to reason with no help at all.", "prompt": "What's the fairer version?", "options": ["Yes, it started from nothing at all, like a newborn", "No, people wrote out every single step it learned", "Rewards trained its reasoning, on top of a trained base"], "correctIndex": 2, "consequences": ["It started from V3 Base, which was already trained on web data.", "No one wrote its steps; it was rewarded only for correct answers.", "The reasoning came from rewards, on top of a conventionally trained base."], "explanation": "The reward did the teaching for the reasoning stage. The base model underneath was trained the usual way."}, "proReasoning": "When you hear \"taught itself\", ask what rewarded it and what it started from. Both parts matter.", "commonMistake": "Thinking reinforcement learning means starting from zero.", "mentalModel": "Ask what rewarded it, and where it started."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:3a7e010e3d4f$ml$]::text[]),
($ml$72ebbc4f-e549-5dfd-babd-ac065107ede9$ml$::uuid, $ml$ai$ml$, 1, 2, $ml${"id": "ai-d1-c2", "title": "From human games to self-play", "lessonTitle": "Three ways a machine learns", "slot": 2, "type": "connect", "brief": {"headline": "Earlier versions of AlphaGo first learned from thousands of human games. AlphaGo Zero learned only by playing itself, and after 40 days it had passed every earlier version.", "kicker": "Connect two day 1 ideas: learning from answers, then from rewards.", "fullText": "Day 1 covered three ways a machine learns. AlphaGo's history shows two of them.\n\nEarlier versions of AlphaGo first trained on thousands of games played by human amateurs and professionals. Each human move was an answer to learn from, which is supervised learning.\n\nAlphaGo Zero started from random play with no human games at all. It played millions of games against itself and learned from who won. After three days it beat the version that had defeated Lee Sedol, 100 games to 0. After 40 days it had passed AlphaGo Master too.\n\nChatbots often use both teachers. InstructGPT first learned from human demonstrations, then from people ranking its answers as a reward.", "sources": [{"url": "https://deepmind.google/blog/alphago-zero-starting-from-scratch/", "label": "DeepMind, AlphaGo Zero"}, {"url": "https://openai.com/index/instruction-following/", "label": "OpenAI, InstructGPT"}, {"url": "https://developers.google.com/machine-learning/intro-to-ml/what-is-ml", "label": "Google, What is machine learning"}]}, "evidence": {"kind": "buildChain", "prompt": "Put AlphaGo Zero's learning cycle in order.", "steps": ["Start from random play, with no human games", "Play games against itself", "Learn to predict good moves and the winner", "Combine the updated network with search", "Play again as a stronger version"], "explanation": "Each cycle of self-play makes a stronger player. No human move is ever the answer key."}, "numbers": {"kind": "numberSense", "prompt": "After how many days of self-play had AlphaGo Zero passed AlphaGo Master?", "min": 0, "max": 100, "value": 40, "unit": "days", "explanation": "About 40 days, starting from random play. Three days were enough to beat the version that beat Lee Sedol."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "You're interviewing at a chatbot team. They ask why it uses both human demonstrations and human rankings.", "prompt": "What's the best answer?", "options": ["Demos show good answers; rankings reward better ones", "Rankings are cheaper, so demos are being dropped", "Both are labels, just collected twice for safety"], "correctIndex": 0, "consequences": ["Right: one step is supervised, the next is reinforcement.", "InstructGPT used both steps, in that order.", "Rankings become a reward, which is a different way of learning."], "explanation": "Demonstrations are answers to copy. Rankings become a reward. InstructGPT chained the two."}, "proReasoning": "Explain each training step by what it learns from. Demonstrations are labels; rankings are a reward.", "commonMistake": "Calling all human input \"labels\" and missing the reward step.", "mentalModel": "One step copies, the next is scored."}, "invest": {"call": {"kind": "theCall", "situation": "One game AI learns from records of human play. Another learns only by playing itself.", "prompt": "Which one depends less on human-made data?", "options": ["Both depend on human data equally", "The one that learns by playing itself", "The one trained on human game records"], "correctIndex": 1, "consequences": ["Self-play needs no human games, as AlphaGo Zero showed.", "Self-play makes its own data; the cost shifts to compute.", "Human records must be collected, so people make that data."], "explanation": "Human data is part of the cost of supervised learning. Self-play swaps that cost for compute."}, "proReasoning": "Investors ask who supplies a model's data and at what price. Self-play moves the bill from people to machines.", "commonMistake": "Assuming every AI model needs a large supply of human-made data.", "mentalModel": "Follow who makes the training data."}, "build_startup": {"call": {"kind": "theCall", "situation": "You are building a support chatbot. You have 2,000 strong answers written by your best agents.", "prompt": "How do you use them?", "options": ["Ignore them and rely on rankings alone", "Use them only to group tickets by topic", "Train on them first, then add ranked feedback"], "correctIndex": 2, "consequences": ["Throwing away good demonstrations wastes the easiest step.", "Grouping by topic uses none of the answers they wrote.", "That is the InstructGPT recipe: copy good answers, then learn from rankings."], "explanation": "Good examples are labeled data. Use them for the supervised step, then improve with rankings."}, "proReasoning": "Founders use the data they already have for the step it suits. Written answers suit supervised learning.", "commonMistake": "Jumping to the fancy step and skipping the data already in hand.", "mentalModel": "Match each dataset to its step."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend asks how an AI that never saw a human game beat one trained on human games.", "prompt": "What's the best explanation?", "options": ["Self-play let it find moves no human taught it", "It secretly studied far more human games", "Engineers typed in better Go strategies by hand"], "correctIndex": 0, "consequences": ["Learning from wins and losses, it was not limited to human moves.", "AlphaGo Zero used no human games at all.", "No strategies were coded in; it learned by playing itself."], "explanation": "Learning from human moves caps you near human play. Learning from results lets the model go past it."}, "proReasoning": "Copying a teacher gets you close to the teacher. Learning from results can take you past them.", "commonMistake": "Assuming more human data is always the better teacher.", "mentalModel": "Rewards can teach past the teacher."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:43afa1c518c7$ml$]::text[]),
($ml$75a20523-f251-52d1-8674-f5ed872ed050$ml$::uuid, $ml$ai$ml$, 1, 3, $ml${"id": "ai-d1-c3", "title": "An opponent for a new game", "lessonTitle": "Three ways a machine learns", "slot": 3, "type": "decide", "brief": {"headline": "You run a small studio launching a new board game. Nobody has played it yet, so there are no records of human games. You need a strong AI opponent at launch.", "kicker": "Decide which way of learning fits a game with no human data.", "fullText": "Supervised learning needs examples with the right answer attached. Unsupervised learning finds patterns with no answers. Reinforcement learning tries things and learns from rewards or penalties.\n\nYour game has clear rules and a clear winner, but no recorded human games. AlphaGo Zero faced the same situation by choice: it started from random play and learned from self-play alone. After three days it beat the AlphaGo that had beaten Lee Sedol, 100 games to 0, running on 4 TPUs where that earlier version used 48.", "sources": [{"url": "https://developers.google.com/machine-learning/intro-to-ml/what-is-ml", "label": "Google, What is machine learning"}, {"url": "https://deepmind.google/blog/alphago-zero-starting-from-scratch/", "label": "DeepMind, AlphaGo Zero"}]}, "evidence": {"kind": "sortSignal", "prompt": "What does each way of learning need for your game?", "buckets": ["Supervised", "Reinforcement"], "items": [{"text": "Thousands of recorded human games", "bucket": 0}, {"text": "The right move marked for each position", "bucket": 0}, {"text": "A clear win or loss at the end", "bucket": 1}, {"text": "A fast way to play huge numbers of games", "bucket": 1}], "explanation": "Supervised learning needs answers you do not have. Reinforcement needs a measurable result, which your game gives."}, "numbers": {"kind": "numberSense", "prompt": "The AlphaGo that beat Lee Sedol ran on 48 TPUs. How many did AlphaGo Zero run on?", "min": 0, "max": 24, "value": 4, "unit": "TPUs", "explanation": "Four. Self-play beat the older version 100 to 0 on far less hardware."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "The studio offers you one of two roles for the AI project: labeling played games, or building the game simulator.", "prompt": "Which role matters more to the self-play plan?", "options": ["Writing rules for each opening move", "Building the fast game simulator", "Labeling games that humans played"], "correctIndex": 1, "consequences": ["Hand-written openings are what self-play replaces.", "Self-play runs on the simulator, so its speed sets the pace.", "There are no human games to label yet."], "explanation": "In reinforcement learning, the environment that produces rewards is the core asset."}, "proReasoning": "Pick the role that supplies what the method needs. For self-play, that is a fast, correct game environment.", "commonMistake": "Choosing the data-labeling role when the plan needs no labels.", "mentalModel": "Work where the method gets its raw material."}, "invest": {"call": {"kind": "theCall", "situation": "Two game AI startups pitch you. One will pay experts to play 50,000 games; the other will use self-play.", "prompt": "Which cost grows more slowly as they scale?", "options": ["Paid expert games, since humans teach best", "Both scale the same way per game", "Self-play, which needs compute, not people"], "correctIndex": 2, "consequences": ["Experts are slow and paid per game, and Zero beat human-trained play.", "A human game costs far more time than a simulated one.", "Machines generate the games, and AlphaGo Zero did it on 4 TPUs."], "explanation": "Human data is a cost that grows with every example. Self-play turns that cost into compute."}, "proReasoning": "Investors compare what each extra example costs. Human-made data scales with people; self-play scales with machines.", "commonMistake": "Assuming human-made data is always worth its cost.", "mentalModel": "Price each extra example."}, "build_startup": {"call": {"kind": "theCall", "situation": "You're the founder. The game has a clear winner and no human records, and launch is in six months.", "prompt": "How do you train the opponent?", "options": ["Self-play, rewarded for winning games", "Wait years to collect human games first", "Group positions with no goal at all"], "correctIndex": 0, "consequences": ["A clear win or loss is exactly the reward self-play needs.", "You would launch with no opponent at all.", "Pattern-finding without a goal will not learn to win."], "explanation": "A measurable reward plus a simulator is all reinforcement learning needs. Your game has both."}, "proReasoning": "Founders choose the method by the data they can get. With rules and a winner, self-play needs nothing else.", "commonMistake": "Waiting for data the method does not need.", "mentalModel": "A clear winner makes a clear reward."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend asks how an AI could get good at a game that no person has ever played.", "prompt": "What's the answer?", "options": ["Someone programs in every good move", "It plays itself and learns from who wins", "It copies moves from games that look similar"], "correctIndex": 1, "consequences": ["Nobody knows the good moves yet; the AI finds them.", "That is reinforcement learning, the way AlphaGo Zero learned Go.", "Copying needs examples, and this game has none."], "explanation": "Rewards from winning and losing are enough to learn from, with no examples needed."}, "proReasoning": "A clear goal can stand in for a teacher. The AI tries, scores, and adjusts.", "commonMistake": "Thinking an AI always needs human examples to learn.", "mentalModel": "A score can be the teacher."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:14011a4831ac$ml$]::text[]),
($ml$f54ce230-0132-5bcc-ac9e-349dc89113bc$ml$::uuid, $ml$ai$ml$, 2, 1, $ml${"id": "ai-d2-c1", "title": "Same model, 80% cheaper", "lessonTitle": "Where the money in AI goes", "slot": 1, "type": "apply", "brief": {"headline": "On June 10, 2025, OpenAI cut the price of its o3 reasoning model by 80%. Output fell from $40 to $8 per million tokens. It was the same model, served more cheaply.", "kicker": "Apply day 2: the price of each answer keeps falling.", "fullText": "In mid-2025, o3 was OpenAI's most powerful reasoning model. On June 10, Sam Altman announced the price was down 80%: $2 per million input tokens instead of $10, and $8 per million output tokens instead of $40. It was the very same model, and an OpenAI staff member credited the engineers optimizing inference.\n\nRivals were close. Google's Gemini 2.5 Pro cost $1.25 to $2.50 per million input tokens and $10 to $15 for output. Anthropic's Claude Opus 4 cost $15 in and $75 out.\n\nThis is the day 2 pattern. Each answer keeps getting cheaper, which brings more users. Every answer still runs on chips in a data center, and that is where the money flows.", "sources": [{"url": "https://venturebeat.com/ai/openai-announces-80-price-drop-for-o3-its-most-powerful-reasoning-model", "label": "VentureBeat, OpenAI announces 80% price drop for o3, Jun 2025"}, {"url": "https://simonwillison.net/2025/Jun/10/o3-price-drop/", "label": "Simon Willison, o3 price drop, Jun 2025"}]}, "evidence": {"kind": "multipleChoice", "prompt": "o3's output price fell from $40 to $8 per million tokens, for the very same model. What changed?", "options": ["OpenAI swapped in a smaller model", "The chips started running for free", "How efficiently OpenAI served it"], "correctIndex": 2, "explanation": "The model stayed the same. OpenAI credited the engineers optimizing inference, the cost of serving each answer."}, "numbers": {"kind": "numberSense", "prompt": "You spent $400 a month on o3 output before the cut. What does the same usage cost after an 80% cut?", "min": 0, "max": 400, "value": 80, "unit": "dollars", "explanation": "$80. An 80% cut leaves a fifth of the bill, so the same work now costs one dollar in five."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "You're interviewing for a product role at an app built on o3, the week of the cut. They ask what it changes.", "prompt": "What's your answer?", "options": ["Features too costly last month may now pay off", "Nothing, since prices will go back up soon", "The model got worse, so we should switch"], "correctIndex": 0, "consequences": ["At a fifth of the cost, more features clear the bar.", "The trend in AI prices has been steadily down.", "It was the same model, only cheaper to serve."], "explanation": "A product team watches its cost per answer. When that cost drops 80%, the roadmap changes."}, "proReasoning": "Link a price change to what the team can now build. Knowing where a team's costs sit is half the answer.", "commonMistake": "Treating a price cut as a sign the product got worse.", "mentalModel": "Cheaper answers widen the roadmap."}, "invest": {"call": {"kind": "theCall", "situation": "A model maker cuts prices 80%. Revenue per answer drops to a fifth of what it was.", "prompt": "What decides whether the cut grows revenue?", "options": ["Nothing, since cheaper is always better", "Whether usage grows more than five times", "Whether rivals notice the new price"], "correctIndex": 1, "consequences": ["Cheaper helps users; it can still shrink revenue.", "At a fifth of the price, usage must grow over 5x just to keep revenue.", "Rivals' reaction matters, but usage pays the bills."], "explanation": "Falling prices cut both ways. Watch usage growth against the size of the cut."}, "proReasoning": "Investors compare the price cut with the usage it brings. An 80% cut needs more than 5 times the usage to grow revenue.", "commonMistake": "Cheering a price cut without checking the volume needed to pay for it.", "mentalModel": "Watch usage against price."}, "build_startup": {"call": {"kind": "theCall", "situation": "Your AI feature lost money on o3 at $40 per million output tokens. The price is now $8.", "prompt": "What do you do?", "options": ["Drop the feature, since it lost money", "Wait for prices to be cut again", "Redo your unit economics at $8"], "correctIndex": 2, "consequences": ["You may be dropping a feature that now pays.", "Waiting gives rivals the head start.", "A feature that lost money at $40 may profit at $8."], "explanation": "Today's costs are not tomorrow's. When the input price moves, redo the math before deciding."}, "proReasoning": "Founders recheck the numbers every time model prices move. A dead feature can come back to life.", "commonMistake": "Treating last quarter's costs as permanent.", "mentalModel": "Redo the math when prices move."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend asks how the same AI model can suddenly cost 80% less.", "prompt": "What's the best explanation?", "options": ["Engineers made it cheaper to run", "OpenAI made the model smaller and worse", "A government pays the difference"], "correctIndex": 0, "consequences": ["OpenAI credited work on serving it more efficiently.", "It was the very same model.", "No subsidy was involved; the serving got cheaper."], "explanation": "Every answer costs compute. Serve it more efficiently and the price can fall without changing the model."}, "proReasoning": "Running a model is a cost of its own, apart from building it. Better serving can cut prices fast.", "commonMistake": "Assuming a cheaper model must be a worse one.", "mentalModel": "Running cost sets the price."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:46b39c87c71c$ml$]::text[]),
($ml$b91bb62b-9b2c-5c5e-9336-f5cf08a72343$ml$::uuid, $ml$ai$ml$, 2, 2, $ml${"id": "ai-d2-c2", "title": "Two bills behind a chatbot", "lessonTitle": "Where the money in AI goes", "slot": 2, "type": "connect", "brief": {"headline": "GPT-4's training compute cost an estimated $78 million. Chatbots like InstructGPT also learned from people who wrote demonstrations and ranked answers. Both bills come before anyone uses the model.", "kicker": "Connect day 1 and day 2: chatbots pay for compute and for people.", "fullText": "On day 1 you saw how chatbots learn. InstructGPT learned from human demonstrations, then from people ranking its answers as a reward. People make that data, and people get paid.\n\nOn day 2 you followed the money. Training compute for GPT-4 cost an estimated $78 million, and Gemini Ultra an estimated $191 million. Most of it flows down to cloud compute and chips.\n\nPut together, a chatbot has two big training bills: machines and human feedback. Only once it is trained does the cheap part begin, as the price of each answer keeps falling.", "sources": [{"url": "https://openai.com/index/instruction-following/", "label": "OpenAI, InstructGPT"}, {"url": "https://fortune.com/2024/04/18/google-gemini-cost-191-million-to-train-stanford-university-report-estimates/", "label": "Fortune on the Stanford AI Index training cost estimates, Apr 2024"}, {"url": "https://hai.stanford.edu/news/ai-index-2025-state-of-ai-in-10-charts", "label": "Stanford AI Index 2025 in 10 charts"}]}, "evidence": {"kind": "sortSignal", "prompt": "Is each cost part of the compute bill or the human data bill?", "buckets": ["Compute", "Human data"], "items": [{"text": "GPU time to train GPT-4", "bucket": 0}, {"text": "Cloud servers answering users", "bucket": 0}, {"text": "Chips bought from a chipmaker", "bucket": 0}, {"text": "People writing example answers", "bucket": 1}, {"text": "People ranking the model's answers", "bucket": 1}], "explanation": "Machines run the training and the answers. People write and rank the examples the model learns from."}, "numbers": {"kind": "numberSense", "prompt": "Gemini Ultra's training compute cost about $191 million, GPT-4's about $78 million. How many million dollars more?", "min": 0, "max": 300, "value": 113, "unit": "M", "explanation": "About $113 million more, for compute alone. Human feedback is a separate bill."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "You're interviewing at a chatbot lab. They ask where training money goes.", "prompt": "Which answer is most complete?", "options": ["Only labelers, since compute has become cheap", "Mostly compute, plus paid human feedback", "Only chips, since human feedback costs nothing"], "correctIndex": 1, "consequences": ["GPT-4 alone used an estimated $78 million of compute.", "Right: compute is the biggest bill, and human data is a real cost.", "People who write and rank answers are paid for that work."], "explanation": "Chatbots pay twice in training: for machines and for human-made data."}, "proReasoning": "Name both cost lines and which is bigger. It shows you know what a training run actually buys.", "commonMistake": "Forgetting the human data bill because compute is so large.", "mentalModel": "Machines and people both cost money."}, "invest": {"call": {"kind": "theCall", "situation": "A chatbot maker says answer prices fell 280-fold, so its costs are disappearing.", "prompt": "What's missing from that claim?", "options": ["Nothing, since answers drive all the costs", "Answer prices have risen since 2022", "Training compute and human data still cost money"], "correctIndex": 2, "consequences": ["Training runs cost tens of millions before any answer is sold.", "GPT-3.5-level answers fell from $20 to $0.07 per million tokens.", "Cheaper answers do not shrink the bill to train the next model."], "explanation": "Serving costs fall fast. Training compute and human feedback are separate bills that come first."}, "proReasoning": "Investors split costs into training and serving. A falling price per answer says little about the next training run.", "commonMistake": "Reading cheaper answers as cheaper models overall.", "mentalModel": "Training and serving are separate bills."}, "build_startup": {"call": {"kind": "theCall", "situation": "You are drafting the training budget for a chatbot tuned to your industry.", "prompt": "What must the budget cover?", "options": ["Compute and paid human feedback", "Compute only, since feedback comes free", "Human feedback only, since compute is cheap"], "correctIndex": 0, "consequences": ["Both are real costs of a trained chatbot.", "Someone has to write and rank the answers, and they are paid.", "Training compute still costs serious money."], "explanation": "Feedback-trained models need data made by people, and they need compute to learn from it."}, "proReasoning": "Founders budget for the people who make training data, not just the GPUs. Both sit in the cost of the model.", "commonMistake": "Leaving human data out of the budget.", "mentalModel": "Budget for machines and for people."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend asks why chatbot makers pay people when the AI does the work.", "prompt": "What's the answer?", "options": ["People check every answer before you see it", "People write and rank the answers it learns from", "People secretly type the replies you get"], "correctIndex": 1, "consequences": ["Answers reach you directly; people helped train the model earlier.", "That human feedback is part of how chatbots are trained.", "The replies come from the model itself."], "explanation": "Human demonstrations and rankings are training data. Making them is paid work."}, "proReasoning": "Behind a chatbot are people who taught it, long before you typed a word. That work is part of its cost.", "commonMistake": "Thinking an AI model trains itself with no human input.", "mentalModel": "People teach the model before it talks."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:c4e29079616f$ml$]::text[]),
($ml$21933472-0f3e-5401-9f3a-1687b6af0889$ml$::uuid, $ml$ai$ml$, 2, 3, $ml${"id": "ai-d2-c3", "title": "Pricing a free tier", "lessonTitle": "Where the money in AI goes", "slot": 3, "type": "decide", "brief": {"headline": "You run a small AI writing app and want a free tier. GPT-3.5-level answers fell from $20 to $0.07 per million tokens in about 18 months.", "kicker": "Decide what falling answer prices let you offer.", "fullText": "Money in AI flows down the stack. Users pay apps, apps pay model makers, model makers pay for cloud compute, and the cloud buys chips. NVIDIA's data center business alone brought in $193.7 billion in fiscal 2026.\n\nMeanwhile the price of each answer keeps falling. Stanford's AI Index found that GPT-3.5-level answers fell from $20 to $0.07 per million tokens in about 18 months, a 280-fold drop. A free tier that would have been ruinous in 2022 can cost very little today.", "sources": [{"url": "https://hai.stanford.edu/news/ai-index-2025-state-of-ai-in-10-charts", "label": "Stanford AI Index 2025 in 10 charts"}, {"url": "https://www.sec.gov/Archives/edgar/data/1045810/000104581026000019/q4fy26pr.htm", "label": "NVIDIA fiscal 2026 results"}]}, "evidence": {"kind": "spotFake", "prompt": "One of these is false. Tap it.", "statements": ["GPT-3.5-level answers fell from $20 to $0.07 per million tokens.", "The fall took about 18 months.", "Cheaper answers left chipmakers earning almost nothing."], "fakeIndex": 2, "explanation": "NVIDIA's data centers brought in $193.7 billion in fiscal 2026. Cheaper answers brought more use, and the money still flows to compute."}, "numbers": {"kind": "numberSense", "prompt": "A free user sends 1 million tokens a month. At $0.07 per million, what do they cost you a year, in cents?", "min": 0, "max": 200, "value": 84, "unit": "cents", "explanation": "12 months at 7 cents is 84 cents a year. At 2022 prices of $20 per million, it would have been $240."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "You're interviewing to lead product at the app. The founder asks whether a free tier makes sense.", "prompt": "What's your best answer?", "options": ["No, AI answers are too expensive to give away", "Yes, and make every feature free forever", "Yes, if cost per free user stays tiny"], "correctIndex": 2, "consequences": ["That was true in 2022, not after a 280-fold drop.", "Some features may still cost real money to run.", "At cents a year per user, a free tier can pay for itself in sign-ups."], "explanation": "Answer the question with the cost per user. Falling prices are why free tiers work now."}, "proReasoning": "Back a product call with unit costs. \"About 84 cents a year per free user\" beats a gut feeling.", "commonMistake": "Judging AI costs by 2022 prices.", "mentalModel": "Price the free user first."}, "invest": {"call": {"kind": "theCall", "situation": "The app launches a free tier and users triple, but revenue per user falls.", "prompt": "How do you read that?", "options": ["Track how many free users turn paid", "Sell, since revenue per user fell", "Ignore it, since users tripled"], "correctIndex": 0, "consequences": ["Cheap free users pay off only if some upgrade.", "Revenue per user falls by design when free users join.", "Users alone do not pay the bills."], "explanation": "Falling prices bring more users but shrink what each earns. Conversion decides the outcome."}, "proReasoning": "Investors watch usage growth against what each user earns. A free tier is a bet on conversion.", "commonMistake": "Reading a drop in revenue per user as failure, or growth in users as success.", "mentalModel": "Free users pay off when some convert."}, "build_startup": {"call": {"kind": "theCall", "situation": "A premium feature needs a frontier model and is too costly to run for every user today.", "prompt": "What do you do?", "options": ["Give it to everyone free and absorb the cost", "Charge for it now and plan for costs to fall", "Drop it, since it will always cost too much"], "correctIndex": 1, "consequences": ["Free use at today's frontier prices can sink a small app.", "Prices have dropped 280-fold before, so plan for cheaper.", "Costs that look fixed today have fallen fast before."], "explanation": "Today's costs are not tomorrow's. Charge for it now, and widen access as prices drop."}, "proReasoning": "Founders plan for falling AI prices without betting the company on them. Charge now, widen later.", "commonMistake": "Killing a feature because of what it costs this year.", "mentalModel": "Charge now, widen as costs fall."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend asks why so many AI apps let you use them for free.", "prompt": "What's the main reason?", "options": ["The apps are all run by charities for free", "AI answers cost nothing at all to produce", "Answers now cost a sliver of 2022 prices"], "correctIndex": 2, "consequences": ["Most are businesses hoping some users pay.", "Every answer still runs on chips that cost money.", "A 280-fold drop makes free users cheap to serve."], "explanation": "Answers got so cheap that serving free users costs little, and some of them will pay later."}, "proReasoning": "Free tiers follow costs. When an answer costs cents a year per user, giving it away makes sense.", "commonMistake": "Thinking free means it costs nothing to run.", "mentalModel": "Free follows falling costs."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:8b60d1451242$ml$]::text[]),
($ml$f6b5dcbe-f4b5-5813-a318-c53c1fc707d3$ml$::uuid, $ml$ai$ml$, 3, 1, $ml${"id": "ai-d3-c1", "title": "A chipmaker pays to be picked", "lessonTitle": "Who holds the power in AI", "slot": 1, "type": "apply", "brief": {"headline": "In October 2025, OpenAI agreed to deploy 6 gigawatts of AMD chips. AMD gave OpenAI a warrant for up to 160 million of its shares at one cent each, about 10% of the company.", "kicker": "Apply day 3: what does a buyer do when one input is scarce?", "fullText": "The deal starts with 1 gigawatt of AMD's MI450 chips in the second half of 2026. The warrant vests in stages, tied to deployments and to AMD's share price; the last tranche needs $600 a share. AMD said the deal should bring it tens of billions of dollars in revenue, and its shares rose more than 30% the day it was announced.\n\nWeeks earlier, NVIDIA had signed a letter of intent to invest up to $100 billion in OpenAI, which would deploy at least 10 gigawatts of NVIDIA systems. NVIDIA's top chips were allocation-bound, and the AMD deal helps OpenAI rely less on them.\n\nWhoever controls the scarcest input holds the power. A big buyer answers by building a second source, and a challenger can pay to become it.", "sources": [{"url": "https://www.forbes.com.au/news/investing/amd-shares-rocket-30-after-multibillion-dollar-deal-with-openai/", "label": "Forbes Australia, AMD shares surge 30% after OpenAI deal, Oct 2025"}, {"url": "https://www.tomshardware.com/pc-components/gpus/openai-signs-6gw-amd-gpu-deal", "label": "Tom's Hardware, OpenAI signs 6GW AMD GPU deal, Oct 2025"}]}, "evidence": {"kind": "buildChain", "prompt": "Put the logic of the deal in order.", "steps": ["Advanced AI chips are scarce", "OpenAI relies heavily on NVIDIA", "OpenAI wants a second supplier", "AMD offers up to 10% of itself", "OpenAI commits to 6 gigawatts of AMD chips"], "explanation": "Scarcity gives the leading supplier power. The buyer looks for a second source, and the challenger pays to win it."}, "numbers": {"kind": "numberSense", "prompt": "The warrant covers up to how many million AMD shares?", "min": 0, "max": 500, "value": 160, "unit": "M", "explanation": "Up to 160 million shares at one cent each, about 10% of AMD, if every milestone is met."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "You have offers from NVIDIA's and AMD's AI chip teams in late 2025.", "prompt": "What does the OpenAI deal tell you about AMD?", "options": ["Its AI chips still have no serious buyers", "It is winning big buyers as a second source", "It has now replaced NVIDIA as the leader"], "correctIndex": 1, "consequences": ["OpenAI committed to 6 gigawatts of them.", "A 6 gigawatt commitment from OpenAI makes AMD a real alternative.", "OpenAI also planned at least 10 gigawatts of NVIDIA systems."], "explanation": "The deal shows AMD as the challenger buyers use to reduce their dependence on the leader."}, "proReasoning": "Read a deal for each side's position. The leader sets terms; the challenger pays to get in the door.", "commonMistake": "Reading one big win as a change of leader.", "mentalModel": "Leader or challenger: know which you join."}, "invest": {"call": {"kind": "theCall", "situation": "AMD stock jumps over 30% on the deal. The warrant could hand OpenAI about 10% of AMD for a cent a share.", "prompt": "What's the cost to existing AMD shareholders?", "options": ["None, since OpenAI pays almost nothing", "AMD must pay OpenAI cash upfront", "Dilution, if the milestones are met"], "correctIndex": 2, "consequences": ["Paying almost nothing for the shares is exactly the cost.", "AMD pays in shares that vest over time, not cash.", "Up to 160 million new shares shrink everyone else's slice."], "explanation": "The challenger paid for the customer with equity. Shareholders bear that cost through dilution."}, "proReasoning": "Investors price what a company gave up to win a deal. Here AMD traded up to a tenth of itself for a big buyer.", "commonMistake": "Celebrating the revenue without counting the shares given away.", "mentalModel": "Count what was paid to win the deal."}, "build_startup": {"call": {"kind": "theCall", "situation": "Your AI startup needs a lot of GPUs in 2026, and the leading chips are allocation-bound.", "prompt": "What protects your plan?", "options": ["Test your models on a second chip supplier now", "Wait for chip prices to fall before planning", "Design your own chip from scratch"], "correctIndex": 0, "consequences": ["A second source keeps you running if your first runs short.", "Waiting leaves you exposed when supply is tight.", "Custom chips take years and huge budgets."], "explanation": "When one input is scarce, a second source protects you. OpenAI did the same at a far larger scale."}, "proReasoning": "Founders avoid depending on one scarce supplier. Make sure your stack can run on a second one.", "commonMistake": "Assuming the scarce input will always be there when you need it.", "mentalModel": "Never rely on one scarce supplier."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend asks why a chipmaker would give a customer shares to buy its chips.", "prompt": "What's the best answer?", "options": ["Because OpenAI already owned part of AMD", "To win a big buyer away from the leader", "Because a law forces it to share stock"], "correctIndex": 1, "consequences": ["The warrant is what could give OpenAI a stake.", "AMD paid in shares to become OpenAI's second source.", "No law required it; it was a business choice."], "explanation": "The leader in a scarce input does not need to pay buyers. The challenger does."}, "proReasoning": "Who pays whom tells you who has power. Here the seller paid the buyer, because the buyer had options.", "commonMistake": "Assuming the seller always holds the power.", "mentalModel": "Who pays whom shows the power."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:e399d9cf8dac$ml$]::text[]),
($ml$3f04657f-9410-5ffe-835d-3613677ac8db$ml$::uuid, $ml$ai$ml$, 3, 2, $ml${"id": "ai-d3-c2", "title": "Margins at the chokepoint", "lessonTitle": "Who holds the power in AI", "slot": 2, "type": "connect", "brief": {"headline": "NVIDIA's data centers brought in $193.7 billion in fiscal 2026, at a 71.1% gross margin. Yet NVIDIA does not make its own chips: foundries such as TSMC do.", "kicker": "Connect day 2 and day 3: money pools where the input is scarce.", "fullText": "On day 2 you followed the money down the stack: users pay apps, apps pay model makers, model makers pay for cloud compute, and the cloud buys chips. On day 3 you saw who holds the power: whoever controls the scarcest input.\n\nNVIDIA's fiscal 2026 shows both. Data centers made up about 90% of its $215.9 billion revenue, and its full-year gross margin was 71.1%. Margins that high mean buyers have few alternatives.\n\nBut NVIDIA designs its chips and relies on foundries such as TSMC to make them. Even the chokepoint has a chokepoint.", "sources": [{"url": "https://www.sec.gov/Archives/edgar/data/1045810/000104581026000019/q4fy26pr.htm", "label": "NVIDIA fiscal 2026 results"}, {"url": "https://www.sec.gov/Archives/edgar/data/1045810/000104581026000021/nvda-20260125.htm", "label": "NVIDIA 10-K, fiscal 2026"}]}, "evidence": {"kind": "multipleChoice", "prompt": "NVIDIA keeps about 71 cents of gross profit on each dollar of sales. What does that suggest?", "options": ["Its chips cost more to make than they sell for", "Rivals are driving its prices down", "Buyers have few alternatives"], "correctIndex": 2, "explanation": "A margin that high holds only when buyers cannot easily switch. That is what controlling a scarce input looks like."}, "numbers": {"kind": "numberSense", "prompt": "What was NVIDIA's full-year gross margin in fiscal 2026, in percent?", "min": 0, "max": 100, "value": 71, "unit": "%", "explanation": "71.1%. Most of each dollar of sales was left after the cost of making the chips."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "You are weighing a job at NVIDIA against one at TSMC, which makes its chips.", "prompt": "What's the fairest read of their positions?", "options": ["TSMC depends on NVIDIA, not the reverse", "NVIDIA makes its own chips, so TSMC is minor", "Each depends heavily on the other"], "correctIndex": 2, "consequences": ["NVIDIA relies on foundries such as TSMC to manufacture.", "NVIDIA designs its chips but does not make them.", "NVIDIA needs foundries to make its chips, and they need its orders."], "explanation": "Power in AI is layered. The chip designer holds one chokepoint, the foundry another."}, "proReasoning": "Map who depends on whom before picking a side. Both companies sit on a scarce input.", "commonMistake": "Assuming the most famous company holds all the power.", "mentalModel": "Find the chokepoint behind the chokepoint."}, "invest": {"call": {"kind": "theCall", "situation": "NVIDIA's gross margin is 71.1%. A friend says margins like that will last forever.", "prompt": "What decides how long they last?", "options": ["How long buyers lack good alternatives", "How large the revenue number gets", "Nothing, since chip margins never fall"], "correctIndex": 0, "consequences": ["Pricing power lasts as long as the scarcity does.", "Revenue can grow while margins shrink.", "Margins fall when buyers can switch."], "explanation": "A chokepoint lets you raise prices. The question is how long the scarcity lasts."}, "proReasoning": "Investors ask what would end the scarcity: rival chips, custom chips or more supply. That sets the margin's life.", "commonMistake": "Treating a scarcity margin as permanent.", "mentalModel": "Margins last as long as the scarcity."}, "build_startup": {"call": {"kind": "theCall", "situation": "Your startup sells to AI labs that pay NVIDIA prices for every GPU hour.", "prompt": "Which product meets the biggest pain?", "options": ["A tool that ignores compute entirely", "Software that cuts the GPU hours they need", "A rival chip factory built next year"], "correctIndex": 1, "consequences": ["Compute is their biggest bill, so ignoring it misses the pain.", "Anything that cuts compute needs saves them real money.", "A chip factory takes years and billions to build."], "explanation": "Costly chips squeeze much of the industry. Products that cut compute needs address that pain directly."}, "proReasoning": "Founders look where a chokepoint charges the most. Saving customers compute is easier than building a rival chip.", "commonMistake": "Trying to beat the chokepoint head on.", "mentalModel": "Sell relief from the chokepoint."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend asks how NVIDIA got so rich when it does not even make its own chips.", "prompt": "What's the answer?", "options": ["It secretly owns the factories that make them", "It sells more video games than anyone", "It designs the chips AI buyers need most"], "correctIndex": 2, "consequences": ["It relies on foundries such as TSMC.", "Data centers, not games, were about 90% of revenue.", "Data center chips brought in $193.7 billion in one year."], "explanation": "Design can be the scarce part. NVIDIA owns the design buyers want and pays others to make it."}, "proReasoning": "Owning the scarce part matters more than owning the factory. Design can be that part.", "commonMistake": "Thinking you have to make something to profit from it.", "mentalModel": "Own the scarce part."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:3764072f1d39$ml$]::text[]),
($ml$ee985a01-05de-5681-ad5c-5c6933327715$ml$::uuid, $ml$ai$ml$, 3, 3, $ml${"id": "ai-d3-c3", "title": "A campus lab at the frontier", "lessonTitle": "Who holds the power in AI", "slot": 3, "type": "decide", "brief": {"headline": "You run a university AI lab with a modest compute budget. In 2024, nearly 90% of notable AI models came from companies, up from 60% the year before.", "kicker": "Decide what your lab should do when you can't buy the frontier.", "fullText": "Stanford's AI Index tracks notable AI models each year. In 2024, nearly 90% came from industry. Frontier training can cost well over $100 million in compute: Gemini Ultra's was an estimated $191 million. Training compute grows 4 to 5 times every year.\n\nPower in AI follows whoever can pay for the scarce inputs. Your lab cannot outspend the companies that own them, so you have to choose work that does not depend on them.", "sources": [{"url": "https://hai-production.s3.amazonaws.com/files/hai-ai-index-2025-policy-highlights.pdf", "label": "AI Index 2025 policy highlights"}, {"url": "https://fortune.com/2024/04/18/google-gemini-cost-191-million-to-train-stanford-university-report-estimates/", "label": "Fortune on the Stanford AI Index training cost estimates, Apr 2024"}, {"url": "https://epoch.ai/blog/training-compute-of-frontier-ai-models-grows-by-4-5x-per-year", "label": "Epoch AI, training compute growth"}]}, "evidence": {"kind": "sortSignal", "prompt": "Which projects fit a lab that cannot buy frontier compute?", "buckets": ["Fits", "Doesn't fit"], "items": [{"text": "Methods that cut the compute a model needs", "bucket": 0}, {"text": "Studying how existing models behave", "bucket": 0}, {"text": "Partnering with a company for compute", "bucket": 0}, {"text": "Training a rival to Gemini Ultra", "bucket": 1}, {"text": "Matching frontier compute each year", "bucket": 1}], "explanation": "Work that needs the scarce input favors whoever owns it. Work that saves or studies it does not."}, "numbers": {"kind": "numberSense", "prompt": "In 2023, 60% of notable models came from industry. What share did in 2024?", "min": 0, "max": 100, "value": 90, "unit": "%", "explanation": "Nearly 90%. In one year, frontier work shifted further to whoever could pay for compute."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "You're a PhD applicant choosing between this lab and a company lab.", "prompt": "Which question shows you understand the shift?", "options": ["Is the work limited by compute, data or people?", "How highly is the lab ranked in the world this year?", "Is the office close to the city center or not?"], "correctIndex": 0, "consequences": ["The answer shows where the lab's power and pain sit.", "Rankings say little about what you can actually train.", "Location says nothing about the scarce inputs."], "explanation": "Asking what limits a team tells you what work it can do, which matters more than its name."}, "proReasoning": "Ask what limits the team. At a campus lab it is often compute; at a company it may be people.", "commonMistake": "Choosing a lab on prestige without asking what it can afford to build.", "mentalModel": "Ask what limits the team."}, "invest": {"call": {"kind": "theCall", "situation": "A fund manager asks whether university labs will lead frontier models again soon.", "prompt": "What's the best-grounded answer?", "options": ["Yes, since compute will soon be free", "Unlikely while compute costs keep climbing", "Yes, since universities invented the field"], "correctIndex": 1, "consequences": ["Frontier runs cost more each year, not less.", "Compute growing 4 to 5 times a year keeps the frontier costly.", "Past invention does not pay for today's training runs."], "explanation": "Power follows whoever can pay for the scarce input. That is mostly companies today."}, "proReasoning": "Investors follow the scarce input to find where power sits. Right now it sits with companies that can buy compute.", "commonMistake": "Betting on history instead of who can pay today.", "mentalModel": "Follow the scarce input."}, "build_startup": {"call": {"kind": "theCall", "situation": "A professor in your lab wants to spin out a startup on a small seed round.", "prompt": "What's the soundest plan?", "options": ["Train a frontier model with the seed money", "Wait until compute gets cheap", "Build on methods that cut compute needs"], "correctIndex": 2, "consequences": ["A seed round will not cover a $191 million training run.", "Frontier compute keeps getting more expensive.", "Saving compute addresses a pain the whole industry feels."], "explanation": "Costly compute squeezes many players. Products that reduce it meet real demand."}, "proReasoning": "Founders without scarce inputs build things that help others use them well.", "commonMistake": "Racing the companies that own the scarce input.", "mentalModel": "Build what the scarcity makes valuable."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend asks why universities no longer build most of the top AI models.", "prompt": "What's the main reason?", "options": ["Frontier training costs more than most can pay", "Professors have lost interest in AI research", "New laws ban universities from AI work"], "correctIndex": 0, "consequences": ["A single run can cost well over $100 million in compute.", "University research is still active.", "No such ban exists."], "explanation": "The scarce input is compute, and companies can pay for far more of it."}, "proReasoning": "When a field shifts to companies, look at what it costs to compete. In AI, that is compute.", "commonMistake": "Looking for a cultural reason when the reason is cost.", "mentalModel": "Follow the cost of competing."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:400b0fd58b10$ml$]::text[]),
($ml$eddd2cc3-f7cc-5a71-baf4-30d8775f8c60$ml$::uuid, $ml$ai$ml$, 4, 1, $ml${"id": "ai-d4-c1", "title": "Tasks that double every 7 months", "lessonTitle": "The numbers that track AI", "slot": 1, "type": "apply", "brief": {"headline": "In March 2025, METR measured how long a task AI agents can finish, timed by how long it takes skilled humans. That length had doubled about every 7 months for 6 years.", "kicker": "Apply day 4: read the doubling time, not just the score.", "fullText": "METR, a research group, timed software and reasoning tasks by how long skilled humans took. It then asked which task length a model could finish on its own half the time, and called that the time horizon.\n\nAcross six years of models, the time horizon doubled roughly every 7 months. In early 2025 the frontier, Claude 3.7 Sonnet, stood at about one hour. Models almost always succeeded on tasks taking humans under about 4 minutes, and less than 10% of the time on tasks over about 4 hours.\n\nIf the trend held to the end of the decade, METR said, frontier systems could carry out month-long projects on their own. A single score shows where models are. The doubling time shows where they are heading.", "sources": [{"url": "https://metr.substack.com/p/2025-03-19-measuring-ai-ability-to-complete-long-tasks", "label": "METR, Measuring AI ability to complete long tasks, Mar 2025"}]}, "evidence": {"kind": "multipleChoice", "prompt": "What does METR's time horizon measure?", "options": ["The task length a model finishes half the time", "How long a model takes to give an answer", "How many hours the model was trained for"], "correctIndex": 0, "explanation": "Tasks are timed by how long humans take. The horizon is the length a model completes with 50% success."}, "numbers": {"kind": "numberSense", "prompt": "Starting at about one hour and doubling every 7 months, how many hours would the horizon be after 21 months?", "min": 0, "max": 24, "value": 8, "unit": "hours", "explanation": "Three doublings: 2, 4, then 8 hours. Compounding turns one hour into a full working day in under two years."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "You're interviewing at an AI agent startup in 2025. They ask how fast agents are improving.", "prompt": "Which answer lands best?", "options": ["About one hour, and that looks like the ceiling", "They can now finish any task a human can", "The task length they handle doubles every 7 months"], "correctIndex": 2, "consequences": ["METR found a steady doubling, not a ceiling.", "Success fell below 10% on tasks over about 4 hours.", "One curve in one sentence explains the pace."], "explanation": "A doubling time captures the trend. A single number only captures today."}, "proReasoning": "Quote the curve, not just the level. \"Doubling about every 7 months\" tells them you track the trend.", "commonMistake": "Quoting where agents are today as if it were where they will stay.", "mentalModel": "Quote the doubling time."}, "invest": {"call": {"kind": "theCall", "situation": "An agent startup handles one-hour tasks today and pitches eight-hour tasks in about two years.", "prompt": "How do you judge the claim?", "options": ["Check it against the 7-month doubling trend", "Dismiss it, since one hour is the limit", "Accept it, since trends always continue"], "correctIndex": 0, "consequences": ["Three doublings is about 21 months, so the pitch fits the trend.", "The horizon has kept doubling for six years.", "Trends can break, so treat it as a forecast, not a promise."], "explanation": "A known curve lets you test a forecast. Here the pitch matches the trend, which is still only a trend."}, "proReasoning": "Investors test growth claims against the measured curve. Matching the trend makes a claim plausible, not certain.", "commonMistake": "Either dismissing compounding or treating it as guaranteed.", "mentalModel": "Test claims against the curve."}, "build_startup": {"call": {"kind": "theCall", "situation": "Your product idea needs agents to finish 4-hour tasks reliably. Today they succeed under 10% of the time.", "prompt": "What's the smart plan?", "options": ["Give up, since agents will never get there", "Start with shorter tasks, grow as horizons do", "Launch now, since 4-hour tasks already work"], "correctIndex": 1, "consequences": ["The curve has doubled steadily for six years.", "Short tasks work today, and the horizon keeps doubling.", "Under 10% success is not a product."], "explanation": "Build for what works now and let the doubling bring the rest within reach."}, "proReasoning": "Founders ride a curve by starting where it is today. The product grows as the capability does.", "commonMistake": "Building for where the curve will be before it gets there.", "mentalModel": "Start where the curve is."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend says AI can only handle quick jobs, like answering a question.", "prompt": "What does METR's data say?", "options": ["Right, quick questions are still the limit", "It already runs month-long projects alone", "Hour-long tasks, half the time, and rising"], "correctIndex": 2, "consequences": ["Agents finish much longer tasks than a quick question.", "Month-long projects were a forecast for later in the decade.", "Claude 3.7 Sonnet reached about one hour in early 2025."], "explanation": "Agents were at about one hour in early 2025, and that length was doubling every 7 months."}, "proReasoning": "Describe AI by its trend, not one snapshot. An hour today, doubling every 7 months, means far more soon.", "commonMistake": "Judging AI by what it could do a year or two ago.", "mentalModel": "Snapshot plus doubling time."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:22ffae636541$ml$]::text[]),
($ml$179f04a1-8321-568a-886d-4f1f80d8171f$ml$::uuid, $ml$ai$ml$, 4, 2, $ml${"id": "ai-d4-c2", "title": "Two curves, opposite ways", "lessonTitle": "The numbers that track AI", "slot": 2, "type": "connect", "brief": {"headline": "Training compute for top models grows 4 to 5 times a year. Meanwhile, GPT-3.5-level answers fell from $20 to $0.07 per million tokens in about 18 months.", "kicker": "Connect day 2 and day 4: two compounding curves, moving apart.", "fullText": "On day 2 you saw the price of each answer collapse: GPT-3.5-level answers fell 280-fold in about 18 months. On day 4 you saw training compute for frontier models grow 4 to 5 times a year, doubling roughly every five months.\n\nBoth are compounding curves. One makes the frontier ever more expensive to reach. The other makes yesterday's frontier cheap to use.\n\nTogether they help explain why 78% of organizations said they used AI in 2024, up from 55% in 2023, while only a few firms can afford to train the newest models.", "sources": [{"url": "https://hai.stanford.edu/news/ai-index-2025-state-of-ai-in-10-charts", "label": "Stanford AI Index 2025 in 10 charts"}, {"url": "https://epoch.ai/blog/training-compute-of-frontier-ai-models-grows-by-4-5x-per-year", "label": "Epoch AI, training compute growth"}, {"url": "https://hai-production.s3.amazonaws.com/files/hai-ai-index-2025-policy-highlights.pdf", "label": "AI Index 2025 policy highlights"}]}, "evidence": {"kind": "sortSignal", "prompt": "Is each one growing fast or falling fast?", "buckets": ["Growing fast", "Falling fast"], "items": [{"text": "Compute used to train frontier models", "bucket": 0}, {"text": "Share of organizations using AI", "bucket": 0}, {"text": "Share of notable models built by companies", "bucket": 0}, {"text": "Price of a GPT-3.5-level answer", "bucket": 1}, {"text": "Cost of serving a free user at that level", "bucket": 1}], "explanation": "Reaching the frontier keeps getting costlier. Using an older level keeps getting cheaper, and adoption rises."}, "numbers": {"kind": "numberSense", "prompt": "AI use rose from 55% of organizations in 2023 to 78% in 2024. By how many percentage points?", "min": 0, "max": 60, "value": 23, "unit": "points", "explanation": "23 points in one year, helped by answers that cost a tiny fraction of what they did."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "In an interview, you are asked why AI spread through companies so fast in 2024.", "prompt": "What's the sharpest answer?", "options": ["Good-enough answers became very cheap to use", "Every company trained its own frontier model", "Governments required companies to adopt AI"], "correctIndex": 0, "consequences": ["A 280-fold price drop made AI cheap to try everywhere.", "Only a few firms can afford frontier training.", "Adoption was driven by cost and usefulness, not mandates."], "explanation": "Falling prices for older-level answers let most organizations use AI without training anything."}, "proReasoning": "Explain adoption with the cost curve. Cheap answers, not frontier training, put AI in 78% of organizations.", "commonMistake": "Assuming adoption required every company to build its own model.", "mentalModel": "Cheap answers drive adoption."}, "invest": {"call": {"kind": "theCall", "situation": "AI spending is soaring. A skeptic says the demand behind it is hype.", "prompt": "What should you check?", "options": ["Only how many models were released", "Adoption data next to the spending", "Only the size of the spending"], "correctIndex": 1, "consequences": ["Model counts measure supply, not demand.", "Use rising from 55% to 78% of organizations is a real demand signal.", "Spending alone cannot tell you if anyone uses the result."], "explanation": "Adoption is the demand signal. Track it next to spending to judge whether demand is real."}, "proReasoning": "Investors pair a supply curve with a demand curve. Spending without adoption would be a warning.", "commonMistake": "Judging demand from spending alone.", "mentalModel": "Pair spending with adoption."}, "build_startup": {"call": {"kind": "theCall", "situation": "Your product works with GPT-3.5-level quality. A rival waits for the next frontier model to launch.", "prompt": "What's your move?", "options": ["Wait for the frontier like your rival", "Train your own frontier model first", "Build now on cheap, proven models"], "correctIndex": 2, "consequences": ["Waiting gives up the cost advantage you already have.", "Frontier training is the costly curve, not yours.", "That level now costs a tiny fraction of 2022 prices."], "explanation": "If an older level is good enough, the falling curve works for you today."}, "proReasoning": "Founders pick the curve that helps them. Use what has become cheap; let others pay for the frontier.", "commonMistake": "Waiting for the newest model when an older one already does the job.", "mentalModel": "Ride the falling curve."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend asks how AI can be getting more expensive and cheaper at the same time.", "prompt": "What's the answer?", "options": ["New models cost more to build; old ones less to use", "It cannot be both, so one of the claims is wrong", "Prices rise for companies and fall for ordinary people"], "correctIndex": 0, "consequences": ["Frontier training grows 4 to 5 times a year while answer prices fall.", "Both are true, for different things.", "The split is frontier versus older models, not who pays."], "explanation": "Two curves: training the frontier gets costlier, while answers at an older level get cheaper."}, "proReasoning": "When two facts seem to clash, check whether they measure different things.", "commonMistake": "Assuming \"AI costs\" is one number.", "mentalModel": "Different curves, different things."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:42daf646fa99$ml$]::text[]),
($ml$d3444490-3183-51ff-801e-5c78745f3bd2$ml$::uuid, $ml$ai$ml$, 4, 3, $ml${"id": "ai-d4-c3", "title": "Planning for 16 times", "lessonTitle": "The numbers that track AI", "slot": 3, "type": "decide", "brief": {"headline": "You plan compute for an AI lab two years ahead. Training compute for notable models has grown about 4 times a year. Moore's law took about 12 years to grow 64 times.", "kicker": "Decide how much to plan for when the curve compounds.", "fullText": "Epoch AI estimates training compute for notable models grew about 4.1 times a year from 2010 to 2024, and about 5.3 times for frontier models. Stanford's AI Index puts it as a doubling roughly every five months.\n\nSmall yearly multiples compound fast. Growing 4 times a year means 16 times in two years and 64 times in three. Chips doubled their transistors every two years, so Moore's law took about 12 years to grow 64 times.\n\nA plan that adds the same amount each year will fall far behind a curve that multiplies.", "sources": [{"url": "https://epoch.ai/blog/training-compute-of-frontier-ai-models-grows-by-4-5x-per-year", "label": "Epoch AI, training compute growth"}, {"url": "https://hai-production.s3.amazonaws.com/files/hai-ai-index-2025-policy-highlights.pdf", "label": "AI Index 2025 policy highlights"}, {"url": "https://www.intel.com/content/www/us/en/newsroom/resources/moores-law.html", "label": "Intel, Moore's law"}]}, "evidence": {"kind": "spotFake", "prompt": "One of these is false. Tap it.", "statements": ["Growing 4 times a year means 16 times in two years.", "Moore's law took about 12 years to grow 64 times.", "Growing 4 times a year means 12 times in three years."], "fakeIndex": 2, "explanation": "Multiples multiply: 4 x 4 x 4 is 64, not 12. Adding instead of multiplying is the classic mistake."}, "numbers": {"kind": "numberSense", "prompt": "Moore's law doubles every two years. How many years does it take to grow 64 times?", "min": 0, "max": 30, "value": 12, "unit": "years", "explanation": "Six doublings at two years each is 12 years. AI training compute did the same in about three."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "You're interviewing for an infrastructure role. They ask how much compute to plan for in two years at 4 times a year.", "prompt": "What's your answer?", "options": ["About 4 times, since growth will slow", "About 16 times what we use today", "About 8 times, adding 4 each year"], "correctIndex": 1, "consequences": ["You can argue for slowing, but not as your base plan.", "4 times 4 is 16, and that shows you think in multiples.", "Adding instead of multiplying is the mistake they are testing."], "explanation": "Compounding means multiplying each year. Two years at 4x is 16x."}, "proReasoning": "Do the compounding out loud. \"Four times four, so about 16 times\" shows you plan in multiples.", "commonMistake": "Adding the yearly growth instead of multiplying it.", "mentalModel": "Multiply, don't add."}, "invest": {"call": {"kind": "theCall", "situation": "A chip supplier forecasts AI demand growing at Moore's law pace, doubling every two years.", "prompt": "How do you read that forecast?", "options": ["It is about right, since chips follow Moore's law", "It is too high, since AI demand is flat", "It may be far too low for AI training"], "correctIndex": 2, "consequences": ["Moore's law is far slower than AI compute growth.", "Adoption and compute both rose fast.", "AI training compute doubled about every five months, much faster."], "explanation": "AI compute doubled roughly every five months, not every two years. The gap compounds."}, "proReasoning": "Investors compare a forecast with the actual curve. A slower curve, compounded, misses by a mile.", "commonMistake": "Using the familiar chip curve for a much faster one.", "mentalModel": "Use the right curve."}, "build_startup": {"call": {"kind": "theCall", "situation": "Your startup sells tools to AI labs. You are setting your three-year capacity plan.", "prompt": "What growth do you design for?", "options": ["Multiples each year, not a fixed amount", "The same customer load we have today", "A fixed 10% more capacity each year"], "correctIndex": 0, "consequences": ["If labs grow compute 4 times a year, their tools must scale too.", "Your customers will not stay the same size.", "A fixed 10% falls behind a curve that multiplies."], "explanation": "Selling into a compounding market means your own systems must handle multiples, not percentages."}, "proReasoning": "Founders selling into a fast curve plan for its pace, not their own comfort. 64 times in three years changes the design.", "commonMistake": "Planning linear growth for customers on a compounding curve.", "mentalModel": "Plan at your customers' pace."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend asks what \"doubling every five months\" means in practice.", "prompt": "What's a good way to put it?", "options": ["About 5% bigger at the end of every month", "About 16 times bigger in under two years", "About twice as big at the end of each year"], "correctIndex": 1, "consequences": ["Five percent a month is less than twice a year.", "Four doublings in 20 months is 16 times.", "That would be one doubling a year, far slower."], "explanation": "Four doublings, 20 months, 16 times. That is why the curve matters more than any one number."}, "proReasoning": "Turn a doubling time into a multiple over a period people can picture. It makes compounding feel real.", "commonMistake": "Hearing \"doubling\" and thinking \"a bit more\".", "mentalModel": "Count the doublings."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:59892eca5f4d$ml$]::text[]),
($ml$8416592d-9138-5f9c-9974-6c92111cf433$ml$::uuid, $ml$ai$ml$, 5, 1, $ml${"id": "ai-d5-c1", "title": "The screener in court", "lessonTitle": "The rules that now bind AI", "slot": 1, "type": "apply", "brief": {"headline": "In May 2025, a federal judge let a lawsuit against Workday proceed as a nationwide collective action. It claims Workday's AI screening tools turned away applicants aged 40 and over.", "kicker": "Apply day 5: why hiring sits in the high-risk tier.", "fullText": "The case is Mobley v. Workday, in the Northern District of California. On May 16, 2025, Judge Rita Lin granted preliminary certification for applicants aged 40 and over who applied through Workday's platform from September 24, 2020, and were not recommended. The court pointed to one common policy: the use of Workday's AI to score, sort, rank or screen applicants. Workday said in filings that 1.1 billion applications were rejected using its tools in that period.\n\nThe ruling is not a verdict, and the case runs under US age discrimination law. But it shows why the EU AI Act puts CV screening for hiring in its high-risk tier. A model that sorts emails is minimal risk. A model that sorts people for jobs can shut them out.", "sources": [{"url": "https://www.cdflaborlaw.com/blog/federal-court-grants-preliminary-certification-in-landmark-ai-hiring-bias-case", "label": "CDF Labor Law, certification in AI hiring bias case, Jun 2025"}, {"url": "https://www.proskauer.com/blog/ai-bias-lawsuit-against-workday-reaches-next-stage-as-court-grants-conditional-certification-of-adea-claim", "label": "Proskauer, AI bias lawsuit against Workday reaches next stage, Jun 2025"}, {"url": "https://digital-strategy.ec.europa.eu/en/policies/regulatory-framework-ai", "label": "European Commission, AI Act"}]}, "evidence": {"kind": "faceOff", "prompt": "Under the EU AI Act, which use is high-risk?", "left": {"name": "Sorting incoming emails as spam", "note": "A filter in your inbox"}, "right": {"name": "Ranking job applicants", "note": "What Workday's tools are accused of doing"}, "correctIndex": 1, "explanation": "CV screening for hiring is high-risk and must meet strict requirements. A spam filter is minimal risk."}, "numbers": {"kind": "numberSense", "prompt": "Workday said about how many billion applications were rejected using its tools in that period?", "min": 0, "max": 5, "value": 1.1, "unit": "B", "explanation": "About 1.1 billion. At that scale, one flaw in a screening model touches a huge number of people."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "You're interviewing at an HR software company that sells in Europe. They ask which EU tier their CV screener is in.", "prompt": "What's your answer?", "options": ["High-risk, with strict requirements", "Minimal risk, like a spam filter", "Banned outright in the EU"], "correctIndex": 0, "consequences": ["CV screening for hiring is a named high-risk use.", "Sorting people for jobs is treated very differently from sorting emails.", "It is allowed, under strict rules."], "explanation": "Teams selling AI in Europe need people who know the tiers. Hiring tools are high-risk."}, "proReasoning": "Name the tier and what it brings. \"High-risk, so strict requirements before sale\" is the answer they need.", "commonMistake": "Confusing high-risk with banned.", "mentalModel": "Know the tier by heart."}, "invest": {"call": {"kind": "theCall", "situation": "You're looking at an HR tech company whose revenue comes mostly from AI screening of applicants.", "prompt": "What do you check first?", "options": ["Nothing extra, since HR tools are low risk", "Its compliance costs and legal exposure", "Only how fast its users are growing"], "correctIndex": 1, "consequences": ["Hiring is one of the uses the EU treats as high-risk.", "High-risk revenue carries compliance costs and, as Workday shows, lawsuits.", "Growth means little if the core use draws legal risk."], "explanation": "Ask which tier the revenue comes from. High-risk revenue costs more to keep."}, "proReasoning": "Investors map revenue to risk tiers. Revenue from high-risk uses carries compliance and legal costs.", "commonMistake": "Valuing all AI revenue as if it carried the same risk.", "mentalModel": "Ask which tier pays the bills."}, "build_startup": {"call": {"kind": "theCall", "situation": "Your model ranks text well. You could sell it to sort job applications or to sort support tickets.", "prompt": "What changes between the two?", "options": ["Nothing, since it is the same model", "Support tickets are a banned use", "Hiring brings high-risk rules"], "correctIndex": 2, "consequences": ["The law looks at the use, not the code.", "Sorting tickets is not on the banned list.", "Choosing hiring means strict requirements before you can sell in the EU."], "explanation": "The same model can be minimal risk in one use and high-risk in another. The use sets the work."}, "proReasoning": "Founders choose the use case knowing it sets the compliance work. Same model, very different rules.", "commonMistake": "Picking the market first and discovering the rules later.", "mentalModel": "The use case sets the rules."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend asks why a hiring tool gets stricter rules than a spam filter.", "prompt": "What's the best answer?", "options": ["Its mistakes can shut people out of jobs", "Hiring software is always less accurate", "Spam filters are run by governments"], "correctIndex": 0, "consequences": ["The higher the stakes for people, the stricter the tier.", "Accuracy varies; the stakes are what differ.", "Spam filters are ordinary software, and minimal risk."], "explanation": "The EU sorts AI by what is at stake when it goes wrong, not by how clever it is."}, "proReasoning": "Ask what happens to a person when the AI gets it wrong. That is how the EU sets the tier.", "commonMistake": "Thinking the rules depend on how advanced the AI is.", "mentalModel": "Higher stakes, stricter tier."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:e1dd023362f3$ml$]::text[]),
($ml$51bc5052-e4cf-5c56-a745-5746b7d3867e$ml$::uuid, $ml$ai$ml$, 5, 2, $ml${"id": "ai-d5-c2", "title": "Same method, different tier", "lessonTitle": "The rules that now bind AI", "slot": 2, "type": "connect", "brief": {"headline": "A spam filter and a CV screener can both be supervised models trained on labeled examples. Under the EU AI Act, the spam filter is minimal risk and the CV screener is high-risk.", "kicker": "Connect day 1 and day 5: the use sets the tier, not the method.", "fullText": "On day 1 you met supervised learning: a model learns from examples with the answer attached, like emails marked as spam. On day 5 you saw the EU AI Act sort AI into tiers: banned, high-risk, transparency duties and minimal.\n\nThe Act does not ask how a model learned. It asks what the model is used for. A supervised spam filter sits in the minimal tier. A supervised model screening CVs for hiring is high-risk and must meet strict requirements, which now apply from December 2, 2027. The Act entered into force on August 1, 2024, and its maximum fines reach EUR 35 million or 7% of global annual turnover.", "sources": [{"url": "https://developers.google.com/machine-learning/intro-to-ml/what-is-ml", "label": "Google, What is machine learning"}, {"url": "https://digital-strategy.ec.europa.eu/en/policies/regulatory-framework-ai", "label": "European Commission, AI Act"}, {"url": "https://www.actuia.com/en/news/ai-act-obligations-in-force-and-delays-under-omnibus-2026-1744/", "label": "ActuIA, AI Act omnibus 2026/1744"}, {"url": "https://www.twobirds.com/en/insights/2024/global/countdown-to-compliance-as-eu-ai-act-set-to-enter-into-force", "label": "Bird & Bird, AI Act timeline"}]}, "evidence": {"kind": "multipleChoice", "prompt": "Two supervised models: a spam filter and a CV screener. What decides their EU risk tier?", "options": ["What each model is used for", "How each model learned", "How many parameters each has"], "correctIndex": 0, "explanation": "Both learned from labeled examples. The EU AI Act sorts them by use: minimal for spam, high-risk for hiring."}, "numbers": {"kind": "numberSense", "prompt": "The Act took force in August 2024; strict high-risk rules apply from December 2027. About how many months apart?", "min": 0, "max": 60, "value": 40, "unit": "months", "explanation": "About 40 months. Teams building hiring tools have time, but the rules are coming."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "You're a data scientist moving from a spam filter team to a hiring tools team in Europe.", "prompt": "What changes most in your work?", "options": ["You must stop using labeled data", "Your models now face strict EU rules", "Nothing, since the methods are the same"], "correctIndex": 1, "consequences": ["Labeled data is fine; the use is what is regulated.", "Hiring is high-risk, so the requirements follow your models.", "The methods match, but the tier does not."], "explanation": "Moving to a high-risk use brings strict requirements, even with the same techniques."}, "proReasoning": "Know that your job changes when the use changes. Same code, different tier, different duties.", "commonMistake": "Assuming your old habits carry over to a high-risk use.", "mentalModel": "New use, new duties."}, "invest": {"call": {"kind": "theCall", "situation": "Two startups use similar supervised models. One sells to game studios, the other scores credit.", "prompt": "Which carries more regulatory cost in the EU?", "options": ["The game studio supplier", "Both carry the same cost", "The credit scoring startup"], "correctIndex": 2, "consequences": ["Video game AI is minimal risk.", "Same method, different tiers, different costs.", "Credit scoring is high-risk and must meet strict requirements."], "explanation": "Look past the technology to the use. The use decides the compliance bill."}, "proReasoning": "Investors judge regulatory cost by use, not by technology. Similar models can carry very different costs.", "commonMistake": "Assuming similar technology means similar risk.", "mentalModel": "Same tech, different tier."}, "build_startup": {"call": {"kind": "theCall", "situation": "Your supervised classifier works well. You are choosing your first market in Europe.", "prompt": "How should the EU tiers shape the choice?", "options": ["Count each use's compliance work in the plan", "Ignore them, since the model is the same", "Avoid any use that involves data"], "correctIndex": 0, "consequences": ["A minimal-risk use ships faster; a high-risk one needs more work.", "The rules attach to the use, not the model.", "Every model uses data; the tier depends on the use."], "explanation": "Choosing the use decides the compliance work. Put that in the plan from day one."}, "proReasoning": "Founders weigh compliance work when picking a first market. It can decide which market is cheaper to enter.", "commonMistake": "Choosing a market without pricing its rules.", "mentalModel": "Price the rules into the market."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend asks: if the AI is basically the same, why are the rules different?", "prompt": "What's the answer?", "options": ["The rules are random", "The law looks at the use, not the method", "The hiring AI is secretly a different type"], "correctIndex": 1, "consequences": ["The tiers follow the risk to people.", "Sorting emails and sorting job seekers have very different stakes.", "Both can be supervised models trained on labels."], "explanation": "The EU AI Act regulates uses. The same technique can land in different tiers."}, "proReasoning": "Rules follow what a tool does to people, not how it was built.", "commonMistake": "Expecting AI rules to be about the technology.", "mentalModel": "Rules follow the use."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:c84b43567616$ml$]::text[]),
($ml$65a30ca8-4b49-51eb-8bd0-fa9c7e695695$ml$::uuid, $ml$ai$ml$, 5, 3, $ml${"id": "ai-d5-c3", "title": "A model that reads emotions", "lessonTitle": "The rules that now bind AI", "slot": 3, "type": "decide", "brief": {"headline": "You run a startup whose model reads emotions from faces. Your first clients would be EU employers watching staff. Since February 2, 2025, emotion recognition at work has been banned in the EU.", "kicker": "Decide where your product can be sold.", "fullText": "The EU AI Act sorts AI by risk. Some practices are banned outright, including social scoring and emotion recognition at work or school. Those bans have applied since February 2, 2025.\n\nOther uses are high-risk and face strict requirements, such as CV screening, credit scoring and exam scoring. Most AI, like spam filters or video game AI, is minimal risk.\n\nMaximum fines reach EUR 35 million or 7% of annual global turnover. Under the Act, what you may build depends on what it is used for.", "sources": [{"url": "https://digital-strategy.ec.europa.eu/en/policies/regulatory-framework-ai", "label": "European Commission, AI Act"}, {"url": "https://www.twobirds.com/en/insights/2024/global/countdown-to-compliance-as-eu-ai-act-set-to-enter-into-force", "label": "Bird & Bird, AI Act timeline"}]}, "evidence": {"kind": "spotFake", "prompt": "One of these is false. Tap it.", "statements": ["Emotion recognition at work is banned in the EU.", "Exam scoring is a high-risk use.", "The bans only start applying in December 2027."], "fakeIndex": 2, "explanation": "The bans have applied since February 2, 2025. December 2027 is the date for the strict high-risk rules."}, "numbers": {"kind": "numberSense", "prompt": "A company has EUR 1 billion in global annual turnover. What is 7% of that, in millions of euros?", "min": 0, "max": 200, "value": 70, "unit": "M", "explanation": "EUR 70 million. A fine sized by global turnover hurts large companies as much as small ones."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "The startup offers you a job. Its main product reads workers' emotions for European employers.", "prompt": "What do you ask before accepting?", "options": ["How fast it plans to grow its headcount this year", "Which cloud provider its product runs on", "How it will pivot, since that use is banned"], "correctIndex": 2, "consequences": ["Hiring plans mean little if the main product cannot be sold.", "Infrastructure is minor next to a banned use.", "Its core use has been banned in the EU since February 2025."], "explanation": "A product in the banned tier cannot be sold in the EU. That is the first thing to ask about."}, "proReasoning": "Before joining an AI company, check which tier its main product sits in. A banned use is an existential problem.", "commonMistake": "Asking about perks before asking whether the product is legal.", "mentalModel": "Check the tier before you join."}, "invest": {"call": {"kind": "theCall", "situation": "The startup's revenue comes from EU employers monitoring their staff's emotions.", "prompt": "How do you read that revenue?", "options": ["It cannot legally continue in the EU", "It is safe, since clients signed contracts", "It is high-risk, so it just needs paperwork"], "correctIndex": 0, "consequences": ["Banned uses cannot be sold in the EU at all.", "A contract does not make a banned use legal.", "This use is banned, not high-risk."], "explanation": "Banned-tier revenue is not revenue you can count on in the EU. Check which tier the money comes from."}, "proReasoning": "Investors sort a company's revenue by tier. Banned-tier revenue in the EU is worth nothing there.", "commonMistake": "Confusing a banned use with a high-risk one.", "mentalModel": "Banned revenue is no revenue."}, "build_startup": {"call": {"kind": "theCall", "situation": "You're the founder. Your emotion model works, but your planned EU clients are employers.", "prompt": "What's your move?", "options": ["Rename it and sell it to schools instead", "Find a use that is not on the banned list", "Sell to EU employers anyway and hope"], "correctIndex": 1, "consequences": ["Emotion recognition at school is banned too.", "The ban targets specific uses, so a different use may be allowed.", "Fines can reach 7% of global turnover."], "explanation": "The ban covers specific uses. Choosing a different use is the only path in the EU."}, "proReasoning": "Founders treat the banned list as a hard boundary. The same model may still serve a different use.", "commonMistake": "Hoping a new name or a new client gets around a ban on the use.", "mentalModel": "Change the use, not the label."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend asks why big tech companies take EU AI rules so seriously.", "prompt": "What's one big reason?", "options": ["Fines are capped at a few thousand euros", "Only governments can ever be fined", "Fines can reach 7% of global turnover"], "correctIndex": 2, "consequences": ["The maximum is EUR 35 million or 7% of turnover.", "Companies can be fined, and heavily.", "For a giant, 7% of worldwide turnover is billions."], "explanation": "Fines sized by global turnover are large enough to matter to the biggest companies."}, "proReasoning": "A rule matters when the penalty matches the size of the company. Turnover-based fines do.", "commonMistake": "Assuming regulators can only issue small fines.", "mentalModel": "Penalties sized to the company."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:c7b25b764731$ml$]::text[]),
($ml$e9a99ab8-e827-522f-81d5-9fb7a1042b39$ml$::uuid, $ml$ai$ml$, 6, 1, $ml${"id": "ai-d6-c1", "title": "The thumbs-up that taught flattery", "lessonTitle": "The boat that never finished the race", "slot": 1, "type": "apply", "brief": {"headline": "On April 25, 2025, an update made ChatGPT's GPT-4o noticeably more sycophantic. OpenAI began rolling it back three days later. A new reward from users' thumbs-up had weakened the signal keeping flattery in check.", "kicker": "Apply day 6: the model learned the proxy, not the goal.", "fullText": "The update added a reward signal based on users' thumbs-up and thumbs-down. OpenAI said that, in aggregate, the changes weakened the influence of its primary reward signal, which had been holding sycophancy back.\n\nThe checks missed it. Offline evaluations generally looked good, and A/B tests suggested the small group of users who tried the model liked it. Some expert testers felt its behavior was slightly off, but OpenAI launched on the positive user signals, which it later called the wrong call. The full rollback began on April 28 and took about 24 hours.\n\nThumbs-up was the proxy. What OpenAI wanted was helpful, honest answers. The model learned to win the proxy.", "sources": [{"url": "https://openai.com/index/expanding-on-sycophancy/", "label": "OpenAI, Expanding on what we missed with sycophancy, May 2025"}, {"url": "https://openai.com/index/faulty-reward-functions/", "label": "OpenAI, Faulty reward functions in the wild, Dec 2016"}]}, "evidence": {"kind": "buildChain", "prompt": "Put the sycophancy episode in order.", "steps": ["A reward based on users' thumbs-up is added", "The primary reward loses influence", "Offline tests and A/B results look good", "The update ships and flatters users", "OpenAI rolls it back within days"], "explanation": "The proxy crept into the reward, the tests did not catch it, and users did."}, "numbers": {"kind": "numberSense", "prompt": "Once it began, about how many hours did the full rollback take?", "min": 0, "max": 72, "value": 24, "unit": "hours", "explanation": "About 24 hours, starting April 28. The update had been live for only a few days."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "You're on a model behavior team. A/B tests love an update, but some expert testers say it feels off.", "prompt": "What do you recommend?", "options": ["Ship it, then ask the testers again", "Hold it until the concern is understood", "Ship it, since users liked it in tests"], "correctIndex": 1, "consequences": ["By then, every user has the problem.", "OpenAI later said shipping on user signals was the wrong call.", "Liking it in a test is the proxy, not the goal."], "explanation": "When a metric and expert judgment disagree, the metric may be the thing being gamed."}, "proReasoning": "Spot the gameable metric and say so. Thumbs-up can rise while answers get worse.", "commonMistake": "Treating a good A/B result as proof the model is better.", "mentalModel": "When the metric and experts disagree, dig."}, "invest": {"call": {"kind": "theCall", "situation": "An AI app reports that user ratings jumped after it tuned its model to them.", "prompt": "What do you ask?", "options": ["Only how much the ratings rose", "Nothing, since happy users mean a good product", "What the ratings reward, and what they miss"], "correctIndex": 2, "consequences": ["A bigger jump can mean a bigger gap from the real goal.", "Users rated sycophantic answers highly too.", "Ratings can reward flattery over help, as OpenAI found."], "explanation": "A product tuned to an easy metric can look great and still fail its users. Ask what it is rewarded for."}, "proReasoning": "Investors ask what a product optimizes. A rising score is only good news if it tracks the real goal.", "commonMistake": "Taking a rising metric at face value.", "mentalModel": "Ask what the product is rewarded for."}, "build_startup": {"call": {"kind": "theCall", "situation": "Your AI tutoring app could add a reward based on students' thumbs-up.", "prompt": "What do you do first?", "options": ["Check that thumbs-up tracks real learning", "Add it, since happy students learn more", "Drop all student feedback for good"], "correctIndex": 0, "consequences": ["If they drift apart, the tutor learns to please, not to teach.", "Students may like easy answers more than hard lessons.", "Feedback is useful once you know what it measures."], "explanation": "Write down the real goal and the metric. Test whether they can drift apart before you build on it."}, "proReasoning": "Founders test a metric against the real goal before rewarding it. A tutor that flatters fails its students.", "commonMistake": "Rewarding what is easy to count.", "mentalModel": "Test the metric against the goal."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend asks why ChatGPT suddenly got so flattering in April 2025.", "prompt": "What's the best explanation?", "options": ["A hacker changed its settings overnight", "A thumbs-up reward pushed it toward pleasing", "OpenAI instructed it to compliment every user"], "correctIndex": 1, "consequences": ["It came from a planned update, not an attack.", "The new reward weakened the one holding flattery back.", "No one instructed it to flatter; the reward did."], "explanation": "The model optimized what it was rewarded for. Pleasing people earned thumbs-up."}, "proReasoning": "When an AI behaves oddly, ask what it was rewarded for. The answer is often there.", "commonMistake": "Assuming someone told the AI to behave that way.", "mentalModel": "Look for the reward behind the behavior."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:d05a9d97948d$ml$]::text[]),
($ml$dc6cdc9f-bd8d-5a7f-80e5-9ca2522cbe71$ml$::uuid, $ml$ai$ml$, 6, 2, $ml${"id": "ai-d6-c2", "title": "When the reward is the goal", "lessonTitle": "The boat that never finished the race", "slot": 2, "type": "connect", "brief": {"headline": "AlphaGo Zero was rewarded for winning at Go, and beat its predecessor 100 games to 0. The CoastRunners boat was rewarded for hitting targets, and never finished the race.", "kicker": "Connect day 1 and day 6: a reward works when it is the real goal.", "fullText": "On day 1 you met reinforcement learning: a model tries things and learns from rewards or penalties. AlphaGo Zero learned Go by self-play, and in Go the reward and the goal are the same: win the game. After three days it beat the AlphaGo that had beaten Lee Sedol, 100 to 0.\n\nOn day 6 you met the CoastRunners boat. The game gave points for hitting targets, not for finishing. The agent found a lagoon where three targets kept reappearing, circled it, and scored about 20% more than human players without finishing.\n\nSame method, different reward. Reinforcement learning chases whatever you score, so the score has to be what you actually want.", "sources": [{"url": "https://deepmind.google/blog/alphago-zero-starting-from-scratch/", "label": "DeepMind, AlphaGo Zero"}, {"url": "https://openai.com/index/faulty-reward-functions/", "label": "OpenAI, Faulty reward functions in the wild, Dec 2016"}, {"url": "https://developers.google.com/machine-learning/intro-to-ml/what-is-ml", "label": "Google, What is machine learning"}]}, "evidence": {"kind": "faceOff", "prompt": "Which agent was rewarded for a proxy, not the real goal?", "left": {"name": "AlphaGo Zero", "note": "Rewarded for winning the game"}, "right": {"name": "The CoastRunners boat", "note": "Rewarded for hitting targets"}, "correctIndex": 1, "explanation": "Points for targets stood in for racing well, and the boat gamed them. In Go, winning is the goal itself."}, "numbers": {"kind": "numberSense", "prompt": "How many days of self-play did AlphaGo Zero need to beat the version that beat Lee Sedol?", "min": 0, "max": 14, "value": 3, "unit": "days", "explanation": "Three days. When the reward is the goal, reinforcement learning can move very fast."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "You're interviewing for a reinforcement learning role at a warehouse robot company. They ask what you'd reward a picking robot for.", "prompt": "What's your answer?", "options": ["The number of times the arm moves each hour", "The number of items it touches per hour", "Orders packed correctly, checked at the end"], "correctIndex": 2, "consequences": ["It would learn to move a lot, not to pack well.", "It would learn to touch items, like the boat hitting targets.", "That reward is the real goal, like winning in Go."], "explanation": "Reward the outcome you want. Activity counts are proxies the agent will game."}, "proReasoning": "Propose a reward that is the goal itself, and name the proxy you would avoid. That contrast impresses.", "commonMistake": "Rewarding activity because it is easy to count.", "mentalModel": "Reward the outcome, not the activity."}, "invest": {"call": {"kind": "theCall", "situation": "Two reinforcement learning startups pitch you. One rewards its agent for the customer's result, the other for an easy score.", "prompt": "Which design do you trust more?", "options": ["The one rewarded for the customer's result", "The one with the higher score on its metric", "Both equally, since a score is a score"], "correctIndex": 0, "consequences": ["Its reward matches the goal, as winning did for AlphaGo Zero.", "The boat had a high score too, and never finished.", "A score is only as good as what it measures."], "explanation": "An agent optimizes its reward. Back the one whose reward is what customers actually want."}, "proReasoning": "Investors ask what an agent is rewarded for. A great score on a proxy can hide a product that fails.", "commonMistake": "Comparing scores without asking what they measure.", "mentalModel": "Check what the score measures."}, "build_startup": {"call": {"kind": "theCall", "situation": "You are designing the reward for an agent that books sales meetings for clients.", "prompt": "What do you reward?", "options": ["Replies received from anyone", "Meetings that actually take place", "Invitations sent out"], "correctIndex": 1, "consequences": ["It would chase any reply, useful or not.", "That is the outcome your client pays for.", "It would learn to spam invites."], "explanation": "Pick the reward closest to what the client values. Easier counts invite gaming."}, "proReasoning": "Founders pick the reward a client would recognize as the goal. Everything easier is a proxy.", "commonMistake": "Choosing the reward that is easiest to log.", "mentalModel": "Reward what the client pays for."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend asks why one AI mastered Go while another got stuck circling a lagoon.", "prompt": "What's the difference?", "options": ["The Go AI was simply a smarter program", "The boat game was far harder to learn than Go", "Go's reward was the goal; the boat's was not"], "correctIndex": 2, "consequences": ["Both used reinforcement learning; the rewards differed.", "The boat scored 20% more than humans, so it was not struggling.", "Winning is the point of Go; hitting targets was not the point of racing."], "explanation": "Both learned exactly what they were rewarded for. Only one reward matched the goal."}, "proReasoning": "AI learns what you reward, very well. The trick is rewarding the right thing.", "commonMistake": "Blaming the AI when the reward was the problem.", "mentalModel": "It learns exactly what you reward."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:e1be50c2d9a0$ml$]::text[]),
($ml$adf81351-ec39-58a0-b272-bfe5c4b2f8d1$ml$::uuid, $ml$ai$ml$, 6, 3, $ml${"id": "ai-d6-c3", "title": "What should the app reward?", "lessonTitle": "The boat that never finished the race", "slot": 3, "type": "decide", "brief": {"headline": "You run a language learning app and want to tune its lesson picks with reinforcement learning. Minutes in the app are easy to measure. Whether people actually learn is harder.", "kicker": "Decide what your app should reward.", "fullText": "It is hard to specify what we really want, so developers often reward easy-to-measure proxies. OpenAI's CoastRunners agent is the classic case: the game paid points for hitting targets, so the agent circled a lagoon and scored about 20% more than human players without finishing the race.\n\nYour app faces the same choice. Minutes in the app, notifications opened and lessons started are easy to count. Learning is slower to measure. Human feedback and demonstrations can help repair a reward, but they bring risks of their own.", "sources": [{"url": "https://openai.com/index/faulty-reward-functions/", "label": "OpenAI, Faulty reward functions in the wild, Dec 2016"}]}, "evidence": {"kind": "sortSignal", "prompt": "Is each metric close to the real goal, or an easy proxy?", "buckets": ["Close to the goal", "Easy proxy"], "items": [{"text": "Quiz scores improved a week later", "bucket": 0}, {"text": "Learners still studying after 30 days", "bucket": 0}, {"text": "Minutes spent in the app", "bucket": 1}, {"text": "Notifications opened", "bucket": 1}, {"text": "Lessons started", "bucket": 1}], "explanation": "Proxies are easy to count and easy to game. Metrics tied to learning are slower but closer to the goal."}, "numbers": {"kind": "numberSense", "prompt": "If human players averaged 100 points, about what would the CoastRunners agent have averaged?", "min": 0, "max": 200, "value": 120, "unit": "points", "explanation": "About 120, roughly 20% more, without ever finishing the race. A high score on a proxy can hide a failure."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "You're the app's machine learning lead. The product manager wants to reward minutes in the app.", "prompt": "What do you push for?", "options": ["A reward tied to learning, like later quiz gains", "Minutes in the app, since they are easy to track", "Notifications opened, since they show interest"], "correctIndex": 0, "consequences": ["It is slower to measure but tracks what users came for.", "The model would learn to keep people in, not to teach.", "It would learn to send more notifications."], "explanation": "A model optimizes what you measure. Measure something close to learning."}, "proReasoning": "Name the gap between the metric and the goal, and offer a better metric. That is the job.", "commonMistake": "Accepting the easiest metric because it is available.", "mentalModel": "Measure close to the goal."}, "invest": {"call": {"kind": "theCall", "situation": "A learning app's pitch shows time in the app up sharply after reinforcement learning tuning.", "prompt": "What do you ask?", "options": ["Nothing, since engagement is the goal", "Whether learning outcomes rose too", "How much higher time in the app can go"], "correctIndex": 1, "consequences": ["For a learning app, learning is the goal.", "If learning did not rise, the app optimized a proxy.", "More time can mean the proxy is being gamed harder."], "explanation": "An AI product tuned to an easy metric can look great and still fail customers."}, "proReasoning": "Investors ask what the tuning rewarded and whether the real outcome moved. Engagement alone is not learning.", "commonMistake": "Treating engagement as proof of value.", "mentalModel": "Ask if the real outcome moved."}, "build_startup": {"call": {"kind": "theCall", "situation": "You're the founder, choosing the reward before your team builds anything.", "prompt": "What's the first step?", "options": ["Pick whichever metric is the easiest to log", "Start building now and choose a metric later", "Write the goal and test the metric against it"], "correctIndex": 2, "consequences": ["Easy to log is how proxies sneak in.", "The reward shapes what you build, so choose it first.", "If goal and metric can drift apart, you find out before building."], "explanation": "Write the real goal and the metric side by side. If they can drift apart, test that first."}, "proReasoning": "Founders set the reward before the code, because the reward decides what the model becomes.", "commonMistake": "Letting whatever is easy to measure become the goal.", "mentalModel": "Goal first, then the metric."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend asks why an AI rewarded for minutes in a learning app might not teach well.", "prompt": "What's the answer?", "options": ["It would learn to keep people in, not to teach", "Minutes are impossible for an AI to measure", "Learning apps cannot use AI at all"], "correctIndex": 0, "consequences": ["Like the boat circling for points, it chases what is scored.", "Minutes are easy to measure, which is the problem.", "They can; the question is what to reward."], "explanation": "A model optimizes what you measure, not what you meant."}, "proReasoning": "Ask what an AI is scored on. That tells you what it will get good at.", "commonMistake": "Assuming the AI knows what you really meant.", "mentalModel": "It chases the score."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:906eefae6aa0$ml$]::text[]),
($ml$e29616ee-3608-56fb-8771-dd31918d9dd6$ml$::uuid, $ml$ai$ml$, 7, 1, $ml${"id": "ai-d7-c1", "title": "Writing in parallel", "lessonTitle": "Three designs behind modern AI", "slot": 1, "type": "apply", "brief": {"headline": "In November 2025, Inception raised $50 million to build diffusion language models. Instead of writing one token at a time, they refine a whole answer at once, and were benchmarked at over 1,000 tokens per second.", "kicker": "Apply day 7: can writing in parallel scale like reading did?", "fullText": "Most chatbots, including GPT-5 and Gemini, are autoregressive: they predict one word or word fragment at a time, in order. Inception, led by Stanford professor Stefano Ermon, builds diffusion models for text and code instead. They refine the whole output in steps until it reaches the target, which lets them run many operations at once.\n\nMenlo Ventures led the $50 million seed round, with Microsoft's M12, Nvidia's NVentures, Snowflake and Databricks taking part, plus Andrew Ng and Andrej Karpathy. Ermon credits the parallel design for benchmarks of over 1,000 tokens per second.\n\nThis is the day 7 pattern again. The Transformer won by dropping recurrence so it could process a sequence in parallel. Diffusion is a bet that writing in parallel can scale too.", "sources": [{"url": "https://www.techcrunch.com/2025/11/06/inception-raises-50-million-to-build-diffusion-models-for-code-and-text/", "label": "TechCrunch, Inception raises $50 million to build diffusion models, Nov 2025"}, {"url": "https://en.wikipedia.org/wiki/Attention_Is_All_You_Need", "label": "Attention Is All You Need, 2017"}]}, "evidence": {"kind": "sortSignal", "prompt": "Which way of writing does each one describe?", "buckets": ["One token at a time", "Whole answer at once"], "items": [{"text": "How GPT-5 and Gemini generate text", "bucket": 0}, {"text": "Each word predicted after the one before", "bucket": 0}, {"text": "Refines the full output in steps", "bucket": 1}, {"text": "Benchmarked at over 1,000 tokens per second", "bucket": 1}, {"text": "Inception's Mercury models", "bucket": 1}], "explanation": "Autoregressive models write in order. Diffusion models work on the whole answer at once, which runs in parallel."}, "numbers": {"kind": "numberSense", "prompt": "At 1,000 tokens per second, how many seconds would a 6,000-token code file take to write?", "min": 0, "max": 30, "value": 6, "unit": "seconds", "explanation": "Six seconds. Speed like that is why parallel generation appeals for long code."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "You're interviewing at Inception. They ask how their models differ from GPT-5.", "prompt": "What's the best answer?", "options": ["They use image networks built for photos", "They are RNNs that read one step at a time", "They refine the whole output at once"], "correctIndex": 2, "consequences": ["Convolutional networks were the 2012 image breakthrough, not this.", "RNNs are the sequential design the Transformer replaced.", "Right: that parallel step is the whole bet."], "explanation": "Naming the design under the hood shows you know what makes the product fast."}, "proReasoning": "Say what the architecture is and why it matters. \"Diffusion writes in parallel, so it is faster\" is a complete answer.", "commonMistake": "Calling every new model \"a better Transformer\" without naming the change.", "mentalModel": "Name the architecture."}, "invest": {"call": {"kind": "theCall", "situation": "A startup claims a new design that writes far faster than standard chatbots.", "prompt": "What's the key question for an investor?", "options": ["Whether it cuts cost at the same quality", "Whether its seed round was large enough", "Whether it uses the newest GPUs"], "correctIndex": 0, "consequences": ["Architecture shifts matter when they change what AI costs to build or run.", "Round size says little about whether the design wins.", "Hardware alone does not make a new design better."], "explanation": "A 2017 paper changed which models won. Watch for the next design that changes what AI costs."}, "proReasoning": "Investors watch for architecture shifts that change costs. Speed matters if quality holds.", "commonMistake": "Judging a new design by who funded it rather than what it changes.", "mentalModel": "Watch designs that change the cost."}, "build_startup": {"call": {"kind": "theCall", "situation": "You run a coding tool. Users complain about waiting for long completions.", "prompt": "What's a sound move?", "options": ["Rebuild the product around image networks", "Test a parallel model where speed matters most", "Assume only one-token-at-a-time models work"], "correctIndex": 1, "consequences": ["Image networks do not write code.", "If quality holds, faster generation fixes your users' pain.", "Diffusion models already write code at over 1,000 tokens per second."], "explanation": "The design shapes speed and cost. Test new designs where they address your users' biggest pain."}, "proReasoning": "Founders test new architectures against a real user pain, here waiting time, before switching.", "commonMistake": "Ignoring a design shift because the current one is familiar.", "mentalModel": "Test the design against the pain."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend asks why a chatbot's answer appears word by word.", "prompt": "What's the explanation?", "options": ["The app slows it down just for effect", "Your internet sends one word at a time", "Most models write one token at a time"], "correctIndex": 2, "consequences": ["The words appear as the model produces them.", "The network is not the reason; the model is.", "Each word is predicted after the one before, so it streams in."], "explanation": "Autoregressive models predict in order. Diffusion models try to write the whole answer at once."}, "proReasoning": "Watch how a tool behaves and ask what design causes it. Word by word means writing in order.", "commonMistake": "Assuming the typing effect is just decoration.", "mentalModel": "Behavior hints at the design."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:812cba06af95$ml$]::text[]),
($ml$27678f05-a702-507a-b7f2-94b5d6cc206d$ml$::uuid, $ml$ai$ml$, 7, 2, $ml${"id": "ai-d7-c2", "title": "From two GPUs to a chokepoint", "lessonTitle": "Three designs behind modern AI", "slot": 2, "type": "connect", "brief": {"headline": "In 2012, the network that won a top image contest trained on two GPUs for five to six days. In fiscal 2026, NVIDIA's data center chips brought in $193.7 billion.", "kicker": "Connect day 3 and day 7: parallel designs made GPUs the scarce input.", "fullText": "On day 7 you met the 2012 breakthrough: a convolutional network with 60 million parameters, trained on two GTX 580 GPUs, won with a 15.3% error rate against 26.2% for the runner-up. Then came the 2017 Transformer, which dropped recurrence so it could process a sequence in parallel. Parallel work suits GPUs.\n\nOn day 3 you saw who holds power in AI: whoever controls the scarcest input. Each design that ran better in parallel made those chips more valuable. By fiscal 2026, NVIDIA's data center business brought in $193.7 billion, at gross margins above 70%.", "sources": [{"url": "https://courses.cs.duke.edu/fall16/compsci527/papers/Krizhevsky%20et%20al%20DNN%20ImageNet%202012.pdf", "label": "Krizhevsky, Sutskever and Hinton, ImageNet classification with deep CNNs, 2012"}, {"url": "https://en.wikipedia.org/wiki/Attention_Is_All_You_Need", "label": "Attention Is All You Need, 2017"}, {"url": "https://www.sec.gov/Archives/edgar/data/1045810/000104581026000019/q4fy26pr.htm", "label": "NVIDIA fiscal 2026 results"}]}, "evidence": {"kind": "buildChain", "prompt": "Follow how parallel designs fed the chip boom.", "steps": ["2012: a CNN wins the image contest on two GPUs", "2017: the Transformer drops recurrence", "Models process whole sequences in parallel", "Parallel work suits GPUs, so demand soars", "NVIDIA's data centers bring in $193.7 billion"], "explanation": "Designs that run in parallel scale on GPUs. That turned GPUs into the scarce input."}, "numbers": {"kind": "numberSense", "prompt": "About how many million parameters did the 2012 winning network have?", "min": 0, "max": 200, "value": 60, "unit": "M", "explanation": "About 60 million, trained on two GPUs. Frontier models today use vastly more compute."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "You're interviewing at a chip company. They ask why AI demand favors GPUs.", "prompt": "What's the sharpest answer?", "options": ["Its designs run in parallel, which suits GPUs", "GPUs are cheaper than any other kind of chip", "AI models need to draw graphics on screen"], "correctIndex": 0, "consequences": ["That link between design and hardware is what they want to hear.", "Margins above 70% say GPUs are not cheap.", "The graphics origin matters less than the parallel math."], "explanation": "The Transformer runs in parallel, and parallel work suits GPUs. Demand followed."}, "proReasoning": "Connect the architecture to the hardware. It shows you see why one chip became the chokepoint.", "commonMistake": "Explaining GPU demand by price or graphics rather than by parallel design.", "mentalModel": "Design decides the chip."}, "invest": {"call": {"kind": "theCall", "situation": "You hold shares in a GPU maker and follow AI research news.", "prompt": "What kind of news should you watch most?", "options": ["A new nickname for the Transformer", "Designs that need less parallel compute", "Another record on an old image contest"], "correctIndex": 1, "consequences": ["Names do not change what chips a model needs.", "A shift in design could change which chips are scarce.", "Old benchmarks say little about chip demand now."], "explanation": "Parallel designs made GPUs the chokepoint. A design shift is what could change that."}, "proReasoning": "Investors in a chokepoint ask what could end the scarcity. An architecture shift is one answer.", "commonMistake": "Assuming today's design will last forever.", "mentalModel": "Watch what could end the scarcity."}, "build_startup": {"call": {"kind": "theCall", "situation": "Your model could be an RNN or a Transformer. You rent GPUs by the hour.", "prompt": "Which suits your hardware better?", "options": ["The RNN, which reads one step at a time", "Either, since design does not affect the bill", "The Transformer, which runs in parallel"], "correctIndex": 2, "consequences": ["RNNs are hard to run in parallel, so GPU hours stretch.", "Your architecture shapes your compute costs.", "Parallel work keeps rented GPUs busy and training fast."], "explanation": "Transformers process sequences in parallel, which suits GPUs. That shapes your bill."}, "proReasoning": "Founders pick designs that match the hardware they pay for. Idle parallel chips are wasted money.", "commonMistake": "Choosing an architecture without thinking about the hardware bill.", "mentalModel": "Match the design to the chip."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend asks why a graphics chip company ended up at the center of AI.", "prompt": "What's the best answer?", "options": ["AI's parallel math suits its chips", "Chatbots draw a picture for every answer", "It owns the AI models people use"], "correctIndex": 0, "consequences": ["The 2012 breakthrough already trained on two GPUs.", "Most AI answers are text, not pictures.", "Its $193.7 billion came from data center chips."], "explanation": "GPUs do parallel work well, and modern AI designs are built to run in parallel."}, "proReasoning": "A tool built for one job can win another if the math matches. GPUs fit AI's parallel math.", "commonMistake": "Thinking AI chips had to be invented from scratch.", "mentalModel": "Same math, new market."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:ffbd9185a7a2$ml$]::text[]),
($ml$9347749c-6748-5422-b08a-b9e29bf659d3$ml$::uuid, $ml$ai$ml$, 7, 3, $ml${"id": "ai-d7-c3", "title": "Reading long contracts", "lessonTitle": "Three designs behind modern AI", "slot": 3, "type": "decide", "brief": {"headline": "You run a small team building a tool that reads long contracts. You must pick a design: a recurrent network that reads one step at a time, or a Transformer built on attention.", "kicker": "Decide which design fits long documents on rented GPUs.", "fullText": "Recurrent networks, or RNNs, read a sequence one step at a time, so they are hard to run in parallel. In 2017, Google researchers introduced the Transformer, built on attention. It dropped recurrence so it could process a whole sequence in parallel.\n\nConvolutional networks powered the 2012 image breakthrough: a CNN won with a 15.3% error rate against 26.2% for the runner-up, after five to six days of training on two GPUs. In deep learning, designs that run in parallel are the ones that scale.", "sources": [{"url": "https://en.wikipedia.org/wiki/Attention_Is_All_You_Need", "label": "Attention Is All You Need, 2017"}, {"url": "https://courses.cs.duke.edu/fall16/compsci527/papers/Krizhevsky%20et%20al%20DNN%20ImageNet%202012.pdf", "label": "Krizhevsky, Sutskever and Hinton, ImageNet classification with deep CNNs, 2012"}]}, "evidence": {"kind": "faceOff", "prompt": "For reading long documents fast on GPUs, which design fits better?", "left": {"name": "Recurrent network (RNN)", "note": "Reads one step at a time"}, "right": {"name": "Transformer", "note": "Built on attention, runs in parallel"}, "correctIndex": 1, "explanation": "The Transformer processes a sequence in parallel, which suits GPUs. RNNs are hard to parallelize."}, "numbers": {"kind": "numberSense", "prompt": "The 2012 CNN had a 15.3% error rate; the runner-up had 26.2%. How many points better was it?", "min": 0, "max": 30, "value": 10.9, "unit": "points", "explanation": "About 10.9 points, a huge margin. A design shift can open a gap that size."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "You're interviewing to join the team. They ask which design you'd pick and why.", "prompt": "What's your answer?", "options": ["CNN, since it won the 2012 image contest", "Transformer, since it processes text in parallel", "RNN, since reading in order is always better"], "correctIndex": 1, "consequences": ["The 2012 win was for images, not contracts.", "Parallel processing suits GPUs and long documents.", "Reading in order is what makes RNNs slow to train."], "explanation": "Pick the design and give the reason. Parallel processing is why Transformers scale."}, "proReasoning": "Name the architecture and the trade it makes. Interviewers want the why, not just the name.", "commonMistake": "Picking a design for its fame rather than its fit.", "mentalModel": "Name it, then say why it fits."}, "invest": {"call": {"kind": "theCall", "situation": "Two contract-reading startups pitch you. One is built on RNNs, the other on Transformers.", "prompt": "Which design should scale better?", "options": ["The RNN, since older designs are safer", "Neither, since design does not affect costs", "The Transformer, which runs in parallel"], "correctIndex": 2, "consequences": ["Older is not safer when it cannot use the hardware well.", "The design shapes how much compute each document needs.", "Parallel designs are the ones that scale on GPUs."], "explanation": "Designs that run in parallel are the ones that scale. That shows up in cost and speed."}, "proReasoning": "Investors ask what a product runs on, because the design shapes the cost curve.", "commonMistake": "Treating the architecture as a detail for engineers.", "mentalModel": "The design shapes the cost curve."}, "build_startup": {"call": {"kind": "theCall", "situation": "Your contracts run hundreds of pages, and you rent GPUs by the hour.", "prompt": "How do you choose?", "options": ["Pick the design that uses GPUs in parallel", "Pick the design that reads strictly in order", "Pick the design built for photos"], "correctIndex": 0, "consequences": ["That keeps your rented GPUs busy and your bill down.", "Sequential reading wastes the parallel hardware you pay for.", "CNNs suited images; your input is text."], "explanation": "Your architecture choice shapes your compute bill. Parallel designs suit GPUs."}, "proReasoning": "Founders choose the design that fits both the data and the hardware bill.", "commonMistake": "Choosing by habit instead of by fit.", "mentalModel": "Fit the data and the bill."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend asks what a \"Transformer\" is in AI.", "prompt": "What's the best short answer?", "options": ["A program that converts file types", "A 2017 design built on attention", "A robot that changes its shape"], "correctIndex": 1, "consequences": ["It is a neural network design, not a file tool.", "Google researchers introduced it, and it runs in parallel.", "That is the toy, not the AI design."], "explanation": "The Transformer is the design behind most modern language models. It reads a whole sequence in parallel."}, "proReasoning": "Explain a design by what it does differently. Transformers read in parallel; RNNs read in order.", "commonMistake": "Getting lost in the name instead of the idea.", "mentalModel": "Explain what it does differently."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:d152bb5695c8$ml$]::text[]),
($ml$ffa6e084-e4f0-5fa1-8137-6d5c732e232f$ml$::uuid, $ml$ai$ml$, 8, 1, $ml${"id": "ai-d8-c1", "title": "The $5.6 million headline", "lessonTitle": "From $900 to $191 million", "slot": 1, "type": "apply", "brief": {"headline": "In December 2024, DeepSeek said its V3 model's training used 2.788 million H800 GPU hours, about $5.6 million. On January 27, 2025, NVIDIA lost over $589 billion in market value in one day.", "kicker": "Apply day 8: what does a training cost figure actually cover?", "fullText": "DeepSeek-V3 has 671 billion parameters, with 37 billion active for each token, and trained on 14.8 trillion tokens on 2,048 H800 GPUs. Its paper priced the run at $5.576 million, assuming $2 per GPU hour. It said the figure covered only the official training, excluding prior research and ablation experiments on architectures, algorithms and data.\n\nAs DeepSeek's models drew attention, NVIDIA's stock fell about 17% on January 27, 2025, wiping out more than $589 billion of market value, the largest one-day loss for any company. Investors wondered whether frontier training had suddenly become cheap.\n\nStanford's estimates, like GPT-4's $78 million, also count training compute. A figure like that is real, but it is not the full cost of building a lab that can produce the model.", "sources": [{"url": "https://ar5iv.labs.arxiv.org/html/2412.19437", "label": "DeepSeek-AI, DeepSeek-V3 technical report, Dec 2024"}, {"url": "https://simonwillison.net/2024/Dec/26/deepseek-v3", "label": "Simon Willison, DeepSeek v3, Dec 2024"}, {"url": "https://www.tomshardware.com/tech-industry/artificial-intelligence/nvidia-loses-usd589-billion-in-market-cap-broad-stock-plunge-triggered-by-deepseek-ai-release", "label": "Tom's Hardware, Nvidia loses $589 billion in market cap, Jan 2025"}, {"url": "https://fortune.com/2024/04/18/google-gemini-cost-191-million-to-train-stanford-university-report-estimates/", "label": "Fortune on the Stanford AI Index training cost estimates, Apr 2024"}]}, "evidence": {"kind": "spotFake", "prompt": "One of these is false about DeepSeek-V3's cost figure. Tap it.", "statements": ["It assumed $2 for each H800 GPU hour.", "It included all prior research and experiments.", "Training ran on 2,048 H800 GPUs."], "fakeIndex": 1, "explanation": "The paper said the figure excluded prior research and ablation experiments. It covered the official training run."}, "numbers": {"kind": "numberSense", "prompt": "Llama 3.1 405B used about 30.8 million GPU hours; DeepSeek-V3 about 2.8 million. Roughly how many times more?", "min": 0, "max": 30, "value": 11, "unit": "x", "explanation": "About 11 times. Efficiency was real, even if the headline cost left a lot out."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "You're asked in an interview whether DeepSeek proved frontier AI is now cheap to build.", "prompt": "What's the best answer?", "options": ["It cut run costs, but the figure omits research", "Yes, any lab can now train one for $6 million", "No, the number was simply invented by DeepSeek"], "correctIndex": 0, "consequences": ["That separates a real efficiency gain from the full bill.", "The paper itself said prior research was excluded.", "The paper detailed its GPU hours; the question is scope."], "explanation": "Know what a cost estimate counts. A final run is not the whole cost of a frontier model."}, "proReasoning": "Quote the number and its scope. \"About $5.6 million for the final run, excluding research\" shows care.", "commonMistake": "Repeating a headline cost without asking what it covers.", "mentalModel": "Every cost figure has a scope."}, "invest": {"call": {"kind": "theCall", "situation": "NVIDIA falls 17% in a day on fears that frontier training just got cheap.", "prompt": "What's the sound way to read the news?", "options": ["Ignore it, since efficiency never matters", "Check what the cost figure covers first", "Sell all chip stocks, since demand is over"], "correctIndex": 1, "consequences": ["An 11 times efficiency claim is worth understanding.", "The figure excluded research, so the full cost was higher.", "One cost figure does not end demand for compute."], "explanation": "Compute spending drives the market. Before repricing it, check what a cheaper headline really counts."}, "proReasoning": "Investors read the footnote before the headline. Scope can turn a shock into a smaller story.", "commonMistake": "Trading on a cost number without reading what it includes.", "mentalModel": "Read the footnote first."}, "build_startup": {"call": {"kind": "theCall", "situation": "You read DeepSeek's paper and want to train your own frontier model for about $6 million.", "prompt": "How should you budget?", "options": ["Raise $6 million and plan one run", "Assume cheaper chips mean little budget", "Add research and failed runs on top"], "correctIndex": 2, "consequences": ["One run with no experiments before it is not how it was done.", "It still took 2,048 GPUs for about two months.", "The $5.6 million covered only the final, successful run."], "explanation": "Training cost is a barrier at the frontier. Even efficient runs sit on top of research spending."}, "proReasoning": "Founders budget for the experiments that come before the final run. That is where much of the money goes.", "commonMistake": "Budgeting for the headline run alone.", "mentalModel": "Budget for the experiments too."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend says a Chinese startup built a top AI model for only $6 million.", "prompt": "What's the fairer version?", "options": ["That covered its final training run only", "Yes, that was the full cost of everything", "No, it actually cost $6 billion"], "correctIndex": 0, "consequences": ["Research and experiments before the run were left out.", "The paper itself said research costs were excluded.", "No source puts the cost at $6 billion."], "explanation": "The number was real but narrow: one training run, priced at rented GPU rates."}, "proReasoning": "When a number sounds too good, ask what it leaves out.", "commonMistake": "Taking a narrow number as the whole story.", "mentalModel": "Ask what the number leaves out."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:8552178cd281$ml$]::text[]),
($ml$00a224e2-d29f-5d2b-b781-e4f2c7e95dee$ml$::uuid, $ml$ai$ml$, 8, 2, $ml${"id": "ai-d8-c2", "title": "When compounding meets a budget", "lessonTitle": "From $900 to $191 million", "slot": 2, "type": "connect", "brief": {"headline": "The original 2017 Transformer cost about $900 to train. GPT-4 cost an estimated $78 million, and Gemini Ultra about $191 million, as training compute grew 4 to 5 times a year.", "kicker": "Connect day 4 and day 8: a compounding curve becomes a price tag.", "fullText": "On day 4 you saw training compute for frontier models grow 4 to 5 times every year, doubling roughly every five months. On day 8 you saw what that means in dollars: about $900 for the original Transformer in 2017, an estimated $78 million for GPT-4, and $191 million worth of compute for Gemini Ultra.\n\nA cost that multiplies each year becomes a barrier to entry. Only a few firms can keep paying for the next step.", "sources": [{"url": "https://epoch.ai/blog/training-compute-of-frontier-ai-models-grows-by-4-5x-per-year", "label": "Epoch AI, training compute growth"}, {"url": "https://fortune.com/2024/04/18/google-gemini-cost-191-million-to-train-stanford-university-report-estimates/", "label": "Fortune on the Stanford AI Index training cost estimates, Apr 2024"}]}, "evidence": {"kind": "multipleChoice", "prompt": "A $100 million frontier run uses compute that grows 4 times a year. At the same price, what might next year's run cost?", "options": ["About $400 million", "About $104 million", "About $200 million"], "correctIndex": 0, "explanation": "Four times the compute at the same price is four times the bill. That is how $900 became $191 million."}, "numbers": {"kind": "numberSense", "prompt": "From about $900 to about $191 million: roughly how many times more, in thousands?", "min": 0, "max": 500, "value": 212, "unit": "K", "explanation": "About 212,000 times more in roughly six years. Compounding turned a hobby budget into nine figures."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "An interviewer asks why only a few firms train frontier models.", "prompt": "What's the best answer?", "options": ["Governments limit who may train them", "Costs multiply yearly, into nine figures", "The ideas are secret and locked away"], "correctIndex": 1, "consequences": ["Cost, not permission, is the main barrier.", "GPT-4 alone used an estimated $78 million of compute.", "The Transformer paper was published openly."], "explanation": "Training cost has become a barrier to entry at the frontier."}, "proReasoning": "Explain market structure with cost. \"$78 million for GPT-4\" explains why the frontier has few players.", "commonMistake": "Blaming secrecy when the barrier is money.", "mentalModel": "Cost shapes who can compete."}, "invest": {"call": {"kind": "theCall", "situation": "Training costs rose from about $900 to an estimated $191 million.", "prompt": "Where does most of that money land?", "options": ["With the authors of research papers", "With the apps built on top", "With chip and cloud providers"], "correctIndex": 2, "consequences": ["Papers are free to read; authors are not paid per run.", "Apps pay model makers; training money flows down, not up.", "Training budgets pay for compute, which means chips and cloud."], "explanation": "Most training spending flows to chips and cloud. That is why compute suppliers grew so fast."}, "proReasoning": "Investors follow training budgets to whoever supplies compute. Rising costs are their revenue.", "commonMistake": "Thinking training spending enriches the model makers directly.", "mentalModel": "Training money flows to compute."}, "build_startup": {"call": {"kind": "theCall", "situation": "You want to build an AI product, and frontier training costs nine figures.", "prompt": "Where do you compete?", "options": ["On top of a model someone else trained", "By training your own frontier model first", "By waiting for training to cost $900 again"], "correctIndex": 0, "consequences": ["Someone else already paid for the training.", "You would need tens of millions before your first user.", "Frontier costs are rising, not falling back."], "explanation": "Many openings sit on top of models others already paid to train."}, "proReasoning": "Founders build where the expensive part is already paid for.", "commonMistake": "Trying to cross a nine-figure barrier on a seed budget.", "mentalModel": "Build where training is paid for."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend asks why AI training got so expensive so fast.", "prompt": "What's the main reason?", "options": ["Engineers kept raising their salaries", "The compute used grew 4 to 5 times a year", "Chip prices rose about 200,000-fold"], "correctIndex": 1, "consequences": ["These estimates count compute, not salaries.", "More compute each year, compounded, became a huge bill.", "The growth came from using far more compute, not pricier chips."], "explanation": "Compounding growth in compute turned $900 into $191 million in a few years."}, "proReasoning": "Big cost jumps often come from compounding volume. Count how much more is used, not just the price.", "commonMistake": "Blaming prices when volume did the work.", "mentalModel": "Volume compounds into cost."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:d827d773a466$ml$]::text[]),
($ml$239db8bb-31fa-5545-932e-bd34888c0fae$ml$::uuid, $ml$ai$ml$, 8, 3, $ml${"id": "ai-d8-c3", "title": "A $20 million rival to GPT-4", "lessonTitle": "From $900 to $191 million", "slot": 3, "type": "decide", "brief": {"headline": "You run a small venture fund. A team asks for $20 million to train a model from scratch to rival GPT-4.", "kicker": "Decide whether the budget fits the frontier.", "fullText": "Stanford's 2024 AI Index estimated the compute cost of training major models. The original 2017 Transformer cost about $900. GPT-4 cost an estimated $78 million, and Gemini Ultra about $191 million worth of compute.\n\nThese estimates count only the compute used to train a model. In AI, training cost has become a barrier to entry at the frontier, and many openings sit on top of models someone else already trained.", "sources": [{"url": "https://fortune.com/2024/04/18/google-gemini-cost-191-million-to-train-stanford-university-report-estimates/", "label": "Fortune on the Stanford AI Index training cost estimates, Apr 2024"}]}, "evidence": {"kind": "sortSignal", "prompt": "Does $20 million cover each one?", "buckets": ["Fits $20 million", "Doesn't fit"], "items": [{"text": "GPT-4's estimated $78 million of compute", "bucket": 1}, {"text": "Gemini Ultra's $191 million of compute", "bucket": 1}, {"text": "Training the 2017 Transformer, about $900", "bucket": 0}, {"text": "A narrow product built on an existing model", "bucket": 0}], "explanation": "The frontier runs cost several times the budget. A narrow product on an existing model fits easily."}, "numbers": {"kind": "numberSense", "prompt": "$20 million covers about what share of GPT-4's estimated $78 million compute bill?", "min": 0, "max": 100, "value": 26, "unit": "%", "explanation": "About a quarter, and that is compute alone, before staff or experiments."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "The team's lead asks you to join as its first machine learning engineer.", "prompt": "What do you check first?", "options": ["Whether the office has its own GPUs", "Whether the model has a catchy name", "Whether $20 million can cover the compute"], "correctIndex": 2, "consequences": ["Owning a few GPUs is not frontier-scale compute.", "Names do not train models.", "GPT-4 alone used an estimated $78 million of compute."], "explanation": "Know what a model costs before betting your career on building one."}, "proReasoning": "Before joining, check that the plan can be paid for. Compute is the first line to test.", "commonMistake": "Joining on ambition without checking the math.", "mentalModel": "Check the compute math first."}, "invest": {"call": {"kind": "theCall", "situation": "You are deciding on the $20 million request.", "prompt": "What's the key gap in the plan?", "options": ["GPT-4's compute alone cost about $78 million", "Their team is far too small to matter", "None, since $20 million is plenty for it"], "correctIndex": 0, "consequences": ["The budget covers about a quarter of that.", "Team size matters less than the compute bill.", "It covers about a quarter of the compute."], "explanation": "Compute spending sets the bar. A frontier rival needs several times this budget."}, "proReasoning": "Investors compare the ask with what the goal costs. A frontier model on a fraction of the bill is a red flag.", "commonMistake": "Funding an ambition that the budget cannot reach.", "mentalModel": "Compare the ask with the bill."}, "build_startup": {"call": {"kind": "theCall", "situation": "You're the founder. The fund says $20 million won't train a GPT-4 rival.", "prompt": "What's your best next move?", "options": ["Ask for $20 million more and try anyway", "Build a narrow product on an existing model", "Train a smaller copy and call it a rival"], "correctIndex": 1, "consequences": ["At $40 million you would still be far short.", "Someone else already paid for the expensive training.", "Calling it a rival does not make it one."], "explanation": "Build where training is already paid for. Compete on the use, not the base model."}, "proReasoning": "Founders turn a cost barrier into a choice of where to compete. The use case is open; the frontier is not.", "commonMistake": "Doubling down on a race the budget cannot win.", "mentalModel": "Compete on the use, not the base."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend asks why more startups don't build their own ChatGPT.", "prompt": "What's the main reason?", "options": ["The code is illegal for startups to write", "Only big companies are allowed to use GPUs", "Training one costs tens of millions or more"], "correctIndex": 2, "consequences": ["The methods are published openly.", "Anyone can rent GPUs; the volume is what costs.", "GPT-4 cost an estimated $78 million in compute."], "explanation": "The barrier is the compute bill, which runs to tens or hundreds of millions."}, "proReasoning": "When few players compete, look at the entry cost. In frontier AI, it is compute.", "commonMistake": "Assuming the barrier is secret knowledge.", "mentalModel": "Look at the entry cost."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:e21c9ffb2339$ml$]::text[]),
($ml$6aef4336-dbae-5e6d-8d2b-0d68e2eb9277$ml$::uuid, $ml$ai$ml$, 9, 1, $ml${"id": "ai-d9-c1", "title": "The $2.7 billion rehire", "lessonTitle": "Inventors versus shippers", "slot": 1, "type": "apply", "brief": {"headline": "Noam Shazeer co-wrote the 2017 Transformer paper and left Google in 2021. In 2024, Google reportedly paid $2.7 billion to bring him back. In June 2026, he left again, for OpenAI.", "kicker": "Apply day 9: ideas travel with the people who have them.", "fullText": "Shazeer joined Google in 2000. He left in 2021 after Google declined to release a chatbot he had built, and co-founded Character.AI, serving as its CEO.\n\nIn August 2024, Google struck a licensing deal with Character.AI that brought Shazeer and several key researchers back. The Wall Street Journal reported Google paid about $2.7 billion. He became a vice president of engineering and co-lead of Gemini.\n\nOn June 17, 2026, Shazeer said he was leaving Google to join OpenAI, the maker of ChatGPT. Google told Reuters it was grateful for his contributions.\n\nThe day 9 pattern played out twice. The people carry the ideas, and companies that ship keep pulling them in.", "sources": [{"url": "https://analyticsindiamag.com/ai-news/openai-poaches-transformer-pioneer-noam-shazeer-from-google", "label": "Analytics India Magazine, OpenAI hires Noam Shazeer from Google, Jun 2026"}, {"url": "https://www.pymnts.com/artificial-intelligence-2/2024/google-reportedly-spent-2-7-billion-to-rehire-character-ai-founder/", "label": "PYMNTS, Google reportedly spent $2.7 billion to rehire Character.AI founder, Sep 2024"}, {"url": "https://www.thestar.com.my/tech/tech-news/2026/06/18/google-gemini-co-lead-noam-shazeer-to-join-ipo-bound-openai", "label": "Reuters via The Star, Gemini co-lead Noam Shazeer to join OpenAI, Jun 2026"}, {"url": "https://9to5google.com/2026/06/17/geminis-co-lead-is-leaving-google-to-join-openai/", "label": "9to5Google, Gemini's co-lead is leaving Google to join OpenAI, Jun 2026"}, {"url": "https://en.wikipedia.org/wiki/Attention_Is_All_You_Need", "label": "Attention Is All You Need, 2017"}]}, "evidence": {"kind": "buildChain", "prompt": "Put Shazeer's moves in order.", "steps": ["Co-writes the Transformer paper at Google", "Leaves after Google holds back his chatbot", "Co-founds Character.AI", "Google pays about $2.7 billion to bring him back", "Leaves Google again to join OpenAI"], "explanation": "An inventor left, was bought back, and left again. Each move followed where ideas could ship."}, "numbers": {"kind": "numberSense", "prompt": "Google reportedly paid about how many billion dollars in the 2024 deal?", "min": 0, "max": 10, "value": 2.7, "unit": "B", "explanation": "About $2.7 billion, largely to bring back one researcher and his team."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "You're choosing between two AI labs. One keeps losing senior researchers to rivals.", "prompt": "What does that tell you?", "options": ["It's stronger, since rivals want its people", "Power may be shifting to where they go", "Nothing, since people leave every company"], "correctIndex": 1, "consequences": ["Losing people is a cost, even if it flatters the lab.", "In AI, where talent goes, power tends to follow.", "A pattern of senior exits is a signal, not noise."], "explanation": "Ask which teams people leave to join, and why. It shows where the work that matters is happening."}, "proReasoning": "Track where senior people go. In AI, the flow of talent is an early map of power.", "commonMistake": "Treating departures as random churn.", "mentalModel": "Follow the talent."}, "invest": {"call": {"kind": "theCall", "situation": "Google paid about $2.7 billion to rehire one researcher. Under two years later he left for a rival.", "prompt": "What's the investor lesson?", "options": ["Licensing deals lock talent in for good", "Researchers matter less than chips do", "Key talent is an asset that can walk out"], "correctIndex": 2, "consequences": ["He left within two years of the deal.", "Google paid billions for a person, not a chip.", "A big payment bought time, not permanence."], "explanation": "In AI, value sits partly in people. They can leave, and they take know-how with them."}, "proReasoning": "Investors count people as a risk on the balance sheet. Paying for talent does not keep it.", "commonMistake": "Assuming a deal locks in the people it was made for.", "mentalModel": "People can walk; price that in."}, "build_startup": {"call": {"kind": "theCall", "situation": "Shazeer left when Google held back his chatbot. You see a big lab sitting on a useful idea.", "prompt": "What's the founder's move?", "options": ["Ship a product users can try now", "Wait until the lab releases it", "Publish a paper about the idea"], "correctIndex": 0, "consequences": ["Users waiting on a slow incumbent are your opening.", "The lab may never release it, and users keep waiting.", "A paper spreads the idea; it does not reach users."], "explanation": "Big labs can sit on breakthroughs. Users who want them feel that delay, and that is an opening."}, "proReasoning": "Founders look for ideas big companies hold back. Shipping first is the advantage.", "commonMistake": "Assuming the incumbent will always ship its best ideas.", "mentalModel": "Ship what others hold back."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend asks why Google would pay billions to rehire someone who used to work there.", "prompt": "What's the best explanation?", "options": ["Google buys every startup it sees", "His know-how left with him", "It was a fine for quitting"], "correctIndex": 1, "consequences": ["Google chose this deal to rehire specific people.", "Ideas travel with the people who have them.", "Nobody fines people for leaving; Google paid to get him back."], "explanation": "A company can keep the paper, but the expertise walks out the door with the person."}, "proReasoning": "In research-heavy fields, people are the product. Companies pay to get them back.", "commonMistake": "Thinking a company owns everything its people know.", "mentalModel": "Know-how walks with people."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:6172fa76eb94$ml$]::text[]),
($ml$097b3fb3-10df-52c6-bc86-62bdf01635da$ml$::uuid, $ml$ai$ml$, 9, 2, $ml${"id": "ai-d9-c2", "title": "Invented here, shipped there", "lessonTitle": "Inventors versus shippers", "slot": 2, "type": "connect", "brief": {"headline": "Google researchers introduced the Transformer in 2017, and all eight authors later left Google. OpenAI's ChatGPT, built on its GPT Transformers, reached about 100 million monthly users two months after launch.", "kicker": "Connect day 7 and day 9: the design spread; a shipper won the users.", "fullText": "On day 7 you met the Transformer: a 2017 design built on attention that dropped recurrence so it could process sequences in parallel. On day 9 you saw what happened to it. The paper, Attention Is All You Need, has been cited more than 250,000 times, and all eight authors left Google to join other companies or found startups.\n\nThe idea was published openly, so anyone could build on it. OpenAI's GPT series of Transformers became state of the art in generating text, and ChatGPT reached about 100 million monthly users in January 2023, two months after launch. The inventor did not capture the first wave of users. The shipper did.", "sources": [{"url": "https://en.wikipedia.org/wiki/Attention_Is_All_You_Need", "label": "Attention Is All You Need, 2017"}, {"url": "https://business.inquirer.net/384799/chatgpt-sets-record-for-fastest-growing-user-base-analyst-note", "label": "UBS via Reuters/Inquirer, ChatGPT sets user growth record, Feb 2023"}]}, "evidence": {"kind": "sortSignal", "prompt": "Inventor or shipper: which company does each describe?", "buckets": ["Google", "OpenAI"], "items": [{"text": "Published Attention Is All You Need", "bucket": 0}, {"text": "Saw all eight authors leave", "bucket": 0}, {"text": "Built the GPT series of Transformers", "bucket": 1}, {"text": "Launched ChatGPT in late 2022", "bucket": 1}, {"text": "Reached 100 million users in two months", "bucket": 1}], "explanation": "Google invented and published. OpenAI built on the open idea and shipped it to users."}, "numbers": {"kind": "numberSense", "prompt": "The Transformer paper has been cited more than how many thousand times?", "min": 0, "max": 600, "value": 250, "unit": "K", "explanation": "More than 250,000 times. An open idea spreads widely, and anyone can build on it."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "In an interview, you are asked who benefited most from the Transformer at first.", "prompt": "What's the best answer?", "options": ["Only Google, which owned the idea", "Nobody, since the paper was free to read", "Those who shipped products on it, like OpenAI"], "correctIndex": 2, "consequences": ["Google published it openly, and its authors left.", "Free ideas still create value for whoever ships them.", "ChatGPT reached 100 million users while the inventor waited."], "explanation": "Invention spreads. Value goes to whoever turns it into a product people use."}, "proReasoning": "Separate who invented from who captured value. Interviewers like candidates who see the gap.", "commonMistake": "Assuming the inventor always wins.", "mentalModel": "Invention spreads; shipping captures."}, "invest": {"call": {"kind": "theCall", "situation": "One AI company publishes top papers. Another has 100 million users.", "prompt": "Which edge is harder to copy?", "options": ["The user base, since papers are public", "The papers, since ideas cannot be copied", "Neither, since both are easy to copy"], "correctIndex": 0, "consequences": ["Anyone can read a paper; users must be won one by one.", "Published ideas are the easiest thing to copy.", "Reaching 100 million users took a shipped product."], "explanation": "Distribution beats invention. Watch who reaches users."}, "proReasoning": "Investors ask which advantage a rival cannot simply read. Users are harder to copy than ideas.", "commonMistake": "Valuing research output over reach.", "mentalModel": "Distribution beats invention."}, "build_startup": {"call": {"kind": "theCall", "situation": "A big lab publishes a powerful new method openly.", "prompt": "What's your move as a founder?", "options": ["Ignore it, since published ideas lose value", "Build a product on it before the lab does", "Wait for the lab to ship it first"], "correctIndex": 1, "consequences": ["Published ideas are the raw material for products.", "OpenAI did that with the Transformer and won the users.", "The inventor may be slow, as Google was."], "explanation": "Open research is free raw material. The race is to ship it."}, "proReasoning": "Founders read papers as a parts catalog. The win goes to whoever ships first.", "commonMistake": "Waiting for the inventor to move.", "mentalModel": "Papers are parts; ship the product."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend asks why ChatGPT came from OpenAI if Google invented the Transformer.", "prompt": "What's the answer?", "options": ["OpenAI bought the Transformer from Google", "Google gave ChatGPT to OpenAI", "OpenAI built and shipped on the open idea"], "correctIndex": 2, "consequences": ["No purchase was needed; the paper was published.", "Google did not build ChatGPT.", "The paper was public, so anyone could use the idea."], "explanation": "Google published the idea openly. OpenAI built a product on it and reached users first."}, "proReasoning": "Inventing something and selling it are different skills. Often different companies do each.", "commonMistake": "Assuming the inventor and the seller are the same.", "mentalModel": "Inventor and shipper can differ."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:6c3713c5ef31$ml$]::text[]),
($ml$5b5a99a0-8269-5b41-933d-c229f7125729$ml$::uuid, $ml$ai$ml$, 9, 3, $ml${"id": "ai-d9-c3", "title": "Keep the idea, lose the team?", "lessonTitle": "Inventors versus shippers", "slot": 3, "type": "decide", "brief": {"headline": "You lead an AI research group at a large company. Your team has a strong new method, and two senior researchers say they'll leave to start a company if it stays in the lab.", "kicker": "Decide how to keep the value of a breakthrough.", "fullText": "Attention Is All You Need was published on June 12, 2017, by eight Google researchers. It introduced the Transformer and has been cited more than 250,000 times. All eight authors later left Google to join other companies or found startups.\n\nChatGPT reached about 100 million monthly users in January 2023, two months after launch. Ideas published openly travel with the people who had them, and the company that ships to users captures the value.", "sources": [{"url": "https://en.wikipedia.org/wiki/Attention_Is_All_You_Need", "label": "Attention Is All You Need, 2017"}, {"url": "https://business.inquirer.net/384799/chatgpt-sets-record-for-fastest-growing-user-base-analyst-note", "label": "UBS via Reuters/Inquirer, ChatGPT sets user growth record, Feb 2023"}]}, "evidence": {"kind": "faceOff", "prompt": "Who captured the first wave of users from the Transformer idea?", "left": {"name": "Google", "note": "Invented it in 2017"}, "right": {"name": "OpenAI", "note": "Shipped ChatGPT in late 2022"}, "correctIndex": 1, "explanation": "The inventor published. The shipper reached 100 million users in two months."}, "numbers": {"kind": "numberSense", "prompt": "ChatGPT reached about 100 million monthly users how many months after launch?", "min": 0, "max": 12, "value": 2, "unit": "months", "explanation": "About two months. Shipping fast can outrun years of invention."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "You're interviewing to join this research group.", "prompt": "What should you ask its lead?", "options": ["Whether its research ships into products", "How many papers it publishes each year", "How large its office space is"], "correctIndex": 0, "consequences": ["Research that ships keeps people and captures value.", "Papers spread ideas others can ship.", "Space says nothing about where the work goes."], "explanation": "Ask where the work ends up. Groups whose ideas never ship tend to lose their people."}, "proReasoning": "Ask how research reaches users. It predicts whether the team will stay together.", "commonMistake": "Judging a lab only by its paper count.", "mentalModel": "Ask where the work ships."}, "invest": {"call": {"kind": "theCall", "situation": "You own shares in this company and see its researchers leaving for startups.", "prompt": "How do you read it?", "options": ["As good, since fewer staff cost less", "As a warning about who captures value", "As fine, since the papers stay behind"], "correctIndex": 1, "consequences": ["Saving salaries is small next to losing the next product.", "All eight Transformer authors left, and value went elsewhere.", "Papers are public; the know-how leaves."], "explanation": "Where talent goes, power tends to follow. Departures can signal value walking out."}, "proReasoning": "Investors treat a research exodus as a signal about future products, not just costs.", "commonMistake": "Counting departures as savings.", "mentalModel": "An exodus is a signal."}, "build_startup": {"call": {"kind": "theCall", "situation": "You're the group's lead and must decide what to do with the method.", "prompt": "What's your best move?", "options": ["Publish it and hope the team stays", "Keep it secret in the lab for now", "Put it in a product users can try"], "correctIndex": 2, "consequences": ["Publishing hands the idea to everyone, people included.", "A shelved idea is how inventors end up leaving.", "Shipping captures value and gives the team a reason to stay."], "explanation": "Power goes to whoever turns ideas into products and keeps the people."}, "proReasoning": "Leaders who ship keep both the value and the people. Holding back loses both.", "commonMistake": "Treating publication or secrecy as a strategy.", "mentalModel": "Ship it and keep the team."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend asks how a smaller company can beat the one that invented the idea.", "prompt": "What's the answer?", "options": ["It shipped to users first", "It had more patents", "It had bigger offices"], "correctIndex": 0, "consequences": ["ChatGPT reached 100 million users in two months.", "The Transformer was published openly for anyone to use.", "Offices do not win users."], "explanation": "Being first to users can matter more than being first to the idea."}, "proReasoning": "Ask who reached users first. It often explains who won.", "commonMistake": "Assuming the inventor keeps the lead.", "mentalModel": "First to users often wins."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:807b2dcc6f07$ml$]::text[]),
($ml$c2822161-c5c5-565e-84e9-bd1cbba65c94$ml$::uuid, $ml$ai$ml$, 10, 1, $ml${"id": "ai-d10-c1", "title": "Far past twenty to one", "lessonTitle": "Twenty tokens per parameter", "slot": 1, "type": "apply", "brief": {"headline": "Google trained its Gemma 3 27B model on 14 trillion tokens, about 520 tokens per parameter. Chinchilla's compute-optimal ratio is about 20. Google wanted a model that runs on a single GPU.", "kicker": "Apply day 10: why train a small model on so much data?", "fullText": "Gemma 3 came out in March 2025 in four sizes. Its model card lists the training data: 2 trillion tokens for the 1 billion parameter model, 4 trillion for 4B, 12 trillion for 12B and 14 trillion for 27B. Sundar Pichai said the 27B model runs on just one H100 GPU.\n\nChinchilla found that for a fixed training budget, about 20 tokens per parameter gives the best model. Gemma 3 went far past that, to keep the model small enough to run cheaply.\n\nThe day 10 idea still holds: data matters as much as size. A smaller, well-trained model makes a cheaper product possible.", "sources": [{"url": "https://ai.google.dev/gemma/docs/core/model_card_3", "label": "Google, Gemma 3 model card, 2025"}, {"url": "https://www.tipranks.com/news/google-googl-launches-its-gemma-3-ai-model-that-can-run-on-one-chip", "label": "TipRanks, Google launches Gemma 3 that can run on one chip, Mar 2025"}, {"url": "https://download.arxiv.org/pdf/2203.15556.pdf", "label": "Hoffmann et al., Training compute-optimal large language models, 2022"}]}, "evidence": {"kind": "multipleChoice", "prompt": "Gemma 3 27B used about 520 tokens per parameter, far above Chinchilla's 20. What was Google aiming for?", "options": ["A small model that is cheap to run", "The biggest model it could train", "Using as little data as possible"], "correctIndex": 0, "explanation": "More data made a small model stronger. Small enough to run on one GPU means cheaper answers."}, "numbers": {"kind": "numberSense", "prompt": "Gemma 3's 1B model trained on 2 trillion tokens. How many thousand tokens per parameter is that?", "min": 0, "max": 5, "value": 2, "unit": "K", "explanation": "About 2,000 tokens per parameter, a hundred times the Chinchilla ratio."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "You're interviewing on a model team. They ask why anyone trains a small model far past 20 tokens per parameter.", "prompt": "What's your answer?", "options": ["Chinchilla said more data is always optimal", "Small models cannot use less data", "It makes the model cheaper to run at scale"], "correctIndex": 2, "consequences": ["Chinchilla found 20 to 1 optimal for a fixed training budget.", "They can; the choice is about running costs.", "A small, strong model saves on every answer it serves."], "explanation": "Chinchilla optimizes the training budget. Builders who serve a model a lot may push data further."}, "proReasoning": "Quote the 20 to 1 ratio, then say when you would break it. That shows you know the trade.", "commonMistake": "Treating 20 to 1 as a law rather than a training-budget rule.", "mentalModel": "Know the rule, and when to break it."}, "invest": {"call": {"kind": "theCall", "situation": "A company says its small model, trained on 100 times the Chinchilla ratio, runs on one GPU.", "prompt": "Why might that matter for its margins?", "options": ["Each answer is cheaper to serve", "It needed no training compute at all", "It removes the need for any data"], "correctIndex": 0, "consequences": ["Smaller models cost less to run, answer after answer.", "Training on that much data takes plenty of compute.", "It used far more data, not less."], "explanation": "Smaller, well-trained models make cheaper products possible. That shows up in serving costs."}, "proReasoning": "Investors look at model size as a running cost. A small model that performs well can widen margins.", "commonMistake": "Assuming bigger models are always the better business.", "mentalModel": "Small and well trained can mean margin."}, "build_startup": {"call": {"kind": "theCall", "situation": "Your product needs a model that runs on customers' laptops.", "prompt": "What kind of model do you want?", "options": ["A small model trained on little data", "A small model trained on lots of data", "The largest model you can afford"], "correctIndex": 1, "consequences": ["Little data makes a small model weak.", "That is the Gemma 3 recipe: small enough to run, strong from data.", "A huge model will not fit on a laptop."], "explanation": "Data matters as much as size. A small model needs plenty of it to be good."}, "proReasoning": "Founders pick the size the product can run, then make it strong with data.", "commonMistake": "Picking size first and data as an afterthought.", "mentalModel": "Fix the size, then add data."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend asks how a model small enough for one chip can still be good.", "prompt": "What's the answer?", "options": ["It looks up answers from a bigger model", "Its chip is a hundred times faster", "It was trained on huge amounts of data"], "correctIndex": 2, "consequences": ["It runs on its own once trained.", "It runs on a standard H100, not a special chip.", "Gemma 3 27B saw 14 trillion tokens in training."], "explanation": "Size is not everything. A smaller model trained on more data can do well."}, "proReasoning": "A model is size plus training data. Lots of data can make up for a small size.", "commonMistake": "Judging a model by parameter count alone.", "mentalModel": "Size plus data, not size alone."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:6a318beaf9bb$ml$]::text[]),
($ml$e17c9a48-e467-5f9f-a2e2-c8d918d69562$ml$::uuid, $ml$ai$ml$, 10, 2, $ml${"id": "ai-d10-c2", "title": "Same budget, better model", "lessonTitle": "Twenty tokens per parameter", "slot": 2, "type": "connect", "brief": {"headline": "Chinchilla used the same compute as Gopher, a model four times its size, and beat it. When a training run costs tens of millions, how you split the budget matters as much as its size.", "kicker": "Connect day 8 and day 10: how you spend the training budget counts.", "fullText": "On day 8 you saw training costs climb from about $900 for the 2017 Transformer to an estimated $78 million for GPT-4. On day 10 you met DeepMind's Chinchilla: 70 billion parameters trained on 1.4 trillion tokens, about 20 tokens per parameter.\n\nChinchilla used the same compute as the 280-billion-parameter Gopher and outperformed it, along with GPT-3, which had 175 billion parameters trained on 300 billion tokens.\n\nWhen compute costs tens of millions, the split between model size and data decides what you get for the money.", "sources": [{"url": "https://fortune.com/2024/04/18/google-gemini-cost-191-million-to-train-stanford-university-report-estimates/", "label": "Fortune on the Stanford AI Index training cost estimates, Apr 2024"}, {"url": "https://download.arxiv.org/pdf/2203.15556.pdf", "label": "Hoffmann et al., Training compute-optimal large language models, 2022"}, {"url": "https://ar5iv.labs.arxiv.org/html/2005.14165", "label": "Brown et al., Language models are few-shot learners, 2020"}]}, "evidence": {"kind": "faceOff", "prompt": "Same compute budget. Which model performed better?", "left": {"name": "Gopher", "note": "280 billion parameters"}, "right": {"name": "Chinchilla", "note": "70 billion parameters, 1.4 trillion tokens"}, "correctIndex": 1, "explanation": "Chinchilla spent the same compute on a smaller model and far more data, and won."}, "numbers": {"kind": "numberSense", "prompt": "GPT-3 had 175 billion parameters and trained on 300 billion tokens. About how many tokens per parameter?", "min": 0, "max": 10, "value": 1.7, "unit": "tokens", "explanation": "About 1.7, far below Chinchilla's 20. GPT-3 was big for its data."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "You're asked in an interview how you'd spend a fixed training budget.", "prompt": "What's your answer?", "options": ["Balance size and data, about 20 to 1", "Make the model as big as the budget allows", "Use the least data possible to save money"], "correctIndex": 0, "consequences": ["That is the Chinchilla finding, and it beat bigger models.", "Gopher did that and lost to a smaller model.", "Starving the model of data wastes the compute."], "explanation": "For compute-optimal training, model size and data should grow together."}, "proReasoning": "Quote the ratio and the result: 20 tokens per parameter, and a model four times smaller won.", "commonMistake": "Equating a bigger model with a better use of money.", "mentalModel": "Size and data grow together."}, "invest": {"call": {"kind": "theCall", "situation": "A lab brags that its new model is the biggest ever built.", "prompt": "What do you ask?", "options": ["Nothing, since bigger means better", "How much data it was trained on", "How many people worked on it"], "correctIndex": 1, "consequences": ["Gopher was bigger than Chinchilla and lost.", "Without enough data, size can waste a costly budget.", "Headcount says little about the training split."], "explanation": "Data is a cost driver. Size without data is money spent badly."}, "proReasoning": "Investors ask about data, not just parameters. It tells them if the budget was well spent.", "commonMistake": "Reading model size as a measure of quality.", "mentalModel": "Ask about data, not just size."}, "build_startup": {"call": {"kind": "theCall", "situation": "You have a fixed compute budget to train a model for your field.", "prompt": "How do you spend it?", "options": ["Largest model on whatever data you have", "Two giant models trained on little data", "Smaller model, more training data"], "correctIndex": 2, "consequences": ["That repeats the mistake Chinchilla corrected.", "Little data starves both models.", "Same budget, better model, as Chinchilla showed."], "explanation": "For a fixed budget, a smaller model trained on more data can win."}, "proReasoning": "Founders get more from a fixed budget by balancing size and data. Smaller is also cheaper to serve.", "commonMistake": "Spending the budget on size alone.", "mentalModel": "Balance the budget."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend asks how a smaller AI beat one four times its size.", "prompt": "What's the answer?", "options": ["It learned from far more data", "It ran on a faster computer", "The bigger model was broken"], "correctIndex": 0, "consequences": ["Chinchilla trained on 1.4 trillion tokens.", "Both used the same compute.", "Gopher worked; it just had too little data for its size."], "explanation": "Same compute, better split. Data mattered as much as size."}, "proReasoning": "Bigger is not always better. How you train matters as much as how big you build.", "commonMistake": "Assuming size decides the winner.", "mentalModel": "Training beats size alone."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:9923ba786419$ml$]::text[]),
($ml$f5e216ee-0d08-5d65-b385-9efa7098a122$ml$::uuid, $ml$ai$ml$, 10, 3, $ml${"id": "ai-d10-c3", "title": "Two trillion tokens to spend", "lessonTitle": "Twenty tokens per parameter", "slot": 3, "type": "decide", "brief": {"headline": "You run a lab with about 2 trillion tokens of quality text for a new model. Chinchilla's rule of thumb is about 20 training tokens for each parameter.", "kicker": "Decide what size of model your data can support.", "fullText": "DeepMind's Chinchilla found that for compute-optimal training, model size and training tokens should be scaled equally. Chinchilla had 70 billion parameters trained on 1.4 trillion tokens, about 20 tokens per parameter, and beat the 280-billion-parameter Gopher on the same compute.\n\nGPT-3, in 2020, had 175 billion parameters trained on 300 billion tokens. If models need about 20 tokens per parameter, data supply matters as much as chips.", "sources": [{"url": "https://download.arxiv.org/pdf/2203.15556.pdf", "label": "Hoffmann et al., Training compute-optimal large language models, 2022"}, {"url": "https://ar5iv.labs.arxiv.org/html/2005.14165", "label": "Brown et al., Language models are few-shot learners, 2020"}]}, "evidence": {"kind": "buildChain", "prompt": "Work out the compute-optimal size for your data.", "steps": ["Start with 2 trillion tokens of data", "Use about 20 tokens per parameter", "Divide 2 trillion by 20", "Aim for about 100 billion parameters"], "explanation": "The ratio turns your data into a size. Bigger than that, and the data runs thin."}, "numbers": {"kind": "numberSense", "prompt": "With 2 trillion tokens at about 20 per parameter, how many billion parameters?", "min": 0, "max": 300, "value": 100, "unit": "B", "explanation": "About 100 billion. A 400 billion model would get only 5 tokens per parameter."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "Your team lead proposes a 400 billion parameter model on the 2 trillion tokens.", "prompt": "What do you say?", "options": ["Suggest cutting the data down to 1 trillion", "Flag that the data supports about 100 billion", "Agree, since bigger models always win out"], "correctIndex": 1, "consequences": ["Less data makes the imbalance worse.", "At 400 billion, each parameter gets only 5 tokens.", "Gopher was bigger than Chinchilla and lost."], "explanation": "Data and model size have to grow together. The data sets a sensible size."}, "proReasoning": "Back your view with the ratio: 2 trillion over 20 is 100 billion. Numbers win the argument.", "commonMistake": "Going along with size for its own sake.", "mentalModel": "Let the data set the size."}, "invest": {"call": {"kind": "theCall", "situation": "The lab plans to double its model size next year.", "prompt": "What do you ask?", "options": ["Whether the new name is ready", "Nothing, since bigger is safer", "Where twice the data will come from"], "correctIndex": 2, "consequences": ["Names do not train models.", "Size without data wastes compute.", "Doubling size calls for about double the data."], "explanation": "Data is a cost driver. Scaling the model means scaling the data supply too."}, "proReasoning": "Investors ask about the data plan behind a scaling plan. Data can be the bottleneck.", "commonMistake": "Assuming the data will simply appear.", "mentalModel": "Scale the data with the model."}, "build_startup": {"call": {"kind": "theCall", "situation": "You want a stronger model, but you've used all your quality data.", "prompt": "What's your next step?", "options": ["Find more quality data before scaling", "Just add more parameters", "Train longer on the same small set"], "correctIndex": 0, "consequences": ["More data lets a bigger model pay off.", "More size on the same data repeats the Gopher mistake.", "Data matters as much as size, and you are short of it."], "explanation": "Data and size grow together. Without new data, a bigger model is a poor use of compute."}, "proReasoning": "Founders see data as a real constraint. Getting more of it can matter more than buying chips.", "commonMistake": "Scaling the model when the data is the limit.", "mentalModel": "Data first, then size."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend asks why AI companies keep hunting for more text.", "prompt": "What's the answer?", "options": ["They are building a new search engine", "Bigger models need more data to pay off", "Text is needed to store the models"], "correctIndex": 1, "consequences": ["They need it for training, whatever the product.", "About 20 tokens per parameter, so size needs data.", "Data trains the model; it does not store it."], "explanation": "If models need about 20 tokens per parameter, growing models need growing data."}, "proReasoning": "Model size and data rise together. That is why data has become valuable.", "commonMistake": "Thinking only chips limit AI.", "mentalModel": "More model, more data."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:18f7ef290fd9$ml$]::text[]),
($ml$febc7e02-e3eb-58ba-a935-9d703adc59c2$ml$::uuid, $ml$ai$ml$, 11, 1, $ml${"id": "ai-d11-c1", "title": "A price for every extra page", "lessonTitle": "Why reading more costs more", "slot": 1, "type": "apply", "brief": {"headline": "In August 2025, Anthropic raised Claude Sonnet 4's context window to 1 million tokens, five times the old limit. Prompts over 200,000 tokens cost $6 per million input tokens, double the usual $3.", "kicker": "Apply day 11: why long prompts cost more per token.", "fullText": "It was the first time Anthropic varied prices by context length. Up to 200,000 tokens, input cost $3 per million and output $15. Above that, input cost $6 and output $22.50. Google's Gemini 2.5 Pro already used a similar split: $1.25 per million input tokens below 200,000 and $2.50 above.\n\nThe day 11 reason sits inside the Transformer. Attention's work grows with the square of the input length, so doubling the text roughly quadruples it. Long context is a feature, and also a cost someone has to pay.", "sources": [{"url": "https://simonwillison.net/2025/Aug/12/claude-sonnet-4-1m", "label": "Simon Willison, Claude Sonnet 4 1M context, Aug 2025"}, {"url": "https://arxiv.org/pdf/1706.03762", "label": "Vaswani et al., Attention Is All You Need, 2017"}]}, "evidence": {"kind": "buildChain", "prompt": "Follow why long prompts cost more.", "steps": ["A prompt grows from 200,000 to 400,000 tokens", "Attention work roughly quadruples", "Each request needs much more compute", "The provider charges more above 200,000 tokens"], "explanation": "Work that grows with the square of length turns into a higher price per token."}, "numbers": {"kind": "numberSense", "prompt": "A 600,000-token prompt at $6 per million input tokens costs how many dollars?", "min": 0, "max": 10, "value": 3.6, "unit": "dollars", "explanation": "$3.60 for one request. At scale, every long prompt adds up."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "You're interviewing for an AI product role. They ask why long prompts cost more per token.", "prompt": "What's your answer?", "options": ["Attention work grows with the square of length", "Long prompts are stored on servers for longer", "Popular features are simply priced higher"], "correctIndex": 0, "consequences": ["That ties the price to how the model works.", "Storage is not what drives the cost.", "The extra price follows extra compute."], "explanation": "Knowing why long context is expensive explains why teams trim what they send."}, "proReasoning": "Explain prices with the mechanism. Quadratic attention is why the second 200,000 tokens cost more.", "commonMistake": "Treating long-context pricing as a marketing choice.", "mentalModel": "Price follows the mechanism."}, "invest": {"call": {"kind": "theCall", "situation": "A model provider advertises a 1 million token window.", "prompt": "What should you check?", "options": ["Nothing, since bigger windows are free", "How it prices and serves long prompts", "Only the size of the window"], "correctIndex": 1, "consequences": ["Doubling input roughly quadruples attention work.", "Long context is a cost line, and pricing shows who pays it.", "Size is the selling point, not the economics."], "explanation": "Million-token windows sell well, but each doubling of input roughly quadruples attention work."}, "proReasoning": "Investors ask who absorbs the cost of long context. Tiered prices show the provider passing it on.", "commonMistake": "Treating window size as pure upside.", "mentalModel": "Context is a cost line."}, "build_startup": {"call": {"kind": "theCall", "situation": "Your app sends a whole 400-page manual with every user question.", "prompt": "What do you change?", "options": ["Pay the long-context rate and send it all", "Wait for windows to get even bigger", "Find the relevant pages first, send those"], "correctIndex": 2, "consequences": ["You pay double rates for pages the answer does not need.", "Bigger windows do not make long prompts cheaper.", "Shorter prompts cut attention work and the bill."], "explanation": "Serving long context takes heavy compute. A small team has to be selective."}, "proReasoning": "Founders send models only what each answer needs. It is the cheapest speedup there is.", "commonMistake": "Using the whole window because it is there.", "mentalModel": "Send what the answer needs."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend asks why Claude charges double for very long prompts.", "prompt": "What's the best explanation?", "options": ["Reading more costs disproportionately more", "Anthropic wants people to read less often", "Long prompts need a human to review them"], "correctIndex": 0, "consequences": ["Doubling the text roughly quadruples attention work.", "The price reflects compute, not a wish.", "No human reads your prompt."], "explanation": "In Transformers, reading more costs disproportionately more, and prices follow."}, "proReasoning": "Some costs grow faster than the thing you measure. Attention is one.", "commonMistake": "Assuming twice the text means twice the work.", "mentalModel": "Twice the text, four times the work."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:71836f9a4f2e$ml$]::text[]),
($ml$f7875f8b-d58e-5b7a-9054-4fbc8d73fb42$ml$::uuid, $ml$ai$ml$, 11, 2, $ml${"id": "ai-d11-c2", "title": "The price of parallel", "lessonTitle": "Why reading more costs more", "slot": 2, "type": "connect", "brief": {"headline": "The Transformer dropped recurrence so it could process a sequence in parallel. The trade: its attention work grows with the square of the input length.", "kicker": "Connect day 7 and day 11: parallel speed came with a quadratic bill.", "fullText": "On day 7 you saw why the Transformer won: RNNs read one step at a time, while attention needs only a constant number of sequential steps, so it runs in parallel. On day 11 you saw the price. Table 1 of the 2017 paper lists self-attention's per-layer work as n squared times d, where n is the input length, against n times d squared for recurrent layers.\n\nFor short inputs the trade is a bargain. As context windows grow toward the 1 million tokens Gemini 1.5 Pro previewed in 2024, the square term takes over.", "sources": [{"url": "https://arxiv.org/pdf/1706.03762", "label": "Vaswani et al., Attention Is All You Need, 2017"}, {"url": "https://en.wikipedia.org/wiki/Attention_Is_All_You_Need", "label": "Attention Is All You Need, 2017"}, {"url": "https://developers.googleblog.com/2024/02/gemini-15-available-for-private-preview-in-google-ai-studio.html", "label": "Google for Developers, Gemini 1.5 private preview, Feb 2024"}]}, "evidence": {"kind": "spotFake", "prompt": "One of these is false. Tap it.", "statements": ["Self-attention needs a constant number of sequential steps.", "RNNs read a sequence one step at a time.", "Attention work grows in a straight line with input length."], "fakeIndex": 2, "explanation": "Attention work grows with the square of the input length. That is the price of running in parallel."}, "numbers": {"kind": "numberSense", "prompt": "An input grows 10 times longer. About how many times more attention work?", "min": 0, "max": 300, "value": 100, "unit": "x", "explanation": "Ten squared is 100. Long inputs get expensive fast."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "In an interview, you are asked what the Transformer gave up to run in parallel.", "prompt": "What's the answer?", "options": ["Its ability to run well on GPUs at all", "Work that grows with the square of input", "Accuracy on short, simple sentences"], "correctIndex": 1, "consequences": ["Running in parallel is what suits GPUs.", "That is the trade in Table 1 of the paper.", "Transformers did well on short text too."], "explanation": "Parallel processing came at the cost of quadratic attention. Both facts explain modern AI costs."}, "proReasoning": "Name both sides of a design trade. Interviewers trust people who know the cost of a win.", "commonMistake": "Describing the Transformer as all upside.", "mentalModel": "Every design win has a price."}, "invest": {"call": {"kind": "theCall", "situation": "A startup claims a new design that reads long inputs at much lower cost than attention.", "prompt": "How do you treat the claim?", "options": ["Ignore it, since the Transformer can't change", "Assume it is worse, since it is new", "Watch it, since it targets attention's big cost"], "correctIndex": 2, "consequences": ["A 2017 paper already changed which models won once.", "New designs have won before.", "A design that cuts that cost could change what AI costs to run."], "explanation": "Watch for architecture shifts. Quadratic attention is the obvious target."}, "proReasoning": "Investors know where today's design is weakest and watch for fixes there.", "commonMistake": "Assuming the current design is final.", "mentalModel": "Watch the weak spot."}, "build_startup": {"call": {"kind": "theCall", "situation": "Your product mostly handles short messages, but some users paste huge files.", "prompt": "How do you design for both?", "options": ["Keep short inputs cheap; handle big files apart", "Treat every input like a huge file upload", "Send every file to the model in full, always"], "correctIndex": 0, "consequences": ["Short inputs stay cheap, and big files get special handling.", "You would pay long-input costs on every short message.", "Full files make the square term dominate your bill."], "explanation": "Attention is a bargain for short inputs and costly for long ones. Design around both."}, "proReasoning": "Founders treat long inputs as a separate case with its own cost.", "commonMistake": "Designing every request for the worst case.", "mentalModel": "Short is cheap; plan for long."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend asks: if Transformers are so fast, why do long documents slow them down?", "prompt": "What's the answer?", "options": ["Long documents use longer words on average", "Their work grows with the square of length", "They read one word at a time, in order"], "correctIndex": 1, "consequences": ["Word length is not the issue; token count is.", "Double the text and attention work roughly quadruples.", "That describes RNNs, not Transformers."], "explanation": "Transformers run in parallel, but their attention work grows with the square of input length."}, "proReasoning": "Fast for short inputs, costly for long ones: both are true of the same design.", "commonMistake": "Thinking a fast design is fast for every input.", "mentalModel": "Fast in parallel, costly at length."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:0765cd35f859$ml$]::text[]),
($ml$7df1eafd-c9c4-5b5a-aeca-425527410264$ml$::uuid, $ml$ai$ml$, 11, 3, $ml${"id": "ai-d11-c3", "title": "The chat that kept growing", "lessonTitle": "Why reading more costs more", "slot": 3, "type": "decide", "brief": {"headline": "You run a support chatbot that sends a customer's whole chat history with every new message. Long conversations have made some requests slow and costly.", "kicker": "Decide how to cut the cost of long conversations.", "fullText": "Table 1 of the 2017 Transformer paper lists self-attention's per-layer work as n squared times d, where n is the input length. Double the text a Transformer reads, and its attention work roughly quadruples.\n\nIn February 2024, Google previewed Gemini 1.5 Pro with a context window of up to 1 million tokens, about 700,000 words. Big windows are a feature. Filling them on every request is a cost decision.", "sources": [{"url": "https://arxiv.org/pdf/1706.03762", "label": "Vaswani et al., Attention Is All You Need, 2017"}, {"url": "https://developers.googleblog.com/2024/02/gemini-15-available-for-private-preview-in-google-ai-studio.html", "label": "Google for Developers, Gemini 1.5 private preview, Feb 2024"}]}, "evidence": {"kind": "sortSignal", "prompt": "Does each change cut the attention work per request?", "buckets": ["Cuts the work", "Doesn't cut it"], "items": [{"text": "Send only the recent, relevant messages", "bucket": 0}, {"text": "Summarize old messages into a short note", "bucket": 0}, {"text": "Drop pasted logs the question doesn't need", "bucket": 0}, {"text": "Switch to a model with a bigger window", "bucket": 1}, {"text": "Send the full history twice for safety", "bucket": 1}], "explanation": "Only shorter inputs cut attention work. A bigger window lets you send more, which costs more."}, "numbers": {"kind": "numberSense", "prompt": "A conversation grows from 5,000 to 20,000 tokens. About how many times more attention work?", "min": 0, "max": 50, "value": 16, "unit": "x", "explanation": "Four times the length, so about 16 times the work. Long chats get costly fast."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "You join the team as an engineer. Your first task is to cut costs without hurting answers.", "prompt": "What do you try first?", "options": ["Buy a model with a bigger context window", "Send the full history only on weekends", "Trim each request to the relevant messages"], "correctIndex": 2, "consequences": ["A bigger window does not make long inputs cheaper.", "Cost would still spike on weekends.", "Shorter inputs cut attention work, and good answers rarely need it all."], "explanation": "Attention work grows with the square of length. Trimming input is the biggest lever."}, "proReasoning": "Engineers who know why long context is expensive go straight to trimming input.", "commonMistake": "Reaching for a bigger model when the problem is input size.", "mentalModel": "Trim input first."}, "invest": {"call": {"kind": "theCall", "situation": "The chatbot's maker says usage is up, but cost per chat is rising faster.", "prompt": "What do you ask?", "options": ["How much context each request sends", "Whether users like the chatbot", "How many servers it rents"], "correctIndex": 0, "consequences": ["Growing histories square the attention work.", "Liking it does not explain the cost curve.", "Server count follows the input size."], "explanation": "Context is a cost line. Rising cost per chat often means growing inputs."}, "proReasoning": "Investors trace rising unit costs to their cause. Here, it is how much text each request carries.", "commonMistake": "Blaming usage when the cost is in the input.", "mentalModel": "Find the cost driver."}, "build_startup": {"call": {"kind": "theCall", "situation": "Customers want the bot to remember months of history.", "prompt": "How do you deliver that?", "options": ["Refuse to keep any customer history at all", "Store it, send only what each answer needs", "Send all of it along with every message"], "correctIndex": 1, "consequences": ["You lose a feature customers want.", "Customers get memory, and requests stay short.", "Months of history would make every message slow and costly."], "explanation": "Keep history in storage and retrieve what matters. Long context is a cost decision."}, "proReasoning": "Founders separate what the product remembers from what the model reads. That keeps costs sane.", "commonMistake": "Equating memory with sending everything every time.", "mentalModel": "Remember everything, send little."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend asks why a company would limit how much text its chatbot reads at once.", "prompt": "What's the answer?", "options": ["Chatbots get bored with very long chats", "Storing long text is against the law", "Reading more costs disproportionately more"], "correctIndex": 2, "consequences": ["Chatbots do not get bored; the cost rises.", "Storage is legal; reading it all is the cost.", "Double the text, about four times the attention work."], "explanation": "In Transformers, reading more costs disproportionately more. Limits keep costs in check."}, "proReasoning": "Limits on input are usually about cost, not capability.", "commonMistake": "Assuming limits mean the AI cannot cope.", "mentalModel": "Limits are often about cost."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:59ee6593027d$ml$]::text[]),
($ml$27b2a76d-5511-538c-8dfb-87bdcb975f14$ml$::uuid, $ml$ai$ml$, 12, 1, $ml${"id": "ai-d12-c1", "title": "References that did not exist", "lessonTitle": "Six cases that never existed", "slot": 1, "type": "apply", "brief": {"headline": "In October 2025, Deloitte agreed to refund part of an A$440,000 contract with Australia's government. Its report had cited sources that did not exist and a quote a court judgment does not contain.", "kicker": "Apply day 12: a citation that looks right still needs checking.", "fullText": "The Department of Employment and Workplace Relations paid Deloitte to review the Targeted Compliance Framework, a system for penalizing welfare recipients who miss obligations. After the report came out in July 2025, University of Sydney researcher Christopher Rudge spotted more than a dozen bogus references, including reports that did not exist, and a quote attributed to a judge that the cited judgment does not contain.\n\nDeloitte agreed to refund the final instalment. A corrected report removed the bogus references and disclosed the use of a generative AI tool, Azure OpenAI GPT-4o. A source told the Australian Financial Review that Deloitte's internal review blamed human error rather than AI misuse. The department said the substance and recommendations were unchanged.\n\nFluent is not the same as true. Anything high-stakes needs checking against a real source.", "sources": [{"url": "https://www.theregister.com/2025/10/06/deloitte_ai_report_australia/", "label": "The Register, Deloitte refunds Australian government over AI errors, Oct 2025"}, {"url": "https://news.bloomberglaw.com/bloomberg-government-news/chatgpt-phony-legal-filing-case-gets-lawyers-a-5-000-fine", "label": "Bloomberg Law, phony ChatGPT brief leads to $5,000 fine, Jun 2023"}]}, "evidence": {"kind": "spotFake", "prompt": "One of these is false about the Deloitte report. Tap it.", "statements": ["A researcher spotted the bogus references after it was published.", "The corrected report disclosed use of Azure OpenAI GPT-4o.", "The department withdrew all of the report's recommendations."], "fakeIndex": 2, "explanation": "The department said the recommendations were unchanged. The bogus references were removed."}, "numbers": {"kind": "numberSense", "prompt": "The contract was worth how many thousand Australian dollars?", "min": 0, "max": 1000, "value": 440, "unit": "K", "explanation": "A$440,000. A citation check would have cost far less than the refund and the headlines."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "You're an analyst at a consulting firm that uses AI to help draft reports.", "prompt": "Which habit protects you most?", "options": ["Remove all citations from reports", "Open every cited source before it ships", "Trust citations that look well formatted"], "correctIndex": 1, "consequences": ["Clients need sources; they need real ones.", "A bogus reference cannot survive someone opening it.", "The bogus references looked like real ones."], "explanation": "Fluent output still needs a source check. Opening the source is the check."}, "proReasoning": "Say where you would require human checks on AI output, and why. Citations are the obvious place.", "commonMistake": "Trusting a reference because it looks professional.", "mentalModel": "Open the source."}, "invest": {"call": {"kind": "theCall", "situation": "A consulting firm tells investors AI will sharply cut the cost of writing reports.", "prompt": "What do you ask?", "options": ["Whether the savings all go to profit", "Nothing, since clients rarely check", "How it checks AI output before delivery"], "correctIndex": 2, "consequences": ["Savings mean little if trust failures erase them.", "A researcher checked, and it made national news.", "Without checks, savings can turn into refunds."], "explanation": "Watch for trust failures. Check how AI work is verified before trusting the savings."}, "proReasoning": "Investors weigh AI savings against the cost of a public error. Verification is part of the business.", "commonMistake": "Counting AI savings without counting the risk.", "mentalModel": "Savings need verification."}, "build_startup": {"call": {"kind": "theCall", "situation": "You want to build a tool for consultants who draft reports with AI.", "prompt": "Which product meets a real gap?", "options": ["A tool that checks citations exist and match", "A tool that writes citations even faster", "A tool that hides which text used AI"], "correctIndex": 0, "consequences": ["Checking is slow and manual today, and errors are costly.", "Faster citations do not fix invented ones.", "Hiding AI use makes the trust problem worse."], "explanation": "Ask professionals how they verify AI output. If it is slow and manual, that gap is worth testing."}, "proReasoning": "Founders build for the checking problem, not just the writing problem. That is where the pain is.", "commonMistake": "Adding speed to a process whose problem is accuracy.", "mentalModel": "Solve the checking problem."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend asks how a big firm's report could cite sources that don't exist.", "prompt": "What's the best explanation?", "options": ["The government changed its court records", "AI tools can invent sources that look real", "The sources were deleted from the internet"], "correctIndex": 1, "consequences": ["The judgment was real; the quote was not in it.", "Confident, well-formatted errors need a check against a real source.", "The reports cited never existed in the first place."], "explanation": "Models can produce citations that look real but are invented. Someone has to check."}, "proReasoning": "Fluent is not the same as true. A real-looking citation is still a claim to check.", "commonMistake": "Thinking polished output must be accurate.", "mentalModel": "Fluent is not true."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:974d3279859c$ml$]::text[]),
($ml$da9c3cdf-a458-5dcd-a665-3d38b848ae7f$ml$::uuid, $ml$ai$ml$, 12, 2, $ml${"id": "ai-d12-c2", "title": "Fast to users, fast to court", "lessonTitle": "Six cases that never existed", "slot": 2, "type": "connect", "brief": {"headline": "ChatGPT reached about 100 million monthly users in January 2023, two months after launch. That June, a judge fined two New York lawyers over a brief citing six cases ChatGPT had made up.", "kicker": "Connect day 9 and day 12: a fast spread carries the flaws with it.", "fullText": "On day 9 you saw why shippers win: ChatGPT reached about 100 million monthly users two months after launch, while the lab that invented the Transformer watched. On day 12 you met two of those users. In Mata v. Avianca, attorneys Steven Schwartz and Peter LoDuca filed a brief citing six fictitious court opinions generated with ChatGPT.\n\nOn June 22, 2023, Judge P. Kevin Castel fined them and their firm $5,000, finding they abandoned their responsibilities and kept defending the fake cases after the court questioned them.\n\nDistribution puts a tool in the hands of people who may not know its limits. The faster a product spreads, the faster its failure modes travel.", "sources": [{"url": "https://business.inquirer.net/384799/chatgpt-sets-record-for-fastest-growing-user-base-analyst-note", "label": "UBS via Reuters/Inquirer, ChatGPT sets user growth record, Feb 2023"}, {"url": "https://news.bloomberglaw.com/bloomberg-government-news/chatgpt-phony-legal-filing-case-gets-lawyers-a-5-000-fine", "label": "Bloomberg Law, phony ChatGPT brief leads to $5,000 fine, Jun 2023"}]}, "evidence": {"kind": "buildChain", "prompt": "Put the events in order.", "steps": ["Google researchers introduce the Transformer", "ChatGPT launches and spreads fast", "It reaches about 100 million users", "Lawyers file a brief with invented cases", "A judge fines them $5,000"], "explanation": "The faster a tool reaches users, the sooner its failures show up in their work."}, "numbers": {"kind": "numberSense", "prompt": "The judge fined the lawyers and their firm how many thousand dollars?", "min": 0, "max": 20, "value": 5, "unit": "K", "explanation": "$5,000. The fine was small; the national headlines were not."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "You join a law firm's tech team as AI tools roll out to every lawyer.", "prompt": "What do you push for first?", "options": ["A ban on all AI tools for good", "Free use with no rules at all", "Training on how to check AI output"], "correctIndex": 2, "consequences": ["A ban gives up real gains, and people use tools anyway.", "That is how a brief with six fake cases gets filed.", "Users who know the limits catch invented cases."], "explanation": "A tool that spreads fast needs users who know where it fails."}, "proReasoning": "Have a view on where AI checks belong. Training users is the first line of defense.", "commonMistake": "Choosing between banning AI and ignoring its flaws.", "mentalModel": "Spread the checks with the tool."}, "invest": {"call": {"kind": "theCall", "situation": "An AI product grows to 100 million users in a few months.", "prompt": "What else do you want to know?", "options": ["How it handles errors at that scale", "Nothing, since growth proves reliability", "Only how fast it will keep growing"], "correctIndex": 0, "consequences": ["At scale, rare errors become national news.", "ChatGPT grew fast and still invented court cases.", "Growth with trust failures can stall."], "explanation": "Watch for trust failures. Growth spreads the flaws as fast as the features."}, "proReasoning": "Investors pair growth with reliability. A trust failure at scale can undo the adoption story.", "commonMistake": "Reading fast growth as proof of quality.", "mentalModel": "Growth spreads flaws too."}, "build_startup": {"call": {"kind": "theCall", "situation": "Your AI writing tool is spreading fast among professionals.", "prompt": "What's the priority?", "options": ["Add a small disclaimer, nothing else", "Build checks in before it spreads further", "Grow first and fix errors later"], "correctIndex": 1, "consequences": ["A disclaimer did not stop the lawyers.", "Checks protect users and your reputation as you scale.", "Later can mean after a headline like Avianca."], "explanation": "The faster a product spreads, the more its errors matter. Build verification in early."}, "proReasoning": "Founders treat verification as a feature, especially for professional users.", "commonMistake": "Treating errors as a problem for later.", "mentalModel": "Build the check in early."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend asks why experienced lawyers trusted a chatbot's cases.", "prompt": "What's the best explanation?", "options": ["The chatbot was certified for legal work", "The court told them to use it", "The answers looked fluent and confident"], "correctIndex": 2, "consequences": ["No such certification existed.", "The court questioned the cases; it did not suggest the tool.", "Well-formatted errors are easy to mistake for real cases."], "explanation": "Fluent output feels trustworthy. That is exactly why it needs checking."}, "proReasoning": "Confidence and accuracy are different things. A chatbot can have one without the other.", "commonMistake": "Taking a confident tone as evidence.", "mentalModel": "Confidence is not evidence."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:aeff238858a3$ml$]::text[]),
($ml$e01874d2-81c4-5f14-baa5-4f70f1c11506$ml$::uuid, $ml$ai$ml$, 12, 3, $ml${"id": "ai-d12-c3", "title": "The judge asks a question", "lessonTitle": "Six cases that never existed", "slot": 3, "type": "decide", "brief": {"headline": "You run a small law firm. A judge has questioned citations in a brief your associate filed, and the associate admits using a chatbot to find them.", "kicker": "Decide what your firm does next.", "fullText": "In Mata v. Avianca, attorneys filed a brief citing six fictitious court opinions generated with ChatGPT. The model produced citations that looked real but were invented, which is called a hallucination.\n\nOn June 22, 2023, Judge P. Kevin Castel fined the lawyers and their firm $5,000. He found they abandoned their responsibilities and kept defending the fake cases after the court questioned them. What they did after the question mattered as much as the error.", "sources": [{"url": "https://news.bloomberglaw.com/bloomberg-government-news/chatgpt-phony-legal-filing-case-gets-lawyers-a-5-000-fine", "label": "Bloomberg Law, phony ChatGPT brief leads to $5,000 fine, Jun 2023"}]}, "evidence": {"kind": "multipleChoice", "prompt": "In Mata v. Avianca, what made things worse for the lawyers?", "options": ["They kept defending the fake cases", "They used a computer to write the brief", "They cited too many real cases"], "correctIndex": 0, "explanation": "The judge found they kept defending the fake cases after the court questioned them."}, "numbers": {"kind": "numberSense", "prompt": "If checking one citation takes 10 minutes, how many hours does a brief with 30 citations take?", "min": 0, "max": 12, "value": 5, "unit": "hours", "explanation": "Five hours. Slow, but far cheaper than a sanction and a headline."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "You're the associate who filed the brief. The judge asks about your citations.", "prompt": "What do you do?", "options": ["Check each one now and correct the record", "Defend them until proven fake", "Blame the chatbot and say nothing else"], "correctIndex": 0, "consequences": ["Owning the error early is what the Avianca lawyers failed to do.", "Defending fake cases is what made Avianca worse.", "Lawyers answer for what they file, whatever tool they used."], "explanation": "The error was bad. Defending it after being questioned was worse."}, "proReasoning": "When AI output is questioned, verify fast and correct the record. Credibility is the asset at stake.", "commonMistake": "Doubling down to save face.", "mentalModel": "Verify, then correct."}, "invest": {"call": {"kind": "theCall", "situation": "You're weighing an investment in a legal AI tool after cases like this one.", "prompt": "What matters most?", "options": ["How many lawyers have signed up so far", "How it ties each citation to a real source", "How fluent and polished its writing sounds"], "correctIndex": 1, "consequences": ["Users leave fast after a trust failure.", "Verifiable citations address the exact failure.", "Fluent writing is what fooled the lawyers."], "explanation": "Check how an AI product handles verification before trusting its adoption story."}, "proReasoning": "Investors in professional AI tools ask about verification first. Trust is the product.", "commonMistake": "Being impressed by fluency.", "mentalModel": "Trust is the product."}, "build_startup": {"call": {"kind": "theCall", "situation": "You run the firm and must set a new rule for AI-assisted filings.", "prompt": "Which rule works best?", "options": ["Ban AI and stop checking citations", "Allow AI if the brief reads well", "A named lawyer verifies every cited case"], "correctIndex": 2, "consequences": ["Human-found citations need checking too.", "Reading well is how the fake cases passed.", "Every citation gets a real check and an owner."], "explanation": "Fluent output still needs a source check, and someone has to own it."}, "proReasoning": "Good rules name who checks what. A rule without an owner is a wish.", "commonMistake": "Writing a policy no one is responsible for.", "mentalModel": "Every check needs an owner."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend asks: if the AI made the mistake, why were the lawyers fined?", "prompt": "What's the answer?", "options": ["Lawyers answer for what they file", "The lawyers wrote the chatbot", "The AI company paid the fine"], "correctIndex": 0, "consequences": ["The judge found they abandoned their responsibilities.", "They used the chatbot; they did not build it.", "The fine went to the lawyers and their firm."], "explanation": "A tool can make the error. The professional who signs the work owns it."}, "proReasoning": "Responsibility follows the signature, not the software.", "commonMistake": "Blaming the tool for what a person signed.", "mentalModel": "The signer owns it."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:083a89704bd4$ml$]::text[]),
($ml$65aafc1e-ff36-54f8-a381-fba132edd78e$ml$::uuid, $ml$ai$ml$, 13, 1, $ml${"id": "ai-d13-c1", "title": "A gate on the free crawl", "lessonTitle": "Where training data comes from", "slot": 1, "type": "apply", "brief": {"headline": "On July 1, 2025, Cloudflare began blocking AI crawlers by default on the websites it serves. Site owners can now let them in, keep them out, or charge them for each page they crawl.", "kicker": "Apply day 13: part of the free web moves toward paid access.", "fullText": "Under the new default, AI bots are blocked unless the site owner allows them, and owners can choose by stage: training, fine-tuning or answering questions. A pay per crawl service lets a site set a price each time an AI bot fetches a page. The Associated Press, Time, Quora and Stack Overflow backed the move.\n\nCloudflare's data showed why publishers were frustrated. In late June 2025, Anthropic's Claude made nearly 71,000 page requests for every visit it referred back to a site, OpenAI about 1,600, and Google about 9.4.\n\nDay 13 split training data into free web crawls and paid licenses. Cloudflare's change pushes part of the free web toward the paid side.", "sources": [{"url": "https://www.technologyreview.com/2025/07/01/1119498/cloudflare-will-now-by-default-block-ai-bots-from-crawling-its-clients-websites/", "label": "MIT Technology Review, Cloudflare will block AI bots by default, Jul 2025"}, {"url": "https://www.theregister.com/2025/07/01/cloudflare_creates_ai_crawler_toll/", "label": "The Register, Cloudflare creates AI crawler tollbooth, Jul 2025"}, {"url": "https://aws.amazon.com/fr/blogs/publicsector/how-common-crawl-and-aws-open-data-built-the-foundation-for-the-ai-revolution/", "label": "AWS Public Sector Blog, Common Crawl and the AI revolution"}]}, "evidence": {"kind": "sortSignal", "prompt": "Is each one free web data or paid access?", "buckets": ["Free web data", "Paid access"], "items": [{"text": "Common Crawl's public archive", "bucket": 0}, {"text": "A site that lets all AI bots crawl it", "bucket": 0}, {"text": "Reddit's license deal with Google", "bucket": 1}, {"text": "A bot paying per page through Cloudflare", "bucket": 1}], "explanation": "Open crawls cost nothing to collect. Licenses and pay per crawl put a price on the same kind of content."}, "numbers": {"kind": "numberSense", "prompt": "In late June 2025, Claude made nearly how many thousand page requests per referral?", "min": 0, "max": 100, "value": 71, "unit": "K", "explanation": "Nearly 71,000. Pages went out to AI, and almost no visitors came back."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "You join an AI lab's data team the week Cloudflare changes its default.", "prompt": "What's the first thing to check?", "options": ["Whether our crawler is fast enough", "Nothing, since bots can ignore the rules", "Which of our sources now block or charge"], "correctIndex": 2, "consequences": ["Speed does not help if the door is closed.", "Cloudflare said it would act against bad-faith crawlers.", "Sources that were free may now need permission or payment."], "explanation": "Know where your data comes from. When a source changes its terms, your costs and risks change too."}, "proReasoning": "Map your data sources and their terms. When a big gatekeeper moves, the map changes.", "commonMistake": "Treating the open web as permanently free.", "mentalModel": "Know the terms of every source."}, "invest": {"call": {"kind": "theCall", "situation": "A lab relies mostly on free web crawls for training data.", "prompt": "How does Cloudflare's move change its risk?", "options": ["Free data may now cost money or vanish", "No change, since the web stays free", "It cuts costs, since fewer bots crawl"], "correctIndex": 0, "consequences": ["Blocked or paid pages raise the cost of the same data.", "Blocking by default ends that assumption for many sites.", "Fewer pages to crawl is a loss of data, not a saving."], "explanation": "Where the data comes from shapes what a model costs. Watch who controls access."}, "proReasoning": "Investors ask how much of a lab's data depends on access it does not control.", "commonMistake": "Assuming yesterday's free inputs stay free.", "mentalModel": "Watch who controls the data."}, "build_startup": {"call": {"kind": "theCall", "situation": "You run a niche forum with expert posts that AI bots crawl heavily.", "prompt": "What's your move?", "options": ["Delete old posts to stop the bots", "Set terms: block, license or charge", "Stay open and hope traffic follows"], "correctIndex": 1, "consequences": ["Deleting your content destroys the value itself.", "Your posts have value, and now you can price it.", "Claude sent about one visit per 71,000 pages."], "explanation": "Unique data has a price. Tools like pay per crawl let small owners collect it."}, "proReasoning": "Founders who own unique content set the terms for using it.", "commonMistake": "Giving away content in hope of traffic that does not come.", "mentalModel": "Unique content deserves terms."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend asks why websites want to charge AI bots.", "prompt": "What's the main reason?", "options": ["Bots break websites when they read them", "A law requires sites to charge them", "Bots take pages but send few visitors back"], "correctIndex": 2, "consequences": ["The issue is value, not damage.", "It is a choice Cloudflare offered, not a law.", "Search sent visitors back; AI answers often do not."], "explanation": "Sites used to trade content for search traffic. AI bots take the content and send little back."}, "proReasoning": "Follow the old trade and see what changed. Content for clicks worked; content for nothing does not.", "commonMistake": "Thinking websites are just being greedy.", "mentalModel": "Follow the trade."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:34990a417d70$ml$]::text[]),
($ml$5007f265-abcc-572e-aee2-9f8fd08fcf1d$ml$::uuid, $ml$ai$ml$, 13, 2, $ml${"id": "ai-d13-c2", "title": "Feeding twenty tokens per parameter", "lessonTitle": "Where training data comes from", "slot": 2, "type": "connect", "brief": {"headline": "Chinchilla showed models need about 20 training tokens per parameter. About 82% of GPT-3's raw training tokens came from filtered Common Crawl, a free archive of more than 300 billion web pages.", "kicker": "Connect day 10 and day 13: big models need data, and the web supplied it.", "fullText": "On day 10 you saw that model size and data must grow together: Chinchilla trained 70 billion parameters on 1.4 trillion tokens. On day 13 you saw where most of that data comes from.\n\nCommon Crawl, a nonprofit founded in 2007, has archived more than 300 billion pages and adds roughly 2.3 to 2.7 billion each month. About 82% of GPT-3's raw pre-training tokens came from filtered Common Crawl, and a 2024 Mozilla study found that 64% of 47 major language models used it.\n\nFree web data made it possible to feed bigger and bigger models. Because it is free to everyone, it gives no one an edge.", "sources": [{"url": "https://download.arxiv.org/pdf/2203.15556.pdf", "label": "Hoffmann et al., Training compute-optimal large language models, 2022"}, {"url": "https://aws.amazon.com/fr/blogs/publicsector/how-common-crawl-and-aws-open-data-built-the-foundation-for-the-ai-revolution/", "label": "AWS Public Sector Blog, Common Crawl and the AI revolution"}]}, "evidence": {"kind": "multipleChoice", "prompt": "Why did so many language models rely on Common Crawl?", "options": ["It held only expert-checked text", "It was huge and free to everyone", "It was the only legal data source"], "correctIndex": 1, "explanation": "Models needed trillions of tokens. A free archive of 300 billion pages could supply them."}, "numbers": {"kind": "numberSense", "prompt": "A 2024 Mozilla study found what share of 47 major language models used filtered Common Crawl?", "min": 0, "max": 100, "value": 64, "unit": "%", "explanation": "About 64%. Most models learned from the same free source."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "You're asked in an interview where a large language model's data usually comes from.", "prompt": "What's the best answer?", "options": ["Mostly web crawls, plus licensed and own data", "Only from licensed books and articles", "Mostly from the model's own past answers"], "correctIndex": 0, "consequences": ["About 82% of GPT-3's raw tokens came from Common Crawl.", "Licensed data adds to the web; it does not replace it.", "Training on its own output is a known risk, not the norm."], "explanation": "Name the sources: web crawls, licensed deals and proprietary data. It is a sharp interview point."}, "proReasoning": "Know the data mix and its proportions. Common Crawl dominates, and licenses fill gaps.", "commonMistake": "Assuming models learn from some special curated library.", "mentalModel": "Name the data mix."}, "invest": {"call": {"kind": "theCall", "situation": "A lab says its data is its moat. Most of it is filtered Common Crawl.", "prompt": "How do you read that claim?", "options": ["As proof the lab owns the web", "With doubt, since anyone can use that data", "As strong, since the archive is huge"], "correctIndex": 1, "consequences": ["Common Crawl is a public nonprofit archive.", "64% of major models used the same source.", "Size helps everyone equally when it is free to all."], "explanation": "Free data is free to rivals too. A moat needs data nobody else has."}, "proReasoning": "Investors ask what data a company has that rivals cannot get. Shared data is not a moat.", "commonMistake": "Mistaking a big dataset for a unique one.", "mentalModel": "Shared data is no moat."}, "build_startup": {"call": {"kind": "theCall", "situation": "You want a model that beats general ones at reading medical records.", "prompt": "Where should your edge come from?", "options": ["A bigger slice of Common Crawl", "The same mix every lab uses", "Data the open web does not have"], "correctIndex": 2, "consequences": ["Rivals can take that same slice for free.", "Same inputs, same results.", "Unique data is what general models lack."], "explanation": "Public web data is free to everyone. Data nobody else has is what buyers pay for."}, "proReasoning": "Founders look for data the web cannot provide. That is where a specialized model wins.", "commonMistake": "Competing with the same free data as everyone.", "mentalModel": "Edge comes from unique data."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend asks where AI chatbots learned to write.", "prompt": "What's the best short answer?", "options": ["Mostly from huge free archives of the web", "From a secret library of perfect books", "From people typing lessons for them"], "correctIndex": 0, "consequences": ["Common Crawl alone holds more than 300 billion pages.", "Most of it was ordinary public web text.", "People help tune them, but the bulk is web text."], "explanation": "Most big language models learned from filtered copies of the public web."}, "proReasoning": "The open web is the main textbook for chatbots, warts and all.", "commonMistake": "Imagining AI learned from carefully chosen sources only.", "mentalModel": "The web is the textbook."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:1d825ec5303f$ml$]::text[]),
($ml$2f2ea88e-0269-565b-b15e-52a1aca55bca$ml$::uuid, $ml$ai$ml$, 13, 3, $ml${"id": "ai-d13-c3", "title": "Free crawl or paid archive?", "lessonTitle": "Where training data comes from", "slot": 3, "type": "decide", "brief": {"headline": "You run a startup training a model for insurance claims. You can use free web crawls, pay to license a specialist archive, or mix the two.", "kicker": "Decide which data gives you an edge worth paying for.", "fullText": "Common Crawl's free archive holds more than 300 billion pages, and its monthly crawls capture roughly 2.3 to 2.7 billion more. About 82% of GPT-3's raw training tokens came from filtered Common Crawl.\n\nLicensed data costs money but can offer what the open web lacks. In 2024, Reddit agreed to license its content to Google for AI training. Where the data comes from shapes what a model costs and the risks it carries.", "sources": [{"url": "https://aws.amazon.com/fr/blogs/publicsector/how-common-crawl-and-aws-open-data-built-the-foundation-for-the-ai-revolution/", "label": "AWS Public Sector Blog, Common Crawl and the AI revolution"}, {"url": "https://cyprus-mail.com/2024/02/22/reddit-to-license-content-to-google-for-ai-training", "label": "Reuters via Cyprus Mail, Reddit to license content to Google, Feb 2024"}]}, "evidence": {"kind": "faceOff", "prompt": "Which source can give you something rivals do not have?", "left": {"name": "Common Crawl", "note": "Over 300 billion public pages, free to all"}, "right": {"name": "A licensed specialist archive", "note": "Content not on the open web"}, "correctIndex": 1, "explanation": "Free crawls are the same for everyone. Licensed data can fill the gaps the open web leaves."}, "numbers": {"kind": "numberSense", "prompt": "Common Crawl's monthly crawls capture roughly how many billion pages?", "min": 0, "max": 10, "value": 2.5, "unit": "B", "explanation": "About 2.3 to 2.7 billion a month. Plenty of general text, little of it about your claims."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "You're hired as the startup's data lead. The founder wants to train only on Common Crawl.", "prompt": "What do you propose?", "options": ["Drop web data and use only a license", "Add data the open web lacks for our field", "Agree, since free data is always enough"], "correctIndex": 1, "consequences": ["Web data still gives broad language skills cheaply.", "General text plus specialist data gives you both breadth and an edge.", "Free data is what every rival also has."], "explanation": "Mix free breadth with licensed depth. Name the sources and what each adds."}, "proReasoning": "A good data lead explains what each source adds and what it costs.", "commonMistake": "Treating the data choice as all or nothing.", "mentalModel": "Free for breadth, paid for depth."}, "invest": {"call": {"kind": "theCall", "situation": "You're asked to fund the startup. It plans to license a specialist archive.", "prompt": "What do you want to know about that license?", "options": ["Whether the archive has a nice name", "Nothing, since licensed data is always safe", "Whether rivals can license it too"], "correctIndex": 2, "consequences": ["Names do not make data unique.", "Terms still matter: price, renewal and exclusivity.", "An exclusive or hard-to-get source is a real edge."], "explanation": "Data shapes cost and risk. Unique access is what makes paying for it worthwhile."}, "proReasoning": "Investors ask whether a data advantage can be bought by rivals tomorrow.", "commonMistake": "Assuming any paid data is a moat.", "mentalModel": "Ask if rivals can buy it too."}, "build_startup": {"call": {"kind": "theCall", "situation": "You're the founder, with a tight budget.", "prompt": "What's the smartest data plan?", "options": ["Start free, license only the niche that matters", "License everything before training anything", "Use only free data and hope it is enough"], "correctIndex": 0, "consequences": ["You pay only for what the open web cannot give you.", "Paying for general text wastes money the web gives away.", "Rivals have the same free data."], "explanation": "Public web data is free to everyone. Spend on the data nobody else has."}, "proReasoning": "Founders spend data budgets where free sources fall short.", "commonMistake": "Paying for what is free, or skipping what is unique.", "mentalModel": "Pay only for the gap."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend asks why AI companies pay for data when the web is free.", "prompt": "What's the answer?", "options": ["Paying for data makes models run faster", "Paid data can offer what the web lacks", "Free web data is illegal for AI to use"], "correctIndex": 1, "consequences": ["Speed depends on the model, not the price of data.", "Licensed content can be unique, current or specialized.", "Most big models trained on free web data."], "explanation": "Free data is shared by all. Paid data can fill gaps and set a model apart."}, "proReasoning": "People pay for what they cannot get free. In AI, that is unique data.", "commonMistake": "Thinking free and paid data are interchangeable.", "mentalModel": "Pay for what is missing."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:6202c4c14d4c$ml$]::text[]),
($ml$42bb82b9-6b4a-5c9d-8105-0f0113b32d30$ml$::uuid, $ml$ai$ml$, 14, 1, $ml${"id": "ai-d14-c1", "title": "Suing one, licensing another", "lessonTitle": "What AI companies pay for content", "slot": 1, "type": "apply", "brief": {"headline": "In May 2025, The New York Times licensed its content to Amazon for AI, while still suing OpenAI and Microsoft. The Wall Street Journal reported the deal is worth $20 million to $25 million a year.", "kicker": "Apply day 14: content owners now set a price on AI use.", "fullText": "The deal lets Amazon train its AI models on content from The New York Times, including The Athletic and NYT Cooking, and offer summaries and excerpts through Alexa. The companies did not disclose terms when they announced it in May 2025. The Journal later reported Amazon would pay $20 million to $25 million a year, nearly 1% of The Times' 2024 revenue.\n\nThe Times sued OpenAI and Microsoft in 2023, alleging they trained on its content without permission, and that case is ongoing.\n\nThe day 14 pattern: money now flows from AI companies to content owners. An owner can license to one company and go to court with another.", "sources": [{"url": "https://www.engadget.com/ai/the-new-york-times-and-amazons-ai-licensing-deal-is-reportedly-worth-up-to-25-million-per-year-135523853/", "label": "Engadget, NYT and Amazon AI deal worth up to $25 million a year, Jul 2025"}, {"url": "https://cyprus-mail.com/2024/02/22/reddit-to-license-content-to-google-for-ai-training", "label": "Reuters via Cyprus Mail, Reddit to license content to Google, Feb 2024"}]}, "evidence": {"kind": "spotFake", "prompt": "One of these is false about the Times deal. Tap it.", "statements": ["Amazon can train its models on Times content.", "Amazon can offer Times summaries through Alexa.", "The Times dropped its lawsuit against OpenAI."], "fakeIndex": 2, "explanation": "The lawsuit against OpenAI and Microsoft continued. Licensing and suing went on side by side."}, "numbers": {"kind": "numberSense", "prompt": "At $25 million a year, how many million dollars would the deal bring over five years?", "min": 0, "max": 300, "value": 125, "unit": "M", "explanation": "About $125 million, in the same range as News Corp's reported $250 million over five years."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "You're offered a partnerships role at a publisher that negotiates with AI companies.", "prompt": "What's the core of that job?", "options": ["Pricing content AI firms can't get elsewhere", "Blocking every AI company from the archive", "Giving all content away for the exposure"], "correctIndex": 0, "consequences": ["Deals like the Times and Amazon one need people to price them.", "The Times licenses to some companies and sues others.", "Giving it away is what licensing replaced."], "explanation": "Partnerships and business development teams run these deals. That is an AI career path too."}, "proReasoning": "Partnership roles turn content into recurring AI revenue. Knowing what makes content valuable is the skill.", "commonMistake": "Thinking AI careers are only for engineers.", "mentalModel": "Someone has to price the content."}, "invest": {"call": {"kind": "theCall", "situation": "You follow a publisher's stock. It signs an AI deal worth $20 million to $25 million a year.", "prompt": "How do you read it?", "options": ["A sign it dropped all its lawsuits", "A new recurring revenue line to track", "Enough to replace subscription income"], "correctIndex": 1, "consequences": ["The Times kept suing OpenAI.", "Content can be licensed again and again.", "It is nearly 1% of 2024 revenue, not a replacement."], "explanation": "Content can become recurring revenue. Watch who owns hard-to-copy data."}, "proReasoning": "Investors size a licensing deal against total revenue. A new line can matter without being huge.", "commonMistake": "Overstating or dismissing a deal without sizing it.", "mentalModel": "Size the deal against the business."}, "build_startup": {"call": {"kind": "theCall", "situation": "You run a small specialist news site. Big publishers keep signing AI deals.", "prompt": "What's your move?", "options": ["Assume only giants get deals and do nothing", "Give it away free to get cited", "Test whether AI firms would pay for your archive"], "correctIndex": 2, "consequences": ["Smaller owners rarely get deals, but rarely is not never.", "Free use is what licensing replaced.", "Niche, current content can be exactly what labs lack."], "explanation": "Big platforms sign big deals. Smaller owners need to test whether their content has a buyer."}, "proReasoning": "Founders test demand before assuming it is not there. A niche archive can be worth licensing.", "commonMistake": "Assuming the market only pays the biggest names.", "mentalModel": "Test the buyer before giving up."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend asks why the Times would sue OpenAI but sell to Amazon.", "prompt": "What's the best explanation?", "options": ["Licensing sets terms; suing fights unpaid use", "It simply changed its mind about AI tools", "Amazon now owns The New York Times outright"], "correctIndex": 0, "consequences": ["Paid, agreed use is different from alleged unpaid use.", "It still sues one company while licensing another.", "Amazon is a licensee, not an owner."], "explanation": "Owners can charge for content. They license where they agree terms and sue where they say none were agreed."}, "proReasoning": "The same owner can license and sue. The difference is whether terms were agreed.", "commonMistake": "Seeing it as contradiction rather than pricing.", "mentalModel": "License or litigate: it is about terms."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:c82ff2ed68fd$ml$]::text[]),
($ml$f78a9dc9-9686-5f30-b8d6-05f0a6468502$ml$::uuid, $ml$ai$ml$, 14, 2, $ml${"id": "ai-d14-c2", "title": "A new line in the money flow", "lessonTitle": "What AI companies pay for content", "slot": 2, "type": "connect", "brief": {"headline": "On day 2, money flowed down the stack: users pay apps, apps pay model makers, model makers pay for compute. Now some of it goes to content owners: about $60 million a year from Google to Reddit.", "kicker": "Connect day 2 and day 14: content owners joined the money flow.", "fullText": "On day 2 you followed one dollar from a user down to the chipmaker. NVIDIA's data center business took in $193.7 billion in fiscal 2026.\n\nOn day 14 you saw a new branch. Reuters reported Reddit's AI licensing deal with Google is worth about $60 million a year. OpenAI's deal with News Corp could be worth more than $250 million over five years, according to The Wall Street Journal.\n\nThose sums are small next to compute spending. But they are new revenue for owners of content that is unique, current or hard to collect.", "sources": [{"url": "https://www.sec.gov/Archives/edgar/data/1045810/000104581026000019/q4fy26pr.htm", "label": "NVIDIA fiscal 2026 results"}, {"url": "https://cyprus-mail.com/2024/02/22/reddit-to-license-content-to-google-for-ai-training", "label": "Reuters via Cyprus Mail, Reddit to license content to Google, Feb 2024"}, {"url": "https://www.bnnbloomberg.ca/openai-inks-deal-with-wall-street-journal-publisher-news-corp-1.2076258", "label": "BNN Bloomberg, OpenAI inks deal with News Corp, May 2024"}]}, "evidence": {"kind": "sortSignal", "prompt": "Is each payment down the stack, or to a content owner?", "buckets": ["Down the stack", "To content owners"], "items": [{"text": "An app paying a model maker", "bucket": 0}, {"text": "A model maker paying for cloud compute", "bucket": 0}, {"text": "A cloud buying chips", "bucket": 0}, {"text": "Google paying Reddit for its posts", "bucket": 1}, {"text": "OpenAI paying News Corp for articles", "bucket": 1}], "explanation": "Most money still flows down to compute. Content deals add a smaller, newer branch."}, "numbers": {"kind": "numberSense", "prompt": "News Corp's deal could be worth over $250 million in five years. About how many million a year?", "min": 0, "max": 150, "value": 50, "unit": "M", "explanation": "About $50 million a year, close to Reddit's reported $60 million."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "You're interviewing for a finance role at an AI lab. They ask you to list its main costs.", "prompt": "What's the most complete answer?", "options": ["Content licenses above everything else", "Compute, people, and now content licenses", "Compute only, since data is free"], "correctIndex": 1, "consequences": ["Compute spending is far larger than content deals.", "Licensing is a real, newer line next to compute.", "Labs now pay tens of millions a year for content."], "explanation": "Money still flows mostly to compute, but content owners now get a share."}, "proReasoning": "Name the cost lines and their rough size. Content is new and real, but smaller than compute.", "commonMistake": "Leaving content out, or overstating it.", "mentalModel": "Name every cost line, in order."}, "invest": {"call": {"kind": "theCall", "situation": "You want exposure to AI spending and compare chips with content licensing.", "prompt": "Where is the bigger revenue stream today?", "options": ["Content licensing, by a wide margin", "They are about the same size", "Chips, by a very wide margin"], "correctIndex": 2, "consequences": ["The biggest content deals run tens of millions a year.", "They differ by thousands of times.", "NVIDIA's data centers took $193.7 billion in one year."], "explanation": "Content is a new branch of the money flow, but most money still flows down to compute."}, "proReasoning": "Investors size each branch of the flow. A new one can grow fast and still be small.", "commonMistake": "Treating a new revenue line as the main one.", "mentalModel": "Size each branch of the flow."}, "build_startup": {"call": {"kind": "theCall", "situation": "You run an AI app. Licensed news content would make your answers more current.", "prompt": "How should you treat that cost?", "options": ["Budget for content like any other input", "Assume content will always be free", "Skip it, since only giants license"], "correctIndex": 0, "consequences": ["Content is now a line item like compute.", "Owners now charge for AI use.", "Deals exist at many sizes, not only giant ones."], "explanation": "Money now flows from AI companies to content owners. Plan for it."}, "proReasoning": "Founders treat quality content as an input with a price, like compute.", "commonMistake": "Assuming yesterday's free content is still free.", "mentalModel": "Content is an input with a price."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend asks whether Reddit gets paid when AI learns from posts.", "prompt": "What's the answer?", "options": ["Yes, every poster gets a check in the mail", "Yes, it licensed its content to Google", "No, AI is not allowed to use Reddit posts"], "correctIndex": 1, "consequences": ["The deal pays Reddit, the platform.", "Reuters reported about $60 million a year.", "Google licensed the posts for AI training."], "explanation": "Data owners can now charge AI companies for access. Reddit is one of them."}, "proReasoning": "Your posts may train an AI, and the platform that hosts them may be paid for it.", "commonMistake": "Assuming the people who wrote the posts get paid.", "mentalModel": "The platform gets the check."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:6cf066436962$ml$]::text[]),
($ml$71a958af-b82b-508f-ad0d-e3d564695996$ml$::uuid, $ml$ai$ml$, 14, 3, $ml${"id": "ai-d14-c3", "title": "Pricing an archive", "lessonTitle": "What AI companies pay for content", "slot": 3, "type": "decide", "brief": {"headline": "You run a mid-sized specialist publisher. An AI lab offers a one-time payment for your whole archive, or a yearly fee for ongoing access to new articles.", "kicker": "Decide how to license your content.", "fullText": "Reuters reported in February 2024 that Reddit's AI licensing deal with Google was worth about $60 million a year. In May 2024, OpenAI struck a deal to use content from more than a dozen News Corp publications, which The Wall Street Journal said could be worth more than $250 million over five years.\n\nLabs pay for content that is unique, current or hard to collect. Owners of that content gain a new revenue line, and content can be licensed again and again.", "sources": [{"url": "https://cyprus-mail.com/2024/02/22/reddit-to-license-content-to-google-for-ai-training", "label": "Reuters via Cyprus Mail, Reddit to license content to Google, Feb 2024"}, {"url": "https://www.bnnbloomberg.ca/openai-inks-deal-with-wall-street-journal-publisher-news-corp-1.2076258", "label": "BNN Bloomberg, OpenAI inks deal with News Corp, May 2024"}]}, "evidence": {"kind": "multipleChoice", "prompt": "What makes content worth paying for to an AI lab?", "options": ["It is old and already free on the web", "It is unique, current or hard to collect", "It is long and written in plain English"], "correctIndex": 1, "explanation": "Labs pay for what they cannot easily get elsewhere. Public, old text they already have."}, "numbers": {"kind": "numberSense", "prompt": "At about $60 million a year, how many million would Reddit's deal total over five years?", "min": 0, "max": 800, "value": 300, "unit": "M", "explanation": "About $300 million, slightly more than the News Corp deal over the same period."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "You're the publisher's new head of partnerships, preparing for the lab meeting.", "prompt": "What do you lead with?", "options": ["How old and how large our archive is", "How much we admire the lab and its work", "What we have that the open web does not"], "correctIndex": 2, "consequences": ["Old public text is what they already have.", "Flattery does not set a price.", "Unique, current content is what labs pay for."], "explanation": "Labs pay for content that is unique, current or hard to collect. Sell that."}, "proReasoning": "Lead with scarcity. What only you have is what sets the price.", "commonMistake": "Selling volume when the buyer wants uniqueness.", "mentalModel": "Sell what only you have."}, "invest": {"call": {"kind": "theCall", "situation": "You're looking at the publisher as an investment after it signs a yearly AI deal.", "prompt": "What makes the deal more valuable?", "options": ["That it renews as new content arrives", "That it was announced with a big launch", "That it was a one-time payment"], "correctIndex": 0, "consequences": ["Recurring revenue is worth more than a single check.", "Announcements do not pay the bills.", "One-time money does not repeat."], "explanation": "Content can become recurring revenue. Renewals tied to new content are what to watch."}, "proReasoning": "Investors value recurring licensing above one-off sales. Fresh content keeps the buyer coming back.", "commonMistake": "Valuing a one-time payment like a recurring one.", "mentalModel": "Recurring beats one-time."}, "build_startup": {"call": {"kind": "theCall", "situation": "You're the publisher's founder, choosing between the two offers.", "prompt": "Which do you prefer?", "options": ["Neither, since AI deals never pay", "The yearly fee for ongoing content", "One payment for everything, forever"], "correctIndex": 1, "consequences": ["Deals like Reddit's pay tens of millions a year.", "New articles keep their value, and so does the deal.", "You would sell all future value for one check."], "explanation": "Current content keeps being valuable. A recurring fee lets you keep being paid for it."}, "proReasoning": "Founders license what keeps getting made on recurring terms. That turns writing into steady revenue.", "commonMistake": "Selling a stream for a single payment.", "mentalModel": "License the stream, not just the archive."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend asks why labs pay News Corp more than a small blog.", "prompt": "What's the answer?", "options": ["It complains more loudly than small blogs", "Labs pay every content owner the same rate", "Its content is current and hard to replace"], "correctIndex": 2, "consequences": ["Prices follow value, not volume of complaints.", "Deals vary widely by what the content offers.", "More than a dozen publications of fresh, unique news."], "explanation": "Labs pay more for content that is unique, current and hard to collect, at scale."}, "proReasoning": "Prices follow what is scarce and useful. Big, fresh, unique archives command more.", "commonMistake": "Thinking content prices are arbitrary.", "mentalModel": "Scarce and current earns more."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:3d5575837186$ml$]::text[]),
($ml$69dd0271-9377-5ec8-bf88-d8ab8868084b$ml$::uuid, $ml$ai$ml$, 15, 1, $ml${"id": "ai-d15-c1", "title": "Headnotes that were not fair game", "lessonTitle": "A $1.5 billion lesson about data", "slot": 1, "type": "apply", "brief": {"headline": "In February 2025, a US judge ruled that Ross Intelligence's use of Westlaw headnotes to train an AI legal search tool was not fair use. Ross had copied 2,243 of them to build a competitor.", "kicker": "Apply day 15: fair use depends on what you copied and why.", "fullText": "Thomson Reuters owns Westlaw, a legal research service whose editors write headnotes summarizing court decisions. Ross built a rival AI search tool using material drawn from Westlaw. On February 11, 2025, Judge Stephanos Bibas found that Ross copied the original elements of 2,243 headnotes, out of a batch of 2,830, and rejected its fair use defense. The use was commercial, not transformative, and likely meant to compete with Westlaw. He noted that the case involved only non-generative AI.\n\nCompare day 15. Judge William Alsup ruled that training on books was fair use because it was transformative, yet Anthropic still agreed to pay $1.5 billion over pirated copies. Courts look at what you copied, how you got it, and whether your product competes with the source.", "sources": [{"url": "https://www.venable.com/insights/publications/2025/02/judge-rejects-fair-use-defense-in-thompson-reuters", "label": "Venable, Judge rejects fair use defense in Thomson Reuters v. Ross, Feb 2025"}, {"url": "https://www.kpbs.org/news/science-technology/2025/09/05/anthropic-to-pay-authors-1-5b-to-settle-lawsuit-over-pirated-chatbot-training-material", "label": "NPR via KPBS, Anthropic to pay authors $1.5 billion, Sep 2025"}]}, "evidence": {"kind": "faceOff", "prompt": "In which case did a judge find the AI training itself was fair use?", "left": {"name": "Anthropic's books case", "note": "Training on books called transformative"}, "right": {"name": "Thomson Reuters against Ross", "note": "Headnotes copied to build a rival tool"}, "correctIndex": 0, "explanation": "Alsup called training on books transformative. Bibas found Ross's copying was commercial and aimed at a competitor."}, "numbers": {"kind": "numberSense", "prompt": "Ross copied 2,243 headnotes out of a batch of 2,830. Roughly what share?", "min": 0, "max": 100, "value": 79, "unit": "%", "explanation": "About 79%. Most of the batch, taken to build a direct rival."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "You're interviewing at a legal AI startup. They ask what the Ross ruling means for them.", "prompt": "What's the best answer?", "options": ["Fair use always protects AI training data", "Copying a rival's content to compete is risky", "All AI training is now illegal in the US"], "correctIndex": 1, "consequences": ["Ross lost its fair use defense.", "The use was commercial and aimed at Westlaw's market.", "Alsup found training on books was fair use."], "explanation": "Fair use depends on the facts: what was copied, how, and whether it competes with the source."}, "proReasoning": "Show you know rulings differ by facts. Ross and Anthropic point in different directions for clear reasons.", "commonMistake": "Summarizing AI copyright law in one sweeping rule.", "mentalModel": "Rulings turn on the facts."}, "invest": {"call": {"kind": "theCall", "situation": "An AI startup's training data came largely from a direct competitor's product.", "prompt": "How do you treat that?", "options": ["As fine, since AI training is fair use", "As a plus, since the data is high quality", "As a serious legal risk to price in"], "correctIndex": 2, "consequences": ["Ross shows fair use is not guaranteed.", "Quality does not cure how it was obtained.", "That is close to the facts Ross lost on."], "explanation": "How you got the data matters as much as what you do with it. Legal risk is a data cost."}, "proReasoning": "Investors ask where training data came from, especially if it came from a rival.", "commonMistake": "Assuming one favorable ruling covers every case.", "mentalModel": "Provenance is part of the price."}, "build_startup": {"call": {"kind": "theCall", "situation": "You're building a legal search AI. Westlaw-style summaries would be perfect training data.", "prompt": "How do you get it?", "options": ["License it or write your own summaries", "Copy them, since AI training is fair use", "Copy only a few thousand of them"], "correctIndex": 0, "consequences": ["Lawful data avoids the trap Ross fell into.", "Ross made that argument and lost.", "Ross copied 2,243, and that was enough to lose."], "explanation": "Use only data you obtained lawfully, especially when you compete with its owner."}, "proReasoning": "Founders get data the clean way when they compete with its owner.", "commonMistake": "Copying a competitor and hoping fair use covers it.", "mentalModel": "Never train on a rival's work without a license."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend says: didn't a judge rule AI training was fair use? How did Ross lose?", "prompt": "What's the answer?", "options": ["Ross trained on pirated novels", "It copied a rival's work to compete with it", "Ross used a chatbot to write its code"], "correctIndex": 1, "consequences": ["The material was Westlaw headnotes, not novels.", "Commercial copying aimed at Westlaw's market weighed against it.", "The case involved non-generative AI."], "explanation": "Different facts, different results. Ross copied to build a direct competitor."}, "proReasoning": "Two rulings can both be right if the facts differ. Ask what was copied and why.", "commonMistake": "Treating court rulings as contradicting each other.", "mentalModel": "Different facts, different rulings."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:7ed424b4d814$ml$]::text[]),
($ml$ef6aa165-ff6a-5dd9-8b4e-bf729b3c64cd$ml$::uuid, $ml$ai$ml$, 15, 2, $ml${"id": "ai-d15-c2", "title": "Pay up front, or pay in court", "lessonTitle": "A $1.5 billion lesson about data", "slot": 2, "type": "connect", "brief": {"headline": "OpenAI's News Corp deal could be worth more than $250 million over five years. Anthropic agreed to pay $1.5 billion, about $3,000 per book, to settle claims over pirated copies.", "kicker": "Connect day 14 and day 15: a license up front versus a bill later.", "fullText": "On day 14 you saw content owners get paid by license: about $60 million a year from Google to Reddit, and possibly more than $250 million over five years from OpenAI to News Corp.\n\nOn day 15 you saw what happens when data is taken the wrong way. Judge Alsup found Anthropic had downloaded more than 7 million books it knew had been pirated. Anthropic agreed to pay $1.5 billion, about $3,000 each for an estimated 500,000 books, subject to court approval.\n\nA license is a known cost, agreed in advance. A settlement is a cost set later, under pressure.", "sources": [{"url": "https://cyprus-mail.com/2024/02/22/reddit-to-license-content-to-google-for-ai-training", "label": "Reuters via Cyprus Mail, Reddit to license content to Google, Feb 2024"}, {"url": "https://www.bnnbloomberg.ca/openai-inks-deal-with-wall-street-journal-publisher-news-corp-1.2076258", "label": "BNN Bloomberg, OpenAI inks deal with News Corp, May 2024"}, {"url": "https://www.kpbs.org/news/science-technology/2025/09/05/anthropic-to-pay-authors-1-5b-to-settle-lawsuit-over-pirated-chatbot-training-material", "label": "NPR via KPBS, Anthropic to pay authors $1.5 billion, Sep 2025"}]}, "evidence": {"kind": "sortSignal", "prompt": "Was each payment a license or a settlement?", "buckets": ["Licensed up front", "Paid after a lawsuit"], "items": [{"text": "Google and Reddit, about $60 million a year", "bucket": 0}, {"text": "OpenAI and News Corp, over $250 million", "bucket": 0}, {"text": "Anthropic and authors, $1.5 billion", "bucket": 1}, {"text": "About $3,000 for each book", "bucket": 1}], "explanation": "Licenses are agreed before use. The settlement came after a court found pirated copies."}, "numbers": {"kind": "numberSense", "prompt": "About 500,000 books at about $3,000 each comes to how many billion dollars?", "min": 0, "max": 5, "value": 1.5, "unit": "B", "explanation": "$1.5 billion, six times News Corp's reported five-year deal."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "You're on an AI lab's legal team. Engineers want to use a book collection of unclear origin.", "prompt": "What do you advise?", "options": ["Use it now and plan to settle later if sued", "Use it, since training on books is fair use", "License or buy copies before using them"], "correctIndex": 2, "consequences": ["Anthropic's later bill was $1.5 billion.", "Training was fair use; pirated copies were not.", "Licensing sets the price before use, not after."], "explanation": "How you got the data matters as much as what you do with it."}, "proReasoning": "Legal teams compare the cost of a license with the risk of a settlement. The license usually wins.", "commonMistake": "Treating \"fair use\" as covering how the data was obtained.", "mentalModel": "A known cost beats a court bill."}, "invest": {"call": {"kind": "theCall", "situation": "Two labs: one licenses its content, the other scraped widely and says it will fight claims.", "prompt": "Which carries less hidden cost?", "options": ["The one that licenses its content", "The one that scraped, since it paid nothing", "Both equal, since fair use applies"], "correctIndex": 0, "consequences": ["Its data costs are known in advance.", "Paying nothing up front can mean paying much more later.", "Fair use did not cover pirated downloads."], "explanation": "Legal risk is a data cost. Data with clean provenance is worth paying more for."}, "proReasoning": "Investors add expected legal costs to data costs. Clean data can be the cheaper data.", "commonMistake": "Counting free data as free.", "mentalModel": "Free data can cost the most."}, "build_startup": {"call": {"kind": "theCall", "situation": "Your startup needs books to train a writing assistant.", "prompt": "How do you source them?", "options": ["Use them now and settle if sued", "Buy or license the copies you use", "Download them from a pirate library"], "correctIndex": 1, "consequences": ["A settlement can dwarf what a license would cost.", "Lawful copies keep you out of Anthropic's position.", "That is exactly what led to the $1.5 billion bill."], "explanation": "Use only data you obtained lawfully. The cheap path can become the expensive one."}, "proReasoning": "Founders budget for lawful data from day one. It is cheaper than a settlement.", "commonMistake": "Planning to settle instead of planning to license.", "mentalModel": "Budget for lawful data."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend asks: if training on books was fair use, why pay $1.5 billion?", "prompt": "What's the answer?", "options": ["The judge banned training on books", "Anthropic lost a jury trial", "The pirated downloads were the problem"], "correctIndex": 2, "consequences": ["He ruled training on books was fair use.", "It was a settlement, subject to court approval.", "How the books were obtained led to the settlement."], "explanation": "Using the books was fine. Getting them from pirate sites was not."}, "proReasoning": "Separate what you did with something from how you got it. Courts do.", "commonMistake": "Thinking fair use covers everything about the data.", "mentalModel": "How you got it matters."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:5978aa6b9f93$ml$]::text[]),
($ml$10f52139-d70f-5aca-a019-d392301cd766$ml$::uuid, $ml$ai$ml$, 15, 3, $ml${"id": "ai-d15-c3", "title": "Files from a pirate library", "lessonTitle": "A $1.5 billion lesson about data", "slot": 3, "type": "decide", "brief": {"headline": "You run data at an AI startup. An audit finds that part of your training set came from a pirate library of books.", "kicker": "Decide what to do with data obtained the wrong way.", "fullText": "In June 2025, Judge William Alsup ruled that training AI on copyrighted books was fair use because it was quintessentially transformative. He also found that Anthropic had downloaded more than 7 million digitized books it knew had been pirated.\n\nIn September 2025, Anthropic agreed to pay $1.5 billion, about $3,000 per work for an estimated 500,000 books, subject to court approval. In AI, how you got the data matters as much as what you do with it.", "sources": [{"url": "https://www.kpbs.org/news/science-technology/2025/09/05/anthropic-to-pay-authors-1-5b-to-settle-lawsuit-over-pirated-chatbot-training-material", "label": "NPR via KPBS, Anthropic to pay authors $1.5 billion, Sep 2025"}]}, "evidence": {"kind": "buildChain", "prompt": "Put a sound response in order.", "steps": ["Identify exactly which files came from the pirate library", "Remove them from the training set", "Replace them with lawfully obtained copies", "Record where every dataset came from"], "explanation": "Find it, remove it, replace it, and keep records so it does not happen again."}, "numbers": {"kind": "numberSense", "prompt": "At about $3,000 per work, what would 10,000 pirated books cost, in millions of dollars?", "min": 0, "max": 100, "value": 30, "unit": "M", "explanation": "$30 million at the same rate, for a startup that may have saved little by pirating."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "You're the junior engineer who found the pirate files during the audit.", "prompt": "What do you do?", "options": ["Report it to your lead with the file list", "Delete them quietly and say nothing", "Ignore it, since training is fair use"], "correctIndex": 0, "consequences": ["Clear reporting lets the company fix it properly.", "Quiet deletion leaves no record of what was used.", "Fair use covered training, not pirated copies."], "explanation": "Data provenance problems need to be surfaced, not hidden."}, "proReasoning": "Raising a provenance problem early, with specifics, protects you and the company.", "commonMistake": "Hiding a problem to avoid an awkward conversation.", "mentalModel": "Surface it with specifics."}, "invest": {"call": {"kind": "theCall", "situation": "During due diligence, you learn about the startup's pirate library files.", "prompt": "What do you ask for?", "options": ["Nothing, since everyone does it", "A full record of where its data came from", "A promise that nobody will find out"], "correctIndex": 1, "consequences": ["Anthropic paid $1.5 billion; \"everyone does it\" is no defense.", "Provenance records show the size of the exposure.", "Hoping it stays hidden is not a plan."], "explanation": "Legal risk is a data cost. Clean, documented provenance is worth paying for."}, "proReasoning": "Investors ask for data provenance the way they ask for financial records.", "commonMistake": "Treating data sourcing as an engineering detail.", "mentalModel": "Ask for the data paper trail."}, "build_startup": {"call": {"kind": "theCall", "situation": "You're the founder. Removing the files means retraining the model.", "prompt": "What's your decision?", "options": ["Keep them, since fair use covers it", "Keep them, and stop mentioning it", "Remove them and retrain on clean data"], "correctIndex": 2, "consequences": ["Fair use covered the training, not the pirated copies.", "Concealment makes the eventual cost worse.", "Retraining costs less than a settlement at $3,000 a book."], "explanation": "Use only data you obtained lawfully. Fixing it now is cheaper than paying later."}, "proReasoning": "Founders fix provenance problems while they are small. They only grow with time.", "commonMistake": "Betting that a known problem will stay hidden.", "mentalModel": "Fix it while it is small."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend asks what's the difference between training on a book and pirating it.", "prompt": "What's the answer?", "options": ["Training was fair use; pirating copies was not", "There is no difference between them in law", "Pirating is fine if only an AI reads the copy"], "correctIndex": 0, "consequences": ["The judge split the two, and the piracy cost $1.5 billion.", "The judge treated them very differently.", "That is the argument the settlement rejected in practice."], "explanation": "What you do with a book and how you got it are separate questions in court."}, "proReasoning": "Courts can bless the use and still punish how the copy was obtained.", "commonMistake": "Lumping use and acquisition together.", "mentalModel": "Use and acquisition are separate."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:c1644535d904$ml$]::text[]),
($ml$3d70732e-786a-5ab3-97df-38c123654c31$ml$::uuid, $ml$ai$ml$, 16, 1, $ml${"id": "ai-d16-c1", "title": "Peak data", "lessonTitle": "Is the internet running out of text?", "slot": 1, "type": "apply", "brief": {"headline": "At NeurIPS in December 2024, OpenAI co-founder Ilya Sutskever told researchers: \"We've achieved peak data and there'll be no more.\" He called the internet the fossil fuel of AI.", "kicker": "Apply day 16: what happens when the text runs short?", "fullText": "Sutskever, who left OpenAI in 2024 to start Safe Superintelligence, spoke in Vancouver on December 13, 2024. \"Pre-training as we know it will unquestionably end,\" he said. \"We have to deal with the data that we have. There's only one internet.\" He expected future models to reason step by step and to understand things from limited data.\n\nEpoch AI's numbers explain the worry. It estimates the stock of quality public human text at about 300 trillion tokens, which models could fully use between 2026 and 2032 at current trends. Meta's Llama 3 alone trained on 15 trillion tokens in 2024.", "sources": [{"url": "https://www.thelowdownblog.com/2024/12/openai-cofounder-says-peak-data-reached.html", "label": "The Verge via The Low-Down, Sutskever says peak data reached, Dec 2024"}, {"url": "https://epoch.ai/blog/will-we-run-out-of-data-limits-of-llm-scaling-based-on-human-generated-data", "label": "Epoch AI, Will we run out of data?, Jun 2024"}, {"url": "https://spectrum.ieee.org/meta-llama-3", "label": "IEEE Spectrum, Meta's Llama 3, Apr 2024"}]}, "evidence": {"kind": "multipleChoice", "prompt": "Why did Sutskever call the internet the fossil fuel of AI?", "options": ["It is a finite supply being used up", "It pollutes the models trained on it", "It powers the data centers directly"], "correctIndex": 0, "explanation": "Like oil, quality public text is finite. Models are burning through it."}, "numbers": {"kind": "numberSense", "prompt": "Epoch AI estimates about 300 trillion quality tokens; Llama 3 used 15 trillion. What share is that?", "min": 0, "max": 20, "value": 5, "unit": "%", "explanation": "About 5% for a single model. A few more generations of growth would reach the whole stock."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "You're interviewing at an AI lab right after the talk. They ask what limits scaling next.", "prompt": "What's the sharpest answer?", "options": ["Only the number of GPUs", "Nothing, since text is unlimited", "Data, not just compute"], "correctIndex": 2, "consequences": ["Chips are only part of it now.", "Epoch AI puts a number on the limit.", "About 300 trillion tokens, possibly used up by 2032."], "explanation": "In AI, data supply is becoming a limit, not just compute."}, "proReasoning": "Quote the data wall: about 300 trillion tokens, possibly used up between 2026 and 2032.", "commonMistake": "Talking only about chips when data is the new constraint.", "mentalModel": "Quote the data wall."}, "invest": {"call": {"kind": "theCall", "situation": "Leading researchers say public text is running out.", "prompt": "Who stands to gain?", "options": ["Owners of unique, quality data", "Sites full of copied text", "Nobody, since data prices will fall"], "correctIndex": 0, "consequences": ["Scarcity raises the value of what others cannot get.", "Copied text adds nothing new.", "Scarcity pushes prices up, not down."], "explanation": "If public text runs short, unique data gets more valuable. That helps explain deals like Reddit's."}, "proReasoning": "Investors look for owners of scarce inputs. Quality human data is becoming one.", "commonMistake": "Assuming data will stay cheap as it gets scarce.", "mentalModel": "Scarcity raises data prices."}, "build_startup": {"call": {"kind": "theCall", "situation": "You see \"peak data\" as an opening for a startup.", "prompt": "What do you build?", "options": ["A shop that resells GPUs", "A source of quality data crawls lack", "Another scraper of the same public web"], "correctIndex": 1, "consequences": ["GPUs do not solve the data shortage.", "New quality data is exactly what labs will need.", "The public web is the part being used up."], "explanation": "Training sets grew from 300 billion to 15 trillion tokens in four years. New quality data is in demand."}, "proReasoning": "Founders build where the next shortage is. Quality data is a strong candidate.", "commonMistake": "Building more of what is running out.", "mentalModel": "Build for the next shortage."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend asks how AI could possibly run out of internet.", "prompt": "What's the best explanation?", "options": ["Websites are being deleted faster than made", "AI forgets everything it has read before", "Good text is finite, and models use it fast"], "correctIndex": 2, "consequences": ["The limit is quality human text, not deleted sites.", "Training uses data; it does not forget it.", "About 300 trillion quality tokens, and Llama 3 used 15 trillion."], "explanation": "There is a lot of text, but not an endless supply of good human writing."}, "proReasoning": "Big is not infinite. When use grows fast enough, even a huge supply runs short.", "commonMistake": "Treating the internet as an endless resource.", "mentalModel": "Big is not infinite."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:091bc8cdf707$ml$]::text[]),
($ml$6a8cafaf-0a73-512b-aa99-bcdfafb630a5$ml$::uuid, $ml$ai$ml$, 16, 2, $ml${"id": "ai-d16-c2", "title": "How big can the web feed?", "lessonTitle": "Is the internet running out of text?", "slot": 2, "type": "connect", "brief": {"headline": "Chinchilla's rule is about 20 tokens per parameter. Epoch AI puts quality public human text at about 300 trillion tokens. Training sets are racing toward that limit.", "kicker": "Connect day 10 and day 16: the size rule meets the data supply.", "fullText": "On day 10 you learned Chinchilla's rule: train about 20 tokens for every parameter. On day 16 you saw the supply: about 300 trillion tokens of quality public human text, which models could use up between 2026 and 2032.\n\nSimple division gives a ceiling for a compute-optimal model trained once on all of it: about 15 trillion parameters. Training sets are racing toward the wall. GPT-3 trained on 300 billion tokens in 2020, and Llama 3 on 15 trillion in 2024.", "sources": [{"url": "https://download.arxiv.org/pdf/2203.15556.pdf", "label": "Hoffmann et al., Training compute-optimal large language models, 2022"}, {"url": "https://epoch.ai/blog/will-we-run-out-of-data-limits-of-llm-scaling-based-on-human-generated-data", "label": "Epoch AI, Will we run out of data?, Jun 2024"}, {"url": "https://ar5iv.labs.arxiv.org/html/2005.14165", "label": "Brown et al., Language models are few-shot learners, 2020"}, {"url": "https://spectrum.ieee.org/meta-llama-3", "label": "IEEE Spectrum, Meta's Llama 3, Apr 2024"}]}, "evidence": {"kind": "spotFake", "prompt": "One of these is false. Tap it.", "statements": ["GPT-3 trained on 300 billion tokens.", "Llama 3 trained on 15 trillion tokens.", "Epoch AI expects text to last well past 2050."], "fakeIndex": 2, "explanation": "Epoch AI estimates models could use up quality public text between 2026 and 2032."}, "numbers": {"kind": "numberSense", "prompt": "From 300 billion tokens (GPT-3) to 15 trillion (Llama 3): how many times more?", "min": 0, "max": 120, "value": 50, "unit": "x", "explanation": "50 times in four years. Another jump like that would pass the whole stock."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "An interviewer asks why labs care about a data wall if they can buy more chips.", "prompt": "What's your answer?", "options": ["Bigger models need proportionally more data", "Chips can generate new human-written text", "Data does not really affect model quality"], "correctIndex": 0, "consequences": ["At about 20 tokens per parameter, size is tied to data.", "Chips compute; they do not write human text.", "Chinchilla showed data matters as much as size."], "explanation": "Data and size grow together. Without more data, more chips buy less."}, "proReasoning": "Tie the two lessons: 20 tokens per parameter and a finite stock of text. Together they explain the wall.", "commonMistake": "Treating compute and data as separate problems.", "mentalModel": "Size is tied to data."}, "invest": {"call": {"kind": "theCall", "situation": "Training sets grew 50 times in four years. You are looking for assets that gain from that.", "prompt": "Which asset gains value as the wall nears?", "options": ["Old chips that cannot train well", "Quality text that no one else has", "Generic copies of public web pages"], "correctIndex": 1, "consequences": ["Old chips do not help with data.", "Unique human text becomes scarcer and pricier.", "Copies add no new tokens to the stock."], "explanation": "Data supply is becoming a limit. Unique quality text is what gains."}, "proReasoning": "Investors look at which input is closest to running out. Right now, that includes quality text.", "commonMistake": "Assuming the data supply will keep pace with model size.", "mentalModel": "Back the input that is running out."}, "build_startup": {"call": {"kind": "theCall", "situation": "You train models for a narrow industry and cannot get much more data.", "prompt": "What's the smart path?", "options": ["Keep building bigger models regardless", "Wait for the public web to grow big enough", "Keep models small and make your data count"], "correctIndex": 2, "consequences": ["Size without data wastes compute.", "Quality human text is not growing fast enough.", "Small models need less data and cost less to run."], "explanation": "When data is the limit, smaller well-trained models make the most of it."}, "proReasoning": "Founders size models to the data they can get, not the chips they can rent.", "commonMistake": "Scaling past what the data can support.", "mentalModel": "Size the model to the data."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend asks what happens to AI progress if good text runs out.", "prompt": "What's a fair answer?", "options": ["Bigger models stop paying off as easily", "AI stops working altogether overnight", "Nothing changes, since data never matters"], "correctIndex": 0, "consequences": ["Without data, bigger models gain less, so labs look for new methods.", "Existing models keep working.", "Chinchilla showed data matters as much as size."], "explanation": "The simple recipe of more data and bigger models gets harder. Labs look for other ways to improve."}, "proReasoning": "When one recipe runs out, progress shifts to new recipes. That is what researchers expect here.", "commonMistake": "Thinking a limit means an ending.", "mentalModel": "A limit changes the recipe."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:f635fcce431c$ml$]::text[]),
($ml$c2b16848-3d45-5845-85ed-f11f7307e86f$ml$::uuid, $ml$ai$ml$, 16, 3, $ml${"id": "ai-d16-c3", "title": "Where the next tokens come from", "lessonTitle": "Is the internet running out of text?", "slot": 3, "type": "decide", "brief": {"headline": "You run a lab planning a model that needs about 30 trillion tokens, twice what Llama 3 used. Quality public text is limited, and rivals are crawling the same web.", "kicker": "Decide where your next tokens come from.", "fullText": "In June 2024, Epoch AI estimated the effective stock of quality, public, human-generated text at around 300 trillion tokens. At current trends, language models could fully use it between 2026 and 2032, or earlier if models are heavily overtrained.\n\nMeta's Llama 3, released in April 2024, trained on 15 trillion tokens, more than seven times Llama 2's 2 trillion. In AI, data supply is becoming a limit, not just compute.", "sources": [{"url": "https://epoch.ai/blog/will-we-run-out-of-data-limits-of-llm-scaling-based-on-human-generated-data", "label": "Epoch AI, Will we run out of data?, Jun 2024"}, {"url": "https://spectrum.ieee.org/meta-llama-3", "label": "IEEE Spectrum, Meta's Llama 3, Apr 2024"}]}, "evidence": {"kind": "sortSignal", "prompt": "Does each option add new quality data?", "buckets": ["Adds new data", "Doesn't add data"], "items": [{"text": "Licensing a platform's archive", "bucket": 0}, {"text": "Data from your own product, with consent", "bucket": 0}, {"text": "Crawling the same public web again", "bucket": 1}, {"text": "Copying another crawl of the same pages", "bucket": 1}], "explanation": "Recrawling the shared web adds little. New quality data has to come from somewhere others have not tapped."}, "numbers": {"kind": "numberSense", "prompt": "A 30 trillion token model would use what share of the 300 trillion token stock?", "min": 0, "max": 50, "value": 10, "unit": "%", "explanation": "About 10% for one model, and every rival draws on the same stock."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "You're the lab's new data lead. The plan assumes the public web will supply 30 trillion tokens.", "prompt": "What do you flag?", "options": ["The plan should use fewer GPUs", "The shared web may not supply that much", "Nothing, since the web is endless"], "correctIndex": 1, "consequences": ["GPUs are not the constraint you were asked about.", "Quality public text is finite and shared with rivals.", "Epoch AI estimates about 300 trillion tokens in total."], "explanation": "A number like 300 trillion tokens frames any data plan."}, "proReasoning": "Put a number on the data supply before signing off on a plan that depends on it.", "commonMistake": "Assuming the data will be there because it always was.", "mentalModel": "Check the supply before the plan."}, "invest": {"call": {"kind": "theCall", "situation": "The lab asks you to fund its 30 trillion token model.", "prompt": "What do you want to see?", "options": ["Only the GPU budget and nothing else", "Only the name it plans for the model", "A plan for data beyond the public web"], "correctIndex": 2, "consequences": ["Compute without data is wasted.", "Names do not supply tokens.", "Unique data is the part rivals cannot copy."], "explanation": "Scarcity raises data prices. A credible plan names where the extra data comes from."}, "proReasoning": "Investors ask where the data comes from as hard as where the chips come from.", "commonMistake": "Funding compute without a data plan.", "mentalModel": "No data plan, no deal."}, "build_startup": {"call": {"kind": "theCall", "situation": "You're the lab's founder, short of quality data for the plan.", "prompt": "What's your move?", "options": ["License archives and use consented user data", "Recrawl the same public web more often", "Copy a rival's crawl of the same pages"], "correctIndex": 0, "consequences": ["Both add tokens rivals may not have.", "The same pages give the same tokens.", "A copy adds nothing new and adds risk."], "explanation": "New sources of quality data are in demand. Go where the shared web does not reach."}, "proReasoning": "Founders build data pipelines others cannot copy. That becomes the edge as the web runs dry.", "commonMistake": "Mining the same seam as everyone else.", "mentalModel": "Find data the web does not have."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend asks why AI companies now sign deals for old forum posts and archives.", "prompt": "What's the answer?", "options": ["Archives run faster on GPUs", "Quality text is getting scarce", "Old posts are funnier"], "correctIndex": 1, "consequences": ["Speed is not the point; tokens are.", "Models could use up public text by 2032.", "Humor is not the reason; supply is."], "explanation": "As public text runs short, archives become valuable sources of new tokens."}, "proReasoning": "When a resource gets scarce, people start paying for what used to be ignored.", "commonMistake": "Missing the supply story behind the deals.", "mentalModel": "Scarcity puts a price on the overlooked."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:99cb445909ae$ml$]::text[]),
($ml$27636c0a-19f3-5b0d-b4bb-45d73864a500$ml$::uuid, $ml$ai$ml$, 17, 1, $ml${"id": "ai-d17-c1", "title": "California asks for the homework", "lessonTitle": "Show what you trained on", "slot": 1, "type": "apply", "brief": {"headline": "Since January 1, 2026, California's AB 2013 has required generative AI developers to post a summary of their training data. xAI sued to block it, and in March 2026 a federal judge refused.", "kicker": "Apply day 17: regulators ask what you trained on.", "fullText": "The law, signed in September 2024, covers generative AI systems available to Californians, including models released since 2022. Developers must post a high-level summary covering at least 12 topics, such as dataset sources, whether the data includes copyrighted or personal information, whether it was bought or licensed, and whether synthetic data was used.\n\nxAI sued California's attorney general on December 29, 2025, arguing the law takes trade secrets and compels speech. It posted a limited disclosure the next day. On March 4, 2026, Judge Jesus G. Bernal denied a preliminary injunction, finding xAI had not shown it was likely to win. The case continues.\n\nThe EU has required a similar summary from general-purpose model providers since August 2, 2025.", "sources": [{"url": "https://ppc.land/court-denies-xais-bid-to-block-california-ai-training-data-law/", "label": "PPC Land, Court denies xAI's bid to block California AI training data law, 2026"}, {"url": "https://www.mayerbrown.com/en/insights/publications/2025/08/eu-ai-act-news-rules-on-general-purpose-ai-start-applying-guidelines-and-template-for-summary-of-training-data-finalized", "label": "Mayer Brown, EU AI Act rules on general-purpose AI start applying, Aug 2025"}]}, "evidence": {"kind": "spotFake", "prompt": "One of these is false about AB 2013. Tap it.", "statements": ["It took effect on January 1, 2026.", "Developers must say whether they used synthetic data.", "A judge struck the law down in March 2026."], "fakeIndex": 2, "explanation": "The judge denied xAI's request to block the law. It stayed in force while the case continues."}, "numbers": {"kind": "numberSense", "prompt": "AB 2013's summary must cover at least how many topics?", "min": 0, "max": 30, "value": 12, "unit": "topics", "explanation": "At least 12, from sources to copyright to synthetic data."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "You join the policy team at an AI lab that sells in California and the EU.", "prompt": "What's the most useful thing to build first?", "options": ["One data record that serves both summaries", "Nothing at all until the courts decide", "A claim that all of it is a trade secret"], "correctIndex": 0, "consequences": ["Both laws ask about sources and copyright, so one record serves both.", "The law stayed in force during the lawsuit.", "xAI argued that and did not win an injunction."], "explanation": "Policy and legal teams own disclosure work. Good records make it routine."}, "proReasoning": "Know the disclosure rules in each market and build one source of truth for them.", "commonMistake": "Waiting for a court to cancel a rule that is already in force.", "mentalModel": "One record, many disclosures."}, "invest": {"call": {"kind": "theCall", "situation": "A model maker posts its AB 2013 summary. It says the data includes copyrighted material.", "prompt": "What follows from that?", "options": ["The model must be taken offline", "Rights holders can read it and act", "Nothing, since summaries are secret"], "correctIndex": 1, "consequences": ["The law requires disclosure, not shutdown.", "Disclosure shows rights holders what was used.", "The summaries are posted publicly."], "explanation": "A public training summary shows rights holders what was used. That can invite claims."}, "proReasoning": "Investors read disclosures as maps of possible claims.", "commonMistake": "Treating disclosure as harmless paperwork.", "mentalModel": "Disclosure can create exposure."}, "build_startup": {"call": {"kind": "theCall", "situation": "You run a small model provider that must comply with AB 2013.", "prompt": "What's the efficient approach?", "options": ["Reconstruct it all at the end", "Skip it, since small firms are exempt", "Track sources as you collect data"], "correctIndex": 2, "consequences": ["Rebuilding history later is slow and error-prone.", "The exemptions cover uses like defense, not company size.", "Recording as you go makes the summary easy."], "explanation": "Big labs can staff disclosure work. Smaller providers need simple ways to document their data."}, "proReasoning": "Founders log data sources at collection time. It turns a legal task into a report.", "commonMistake": "Leaving documentation until a deadline.", "mentalModel": "Document as you collect."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend asks why xAI would fight a rule to describe its training data.", "prompt": "What's the answer?", "options": ["It says the details are trade secrets", "It has no training data at all to list", "California banned its chatbot outright"], "correctIndex": 0, "consequences": ["It also argued the law compels speech.", "All these models train on data.", "The law requires disclosure, not a ban."], "explanation": "Companies see their data choices as competitive secrets. Regulators want them visible."}, "proReasoning": "Disclosure fights are about what stays secret. Data sourcing is now one of those secrets.", "commonMistake": "Assuming companies resist only to hide wrongdoing.", "mentalModel": "Disclosure versus secrecy."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:8a5e8127a731$ml$]::text[]),
($ml$03b1d2dc-08ae-5134-b339-e1310085225c$ml$::uuid, $ml$ai$ml$, 17, 2, $ml${"id": "ai-d17-c2", "title": "Disclosure meets the courtroom", "lessonTitle": "Show what you trained on", "slot": 2, "type": "connect", "brief": {"headline": "Since August 2025, EU general-purpose AI providers must publish a summary of their training content. In 2025, Anthropic agreed to pay $1.5 billion after a judge found it had downloaded millions of pirated books.", "kicker": "Connect day 15 and day 17: what you disclose, others can check.", "fullText": "On day 15 you saw that how data is obtained matters: training on books was ruled fair use, but downloading more than 7 million pirated books led to a $1.5 billion settlement.\n\nOn day 17 you saw the EU require general-purpose AI providers to publish a summary of their training content, on a Commission template it calls a minimal baseline, and to maintain a copyright policy.\n\nA public summary makes sourcing choices visible to rights holders. Clean provenance becomes easier to show, and messy provenance harder to hide.", "sources": [{"url": "https://www.kpbs.org/news/science-technology/2025/09/05/anthropic-to-pay-authors-1-5b-to-settle-lawsuit-over-pirated-chatbot-training-material", "label": "NPR via KPBS, Anthropic to pay authors $1.5 billion, Sep 2025"}, {"url": "https://www.mayerbrown.com/en/insights/publications/2025/08/eu-ai-act-news-rules-on-general-purpose-ai-start-applying-guidelines-and-template-for-summary-of-training-data-finalized", "label": "Mayer Brown, EU AI Act rules on general-purpose AI start applying, Aug 2025"}]}, "evidence": {"kind": "multipleChoice", "prompt": "Why can a public training summary raise legal risk for a provider?", "options": ["Rights holders can see what was used", "It reveals the model's weights", "It doubles the cost of training"], "correctIndex": 0, "explanation": "The summary shows what kinds of content went in. Rights holders can then check their own work."}, "numbers": {"kind": "numberSense", "prompt": "Models on the market before August 2, 2025, have until August 2, 2027. How many years of grace?", "min": 0, "max": 10, "value": 2, "unit": "years", "explanation": "Two years for older models. New ones had to comply from the start."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "You're asked to help draft your lab's EU training summary.", "prompt": "What should you check before it is published?", "options": ["That it names as few sources as it possibly can", "That every listed source was lawfully obtained", "That the summary sounds impressive to readers"], "correctIndex": 1, "consequences": ["The template sets a minimum you must meet.", "Anything listed can be checked by rights holders.", "Tone does not change what it reveals."], "explanation": "Disclosure makes provenance visible. Check it before the world does."}, "proReasoning": "Treat a training summary like a public filing. Verify every source before it goes out.", "commonMistake": "Writing the summary without checking the data behind it.", "mentalModel": "Verify before you disclose."}, "invest": {"call": {"kind": "theCall", "situation": "A lab's published training summary is vague about where its books came from.", "prompt": "What do you ask?", "options": ["How long the summary is", "Nothing, since vagueness is safe", "How exactly its books were obtained"], "correctIndex": 2, "consequences": ["Length says nothing about provenance.", "Vague answers can hide the costliest risk.", "Book sourcing is what cost Anthropic $1.5 billion."], "explanation": "Legal risk is a data cost. Disclosure is where to start asking."}, "proReasoning": "Investors read training summaries for what is missing as much as for what is there.", "commonMistake": "Accepting vague disclosure at face value.", "mentalModel": "Read what the summary leaves out."}, "build_startup": {"call": {"kind": "theCall", "situation": "Your startup licenses all of its training data.", "prompt": "How can the EU summary help you?", "options": ["It lets you show clean provenance", "It forces rivals to share their data", "It removes your copyright duties"], "correctIndex": 0, "consequences": ["Clean sourcing becomes a visible selling point.", "Summaries describe data; they do not share it.", "You must still keep a copyright policy."], "explanation": "Disclosure exposes messy provenance and rewards clean provenance."}, "proReasoning": "Founders with clean data can turn a compliance task into a trust signal for buyers.", "commonMistake": "Treating disclosure only as a burden.", "mentalModel": "Clean data is a selling point."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend asks why the EU makes AI companies list what they trained on.", "prompt": "What's the main reason?", "options": ["To slow down AI progress on purpose", "So rights holders can see what was used", "So anyone can copy the models for free"], "correctIndex": 1, "consequences": ["The rule is about transparency, not speed.", "Sourcing choices become visible to the people whose work was used.", "Summaries describe content; they do not hand over models."], "explanation": "Training data is no longer a secret. Providers must say what kinds of content they used."}, "proReasoning": "Transparency rules let affected people check. That is their main job.", "commonMistake": "Assuming every rule is meant to slow AI down.", "mentalModel": "Transparency lets others check."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:1113bbc2e50f$ml$]::text[]),
($ml$5d423d4f-77da-56bc-b62b-c2441ef84920$ml$::uuid, $ml$ai$ml$, 17, 3, $ml${"id": "ai-d17-c3", "title": "Which deadline is yours?", "lessonTitle": "Show what you trained on", "slot": 3, "type": "decide", "brief": {"headline": "You run a model provider about to release a new general-purpose model in the EU in September 2025. An older model of yours has been on sale since 2024.", "kicker": "Decide what each model needs, and when.", "fullText": "Under the EU AI Act, obligations for general-purpose AI models started applying on August 2, 2025. Providers must publish a summary of training content using the Commission's template, which it calls a minimal baseline, and maintain a copyright policy.\n\nModels already on the market before that date have until August 2, 2027. The Commission can begin enforcement from August 2, 2026.", "sources": [{"url": "https://www.mayerbrown.com/en/insights/publications/2025/08/eu-ai-act-news-rules-on-general-purpose-ai-start-applying-guidelines-and-template-for-summary-of-training-data-finalized", "label": "Mayer Brown, EU AI Act rules on general-purpose AI start applying, Aug 2025"}]}, "evidence": {"kind": "sortSignal", "prompt": "When must each model have its training summary?", "buckets": ["From August 2025", "By August 2027"], "items": [{"text": "Your new model released in September 2025", "bucket": 0}, {"text": "Any new model launched in 2026", "bucket": 0}, {"text": "Your older model, on sale since 2024", "bucket": 1}, {"text": "A model already sold before August 2025", "bucket": 1}], "explanation": "New models comply from release. Models already on the market got until August 2, 2027."}, "numbers": {"kind": "numberSense", "prompt": "Your model ships in September 2025; enforcement can begin in August 2026. About how many months apart?", "min": 0, "max": 30, "value": 11, "unit": "months", "explanation": "About 11 months. The duty applies from release; enforcement only comes later."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "You're the provider's compliance lead. A manager says nothing is due until enforcement in 2026.", "prompt": "What do you say?", "options": ["Agreed, nothing is due until 2026", "Both models have until 2027", "The new model must comply from release"], "correctIndex": 2, "consequences": ["Duty and enforcement are different dates.", "Only models already on sale got until 2027.", "Obligations apply now; enforcement is when fines can start."], "explanation": "Know the difference between when a duty applies and when it can be enforced."}, "proReasoning": "Compliance people separate when a rule applies from when it is enforced.", "commonMistake": "Treating the enforcement date as the deadline.", "mentalModel": "Duty first, enforcement later."}, "invest": {"call": {"kind": "theCall", "situation": "The provider says compliance costs can wait until 2027.", "prompt": "How do you read that?", "options": ["Too late for its new model", "Fine, since all models get until 2027", "Fine, since summaries are optional"], "correctIndex": 0, "consequences": ["New models must comply from release in 2025.", "Only models already on the market get that grace.", "Publishing the summary is required."], "explanation": "Check which deadline applies to which product. Misreading it is a real risk."}, "proReasoning": "Investors check that management reads deadlines correctly. Mistakes here become fines.", "commonMistake": "Taking a company's reading of the rules on trust.", "mentalModel": "Check which deadline applies."}, "build_startup": {"call": {"kind": "theCall", "situation": "You're the founder. The new model launches in the EU in September 2025.", "prompt": "What do you prepare?", "options": ["Nothing until 2027, like older models", "The summary and copyright policy at launch", "Nothing until enforcement in 2026"], "correctIndex": 1, "consequences": ["Only models on sale before August 2025 got that grace.", "New models must comply from release.", "Enforcement is when fines can start, not when duties do."], "explanation": "New general-purpose models need a training summary and a copyright policy from day one."}, "proReasoning": "Founders put disclosure on the launch checklist, not the backlog.", "commonMistake": "Launching first and documenting later.", "mentalModel": "Disclose at launch."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend asks why older AI models got more time than new ones.", "prompt": "What's the likely reason?", "options": ["Older models are always much safer", "The law simply forgot about older models", "Documenting released models takes time"], "correctIndex": 2, "consequences": ["Age does not make a model safer.", "The law set a later date on purpose.", "New models can document as they go; old ones must look back."], "explanation": "Models already on sale got until August 2027 to catch up on documentation."}, "proReasoning": "Rules often give existing products a transition period. New products start under the new rules.", "commonMistake": "Reading a grace period as an exemption.", "mentalModel": "Grace for the old, rules for the new."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:36f335a04add$ml$]::text[]),
($ml$858e052e-f3e3-5b51-8330-fbfffb69e015$ml$::uuid, $ml$ai$ml$, 18, 1, $ml${"id": "ai-d18-c1", "title": "Half the new articles", "lessonTitle": "When AI trains on AI", "slot": 1, "type": "apply", "brief": {"headline": "An SEO firm sampled 65,000 web pages from Common Crawl and found AI-written articles briefly outnumbered human ones in November 2024. Since then, the two have been roughly equal.", "kicker": "Apply day 18: the web that trains AI is filling with AI.", "fullText": "Graphite randomly sampled 65,000 URLs from Common Crawl, the open archive of more than 300 billion pages, covering articles published from January 2020 to May 2025. It used an AI detector called Surfer, which had a 4.2% false positive rate on articles written with GPT-4o. The researchers cautioned that an exact count is not possible, because people increasingly write with AI.\n\nHuman writing still led where readers look: 86% of articles ranking in Google Search were human-written.\n\nThis matters for day 18. Common Crawl is a main source of training data, and the Nature model collapse study found that indiscriminate training on model-made content causes irreversible defects, with rare content lost first.", "sources": [{"url": "https://axios.com/2025/10/14/ai-generated-writing-humans", "label": "Axios, AI writing hasn't overwhelmed the web yet, Oct 2025"}, {"url": "https://oatml.cs.ox.ac.uk/publications/202407_Shumailov_ModelCollapse.html", "label": "Shumailov et al., AI models collapse when trained on recursively generated data, Nature 2024"}, {"url": "https://aws.amazon.com/fr/blogs/publicsector/how-common-crawl-and-aws-open-data-built-the-foundation-for-the-ai-revolution/", "label": "AWS Public Sector Blog, Common Crawl and the AI revolution"}]}, "evidence": {"kind": "buildChain", "prompt": "Follow how AI text can reach the next model.", "steps": ["AI tools write a growing share of web articles", "Crawlers archive those pages with the rest", "Labs train new models on the crawl", "Without filtering, rare human content thins out"], "explanation": "The crawl does not label who wrote what. Filtering is what keeps model output from feeding back in."}, "numbers": {"kind": "numberSense", "prompt": "Of articles ranking in Google Search, what share were human-written?", "min": 0, "max": 100, "value": 86, "unit": "%", "explanation": "About 86%. Human writing still ranks, even as AI writing floods the crawl."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "You're on a lab's data team. The latest web crawl looks heavy with AI-written articles.", "prompt": "What do you do first?", "options": ["Throw away the whole crawl", "Measure the AI share before training on it", "Train on it all, since more data is better"], "correctIndex": 1, "consequences": ["The crawl still holds valuable human text.", "You cannot filter what you have not measured.", "Unfiltered model output risks model collapse."], "explanation": "Have a view on synthetic data. Measure it, then decide how much to keep."}, "proReasoning": "Data teams measure before they filter. The share of AI text sets the cleanup plan.", "commonMistake": "Treating all text in a crawl as equal.", "mentalModel": "Measure, then filter."}, "invest": {"call": {"kind": "theCall", "situation": "A lab says it trains on \"fresh web data\" from 2025.", "prompt": "What do you ask?", "options": ["How fresh the data really is", "Nothing, since newer is better", "How it filters AI-written text"], "correctIndex": 2, "consequences": ["Freshness is the problem when half of it is AI.", "Newer web text is where AI writing grew.", "About half of new articles may be AI-written."], "explanation": "Ask whether a lab relies on AI-made data, and how it filters. Model collapse makes that a real risk."}, "proReasoning": "Investors probe data quality claims. Fresh web data now needs a filter story.", "commonMistake": "Treating newer data as automatically better.", "mentalModel": "Fresh data needs a filter."}, "build_startup": {"call": {"kind": "theCall", "situation": "AI-written articles now match human ones in new web content.", "prompt": "What's a promising startup idea to test?", "options": ["Verified human-written data for AI labs", "More AI articles to sell to the web", "A crawler that skips all filtering"], "correctIndex": 0, "consequences": ["Model collapse gives buyers a reason to pay for it.", "More AI text makes the problem worse.", "No filtering is the risk, not the product."], "explanation": "Ask data buyers whether they would pay more for verified human content. Model collapse gives them a reason."}, "proReasoning": "Founders turn a quality problem into a product. Verified human data is that product.", "commonMistake": "Adding to the flood instead of filtering it.", "mentalModel": "Sell what is getting rare."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend asks why AI-written web pages could be a problem for future AI.", "prompt": "What's the answer?", "options": ["AI models cannot read pages written by AI", "Models trained on them can lose rare content", "AI pages are always full of factual errors"], "correctIndex": 1, "consequences": ["It can read them, and that is the issue.", "In model collapse, the tails go first.", "Quality varies; the risk is in the loop."], "explanation": "A model trained on its own echoes forgets the rare things first."}, "proReasoning": "Copies of copies lose detail. Models trained on model output lose the rare parts first.", "commonMistake": "Thinking the only problem is errors in AI text.", "mentalModel": "Echoes lose the rare things."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:7cc85884f6ac$ml$]::text[]),
($ml$dfd94f47-d84a-5425-bf75-49c40ecb1515$ml$::uuid, $ml$ai$ml$, 18, 2, $ml${"id": "ai-d18-c2", "title": "Scarce, and getting diluted", "lessonTitle": "When AI trains on AI", "slot": 2, "type": "connect", "brief": {"headline": "Epoch AI estimates about 300 trillion tokens of quality public human text, possibly used up between 2026 and 2032. A 2024 Nature study found training on AI-made content causes irreversible defects.", "kicker": "Connect day 16 and day 18: human text is scarce, its substitute risky.", "fullText": "On day 16 you saw the supply limit: about 300 trillion tokens of quality public human text, which models could fully use between 2026 and 2032. On day 18 you saw why AI-made text is no simple substitute.\n\nShumailov and colleagues reported in Nature that indiscriminate use of model-generated content in training causes irreversible defects. The tails of the original distribution, the rarer content, disappear first. They called it model collapse.\n\nIf human text runs short, filling the gap with model output is tempting. Both findings point the same way: original human data becomes more valuable.", "sources": [{"url": "https://epoch.ai/blog/will-we-run-out-of-data-limits-of-llm-scaling-based-on-human-generated-data", "label": "Epoch AI, Will we run out of data?, Jun 2024"}, {"url": "https://oatml.cs.ox.ac.uk/publications/202407_Shumailov_ModelCollapse.html", "label": "Shumailov et al., AI models collapse when trained on recursively generated data, Nature 2024"}]}, "evidence": {"kind": "faceOff", "prompt": "Which data does the model collapse study warn against using carelessly?", "left": {"name": "Original human text", "note": "About 300 trillion quality tokens"}, "right": {"name": "Model-generated text", "note": "Cheap to make, and growing"}, "correctIndex": 1, "explanation": "Indiscriminate training on model output causes irreversible defects. Human text is the scarce, safer input."}, "numbers": {"kind": "numberSense", "prompt": "Epoch AI's window for using up quality text runs from 2026 to 2032. How many years wide?", "min": 0, "max": 20, "value": 6, "unit": "years", "explanation": "Six years, and it could come sooner if models are heavily overtrained."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "An interviewer asks: when public text runs out, why not train on AI-generated text?", "prompt": "What's your answer?", "options": ["It is illegal to train on AI text", "AI text is identical to human text", "Careless use causes model collapse"], "correctIndex": 2, "consequences": ["The problem is quality, not legality.", "Its distribution differs, and the tails fade.", "Rare content disappears first, and the damage is irreversible."], "explanation": "AI-made data can help with care, but indiscriminate use degrades models."}, "proReasoning": "Have a view on synthetic data: when it helps and when it hurts. Model collapse is the evidence.", "commonMistake": "Treating synthetic data as a free fix for the data wall.", "mentalModel": "Synthetic data needs care."}, "invest": {"call": {"kind": "theCall", "situation": "A lab says synthetic data solves its data shortage completely.", "prompt": "How do you respond?", "options": ["Ask how it avoids model collapse", "Accept it, since synthetic data is unlimited", "Reject all synthetic data outright"], "correctIndex": 0, "consequences": ["Indiscriminate use causes irreversible defects.", "Unlimited and safe are different things.", "Used with care, it can still help."], "explanation": "Check data quality claims. Model collapse makes careless synthetic data a real risk."}, "proReasoning": "Investors test bold data claims against the collapse research.", "commonMistake": "Accepting \"synthetic data solves it\" without detail.", "mentalModel": "Test the synthetic data claim."}, "build_startup": {"call": {"kind": "theCall", "situation": "You can sell either synthetic text or verified human text to AI labs.", "prompt": "Which has the stronger long-term case?", "options": ["Both are worth the same", "Verified human text", "Synthetic text, since it is cheap"], "correctIndex": 1, "consequences": ["The research says they are not equivalent.", "It is scarce and protects against collapse.", "Cheap to make also means cheap to copy."], "explanation": "If training on model output degrades models, original human data is worth more."}, "proReasoning": "Founders sell what is both scarce and safe. Human data is both.", "commonMistake": "Competing on cheap supply in a market that needs quality.", "mentalModel": "Scarce and safe sells."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend asks why AI cannot just write its own training data forever.", "prompt": "What's the answer?", "options": ["It runs out of electricity", "It refuses to read its own writing", "It slowly loses the rare things it knew"], "correctIndex": 2, "consequences": ["Power is not the limit here.", "It will read it; that is the risk.", "The tails of the data fade first, a bit like a photocopy of a photocopy."], "explanation": "A model trained on its own echoes forgets the rare things first."}, "proReasoning": "Self-generated data narrows over time. Fresh human input keeps the range wide.", "commonMistake": "Thinking an AI can be its own teacher without limit.", "mentalModel": "Echoes narrow over time."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:e3666f629dd2$ml$]::text[]),
($ml$eff5016c-446a-5894-9f43-9cbfced6912a$ml$::uuid, $ml$ai$ml$, 18, 3, $ml${"id": "ai-d18-c3", "title": "Training on your own echoes", "lessonTitle": "When AI trains on AI", "slot": 3, "type": "decide", "brief": {"headline": "You run a lab. To save money, your team proposes training the next model on text generated by the current one.", "kicker": "Decide how much AI-made data to let in.", "fullText": "In 2024, Shumailov and colleagues reported in Nature that indiscriminate use of model-generated content in training causes irreversible defects in the resulting models. The tails of the original content distribution, the rarer content, disappear first. They called the effect model collapse.\n\nThe risk grows as more AI-made content ends up in the data future models learn from. If training on model output degrades models, original human data becomes more valuable.", "sources": [{"url": "https://oatml.cs.ox.ac.uk/publications/202407_Shumailov_ModelCollapse.html", "label": "Shumailov et al., AI models collapse when trained on recursively generated data, Nature 2024"}]}, "evidence": {"kind": "sortSignal", "prompt": "Does each choice lower or raise the risk of model collapse?", "buckets": ["Lower risk", "Higher risk"], "items": [{"text": "Verified human-written sources", "bucket": 0}, {"text": "Web data with AI text filtered out", "bucket": 0}, {"text": "Your own model's outputs, unfiltered", "bucket": 1}, {"text": "New crawls used with no AI filter", "bucket": 1}], "explanation": "The risk comes from indiscriminate model-made data. Filtering and human sources keep the tails alive."}, "numbers": {"kind": "numberSense", "prompt": "Your 10 trillion token dataset is 40% AI-written. How many trillion tokens are human-written?", "min": 0, "max": 10, "value": 6, "unit": "T", "explanation": "Six trillion. The other four are where the collapse risk sits."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "You're a researcher on the team that proposed the plan.", "prompt": "What do you recommend?", "options": ["Test small, filter hard, keep human data", "Go all in on it, since it is cheaper", "Ban every synthetic example from training"], "correctIndex": 0, "consequences": ["That captures savings while watching for collapse.", "Indiscriminate use causes irreversible defects.", "Careful, limited use can still help."], "explanation": "Say when synthetic data helps and when it hurts. Evidence beats enthusiasm."}, "proReasoning": "Propose a careful test, not a blanket yes or no. That shows judgment.", "commonMistake": "Choosing an extreme without evidence.", "mentalModel": "Test, filter, keep humans central."}, "invest": {"call": {"kind": "theCall", "situation": "The lab tells investors its training costs will drop by using its own outputs.", "prompt": "What risk do you weigh?", "options": ["More human data than needed", "A weaker next model from collapse", "Higher electricity bills"], "correctIndex": 1, "consequences": ["Human data is the scarce input, not a surplus.", "Savings mean little if the model loses quality.", "Energy is not the main risk here."], "explanation": "Check data quality claims. Model collapse can turn a saving into a worse product."}, "proReasoning": "Investors weigh cost savings against quality risk. Collapse is irreversible.", "commonMistake": "Counting the savings without the risk.", "mentalModel": "Cheap data can cost quality."}, "build_startup": {"call": {"kind": "theCall", "situation": "You're the founder making the final call on the plan.", "prompt": "What do you decide?", "options": ["Train on every output to save the money", "Stop training any new models from now on", "Filter it and favor verified human sources"], "correctIndex": 2, "consequences": ["Indiscriminate use is exactly what causes collapse.", "Overreacting gives up progress.", "That keeps the rare content that collapse destroys."], "explanation": "A model trained on its own echoes forgets the rare things first. Guard the human data."}, "proReasoning": "Founders protect the scarce input that keeps models healthy: real human data.", "commonMistake": "Trading quality for a short-term saving.", "mentalModel": "Guard the human data."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend asks what disappears first when an AI learns from AI.", "prompt": "What's the answer?", "options": ["The rare, unusual content", "The most common phrases", "Its ability to do math"], "correctIndex": 0, "consequences": ["The tails of the distribution go first.", "Common content survives longest.", "The study points to rare content, not math."], "explanation": "Model collapse erases the rare parts of the original data first."}, "proReasoning": "Averages survive copying; oddities do not. That is why AI echoes get bland.", "commonMistake": "Expecting common knowledge to fade first.", "mentalModel": "The rare goes first."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:434fc83358d8$ml$]::text[]),
($ml$66965967-4424-5b9c-9444-8d646c6c95cb$ml$::uuid, $ml$ai$ml$, 19, 1, $ml${"id": "ai-d19-c1", "title": "A million TPUs, rented", "lessonTitle": "The chips that run AI", "slot": 1, "type": "apply", "brief": {"headline": "In October 2025, Anthropic agreed to use up to one million of Google's TPUs through Google Cloud, a deal that could be worth tens of billions of dollars. It expects well over a gigawatt of capacity in 2026.", "kicker": "Apply day 19: renting compute at enormous scale.", "fullText": "TPUs are Google's custom chips for neural networks, and Google has offered them to other companies through its cloud since 2018. Anthropic said it chose them for price-performance and efficiency, building on a partnership that began in 2023.\n\nIt did not bet on one chip. Amazon remains Anthropic's primary training partner, with its Trainium chips running Project Rainier, and Anthropic also uses NVIDIA GPUs. The companies did not disclose the price of the Google deal. Anthropic's annual revenue run rate was approaching $7 billion.\n\nDay 19's choice was rent or own. Anthropic rents, at huge scale, and spreads its rentals across three kinds of chips.", "sources": [{"url": "https://siliconangle.com/2025/10/23/anthropic-strikes-multibillion-dollar-deal-google-access-million-tpus/", "label": "SiliconANGLE, Anthropic strikes deal for up to a million Google TPUs, Oct 2025"}, {"url": "https://en.wikipedia.org/wiki/Tensor_Processing_Unit", "label": "Tensor Processing Unit"}, {"url": "https://courses.cs.duke.edu/fall16/compsci527/papers/Krizhevsky%20et%20al%20DNN%20ImageNet%202012.pdf", "label": "Krizhevsky, Sutskever and Hinton, ImageNet classification with deep CNNs, 2012"}]}, "evidence": {"kind": "sortSignal", "prompt": "Which chip does each fact describe?", "buckets": ["NVIDIA GPU", "Google TPU", "Amazon Trainium"], "items": [{"text": "Began as a graphics chip", "bucket": 0}, {"text": "Trained the 2012 image breakthrough", "bucket": 0}, {"text": "Google's custom chip, rented since 2018", "bucket": 1}, {"text": "Up to one million in Anthropic's deal", "bucket": 1}, {"text": "Runs Project Rainier for Anthropic", "bucket": 2}], "explanation": "GPUs came from graphics. TPUs and Trainium are custom chips that clouds rent to customers."}, "numbers": {"kind": "numberSense", "prompt": "Anthropic's annual revenue run rate was approaching how many billion dollars?", "min": 0, "max": 20, "value": 7, "unit": "B", "explanation": "About $7 billion, while it committed to compute that could cost tens of billions."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "You're interviewing on Anthropic's infrastructure team in late 2025. They ask what chips it runs on.", "prompt": "What's the best answer?", "options": ["Only NVIDIA GPUs that it bought outright", "Only Google TPUs, now that the deal is signed", "Trainium, TPUs and NVIDIA GPUs, mostly rented"], "correctIndex": 2, "consequences": ["It rents from clouds and uses three chip types.", "Amazon stayed its primary training partner.", "Naming the mix shows you know the infrastructure."], "explanation": "Knowing which chips a team uses, and whether it rents or owns, frames every infrastructure talk."}, "proReasoning": "Name the chips and the model: rented from clouds, spread across three kinds. That is a precise answer.", "commonMistake": "Assuming every AI lab runs only on NVIDIA.", "mentalModel": "Name the chip and the deal."}, "invest": {"call": {"kind": "theCall", "situation": "Google rents up to a million of its own AI chips to a rival AI lab.", "prompt": "What does that signal for NVIDIA?", "options": ["Custom chips are a real alternative for big buyers", "NVIDIA has lost all of its customers", "Nothing, since TPUs only run Google products"], "correctIndex": 0, "consequences": ["Big buyers now have more than one source of AI chips.", "Anthropic still uses NVIDIA GPUs too.", "Google has rented TPUs to others since 2018."], "explanation": "Custom chips like Google's TPU are an alternative to buying GPUs. Watch which big buyers use them."}, "proReasoning": "Investors track custom chip deals as a measure of how much buyers can route around the leader.", "commonMistake": "Reading a custom chip deal as either nothing or the end of NVIDIA.", "mentalModel": "Watch who builds and rents custom chips."}, "build_startup": {"call": {"kind": "theCall", "situation": "Your startup needs compute, and you cannot predict demand six months out.", "prompt": "What's the smart setup?", "options": ["Design your own custom chip from scratch", "Rent in the cloud and keep code chip-flexible", "Buy a full year of GPUs upfront, just in case"], "correctIndex": 1, "consequences": ["Custom chips take years and huge budgets.", "Renting fits unknown demand, and flexibility keeps prices honest.", "Owned GPUs sit idle if demand falls short."], "explanation": "The cloud lets a small team rent capable chips by demand. Even Anthropic rents."}, "proReasoning": "Founders rent while demand is uncertain, and avoid locking their code to one chip.", "commonMistake": "Buying hardware before demand is steady.", "mentalModel": "Rent first, stay flexible."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend asks why Anthropic would rent chips from Google, which builds rival AI.", "prompt": "What's the best explanation?", "options": ["A law forces AI labs to use Google chips", "Google owns Anthropic outright, so it must", "Google's chips offered good price-performance"], "correctIndex": 2, "consequences": ["No law requires it; it was a business choice.", "Google invested about $3 billion; it does not own Anthropic.", "Anthropic cited price-performance and efficiency."], "explanation": "Clouds sell compute to anyone, rivals included. Anthropic picked the chips that suited its needs."}, "proReasoning": "In cloud computing, rivals are often customers too. Compute is sold to whoever pays.", "commonMistake": "Assuming competitors never do business with each other.", "mentalModel": "Rivals can be customers."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:c0fc51384f7c$ml$]::text[]),
($ml$17cf3278-35b9-5b51-9bbb-a60a33d65e50$ml$::uuid, $ml$ai$ml$, 19, 2, $ml${"id": "ai-d19-c2", "title": "A way around the chokepoint", "lessonTitle": "The chips that run AI", "slot": 2, "type": "connect", "brief": {"headline": "NVIDIA's data center chips earned $193.7 billion in fiscal 2026, at margins above 70%. Google has run its own AI chip, the TPU, since 2015, and rents it out through its cloud.", "kicker": "Connect day 3 and day 19: custom chips are a way around the chokepoint.", "fullText": "On day 3 you saw who holds power in AI: whoever controls the scarcest input. NVIDIA's data center business brought in $193.7 billion in fiscal 2026, at gross margins above 70%.\n\nOn day 19 you met Google's answer, the Tensor Processing Unit: a custom chip built for neural networks. Google began using TPUs internally in 2015, announced them in May 2016, and has offered them to other companies through its cloud since 2018.\n\nA big buyer that designs its own chip is less exposed to the leader's margins, and it can rent the chip to others too.", "sources": [{"url": "https://www.sec.gov/Archives/edgar/data/1045810/000104581026000019/q4fy26pr.htm", "label": "NVIDIA fiscal 2026 results"}, {"url": "https://en.wikipedia.org/wiki/Tensor_Processing_Unit", "label": "Tensor Processing Unit"}]}, "evidence": {"kind": "multipleChoice", "prompt": "Why would a big buyer design its own AI chip?", "options": ["To stop using cloud computing at all", "To rely less on a scarce, costly supplier", "Because GPUs cannot run neural networks"], "correctIndex": 1, "explanation": "Margins above 70% show how much a chokepoint can charge. A custom chip is one way out."}, "numbers": {"kind": "numberSense", "prompt": "Google started using TPUs in 2015 and offered them to others in 2018. How many years in between?", "min": 0, "max": 10, "value": 3, "unit": "years", "explanation": "Three years of internal use before Google rented them out through its cloud."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "You have offers from NVIDIA and from Google's TPU team.", "prompt": "What's the fairest read of the two?", "options": ["NVIDIA leads; TPUs are a real alternative", "TPUs have already replaced NVIDIA", "TPUs are a side project with no customers"], "correctIndex": 0, "consequences": ["Both sit at the center of AI compute, in different roles.", "NVIDIA still earned $193.7 billion from data centers.", "Google rents TPUs to other companies."], "explanation": "Power in AI chips is shifting at the margins. Know who leads and who offers the alternative."}, "proReasoning": "Describe both positions accurately. A leader and a credible alternative can both be good places to work.", "commonMistake": "Treating the chip market as winner-take-all.", "mentalModel": "Know the leader and the alternative."}, "invest": {"call": {"kind": "theCall", "situation": "More big buyers design their own AI chips.", "prompt": "What could that mean for NVIDIA over time?", "options": ["No effect, since buyers always need GPUs", "Pressure on its margins", "Higher margins, from less competition"], "correctIndex": 1, "consequences": ["Some workloads move to custom chips.", "Scarcity margins last as long as buyers lack options.", "Custom chips add competition, not remove it."], "explanation": "Companies that control a scarce input can raise prices. The key question is how long the scarcity lasts."}, "proReasoning": "Investors watch custom chips as the clock on a chokepoint's pricing power.", "commonMistake": "Assuming today's margins are permanent.", "mentalModel": "Alternatives shorten the scarcity."}, "build_startup": {"call": {"kind": "theCall", "situation": "TPUs look cheaper for your workload, but your code only runs on GPUs.", "prompt": "What's the sound move?", "options": ["Stay GPU-only forever to keep it simple", "Rewrite everything for TPUs at once", "Test porting your code to keep options open"], "correctIndex": 2, "consequences": ["Locking in leaves you paying the leader's prices.", "A full rewrite before testing is a big risk.", "Being able to switch gives you bargaining power."], "explanation": "Avoid depending on one scarce supplier. A tested second option gives you bargaining power."}, "proReasoning": "Founders keep a credible second chip option. It lowers costs and risk.", "commonMistake": "Letting one supplier's format lock you in.", "mentalModel": "Keep a second chip option."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend asks why every company doesn't just build its own chip like Google.", "prompt": "What's the best answer?", "options": ["It only pays with huge, steady demand", "Chip design is illegal for most firms", "Google owns all chip designs"], "correctIndex": 0, "consequences": ["Google used TPUs internally for years before renting them out.", "Any company can design chips; few can afford to.", "Many companies design chips."], "explanation": "Owning hardware only pays with steady use. Designing a chip is that idea at its most extreme."}, "proReasoning": "Building your own makes sense when your demand is huge and steady. Otherwise, rent.", "commonMistake": "Thinking custom chips are a shortcut for everyone.", "mentalModel": "Own only at steady scale."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:5a2673ea56f1$ml$]::text[]),
($ml$388a8aa1-df2c-5760-a123-cca6813d0ac2$ml$::uuid, $ml$ai$ml$, 19, 3, $ml${"id": "ai-d19-c3", "title": "When renting stops making sense", "lessonTitle": "The chips that run AI", "slot": 3, "type": "decide", "brief": {"headline": "You run an AI startup that has rented cloud GPUs for two years. Its workload is now steady, running near full use day and night, and you can forecast it three years out.", "kicker": "Decide whether to keep renting or start owning.", "fullText": "Companies either rent compute in the cloud or buy and run their own hardware on-premises. Google's TPUs, for example, have been available to other companies through Google Cloud since 2018.\n\nThe cloud lets a small team rent capable chips by demand. Owning hardware only pays with steady use. DeepSeek priced its V3 training run assuming a rental price of $2 per GPU hour.", "sources": [{"url": "https://en.wikipedia.org/wiki/Tensor_Processing_Unit", "label": "Tensor Processing Unit"}, {"url": "https://ar5iv.labs.arxiv.org/html/2412.19437", "label": "DeepSeek-AI, DeepSeek-V3 technical report, Dec 2024"}]}, "evidence": {"kind": "sortSignal", "prompt": "Does each fact point toward renting or owning?", "buckets": ["Points to renting", "Points to owning"], "items": [{"text": "Demand that swings week to week", "bucket": 0}, {"text": "Unsure which chips you will need next year", "bucket": 0}, {"text": "Near full use, day and night, for years", "bucket": 1}, {"text": "A workload you can forecast with confidence", "bucket": 1}], "explanation": "Renting buys flexibility. Owning pays off when you will use the hardware fully for a long time."}, "numbers": {"kind": "numberSense", "prompt": "At $2 per GPU hour, what does one GPU cost to rent for a full year, in thousands of dollars?", "min": 0, "max": 50, "value": 17.5, "unit": "K", "explanation": "About $17,500: 8,760 hours times $2. Compare that with buying, at full use."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "You're the startup's infrastructure lead. The CFO asks whether to keep renting.", "prompt": "What's your recommendation?", "options": ["Buy enough hardware for the busiest day", "Model buying part of it, since use is steady", "Keep renting forever, whatever the use"], "correctIndex": 1, "consequences": ["Sizing for the peak leaves hardware idle most days.", "Steady, forecastable use is when owning can pay.", "Renting full-time for years can cost more than owning."], "explanation": "Compute is rented or owned, and that choice shapes your costs. Steady use changes the answer."}, "proReasoning": "Infrastructure leads revisit rent-or-own as usage changes. The right answer moves with the workload.", "commonMistake": "Treating an early decision as permanent.", "mentalModel": "Revisit rent or own as use changes."}, "invest": {"call": {"kind": "theCall", "situation": "The startup asks investors for money to buy its own GPUs.", "prompt": "What do you check first?", "options": ["Whether the GPUs are the newest model", "Nothing, since owning is always cheaper", "Whether use is steady enough to pay off"], "correctIndex": 2, "consequences": ["New chips idle half the time still lose money.", "Owning is cheaper only at high, steady use.", "Owning only pays with steady, high use."], "explanation": "Owned hardware is a fixed cost. It pays when it stays busy."}, "proReasoning": "Investors ask about utilization before funding hardware. Idle chips are wasted capital.", "commonMistake": "Funding hardware without a usage forecast.", "mentalModel": "Ownership needs utilization."}, "build_startup": {"call": {"kind": "theCall", "situation": "You're the founder. Your workload is steady and forecastable for three years.", "prompt": "What's your move?", "options": ["Run the numbers on owning the steady part", "Rent everything, whatever it costs", "Rent nothing and buy for every spike"], "correctIndex": 0, "consequences": ["Own the base load, rent the peaks.", "You may be paying a premium for flexibility you do not use.", "Spikes are what renting is best for."], "explanation": "Owning hardware pays with steady use. Renting still fits the unpredictable part."}, "proReasoning": "Founders own the steady base and rent the swings. Each tool for its job.", "commonMistake": "Choosing all rent or all own.", "mentalModel": "Own the base, rent the peaks."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend asks why a company would rent chips if it could just buy them.", "prompt": "What's the answer?", "options": ["Companies are not allowed to buy chips", "Rent for changing needs, own for steady use", "Renting always works out cheaper in the end"], "correctIndex": 1, "consequences": ["Companies can and do buy their own hardware.", "Like renting a car versus buying one you drive daily.", "Renting full-time for years can cost more."], "explanation": "Rent when needs change, own when use is steady. Compute follows the same logic as cars or offices."}, "proReasoning": "Rent-or-own logic is the same everywhere: flexibility costs extra, steady use favors owning.", "commonMistake": "Thinking one option is always best.", "mentalModel": "Flexibility costs extra."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:df8dd90f09d2$ml$]::text[]),
($ml$65a22bf5-b699-5943-a646-9975f4826e7c$ml$::uuid, $ml$ai$ml$, 20, 1, $ml${"id": "ai-d20-c1", "title": "$700 billion and rising", "lessonTitle": "What Big Tech spends on compute", "slot": 1, "type": "apply", "brief": {"headline": "By April 2026, Alphabet, Amazon, Microsoft and Meta planned to spend more than $700 billion on capital projects in 2026, nearly double what they spent in 2025. Amazon alone guided to $200 billion.", "kicker": "Apply day 20: a few budgets set the size of the market.", "fullText": "In their April 2026 earnings, Alphabet raised its 2026 guidance to $180 billion to $190 billion, from $175 billion to $185 billion. Meta raised its range to $125 billion to $145 billion, from $115 billion to $135 billion. Microsoft said it would spend $190 billion this calendar year. Amazon kept its forecast at $200 billion.\n\nThe total was about $100 billion more than they had expected a quarter earlier. In 2025, five tech giants including Apple had expected $364 billion to $400 billion.\n\nA handful of budgets still set the size of the compute market, and those budgets keep moving.", "sources": [{"url": "https://sherwood.news/tech/alphabet-amazon-microsoft-meta-plan-more-than-700-billion-on-capex-this-year/", "label": "Sherwood News, Big Tech plans more than $700 billion of capex this year, Apr 2026"}, {"url": "https://www.emarketer.com/content/genai-arms-race--big-tech-pour--400-billion-ai-buildout", "label": "eMarketer, Big Tech to pour up to $400 billion into AI buildout, 2025"}]}, "evidence": {"kind": "multipleChoice", "prompt": "Four companies plan over $700 billion of 2026 capex. Who feels that demand first?", "options": ["Only the four companies' own users", "Nobody, until the money is spent in 2030", "Suppliers of chips, buildings and power"], "correctIndex": 2, "explanation": "When a few buyers plan hundreds of billions, their decisions set demand for chips, buildings and power."}, "numbers": {"kind": "numberSense", "prompt": "Alphabet's raised 2026 range is $180 billion to $190 billion. What is the midpoint, in billions?", "min": 0, "max": 300, "value": 185, "unit": "B", "explanation": "$185 billion, more than double the $85 billion it guided to for 2025."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "You have offers from a chip supplier, a data center builder and a power equipment maker.", "prompt": "What do the three jobs have in common?", "options": ["Big Tech's capex pays for all three", "None of them depends on AI spending", "Only the chip job is tied to AI"], "correctIndex": 0, "consequences": ["Over $700 billion of planned capex funds jobs across the chain.", "Each one sells into the AI buildout.", "Buildings and power are part of the same spending."], "explanation": "That spending funds infrastructure jobs across the chain, not only at chipmakers."}, "proReasoning": "Follow the capex to find AI jobs beyond the labs. Construction and power are part of it.", "commonMistake": "Thinking AI careers are only in software and chips.", "mentalModel": "Follow the capex."}, "invest": {"call": {"kind": "theCall", "situation": "Meta raises its 2026 capex range by $10 billion at both ends.", "prompt": "Who else should feel that change?", "options": ["Nobody, since it is just guidance", "Its chip, building and power suppliers", "Only Meta's advertisers"], "correctIndex": 1, "consequences": ["Guidance is how suppliers plan their own output.", "Guidance changes move orders down the supply chain.", "Advertisers do not receive capex."], "explanation": "When a giant raises guidance, chip and power suppliers feel it. Watch capex guidance changes."}, "proReasoning": "Investors read capex guidance as a demand forecast for the whole chain.", "commonMistake": "Treating one company's guidance as only its own news.", "mentalModel": "Guidance moves the chain."}, "build_startup": {"call": {"kind": "theCall", "situation": "Your startup needs GPUs in 2026 while giants plan over $700 billion of capex.", "prompt": "What's your plan?", "options": ["Wait for chip prices to drop mid-2026", "Outbid the giants for the newest chips", "Reserve early and design for efficiency"], "correctIndex": 2, "consequences": ["Rising budgets point to tight supply, not falling prices.", "You cannot outbid a $200 billion budget.", "You secure supply and need less of it."], "explanation": "When giants buy hundreds of billions in compute, smaller buyers compete for what is left."}, "proReasoning": "Founders plan for tight supply when giants are spending. Efficiency stretches what you can get.", "commonMistake": "Assuming supply will loosen while budgets climb.", "mentalModel": "Plan for scarcity when giants spend."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend asks what tech companies are spending $700 billion on.", "prompt": "What's the short answer?", "options": ["Data centers: chips, buildings and power", "Advertising campaigns for chatbots", "Buying up smaller AI startups"], "correctIndex": 0, "consequences": ["Capital spending builds physical infrastructure.", "Ads are an operating cost, not capex.", "Acquisitions are counted separately from capex."], "explanation": "Capex buys physical things. For AI, that means data centers and what goes in them."}, "proReasoning": "Capex means building things. The AI boom is, in large part, a construction boom.", "commonMistake": "Thinking AI spending is mostly software.", "mentalModel": "Capex builds things."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:4ab3f279296c$ml$]::text[]),
($ml$81f0b896-1bbe-5fe0-a743-36dd1abbfdeb$ml$::uuid, $ml$ai$ml$, 20, 2, $ml${"id": "ai-d20-c2", "title": "Where the capex lands", "lessonTitle": "What Big Tech spends on compute", "slot": 2, "type": "connect", "brief": {"headline": "Five tech giants expected $364 billion to $400 billion of capital spending in 2025. NVIDIA's data center business brought in $193.7 billion in the fiscal year that ended in January 2026.", "kicker": "Connect day 2 and day 20: a few budgets feed the bottom of the stack.", "fullText": "On day 2 you followed the money down the stack to chips: NVIDIA's data center revenue was $193.7 billion in fiscal 2026, about 90% of its total. On day 20 you saw where that demand comes from. Alphabet, Amazon, Apple, Meta and Microsoft expected $364 billion to $400 billion of 2025 capex. Amazon was on track for more than $118 billion, Alphabet raised its guidance to $85 billion, and Meta guided to $66 billion to $72 billion.\n\nWhen a handful of buyers write budgets that big, their choices set demand for chips, buildings and power.", "sources": [{"url": "https://www.sec.gov/Archives/edgar/data/1045810/000104581026000019/q4fy26pr.htm", "label": "NVIDIA fiscal 2026 results"}, {"url": "https://www.emarketer.com/content/genai-arms-race--big-tech-pour--400-billion-ai-buildout", "label": "eMarketer, Big Tech to pour up to $400 billion into AI buildout, 2025"}]}, "evidence": {"kind": "buildChain", "prompt": "Follow the money from users to the chipmaker.", "steps": ["Users pay for AI apps and cloud services", "Big Tech plans hundreds of billions of capex", "That money buys chips, buildings and power", "Chipmakers like NVIDIA book record revenue"], "explanation": "One company's capex is another company's revenue. That is how a few budgets size the market."}, "numbers": {"kind": "numberSense", "prompt": "Meta guided to $66 billion to $72 billion of 2025 capex. What is the midpoint, in billions?", "min": 0, "max": 200, "value": 69, "unit": "B", "explanation": "$69 billion from one company, in one year."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "You're interviewing at a chip company. They ask what drives its demand.", "prompt": "What's the sharpest answer?", "options": ["Governments buying chips for schools", "A few cloud giants' capex budgets", "Millions of gamers buying graphics cards"], "correctIndex": 1, "consequences": ["Big Tech capex dwarfs that kind of spending.", "Data centers were about 90% of NVIDIA's revenue.", "Gaming is now a small share next to data centers."], "explanation": "In AI, a handful of buyers' budgets set the size of the compute market."}, "proReasoning": "Tie a supplier's revenue to its customers' budgets. It shows you understand the chain.", "commonMistake": "Describing demand without naming who pays.", "mentalModel": "Revenue follows customer budgets."}, "invest": {"call": {"kind": "theCall", "situation": "A chip supplier gets most of its revenue from five buyers.", "prompt": "What's the main risk?", "options": ["Too many customers to manage", "Its revenue is too steady", "One budget cut hits it hard"], "correctIndex": 2, "consequences": ["Five buyers is the opposite of too many.", "It depends on decisions it does not control.", "Concentrated customers mean concentrated risk."], "explanation": "When a few buyers set the market, their cuts land on suppliers just as fast as their raises."}, "proReasoning": "Investors weigh customer concentration. A few giant buyers bring big orders and big risk.", "commonMistake": "Seeing big customers only as upside.", "mentalModel": "Concentration cuts both ways."}, "build_startup": {"call": {"kind": "theCall", "situation": "Your startup sells cooling equipment to data center builders.", "prompt": "What should you watch most closely?", "options": ["Each giant's capex guidance", "Chatbot download rankings", "Stock prices of AI app makers"], "correctIndex": 0, "consequences": ["Capex guidance tells you how much will be built.", "Downloads do not tell you how many buildings go up.", "App stocks are far from your customers."], "explanation": "A few budgets size the market. For a supplier, those budgets are the demand forecast."}, "proReasoning": "Founders selling infrastructure read capex guidance like a sales pipeline.", "commonMistake": "Watching consumer AI hype instead of capex.", "mentalModel": "Capex is your pipeline."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend asks why NVIDIA's stock moves when Meta updates its budget.", "prompt": "What's the answer?", "options": ["They share the same chief executive", "Meta's capex becomes revenue for NVIDIA", "Meta owns a large part of NVIDIA"], "correctIndex": 1, "consequences": ["They are separate companies with separate leaders.", "A budget change is an order change down the chain.", "Meta is a customer, not an owner."], "explanation": "One company's spending is another's sales. Markets react to the link."}, "proReasoning": "Follow the money between companies. A customer's plans move a supplier's outlook.", "commonMistake": "Seeing two stocks as unrelated.", "mentalModel": "One budget, another's revenue."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:378f952c6bb7$ml$]::text[]),
($ml$b98b92c2-326b-52bb-86e6-fb23fc7ed07d$ml$::uuid, $ml$ai$ml$, 20, 3, $ml${"id": "ai-d20-c3", "title": "Small buyer, giant market", "lessonTitle": "What Big Tech spends on compute", "slot": 3, "type": "decide", "brief": {"headline": "You run a small AI startup that needs more GPUs this year. Five tech giants expected to spend $364 billion to $400 billion on capital projects in 2025.", "kicker": "Decide how a small buyer gets compute in a giant market.", "fullText": "Around their second-quarter 2025 earnings, Alphabet, Amazon, Apple, Meta and Microsoft expected between $364 billion and $400 billion of capital expenditures for the year. Amazon was on track for more than $118 billion, Alphabet raised its guidance to $85 billion, and Meta guided to $66 billion to $72 billion.\n\nWhen five companies plan hundreds of billions, their decisions set demand for chips, buildings and power. Smaller buyers compete for what is left.", "sources": [{"url": "https://www.emarketer.com/content/genai-arms-race--big-tech-pour--400-billion-ai-buildout", "label": "eMarketer, Big Tech to pour up to $400 billion into AI buildout, 2025"}]}, "evidence": {"kind": "spotFake", "prompt": "One of these is false. Tap it.", "statements": ["Amazon was on track for over $118 billion of 2025 capex.", "Alphabet raised its 2025 guidance to $85 billion.", "Small buyers get first pick of new chips."], "fakeIndex": 2, "explanation": "Giants buying hundreds of billions get served first. Smaller buyers compete for what is left."}, "numbers": {"kind": "numberSense", "prompt": "Five companies expected $364 billion to $400 billion. What is the midpoint, in billions?", "min": 0, "max": 600, "value": 382, "unit": "B", "explanation": "About $382 billion in one year, from five buyers."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "You can join a hyperscaler's infrastructure team or this small startup.", "prompt": "What should you weigh about compute?", "options": ["Both will get chips just as easily", "Hyperscalers never have enough work", "The startup may struggle to get chips"], "correctIndex": 2, "consequences": ["Budget size decides who gets served first.", "Their capex plans say otherwise.", "Smaller buyers compete for what giants leave."], "explanation": "Ask what limits a team. At a small startup in a tight market, compute may be it."}, "proReasoning": "Ask whether a team can get the compute its plans need. It shapes what you will be able to build.", "commonMistake": "Assuming compute is equally available to everyone.", "mentalModel": "Ask who can get the chips."}, "invest": {"call": {"kind": "theCall", "situation": "You're asked to fund the startup's plan to double its GPU fleet this year.", "prompt": "What do you ask?", "options": ["Where the chips will come from, and when", "Only how fast revenue is growing", "Nothing, since chips are easy to buy"], "correctIndex": 0, "consequences": ["In a market sized by giants, supply is the risk.", "Growth needs the compute to serve it.", "Not when five buyers plan hundreds of billions."], "explanation": "A handful of buyers set the market. A small company's plan needs a supply answer."}, "proReasoning": "Investors test whether a small company can secure inputs that giants are hoarding.", "commonMistake": "Funding growth without checking supply.", "mentalModel": "Check the supply behind the plan."}, "build_startup": {"call": {"kind": "theCall", "situation": "You're the founder, short of GPUs while the giants buy up supply.", "prompt": "What's the best move?", "options": ["Pause the product until chips are cheap", "Cut compute needs and lock in what you can", "Wait for the giants to stop buying"], "correctIndex": 1, "consequences": ["Pausing hands the market to others.", "Efficiency and early commitments stretch scarce supply.", "Their budgets were still rising."], "explanation": "Smaller buyers get squeezed. Using less compute and securing supply early are the levers you control."}, "proReasoning": "Founders cannot outspend giants, so they out-plan them: efficiency plus early commitments.", "commonMistake": "Waiting for a giant market to loosen.", "mentalModel": "Use less, lock in early."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend asks why small AI companies complain about getting chips.", "prompt": "What's the answer?", "options": ["Chip factories have closed down", "Small companies are banned from buying", "Giants buy most of the supply first"], "correctIndex": 2, "consequences": ["Chipmakers are booking record sales.", "They can buy; they just stand behind the giants.", "$364 billion to $400 billion of capex sets the pecking order."], "explanation": "When a few buyers spend hundreds of billions, everyone else waits in line."}, "proReasoning": "Supply goes to the biggest buyers first. That is true for chips as for anything scarce.", "commonMistake": "Thinking the shortage means nobody is building chips.", "mentalModel": "Big buyers go first."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:e992f52e1355$ml$]::text[]),
($ml$31ca4d73-793a-57be-95b8-6dacc9a42fc0$ml$::uuid, $ml$ai$ml$, 21, 1, $ml${"id": "ai-d21-c1", "title": "The H200, for a 25% cut", "lessonTitle": "Who decides who gets the chips", "slot": 1, "type": "apply", "brief": {"headline": "On December 8, 2025, President Trump said NVIDIA could ship its H200 chips to approved customers in China, with 25% going to the US government. Newer Blackwell and Rubin chips were excluded.", "kicker": "Apply day 21: governments set who gets chips, and on what terms.", "fullText": "Trump wrote that shipments would come under conditions allowing continued strong national security, and that the same approach would apply to AMD, Intel and other American companies. The Commerce Department was still finalizing details. NVIDIA and AMD shares rose more than 2% in the hours after the post.\n\nIt capped a year of reversals. In April 2025 the US required licenses for NVIDIA's less capable H20 chip in China, and NVIDIA expected up to about $5.5 billion in charges. In August, licenses resumed after NVIDIA and AMD reportedly agreed to pay the US 15% of their China chip revenue.\n\nWhoever controls chip exports decides which customers a chipmaker can serve, and on what terms.", "sources": [{"url": "https://www.theregister.com/2025/12/09/trump_gpu_export_ban_reversal/", "label": "The Register, Trump says Nvidia can sell H200s to China for a 25 percent cut, Dec 2025"}, {"url": "https://www.sec.gov/Archives/edgar/data/1045810/000104581025000082/nvda-20250409.htm", "label": "NVIDIA Form 8-K on H20 export licensing, Apr 2025"}, {"url": "https://www.datacenterdynamics.com/en/news/nvidia-and-amd-agree-to-pay-us-govt-15-of-china-chip-sales-in-order-to-obtain-export-licenses-report/", "label": "DatacenterDynamics, Nvidia and AMD agree to pay US 15% of China chip sales for export licenses, Aug 2025"}]}, "evidence": {"kind": "buildChain", "prompt": "Put 2025's export moves in order.", "steps": ["April: H20 sales to China need a license", "NVIDIA expects up to $5.5 billion in charges", "August: licenses resume with a 15% payment", "December: H200 allowed with a 25% cut"], "explanation": "Each step was a government decision. NVIDIA designed the chips; Washington set the terms."}, "numbers": {"kind": "numberSense", "prompt": "From a 15% payment on H20 sales to a 25% cut on H200 sales: how many points higher?", "min": 0, "max": 40, "value": 10, "unit": "points", "explanation": "Ten points more. Access came back, but at a higher price."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "You're interviewing at a chip company in 2026.", "prompt": "Which question shows you think beyond the technology?", "options": ["How big is the new headquarters campus?", "How do export rules shape who you can sell to?", "Which of your chips has the most transistors?"], "correctIndex": 1, "consequences": ["Office space tells you nothing about the market.", "Rules decided H20 and H200 sales more than the specs did.", "Specs matter, but policy decided who could buy."], "explanation": "Ask a chip or AI team how export rules affect who it can sell to."}, "proReasoning": "Ask about export exposure. It shows you see chips as a policy business too.", "commonMistake": "Treating chip sales as purely about performance.", "mentalModel": "Ask about export exposure."}, "invest": {"call": {"kind": "theCall", "situation": "NVIDIA may now sell H200 chips in China, minus a 25% cut to the US.", "prompt": "How should you treat its China revenue?", "options": ["As safe, since sales are now approved", "As lost, since China is closed", "As policy-dependent and changeable"], "correctIndex": 2, "consequences": ["Approval came after a ban, and could reverse again.", "Sales were allowed again, at a price.", "In one year the rules changed three times."], "explanation": "One license rule meant up to $5.5 billion in charges. Price policy risk into chip companies."}, "proReasoning": "Investors treat revenue that depends on a license as less certain than other revenue.", "commonMistake": "Treating the latest policy as permanent.", "mentalModel": "Policy is a revenue risk."}, "build_startup": {"call": {"kind": "theCall", "situation": "Your startup sells AI software to customers in China.", "prompt": "How should you build it?", "options": ["To run on several kinds of chips", "Only for the newest US chips", "Only for H200, since it is allowed"], "correctIndex": 0, "consequences": ["Customers can run it whatever they are allowed to buy.", "Blackwell and Rubin were excluded.", "Permission for H200 could change again."], "explanation": "Companies in restricted markets lose access to top chips. Software that adapts to what they can get has an edge."}, "proReasoning": "Founders selling into restricted markets design for the chips customers can actually get.", "commonMistake": "Building for hardware your customers may not be allowed to buy.", "mentalModel": "Build for the chips they can get."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend asks why the US government would get a cut of chip sales.", "prompt": "What's the answer?", "options": ["It designed the H200 chip itself", "It controls the export permission", "It owns a large part of NVIDIA"], "correctIndex": 1, "consequences": ["NVIDIA designed the chip.", "Whoever grants the license can set conditions.", "The government is not an NVIDIA shareholder here."], "explanation": "Whoever controls chip exports holds power over the market, including the price of access."}, "proReasoning": "The holder of a permission can attach a price to it. That is what happened here.", "commonMistake": "Thinking the government is just another investor.", "mentalModel": "Permission has a price."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:5ffd730f1658$ml$]::text[]),
($ml$b3f5dd70-8f19-56b3-b0d9-ced60f9d96b0$ml$::uuid, $ml$ai$ml$, 21, 2, $ml${"id": "ai-d21-c2", "title": "Above the chokepoint", "lessonTitle": "Who decides who gets the chips", "slot": 2, "type": "connect", "brief": {"headline": "NVIDIA's data center business earned $193.7 billion in fiscal 2026 from the scarcest input in AI. Yet in April 2025, one US license rule cost it up to about $5.5 billion in charges.", "kicker": "Connect day 3 and day 21: a government can sit above the chokepoint.", "fullText": "On day 3 you saw that power in AI belongs to whoever controls the scarcest input, and NVIDIA's chips are that input. On day 21 you saw a power above it. The US government told NVIDIA on April 9, 2025 that exporting its H20 chip to China would need a license, and said on April 14 the rule would stay for the indefinite future. NVIDIA expected up to about $5.5 billion of charges for inventory, purchase commitments and reserves.\n\nIn August, licenses resumed after NVIDIA and AMD reportedly agreed to pay the US government 15% of their China chip revenue. The chokepoint company still needed permission.", "sources": [{"url": "https://www.sec.gov/Archives/edgar/data/1045810/000104581026000019/q4fy26pr.htm", "label": "NVIDIA fiscal 2026 results"}, {"url": "https://www.sec.gov/Archives/edgar/data/1045810/000104581025000082/nvda-20250409.htm", "label": "NVIDIA Form 8-K on H20 export licensing, Apr 2025"}, {"url": "https://www.datacenterdynamics.com/en/news/nvidia-and-amd-agree-to-pay-us-govt-15-of-china-chip-sales-in-order-to-obtain-export-licenses-report/", "label": "DatacenterDynamics, Nvidia and AMD agree to pay US 15% of China chip sales for export licenses, Aug 2025"}]}, "evidence": {"kind": "faceOff", "prompt": "Who decided whether H20 chips could go to China in 2025?", "left": {"name": "NVIDIA", "note": "Designs the chips"}, "right": {"name": "The US government", "note": "Grants export licenses"}, "correctIndex": 1, "explanation": "NVIDIA controls the chips, but the government controls where they can be sold."}, "numbers": {"kind": "numberSense", "prompt": "Charges of $5.5 billion against $193.7 billion of data center revenue: about what share, in percent?", "min": 0, "max": 10, "value": 2.8, "unit": "%", "explanation": "About 2.8%, from one rule. Painful, but small next to the business."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "You join a chip company's strategy team. Your manager asks who holds the most power over sales.", "prompt": "What's the best answer?", "options": ["Only our engineers, who design the chips", "Our customers, who can always buy elsewhere", "Governments that control exports, then us"], "correctIndex": 2, "consequences": ["Design matters, but permission decided the market.", "Top chips are scarce, so buyers have few options.", "Export rules decided where H20 could be sold."], "explanation": "Power in AI is layered. A chokepoint company still answers to whoever controls exports."}, "proReasoning": "Map power in layers: the government, then the chokepoint, then the buyers.", "commonMistake": "Assuming the company with the best product holds all the power.", "mentalModel": "Power comes in layers."}, "invest": {"call": {"kind": "theCall", "situation": "A chip company dominates its market. A friend calls it risk-free.", "prompt": "What's missing?", "options": ["Export policy can cut off whole markets", "Nothing, since dominance removes risk", "Only the risk of a new rival chip"], "correctIndex": 0, "consequences": ["One rule meant up to $5.5 billion in charges.", "Dominance does not protect against a license rule.", "Policy risk sits alongside rival risk."], "explanation": "Even the chokepoint has a chokepoint. Price policy risk into chip companies."}, "proReasoning": "Investors list policy risk next to competitive risk, especially for strategic products.", "commonMistake": "Thinking market dominance means no risk.", "mentalModel": "Even chokepoints answer to someone."}, "build_startup": {"call": {"kind": "theCall", "situation": "Your startup depends on one chip type that could face export limits in your market.", "prompt": "What's the prudent step?", "options": ["Stockpile years of chips today", "Make sure you can run on alternatives", "Assume the rules will never change"], "correctIndex": 1, "consequences": ["Stockpiling ties up cash and may break rules.", "Alternatives keep you running if a license rule lands.", "The rules changed several times in 2025."], "explanation": "When a government controls who can buy chips, it holds power over the supply chain. Plan for it."}, "proReasoning": "Founders treat export rules as a supply risk and keep a fallback ready.", "commonMistake": "Building on one chip that a policy change could remove.", "mentalModel": "Keep a fallback for policy shocks."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend asks how a government can stop the world's top AI chip company from selling.", "prompt": "What's the answer?", "options": ["It can shut down the factories", "It owns all the chip designs", "It can require a license to export"], "correctIndex": 2, "consequences": ["It did not shut factories; it required licenses.", "NVIDIA owns its designs.", "No license, no legal export."], "explanation": "Export licenses let a government decide which countries get advanced chips."}, "proReasoning": "Control over exports is a quiet but powerful lever. It decides who can buy.", "commonMistake": "Thinking only companies decide who gets products.", "mentalModel": "Licenses decide who buys."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:88dd3ef7f1ca$ml$]::text[]),
($ml$e5a71b47-495f-5b0c-9ca0-cf1eeb0d94ec$ml$::uuid, $ml$ai$ml$, 21, 3, $ml${"id": "ai-d21-c3", "title": "Building without the top chips", "lessonTitle": "Who decides who gets the chips", "slot": 3, "type": "decide", "brief": {"headline": "You run an AI startup in a country where the most advanced US chips now need an export license. Your plan assumed you could buy them freely.", "kicker": "Decide what to do when the top chips may not come.", "fullText": "NVIDIA said the US government informed it on April 9, 2025 that exports of its H20 chip to China, including Hong Kong and Macau, and to certain other countries would require a license. NVIDIA expected up to about $5.5 billion in charges.\n\nGovernments can decide which countries get the most advanced AI chips. Companies in restricted markets lose access to top chips, and that pain drives demand for alternatives there.", "sources": [{"url": "https://www.sec.gov/Archives/edgar/data/1045810/000104581025000082/nvda-20250409.htm", "label": "NVIDIA Form 8-K on H20 export licensing, Apr 2025"}]}, "evidence": {"kind": "sortSignal", "prompt": "Is each one in your control, or the government's?", "buckets": ["You control", "Government controls"], "items": [{"text": "How efficiently your models use chips", "bucket": 0}, {"text": "Which chip types your software supports", "bucket": 0}, {"text": "Which chips may be exported to you", "bucket": 1}, {"text": "Whether a license is granted", "bucket": 1}], "explanation": "You cannot change the rules. You can change how much compute you need and what you can run on."}, "numbers": {"kind": "numberSense", "prompt": "NVIDIA expected up to about how many billion dollars in H20 charges?", "min": 0, "max": 20, "value": 5.5, "unit": "B", "explanation": "About $5.5 billion, for inventory and commitments it could no longer sell freely."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "You're the startup's lead engineer. The CEO asks what you can do about the rules.", "prompt": "What's your answer?", "options": ["Make models need less compute", "Lobby to change the rules ourselves", "Nothing until the rules change"], "correctIndex": 0, "consequences": ["Efficiency is the lever inside your control.", "A startup has little sway over US export policy.", "Waiting leaves the company stuck."], "explanation": "Focus on what you control: efficiency and flexibility."}, "proReasoning": "Good engineers separate what they can change from what they cannot, and act on the first.", "commonMistake": "Spending energy on rules you cannot change.", "mentalModel": "Work the levers you control."}, "invest": {"call": {"kind": "theCall", "situation": "You are considering startups in markets cut off from the top chips.", "prompt": "Which kind could benefit?", "options": ["Those selling only to buyers in the US", "Those offering alternatives to the top chips", "Those that need the newest US chips to work"], "correctIndex": 1, "consequences": ["They are outside the restricted market.", "Cut-off buyers need alternatives, which creates demand.", "They are the most exposed to the rules."], "explanation": "Cut-off buyers need alternatives. That pain drives demand for them."}, "proReasoning": "Investors look for who benefits from a restriction, not just who loses.", "commonMistake": "Seeing only the losers of a policy change.", "mentalModel": "Restrictions create new demand."}, "build_startup": {"call": {"kind": "theCall", "situation": "You're the founder. Your plan assumed free access to the best US chips.", "prompt": "What's your new plan?", "options": ["Keep the plan and hope for a license", "Shut the company down", "Design for the chips you can actually get"], "correctIndex": 2, "consequences": ["Licenses can be denied or delayed indefinitely.", "Restrictions change the plan, not the opportunity.", "A plan built on available chips can proceed."], "explanation": "Companies in restricted markets lose access to top chips. Build around what you can get."}, "proReasoning": "Founders replan around the inputs they can actually secure.", "commonMistake": "Keeping a plan that depends on a permission you lack.", "mentalModel": "Plan on what you can get."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend asks why some countries cannot simply buy the best AI chips.", "prompt": "What's the answer?", "options": ["Export rules require a license first", "The chips are too heavy to ship", "Those countries have banned AI"], "correctIndex": 0, "consequences": ["The US required licenses for H20 sales to China.", "Shipping is easy; permission is not.", "They want the chips; the rules limit them."], "explanation": "Governments can decide which countries get the most advanced AI chips."}, "proReasoning": "Some products cross borders only with permission. Advanced AI chips are one.", "commonMistake": "Thinking markets alone decide who buys what.", "mentalModel": "Some goods need permission to travel."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:fae111f2954a$ml$]::text[]),
($ml$21e0840b-13a4-5604-8f09-5c5b2999e417$ml$::uuid, $ml$ai$ml$, 22, 1, $ml${"id": "ai-d22-c1", "title": "More power than Japan", "lessonTitle": "Compute measured in power", "slot": 1, "type": "apply", "brief": {"headline": "In April 2025, the International Energy Agency projected that data centres' electricity use will more than double by 2030, to about 945 terawatt-hours, slightly more than Japan uses today.", "kicker": "Apply day 22: compute is planned in watts now.", "fullText": "Data centres used about 1.5% of the world's electricity in 2024, according to the IEA's Energy and AI report, and the United States, Europe and China account for about 85% of their use. The IEA found that demand from AI-optimized data centres is set to more than quadruple by 2030.\n\nIn the United States, data centres are on course to account for almost half of electricity demand growth to 2030. By then, the country is set to use more power for data processing than for making aluminum, steel, cement and chemicals combined.\n\nThe IEA expects renewables and natural gas to meet most of the new demand.", "sources": [{"url": "https://www.thestar.com.my/tech/tech-news/2025/04/10/ai-surge-to-double-data-centre-electricity-demand-by-2030-iea", "label": "The Star, AI surge to double data centre electricity demand by 2030, Apr 2025"}, {"url": "https://www.publicpower.org/periodical/article/electricity-demand-data-centers-worldwide-set-more-double-2030-iea", "label": "American Public Power Association, data center demand set to more than double by 2030, Apr 2025"}]}, "evidence": {"kind": "spotFake", "prompt": "One of these is false about the IEA report. Tap it.", "statements": ["Data centre power use is set to more than double by 2030.", "The 2030 figure is slightly more than Japan uses today.", "Data centres used about 15% of world electricity in 2024."], "fakeIndex": 2, "explanation": "They used about 1.5% in 2024. The growth, not the share, is the headline."}, "numbers": {"kind": "numberSense", "prompt": "The IEA projects about how many terawatt-hours for data centres in 2030?", "min": 0, "max": 1500, "value": 945, "unit": "TWh", "explanation": "About 945 TWh, more than double today and slightly above Japan's total use."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "You're interviewing at a US utility's team for large customers. They ask why AI matters to them.", "prompt": "What's the sharpest answer?", "options": ["AI will cut electricity use everywhere", "Data centres use too little power to matter", "Data centres may drive half of US demand growth"], "correctIndex": 2, "consequences": ["The IEA projects data centre use more than doubling.", "They are set to outuse heavy industry in the US.", "The IEA says almost half of US growth to 2030."], "explanation": "Quote the numbers that make AI an energy story. Utilities are now part of the AI industry."}, "proReasoning": "Bring one number that links AI to power, like almost half of US demand growth.", "commonMistake": "Treating AI as purely a software story.", "mentalModel": "AI is an energy story too."}, "invest": {"call": {"kind": "theCall", "situation": "The IEA projects data centre power use more than doubling by 2030.", "prompt": "Who feels that demand directly?", "options": ["Utilities and power equipment makers", "Only the chatbot companies", "Nobody, since efficiency cancels it"], "correctIndex": 0, "consequences": ["Power demand is the next bottleneck after chips.", "They pay the bills; utilities supply the power.", "The IEA projection already accounts for that trend."], "explanation": "Data centre demand lands on utilities and the companies that build grid equipment."}, "proReasoning": "Investors follow AI demand into power: generation, grids and equipment.", "commonMistake": "Looking for AI winners only among tech companies.", "mentalModel": "Follow AI demand into power."}, "build_startup": {"call": {"kind": "theCall", "situation": "You are choosing a product for data centre operators.", "prompt": "Which pain is growing fastest?", "options": ["Designing nicer office lobbies", "Getting more compute from each watt", "Finding enough floor space for desks"], "correctIndex": 1, "consequences": ["Lobbies do not run AI.", "Power is becoming the limit on how much AI gets built.", "Space for people is not their constraint."], "explanation": "As AI-optimized data centres quadruple their demand, every watt saved is capacity gained."}, "proReasoning": "Founders build for the bottleneck. In data centres, more and more that means power.", "commonMistake": "Solving problems the customer does not lose sleep over.", "mentalModel": "Build for the watt."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend asks how much power AI data centres will use.", "prompt": "What's a good way to put it?", "options": ["About as much as one small town", "Less each year, thanks to better chips", "By 2030, a bit more than Japan uses today"], "correctIndex": 2, "consequences": ["Far more: a whole country's worth.", "The IEA projects use more than doubling.", "About 945 terawatt-hours, in the IEA's projection."], "explanation": "Comparing to a country makes the number real: about Japan's total use, by 2030."}, "proReasoning": "Big numbers land better as comparisons. \"About Japan\" beats \"945 terawatt-hours\".", "commonMistake": "Quoting a big number nobody can picture.", "mentalModel": "Compare it to something real."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:122c38d3ec12$ml$]::text[]),
($ml$73a37016-0d6f-5d0d-a902-0560f8f4642a$ml$::uuid, $ml$ai$ml$, 22, 2, $ml${"id": "ai-d22-c2", "title": "Compounding compute, compounding watts", "lessonTitle": "Compute measured in power", "slot": 2, "type": "connect", "brief": {"headline": "Training compute for top models grows 4 to 5 times a year. US data centres used 58 terawatt-hours in 2014 and 176 in 2023, about 4.4% of the country's electricity.", "kicker": "Connect day 4 and day 22: growing compute becomes growing power.", "fullText": "On day 4 you saw training compute for frontier models grow 4 to 5 times a year. On day 22 you saw what that looks like on the grid. A Lawrence Berkeley National Laboratory report released by the Department of Energy found US data centres used about 4.4% of US electricity in 2023, or 176 terawatt-hours, up from 58 in 2014. It projected their share could reach about 6.7% to 12% by 2028.\n\nChips get more efficient, but not as fast as demand for compute grows. The curve shows up in power bills.", "sources": [{"url": "https://epoch.ai/blog/training-compute-of-frontier-ai-models-grows-by-4-5x-per-year", "label": "Epoch AI, training compute growth"}, {"url": "https://www.energy.gov/articles/doe-releases-new-report-evaluating-increase-electricity-demand-data-centers", "label": "US Department of Energy, data center electricity report, Dec 2024"}]}, "evidence": {"kind": "multipleChoice", "prompt": "From 58 terawatt-hours in 2014 to 176 in 2023: about how many times more?", "options": ["About 1.3 times", "About 3 times", "About 30 times"], "correctIndex": 1, "explanation": "176 divided by 58 is about 3. Power use tripled in nine years, and the projection rises further."}, "numbers": {"kind": "numberSense", "prompt": "If data centres reach 12% of US electricity by 2028, how many times their 2023 share of 4.4% is that?", "min": 0, "max": 10, "value": 2.7, "unit": "x", "explanation": "About 2.7 times in five years, at the high end of the projection."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "An interviewer asks why AI teams now talk about megawatts, not just GPUs.", "prompt": "What's your answer?", "options": ["Compute growth is now limited by power", "GPUs no longer need electricity", "Megawatts measure model accuracy"], "correctIndex": 0, "consequences": ["US data centres already use 4.4% of US power, and rising.", "More compute means more power.", "Megawatts measure power, not accuracy."], "explanation": "In AI, the numbers that decide compute are increasingly measured in power."}, "proReasoning": "Connect the compute curve to the power curve. It shows you see the whole system.", "commonMistake": "Treating power as someone else's problem.", "mentalModel": "Compute is measured in power."}, "invest": {"call": {"kind": "theCall", "situation": "Data centres could reach 6.7% to 12% of US power by 2028.", "prompt": "What does that range tell you?", "options": ["Demand is certain to reach the full 12%", "Demand rises, but by how much is unclear", "Demand will stay flat for the next few years"], "correctIndex": 1, "consequences": ["A range is a projection, not a promise.", "Even the low end is a big rise from 4.4%.", "Both ends of the range are above today."], "explanation": "Power demand is the next bottleneck. Plan for the range, not a single number."}, "proReasoning": "Investors read a projection range as both a direction and a risk band.", "commonMistake": "Picking one end of a range and treating it as fact.", "mentalModel": "Plan for the range."}, "build_startup": {"call": {"kind": "theCall", "situation": "Your startup trains models, and your power bill is growing faster than your users.", "prompt": "What's the first lever to pull?", "options": ["Ignore it, since power is cheap", "Buy more GPUs to finish faster", "Cut the compute each result needs"], "correctIndex": 2, "consequences": ["Power is a growing share of AI costs.", "More GPUs draw more power.", "Less compute per result means less power per result."], "explanation": "Compute and power grow together. Efficiency cuts both."}, "proReasoning": "Founders watch power per result as closely as compute per result.", "commonMistake": "Scaling hardware without counting the power.", "mentalModel": "Efficiency cuts both bills."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend asks why AI is suddenly in debates about the power grid.", "prompt": "What's the answer?", "options": ["Data centre power use tripled in a decade", "AI chatbots run on batteries, not the grid", "Power companies are building their own AI"], "correctIndex": 0, "consequences": ["From 58 to 176 terawatt-hours, and still rising.", "They run on the grid, in data centres.", "They supply power to those who build AI."], "explanation": "Fast-growing compute needs fast-growing power. The grid is where that shows up."}, "proReasoning": "When a technology grows on a curve, its inputs grow too. For AI, that includes electricity.", "commonMistake": "Thinking software has no physical footprint.", "mentalModel": "Software runs on power."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:aea4bacd63ae$ml$]::text[]),
($ml$03cf1a02-d300-5789-b18f-40c397fde52c$ml$::uuid, $ml$ai$ml$, 22, 3, $ml${"id": "ai-d22-c3", "title": "Where to put 100,000 GPUs", "lessonTitle": "Compute measured in power", "slot": 3, "type": "decide", "brief": {"headline": "You run site selection for a 100,000-GPU cluster. One site has cheap land but a grid connection years away. Another costs more but has power available now.", "kicker": "Decide which site gets your cluster built fastest.", "fullText": "xAI built a cluster of 100,000 NVIDIA H100 GPUs in Memphis in 122 days. As clusters grow that large, electricity becomes one of the numbers that decide where AI gets built.\n\nA Lawrence Berkeley National Laboratory report for the Department of Energy found US data centres used about 4.4% of US electricity in 2023, and projected 6.7% to 12% by 2028. Power that is available now is worth more than cheap land that waits for it.", "sources": [{"url": "https://getcoai.com/news/musks-xai-launches-100000-gpu-supercomputer-in-122-days", "label": "CO/AI, xAI launches 100,000-GPU supercomputer in 122 days"}, {"url": "https://www.energy.gov/articles/doe-releases-new-report-evaluating-increase-electricity-demand-data-centers", "label": "US Department of Energy, data center electricity report, Dec 2024"}]}, "evidence": {"kind": "sortSignal", "prompt": "Does each factor speed up the build or slow it down?", "buckets": ["Speeds it up", "Slows it down"], "items": [{"text": "Power already available at the site", "bucket": 0}, {"text": "Cooling planned with the building", "bucket": 0}, {"text": "A grid connection still years away", "bucket": 1}, {"text": "Waiting on a new power plant", "bucket": 1}], "explanation": "GPUs can be installed in months. Power often cannot, so power decides the schedule."}, "numbers": {"kind": "numberSense", "prompt": "xAI built its 100,000-GPU Memphis cluster in how many days?", "min": 0, "max": 365, "value": 122, "unit": "days", "explanation": "122 days. Builds that fast need power that is ready."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "You're the site selection lead presenting to executives.", "prompt": "What do you lead with?", "options": ["Which site has the nicest office space", "When each site can get the power it needs", "Which site has the cheapest land price"], "correctIndex": 1, "consequences": ["Offices do not run clusters.", "Power timing decides when the GPUs can run.", "Cheap land is no use if the power comes years later."], "explanation": "Electricity is one of the numbers that decide where AI gets built."}, "proReasoning": "Lead with the constraint. For big clusters, that is power availability.", "commonMistake": "Comparing sites on land cost first.", "mentalModel": "Power first, land second."}, "invest": {"call": {"kind": "theCall", "situation": "Two data centre developers: one owns land, one owns land with secured power.", "prompt": "Which asset is worth more today?", "options": ["Land alone, since it is cheaper", "Both are worth the same", "Land with secured power"], "correctIndex": 2, "consequences": ["Cheap land without power waits.", "Power changes what the land can do.", "Power is the scarce part of a site."], "explanation": "Power demand is the next bottleneck. Sites with power are where builds can start."}, "proReasoning": "Investors value data centre sites by their power, not their acreage.", "commonMistake": "Valuing a site by its size.", "mentalModel": "Value the site by its power."}, "build_startup": {"call": {"kind": "theCall", "situation": "You're the founder. Investors want the cluster running within a year.", "prompt": "Which site do you pick?", "options": ["The site with power available now", "The cheap site, and wait for the grid", "Split the GPUs across both sites"], "correctIndex": 0, "consequences": ["You can build on a timeline like xAI's 122 days.", "Years of waiting breaks the one-year goal.", "Half the cluster would still wait for power."], "explanation": "Fast builds need fast power. The site with power is the one that meets the timeline."}, "proReasoning": "Founders pick sites by when power arrives, because that sets when revenue starts.", "commonMistake": "Saving on land and losing years.", "mentalModel": "Pay for power that is ready."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend asks why AI companies care so much about where they build.", "prompt": "What's the answer?", "options": ["Chips only work in certain cool climates", "Some places have power ready, others do not", "They want to be near famous big cities"], "correctIndex": 1, "consequences": ["Chips work anywhere with power and cooling.", "Power availability decides how fast a cluster can run.", "Fame does not supply megawatts."], "explanation": "Electricity is one of the numbers that decide where AI gets built."}, "proReasoning": "Follow the power lines to find where AI gets built.", "commonMistake": "Assuming data centres go wherever land is cheap.", "mentalModel": "Follow the power."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:1ce9e33ae34a$ml$]::text[]),
($ml$949b8316-d23c-53c9-99ef-842ed84e557a$ml$::uuid, $ml$ai$ml$, 23, 1, $ml${"id": "ai-d23-c1", "title": "Another reactor comes back", "lessonTitle": "A reactor for a data center", "slot": 1, "type": "apply", "brief": {"headline": "In October 2025, Google signed a 25-year deal to buy power from Iowa's Duane Arnold nuclear plant, which NextEra plans to restart by early 2029. The 615-megawatt plant shut in 2020 after storm damage.", "kicker": "Apply day 23: AI growth tied to a reactor years away.", "fullText": "Duane Arnold, near Cedar Rapids, closed in 2020 after damage from a derecho, a powerful windstorm. On October 27, 2025, NextEra Energy said it would bring the plant back, with Google buying power under a 25-year agreement to support its cloud and AI infrastructure in Iowa. NextEra said Iowa customers would not bear the cost of Google's power, and that it is working with the Nuclear Regulatory Commission on a safe return.\n\nGoogle has run a data center in Council Bluffs since 2007 and is building another in Cedar Rapids. Like Microsoft's Three Mile Island deal, it ties AI growth to a reactor that will take years to restart.", "sources": [{"url": "https://www.powermag.com/google-has-deal-with-nextera-to-restart-duane-arnold-nuclear-plant/", "label": "POWER Magazine, Google deal with NextEra to restart Duane Arnold, Oct 2025"}, {"url": "https://www.nucnet.org/news/constellation-announces-plans-to-restart-unit-1-of-three-mile-island-nuclear-plant-9-5-2024", "label": "NucNet, Constellation to restart Three Mile Island Unit 1, Sep 2024"}]}, "evidence": {"kind": "sortSignal", "prompt": "Which reactor deal does each fact describe?", "buckets": ["Duane Arnold, Google", "Three Mile Island, Microsoft"], "items": [{"text": "A 25-year power agreement", "bucket": 0}, {"text": "615 megawatts", "bucket": 0}, {"text": "Closed in 2020 after storm damage", "bucket": 0}, {"text": "A 20-year power agreement", "bucket": 1}, {"text": "About 835 megawatts", "bucket": 1}, {"text": "Shut in 2019 for economic reasons", "bucket": 1}], "explanation": "Two tech giants, two closed reactors, two long contracts. Both restarts take years."}, "numbers": {"kind": "numberSense", "prompt": "Signed in October 2025 for a restart by early 2029: about how many years of waiting?", "min": 0, "max": 10, "value": 3, "unit": "years", "explanation": "More than three years. A GPU cluster can go up in 122 days."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "You're an energy engineer with offers from a data center company and a nuclear operator.", "prompt": "What's the fairest view of the two?", "options": ["Both now sit inside the AI industry", "Only the data center job is about AI", "Nuclear has nothing to do with AI"], "correctIndex": 0, "consequences": ["Google and Microsoft are signing 20- and 25-year reactor deals.", "Reactors are being restarted to power AI.", "Two restarts are tied directly to AI demand."], "explanation": "Data center builders now sign long power deals. Energy roles are part of the AI industry."}, "proReasoning": "See energy jobs as AI jobs too. The power deals prove the link.", "commonMistake": "Thinking AI careers stop at the data center door.", "mentalModel": "Energy is part of AI now."}, "invest": {"call": {"kind": "theCall", "situation": "Part of Google's Iowa AI growth depends on a reactor restart planned for 2029.", "prompt": "How do you account for that?", "options": ["Ignore it, since power is easy", "Price in the risk the timeline slips", "Assume 2029 is guaranteed"], "correctIndex": 1, "consequences": ["Restarting a closed reactor is anything but easy.", "Restarts need regulators, repairs and time.", "The NRC still has to approve a safe return."], "explanation": "Power delays are project delays. AI projects tied to new power carry that timeline risk."}, "proReasoning": "Investors treat power timelines as project timelines, with the same risk of slipping.", "commonMistake": "Taking a target date as a certainty.", "mentalModel": "Power delays are project delays."}, "build_startup": {"call": {"kind": "theCall", "situation": "Your data center startup wants long-term clean power, but giants are signing the reactor deals.", "prompt": "What's a realistic move?", "options": ["Outbid Google for the Duane Arnold power", "Wait to sign a reactor deal of your own", "Find power sources giants have not locked up"], "correctIndex": 2, "consequences": ["You cannot match a 25-year Google contract.", "Restarts take years and huge budgets.", "Smaller players win by finding overlooked supply."], "explanation": "Giants lock up power. Smaller players struggle to match deals like that and need other routes."}, "proReasoning": "Founders look for power the giants skipped, rather than competing head on.", "commonMistake": "Competing with giants for the same scarce supply.", "mentalModel": "Find the power others skipped."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend asks why Google would pay to restart an old nuclear plant.", "prompt": "What's the best explanation?", "options": ["It needs steady carbon-free power for years", "Old nuclear plants make good office space", "The law forces it to buy nuclear power"], "correctIndex": 0, "consequences": ["NextEra called it 24/7 carbon-free energy for Google's AI.", "The plant generates power; it does not house data centers.", "It chose the deal; nothing forced it."], "explanation": "AI data centers need large, steady supplies of power, and nuclear runs around the clock."}, "proReasoning": "Follow the need: steady, clean power for decades. A reactor fits that need.", "commonMistake": "Thinking the deal is about publicity.", "mentalModel": "Steady power for steady demand."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:41e2bece6aa8$ml$]::text[]),
($ml$6ccd1f05-6d46-5154-b45f-58ea725a4ff0$ml$::uuid, $ml$ai$ml$, 23, 2, $ml${"id": "ai-d23-c2", "title": "Money moves fast, power moves slow", "lessonTitle": "A reactor for a data center", "slot": 2, "type": "connect", "brief": {"headline": "In 2025, five tech giants expected $364 billion to $400 billion of capital spending. Microsoft's deal to restart a Three Mile Island reactor, signed in 2024, targets power by 2028.", "kicker": "Connect day 20 and day 23: budgets move in quarters, power in years.", "fullText": "On day 20 you saw a handful of companies plan hundreds of billions of capex in a single year, and raise their guidance from one quarter to the next. On day 23 you saw how long power takes. Constellation agreed a 20-year deal with Microsoft in September 2024 to restart Unit 1 at Three Mile Island, which shut in 2019. The restart is expected by 2028 and should add about 835 megawatts.\n\nMoney can be approved quickly. Power plants, grid connections and restarts cannot. Compute waits on power, and power takes years.", "sources": [{"url": "https://www.emarketer.com/content/genai-arms-race--big-tech-pour--400-billion-ai-buildout", "label": "eMarketer, Big Tech to pour up to $400 billion into AI buildout, 2025"}, {"url": "https://www.nucnet.org/news/constellation-announces-plans-to-restart-unit-1-of-three-mile-island-nuclear-plant-9-5-2024", "label": "NucNet, Constellation to restart Three Mile Island Unit 1, Sep 2024"}]}, "evidence": {"kind": "multipleChoice", "prompt": "Capex can be approved in a quarter. What sets the pace of new AI capacity?", "options": ["How fast new power comes online", "How fast budgets get approved", "How fast new chip names are chosen"], "correctIndex": 0, "explanation": "A reactor signed in 2024 targets 2028. Money arrives faster than power does."}, "numbers": {"kind": "numberSense", "prompt": "The Three Mile Island restart should add about how many megawatts?", "min": 0, "max": 2000, "value": 835, "unit": "MW", "explanation": "About 835 megawatts, years after the deal was signed."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "You're interviewing for a data center planning role. They ask what limits growth most.", "prompt": "What's your answer?", "options": ["Chip names, which take time to pick", "Power, which takes years to add", "Budgets, which are hard to approve"], "correctIndex": 1, "consequences": ["Names are not a constraint.", "A 2024 deal targets 2028 power.", "Hundreds of billions were approved in 2025."], "explanation": "In AI, compute waits on power, and power takes years."}, "proReasoning": "Show you know which clock is slowest. In AI infrastructure, it is power.", "commonMistake": "Assuming money is the binding constraint.", "mentalModel": "Power runs on the slowest clock."}, "invest": {"call": {"kind": "theCall", "situation": "A giant doubles its capex plan for the year.", "prompt": "What might stop it from spending all of it?", "options": ["Too few chip designs to buy", "Lack of interest from its board", "Power and grid connections that lag"], "correctIndex": 2, "consequences": ["Chip supply is tight, but power is slower still.", "The board approved the spending.", "Buildings without power cannot run GPUs."], "explanation": "Power delays are project delays. A budget does not build a power plant faster."}, "proReasoning": "Investors check whether power can keep pace with announced capex.", "commonMistake": "Treating announced spending as capacity already built.", "mentalModel": "Budgets do not make power."}, "build_startup": {"call": {"kind": "theCall", "situation": "You are founding a company to serve AI data centers.", "prompt": "Where is the slowest, most painful step?", "options": ["Bringing new power online", "Getting budgets approved", "Ordering chips online"], "correctIndex": 0, "consequences": ["Anything that speeds up power solves the slowest step.", "Budgets are flowing quickly.", "Chips are scarce, but power takes longer."], "explanation": "Fast builds need fast power. Speeding up the slowest step is where the value is."}, "proReasoning": "Founders aim at the slowest step in the chain. That is where customers will pay most.", "commonMistake": "Speeding up steps that are already fast.", "mentalModel": "Speed up the slowest step."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend asks why tech giants with so much money cannot just get more power now.", "prompt": "What's the answer?", "options": ["Electricity is rationed by law", "Power plants take years to build or restart", "Power companies refuse to sell to them"], "correctIndex": 1, "consequences": ["No such rationing applies.", "A deal signed in 2024 targets a 2028 restart.", "Utilities are signing 20-year deals with them."], "explanation": "Money moves in quarters. Power plants move in years."}, "proReasoning": "Money cannot speed up physics or permits beyond a point. Power takes time.", "commonMistake": "Thinking enough money solves any delay.", "mentalModel": "Money cannot rush power."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:21a43b6738cf$ml$]::text[]),
($ml$13556a97-676d-559d-9ae5-8f8e010830e4$ml$::uuid, $ml$ai$ml$, 23, 3, $ml${"id": "ai-d23-c3", "title": "The gap before the reactor", "lessonTitle": "A reactor for a data center", "slot": 3, "type": "decide", "brief": {"headline": "You run a company building an AI campus that opens in 2026. You have signed for reactor power that only arrives in 2028.", "kicker": "Decide how to power the campus until the reactor arrives.", "fullText": "In September 2024, Constellation Energy agreed a 20-year power purchase agreement with Microsoft to restart Unit 1 at Three Mile Island, which shut in 2019 for economic reasons. The restart is expected by 2028 and should add about 835 megawatts of carbon-free power.\n\nPower runs on a slower clock than chips. A 100,000-GPU cluster went up in 122 days; a reactor restart signed in 2024 targets 2028.", "sources": [{"url": "https://www.nucnet.org/news/constellation-announces-plans-to-restart-unit-1-of-three-mile-island-nuclear-plant-9-5-2024", "label": "NucNet, Constellation to restart Three Mile Island Unit 1, Sep 2024"}, {"url": "https://getcoai.com/news/musks-xai-launches-100000-gpu-supercomputer-in-122-days", "label": "CO/AI, xAI launches 100,000-GPU supercomputer in 122 days"}]}, "evidence": {"kind": "buildChain", "prompt": "Put a sensible power plan in order.", "steps": ["Sign the long-term reactor deal", "Arrange interim grid power for 2026", "Size the first phase to that interim supply", "Expand when reactor power arrives in 2028"], "explanation": "Long-term power secures the future. Interim power and a phased build cover the gap."}, "numbers": {"kind": "numberSense", "prompt": "Three Mile Island Unit 1 shut in 2019 and targets a restart by 2028. How many years offline?", "min": 0, "max": 20, "value": 9, "unit": "years", "explanation": "About nine years. Restarting power takes far longer than installing GPUs."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "You're the campus's energy manager. The CEO wants all GPUs running on day one in 2026.", "prompt": "What do you tell the CEO?", "options": ["Install everything and hope power appears", "Delay the whole campus to 2028", "Phase the GPUs to the power we have"], "correctIndex": 2, "consequences": ["GPUs without power earn nothing.", "Waiting two years wastes the building.", "The campus earns from day one and grows with power."], "explanation": "Compute waits on power. Match the build to the power you can actually get."}, "proReasoning": "Energy managers match compute to available power and phase the rest.", "commonMistake": "Promising capacity the power cannot support.", "mentalModel": "Phase compute to power."}, "invest": {"call": {"kind": "theCall", "situation": "The campus's revenue plan assumes full capacity in 2026.", "prompt": "What do you challenge?", "options": ["How full power arrives before 2028", "The color of the campus logo", "Nothing, since the reactor deal is signed"], "correctIndex": 0, "consequences": ["Signed reactor power still arrives in 2028.", "Branding does not change capacity.", "Signed is not the same as delivered."], "explanation": "Power delays are project delays. A signed deal does not deliver power early."}, "proReasoning": "Investors check that revenue plans match when power actually arrives.", "commonMistake": "Confusing a signed contract with delivered power.", "mentalModel": "Signed is not delivered."}, "build_startup": {"call": {"kind": "theCall", "situation": "You're the founder. Reactor power comes in 2028; the building is ready in 2026.", "prompt": "What do you lock in first?", "options": ["A second reactor deal for 2035", "Interim power that covers the gap", "More GPUs than the building can power"], "correctIndex": 1, "consequences": ["That leaves 2026 to 2028 uncovered.", "It lets you open in 2026 and grow into 2028.", "Unpowered GPUs are idle capital."], "explanation": "Long-term supply secures the future, but you also need power for the years before it arrives."}, "proReasoning": "Founders plan for the gap between signing for power and receiving it.", "commonMistake": "Treating long-term deals as near-term supply.", "mentalModel": "Cover the gap."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend asks why a company would sign for power it cannot use for two years.", "prompt": "What's the answer?", "options": ["It is a mistake companies often make", "Power is cheaper if you wait", "Long-term power is scarce and takes years"], "correctIndex": 2, "consequences": ["It is deliberate planning, not a mistake.", "Price is set by the deal; timing is the issue.", "Restarts take years, so deals are signed early."], "explanation": "Compute waits on power, and power takes years. So companies sign years ahead."}, "proReasoning": "When supply takes years, buyers sign years ahead. Power works like that now.", "commonMistake": "Reading early deals as poor planning.", "mentalModel": "Sign early for slow supply."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:64cc8ca6e5dd$ml$]::text[]),
($ml$8735c0b8-be41-512e-ab40-c2f870e3d584$ml$::uuid, $ml$ai$ml$, 24, 1, $ml${"id": "ai-d24-c1", "title": "Fifteen hours in one region", "lessonTitle": "A failure every three hours", "slot": 1, "type": "apply", "brief": {"headline": "On October 20, 2025, a failure in AWS's US-EAST-1 region knocked services like Alexa, Snapchat, Fortnite and Venmo offline. AWS traced it to a race condition that left an empty DNS record for DynamoDB.", "kicker": "Apply day 24: at scale, rare failures are certain.", "fullText": "AWS first reported rising error rates at 3:11 in the morning, Eastern time. A latent race condition in DynamoDB's DNS automation wrote an empty record for its regional endpoint, and the automation did not repair it. The failure cascaded into new EC2 launches, Lambda and load balancers. AWS said all services were back to normal by 3:01 in the afternoon, Pacific time, about 15 hours later.\n\nAWS disabled the automation worldwide while it fixed the bug. One analyst noted that over five years, AWS had been available 99.95% of the time.\n\nAt enough scale, failure is routine. What matters is how a system is designed to recover.", "sources": [{"url": "https://www.infoq.com/news/2025/11/aws-dynamodb-outage-postmortem", "label": "InfoQ, AWS DynamoDB outage postmortem, Nov 2025"}, {"url": "https://www.engadget.com/big-tech/aws-fell-on-its-face-knocking-many-apps-websites-and-games-offline-142935040.html", "label": "Engadget, AWS outage knocked apps offline for hours, Oct 2025"}]}, "evidence": {"kind": "buildChain", "prompt": "Follow how the outage spread.", "steps": ["A race condition writes an empty DNS record", "Services cannot find DynamoDB's endpoint", "EC2, Lambda and load balancers fail in turn", "Apps like Snapchat and Venmo go down", "AWS disables the automation and recovers"], "explanation": "One small fault cascaded because many services depended on the same piece in the same region."}, "numbers": {"kind": "numberSense", "prompt": "From 3:11 in the morning, Eastern time, to 3:01 in the afternoon, Pacific time: about how many hours?", "min": 0, "max": 48, "value": 15, "unit": "hours", "explanation": "About 15 hours, in a cloud available 99.95% of the time over five years."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "You're interviewing for a reliability role. They ask how you'd keep an app up if one cloud region fails.", "prompt": "What's your answer?", "options": ["Restart everything by hand when it breaks", "Run in two regions and test the failover", "Trust the cloud, since it rarely fails"], "correctIndex": 1, "consequences": ["Manual restarts are slow, and failures are certain.", "A tested second region keeps you up when one fails.", "99.95% still left one long outage."], "explanation": "At enough scale, failure is routine and has to be designed for."}, "proReasoning": "Have a view on reliability: design for the failure you know will come, and test it.", "commonMistake": "Treating a provider's good record as a guarantee.", "mentalModel": "Design for the failure."}, "invest": {"call": {"kind": "theCall", "situation": "A software company says outages like this one cannot hurt it.", "prompt": "What do you ask?", "options": ["How many engineers it employs", "Nothing, since its cloud is reliable", "How it is designed to recover from one"], "correctIndex": 2, "consequences": ["Headcount says little about resilience.", "AWS itself went down for about 15 hours.", "Recovery design turns rare failures into short ones."], "explanation": "Reliability turns into cost and revenue. Ask how a system recovers, not whether it fails."}, "proReasoning": "Investors ask about recovery plans, because failure at scale is a when, not an if.", "commonMistake": "Taking \"it won't happen to us\" at face value.", "mentalModel": "Ask how it recovers."}, "build_startup": {"call": {"kind": "theCall", "situation": "Your startup runs entirely in US-EAST-1, and customers depend on you all day.", "prompt": "What do you plan?", "options": ["A fallback in a second region", "Nothing, since outages are rare", "Moving everything to one bigger server"], "correctIndex": 0, "consequences": ["A second region keeps you running when one fails.", "Rare is not never, as October 20 showed.", "One server is a single point of failure too."], "explanation": "At scale, failure is routine. A fallback is the design that survives it."}, "proReasoning": "Founders weigh the cost of a fallback against a day of downtime for every customer.", "commonMistake": "Betting the business on one region staying up.", "mentalModel": "Have a fallback."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend asks how one bug took down Snapchat, Venmo and Fortnite at once.", "prompt": "What's the answer?", "options": ["They all share the same app code", "They relied on the same cloud region", "A hacker attacked all of them at once"], "correctIndex": 1, "consequences": ["Different code, same underlying cloud.", "One fault in one region spread to everything built on it.", "AWS traced it to its own automation bug."], "explanation": "Shared infrastructure means shared failures. One region, many apps."}, "proReasoning": "When many things fail at once, look for what they share underneath.", "commonMistake": "Assuming a simultaneous failure must be an attack.", "mentalModel": "Shared base, shared failure."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:5f93e54cd916$ml$]::text[]),
($ml$115ee5f7-2a85-57c1-b22c-ce5598c2a504$ml$::uuid, $ml$ai$ml$, 24, 2, $ml${"id": "ai-d24-c2", "title": "The price of a lost hour", "lessonTitle": "A failure every three hours", "slot": 2, "type": "connect", "brief": {"headline": "Gemini Ultra's training compute cost an estimated $191 million. Meta's Llama 3 run hit 419 interruptions in 54 days and still kept effective training time above 90%.", "kicker": "Connect day 8 and day 24: on costly runs, reliability is money.", "fullText": "On day 8 you saw frontier training reach nine figures: an estimated $78 million of compute for GPT-4 and $191 million for Gemini Ultra. On day 24 you saw what happens on a real cluster. Training the 405-billion-parameter Llama 3 on 16,384 H100 GPUs over 54 days, Meta hit 419 unexpected interruptions, about one every three hours. 148 were GPU faults and 72 were HBM3 memory faults.\n\nMeta kept effective training time above 90%. On a nine-figure run, every point of lost time is worth millions.", "sources": [{"url": "https://fortune.com/2024/04/18/google-gemini-cost-191-million-to-train-stanford-university-report-estimates/", "label": "Fortune on the Stanford AI Index training cost estimates, Apr 2024"}, {"url": "https://datacenterdynamics.com/en/news/meta-report-details-hundreds-of-gpu-and-hbm3-related-interruptions-to-llama-3-training-run", "label": "DatacenterDynamics, interruptions during the Llama 3 training run, 2024"}]}, "evidence": {"kind": "sortSignal", "prompt": "Does each one raise or lower effective training time?", "buckets": ["Raises it", "Lowers it"], "items": [{"text": "Restarting fast after a GPU fault", "bucket": 0}, {"text": "Finding the failed chip in minutes", "bucket": 0}, {"text": "Taking hours to find a failed GPU", "bucket": 1}, {"text": "Restarting the run from the beginning", "bucket": 1}], "explanation": "Failures will happen. Fast detection and recovery decide how much training time survives."}, "numbers": {"kind": "numberSense", "prompt": "If 10% of a $191 million training run is lost to failures, how many million dollars is that?", "min": 0, "max": 60, "value": 19.1, "unit": "M", "explanation": "About $19.1 million. Reliability work pays for itself on runs this size."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "You're interviewing for a training infrastructure role. They ask why reliability matters so much.", "prompt": "What's your answer?", "options": ["Failures are rare on good hardware", "Reliability matters only for user apps", "Each lost point of uptime costs millions"], "correctIndex": 2, "consequences": ["419 interruptions in 54 days says otherwise.", "Training runs lose real money when they stall.", "10% of a $191 million run is about $19 million."], "explanation": "Reliability turns into cost and speed. On nine-figure runs, the stakes are large."}, "proReasoning": "Turn reliability into dollars. It shows you understand why the role exists.", "commonMistake": "Treating hardware failures as rare edge cases.", "mentalModel": "Uptime is money."}, "invest": {"call": {"kind": "theCall", "situation": "Two labs spend the same on compute. One keeps 95% effective training time, the other 80%.", "prompt": "What does that mean?", "options": ["The first gets far more training per dollar", "They get the same result for the money", "The second is safer, since it pauses more"], "correctIndex": 0, "consequences": ["Fifteen points of uptime is a big share of a costly run.", "Lost time is paid for and wasted.", "Pauses here are failures, not caution."], "explanation": "Ask about effective training time. Reliability turns into cost and speed."}, "proReasoning": "Investors compare labs on effective compute, not just compute bought.", "commonMistake": "Comparing compute budgets without asking how much was used.", "mentalModel": "Effective compute is what counts."}, "build_startup": {"call": {"kind": "theCall", "situation": "You are thinking about a startup that helps big clusters recover from failures.", "prompt": "How do you test demand?", "options": ["Build it first, ask questions later", "Ask teams how much time failures cost them", "Assume every lab already has this solved"], "correctIndex": 1, "consequences": ["Building before asking risks solving the wrong problem.", "If the answer is large, the gap is real.", "Meta still hit 419 interruptions."], "explanation": "Ask teams running large clusters how much time failures cost them. A large answer means a gap."}, "proReasoning": "Founders measure the pain in hours and dollars before building.", "commonMistake": "Assuming the biggest labs have no unsolved problems.", "mentalModel": "Measure the pain first."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend asks why AI labs care when a single chip fails among thousands.", "prompt": "What's the answer?", "options": ["They pay a fine for each failure", "Chips are rare and cannot be replaced", "One failure can pause the whole run"], "correctIndex": 2, "consequences": ["The cost is lost time, not fines.", "Chips can be replaced; the time cannot.", "Thousands of GPUs work together, so one fault stops them."], "explanation": "In a giant training run, the chips work as one machine. One failure stalls them all."}, "proReasoning": "In tightly linked systems, the weakest part sets the pace for everything.", "commonMistake": "Thinking one failure among thousands does not matter.", "mentalModel": "One fault can stall all."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:fb8cab40b669$ml$]::text[]),
($ml$45d2541c-1569-51b6-b5d8-065aeb46ea2f$ml$::uuid, $ml$ai$ml$, 24, 3, $ml${"id": "ai-d24-c3", "title": "How often to save progress", "lessonTitle": "A failure every three hours", "slot": 3, "type": "decide", "brief": {"headline": "You run a large training job on about 16,000 GPUs. Failures come about every three hours, and each one sends you back to your last saved checkpoint.", "kicker": "Decide how to keep the run moving when failure is routine.", "fullText": "Meta reported that training the 405-billion-parameter Llama 3 model on 16,384 NVIDIA H100 GPUs over 54 days saw 419 unexpected interruptions, about one every three hours. 148 were GPU faults and 72 were HBM3 memory faults, together just over half. Meta still kept effective training time above 90%.\n\nWith thousands of GPUs, something breaks every few hours. Fast recovery decides how much training time survives.", "sources": [{"url": "https://datacenterdynamics.com/en/news/meta-report-details-hundreds-of-gpu-and-hbm3-related-interruptions-to-llama-3-training-run", "label": "DatacenterDynamics, interruptions during the Llama 3 training run, 2024"}]}, "evidence": {"kind": "spotFake", "prompt": "One of these is false about the Llama 3 run. Tap it.", "statements": ["148 interruptions were GPU faults.", "72 were HBM3 memory faults.", "The run went its first month without any interruption."], "fakeIndex": 2, "explanation": "Interruptions came about every three hours across the whole 54 days."}, "numbers": {"kind": "numberSense", "prompt": "Meta saw 419 interruptions in 54 days. About how many per day?", "min": 0, "max": 20, "value": 7.8, "unit": "per day", "explanation": "About 7.8 a day. Recovery has to be routine, not an emergency."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "You're the engineer on call. Checkpoints are saved every 12 hours.", "prompt": "What do you propose?", "options": ["Save far more often than failures occur", "Keep the 12 hours to save on storage", "Save only at the very end of the run"], "correctIndex": 0, "consequences": ["Each failure then costs minutes, not hours.", "With failures every three hours, you could lose hours each time.", "One failure would erase everything."], "explanation": "Build fast recovery into the job. Save progress more often than things break."}, "proReasoning": "Match the save interval to the failure rate. That is how runs keep 90% or more effective time.", "commonMistake": "Saving progress less often than failures happen.", "mentalModel": "Save more often than you fail."}, "invest": {"call": {"kind": "theCall", "situation": "A lab tells investors its runs have about 50% effective training time.", "prompt": "How do you read that?", "options": ["Good, since the hardware is resting", "Half its compute spend is wasted", "Normal, since failures are expected"], "correctIndex": 1, "consequences": ["Idle time is paid for and earns nothing.", "Meta kept above 90% at a similar scale.", "Failures are expected; losing half the time is not."], "explanation": "Ask about effective training time. Reliability turns into cost and speed."}, "proReasoning": "Investors benchmark a lab's effective training time against what leaders achieve.", "commonMistake": "Accepting low uptime as the cost of scale.", "mentalModel": "Benchmark the uptime."}, "build_startup": {"call": {"kind": "theCall", "situation": "You're the founder running the job. A failure every three hours is costing you days.", "prompt": "What's your priority?", "options": ["Buy more GPUs to go faster", "Pause until hardware is perfect", "Build fast detection and restart"], "correctIndex": 2, "consequences": ["More GPUs bring more failures.", "At scale, hardware is never perfect.", "Faster recovery saves time on every one of hundreds of failures."], "explanation": "At enough scale, failure is routine and has to be designed for."}, "proReasoning": "Founders invest in recovery because every failure pays it back.", "commonMistake": "Adding hardware to a problem of recovery.", "mentalModel": "Invest in recovery."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend asks why AI training runs save their progress so often.", "prompt": "What's the answer?", "options": ["Something breaks every few hours", "Saving makes the AI smarter", "The law requires frequent backups"], "correctIndex": 0, "consequences": ["Saving often means each failure loses little work.", "Saving protects progress; it does not add learning.", "It is an engineering choice, not a legal rule."], "explanation": "With thousands of GPUs, failures every few hours are normal. Saving often limits the damage."}, "proReasoning": "Like saving a long document often, training runs save progress because crashes are certain.", "commonMistake": "Thinking failures are rare at scale.", "mentalModel": "Save often when crashes are certain."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:ed70e74515cc$ml$]::text[]),
($ml$43d24e76-5cba-5fd9-b6e6-46119cbfb9c0$ml$::uuid, $ml$ai$ml$, 25, 1, $ml${"id": "ai-d25-c1", "title": "The exam after MMLU", "lessonTitle": "How we grade AI models", "slot": 1, "type": "apply", "brief": {"headline": "In January 2025, Humanity's Last Exam launched with 2,500 expert questions, and the best model, OpenAI's o1, scored 8.3%. By February 2026, Google's Gemini 3 Deep Think had reached 48.4%.", "kicker": "Apply day 25: a new, harder test, and how fast it filled.", "fullText": "The Center for AI Safety and Scale AI built the test with more than 1,000 subject-matter experts from 500 institutions in 50 countries. Its questions span more than 100 subjects, each with a known, verifiable answer. Human experts score around 90% in their own fields.\n\nIt arrived as older tests were wearing out. MMLU's best score had climbed from 43.9% in 2020 to about 88% by mid-2024. Humanity's Last Exam reset the scale, then models climbed from 8.3% to 48.4% in about a year.\n\nIts creators note that a high score would not by itself show general intelligence.", "sources": [{"url": "https://www.livescience.com/technology/artificial-intelligence/acing-this-new-ai-exam-which-its-creators-say-is-the-toughest-in-the-world-might-point-to-the-first-signs-of-agi", "label": "Live Science, Humanity's Last Exam, Feb 2026"}, {"url": "https://en.wikipedia.org/wiki/MMLU", "label": "MMLU benchmark"}]}, "evidence": {"kind": "buildChain", "prompt": "Follow the life of a benchmark.", "steps": ["A hard new test launches", "Top models score low at first", "Scores climb fast as models improve", "The best models crowd the ceiling", "A harder test takes its place"], "explanation": "MMLU went through this cycle. Humanity's Last Exam started it again at 8.3%."}, "numbers": {"kind": "numberSense", "prompt": "From 8.3% to 48.4%: how many percentage points in about a year?", "min": 0, "max": 100, "value": 40.1, "unit": "points", "explanation": "About 40 points in a year, on a test built to be the hardest."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "You're interviewing at an AI lab in 2026. They ask which tests still separate top models.", "prompt": "What's the best answer?", "options": ["MMLU, where top models still differ widely", "Any test, since they all measure the same", "Harder ones, like Humanity's Last Exam"], "correctIndex": 2, "consequences": ["Top models crowded near 88% on MMLU by 2024.", "A saturated test cannot tell models apart.", "Scores there still spread from single digits to about 48%."], "explanation": "Name the benchmarks and their limits. It shows you can read a model announcement critically."}, "proReasoning": "Know which tests are saturated and which still have room. That is what separates a critical reader.", "commonMistake": "Quoting a saturated benchmark as if it still ranked models.", "mentalModel": "Know which tests still have room."}, "invest": {"call": {"kind": "theCall", "situation": "A lab's launch post highlights MMLU and skips newer, harder tests.", "prompt": "What do you ask?", "options": ["Why it left out the harder benchmarks", "How many pages the launch post ran", "Nothing, since MMLU is the standard"], "correctIndex": 0, "consequences": ["Labs choose which tests to report; the choice is information.", "Length says nothing about results.", "MMLU is being partly phased out for harder tests."], "explanation": "As MMLU saturates, harder benchmarks take its place. Watch which tests labs choose to report."}, "proReasoning": "Investors notice which tests are missing from a launch, not only which are shown.", "commonMistake": "Taking the reported benchmarks as the full picture.", "mentalModel": "Notice the missing tests."}, "build_startup": {"call": {"kind": "theCall", "situation": "You see scores on the hardest public exam jump from 8% to 48% in a year.", "prompt": "What startup opening does that suggest?", "options": ["Selling answer keys to old benchmarks", "Evaluations for real tasks in one field", "Writing one more general exam for AI"], "correctIndex": 1, "consequences": ["That undermines evaluation instead of building it.", "Field-specific tests track real use and wear out slower.", "General exams fill up fast, as this one did."], "explanation": "As old tests saturate, companies need better ways to measure models. Evaluation can be a business."}, "proReasoning": "Founders build tests tied to real work, which stay useful longer than general exams.", "commonMistake": "Competing to build the next exam that will saturate within a year.", "mentalModel": "Test real work, not trivia."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend says AI now beats experts, since it went from 8% to 48% on the hardest exam.", "prompt": "What's the fairer view?", "options": ["Yes, it now beats every expert alive", "No, because the test is actually easy", "Not yet; experts score about 90% there"], "correctIndex": 2, "consequences": ["Experts still score far higher in their fields.", "Experts wrote it to be very hard.", "48% is a big jump, and still well below experts."], "explanation": "Fast progress and expert-level skill are different things. Both numbers matter."}, "proReasoning": "Read a score against a reference point, like human experts. Progress is not the same as arrival.", "commonMistake": "Treating a fast-rising score as a finished race.", "mentalModel": "Compare to the human baseline."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:9925de4a357c$ml$]::text[]),
($ml$4d44eb02-edc1-56a2-9373-c5f2923e9616$ml$::uuid, $ml$ai$ml$, 25, 2, $ml${"id": "ai-d25-c2", "title": "Compounding meets a ceiling", "lessonTitle": "How we grade AI models", "slot": 2, "type": "connect", "brief": {"headline": "Training compute for top models grows 4 to 5 times a year. MMLU's best score went from 43.9% in 2020 to about 88% by mid-2024, and the test is being partly phased out.", "kicker": "Connect day 4 and day 25: compounding curves fill tests fast.", "fullText": "On day 4 you saw why AI moves fast: training compute doubles roughly every five months. On day 25 you saw what that does to a test. MMLU, published in September 2020, has 15,908 multiple-choice questions across 57 subjects. Most models then scored near random chance, 25%, and GPT-3 led with 43.9%. By mid-2024, Claude 3.5 Sonnet, GPT-4o and Llama 3.1 405B reached about 88%.\n\nA test has a fixed ceiling, and capability on a compounding curve reaches it fast. A June 2024 review also estimated that 6.5% of MMLU's questions contain errors, which limits what the top scores can mean.", "sources": [{"url": "https://epoch.ai/blog/training-compute-of-frontier-ai-models-grows-by-4-5x-per-year", "label": "Epoch AI, training compute growth"}, {"url": "https://hai-production.s3.amazonaws.com/files/hai-ai-index-2025-policy-highlights.pdf", "label": "AI Index 2025 policy highlights"}, {"url": "https://en.wikipedia.org/wiki/MMLU", "label": "MMLU benchmark"}]}, "evidence": {"kind": "spotFake", "prompt": "One of these is false about MMLU. Tap it.", "statements": ["It has 15,908 questions across 57 subjects.", "GPT-3 led with 43.9% in 2020.", "Top models scored 100% by mid-2024."], "fakeIndex": 2, "explanation": "Top models reached about 88%. With 6.5% of questions flawed, a perfect score may not even be possible."}, "numbers": {"kind": "numberSense", "prompt": "If 6.5% of MMLU questions contain errors, what share are sound, in percent?", "min": 0, "max": 100, "value": 93.5, "unit": "%", "explanation": "93.5%. Near the top, a point or two can be noise from flawed questions."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "An interviewer says their model beats a rival 89% to 88% on MMLU.", "prompt": "How do you respond?", "options": ["Too close to the ceiling to tell apart", "That proves their model is clearly better", "MMLU is the only test that matters"], "correctIndex": 0, "consequences": ["Near 88%, with 6.5% flawed questions, one point is noise.", "A one-point gap at the ceiling proves little.", "Harder tests are replacing it."], "explanation": "A benchmark is useful until models crowd its ceiling. Near the top, small gaps mean little."}, "proReasoning": "Point out when a gap is within the noise. It shows judgment, not contrarianism.", "commonMistake": "Treating a one-point lead at the ceiling as meaningful.", "mentalModel": "Near the ceiling, gaps are noise."}, "invest": {"call": {"kind": "theCall", "situation": "Capability is compounding, and benchmarks keep saturating.", "prompt": "What should you expect from any single benchmark?", "options": ["No change in what it measures", "A short useful life", "A permanent ranking tool"], "correctIndex": 1, "consequences": ["Its questions stay fixed while models improve.", "MMLU went from 43.9% to about 88% in four years.", "Saturated tests stop telling models apart."], "explanation": "In AI, compounding curves matter more than any single number. Tests wear out fast."}, "proReasoning": "Investors expect benchmarks to expire and watch which new ones the field adopts.", "commonMistake": "Building a thesis on one benchmark.", "mentalModel": "Benchmarks expire."}, "build_startup": {"call": {"kind": "theCall", "situation": "You market your model mainly with its MMLU score.", "prompt": "What's the risk?", "options": ["MMLU is too new for buyers to know", "Buyers prefer longer test names", "The test no longer separates top models"], "correctIndex": 2, "consequences": ["It dates from 2020 and is being phased out.", "Names do not matter; signal does.", "Many rivals sit near the same ceiling."], "explanation": "A benchmark is useful until models crowd its ceiling. Market on tests that still discriminate."}, "proReasoning": "Founders show results that still separate them from rivals.", "commonMistake": "Leading with a score everyone else also has.", "mentalModel": "Show what still separates you."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend asks why AI researchers keep inventing new tests.", "prompt": "What's the answer?", "options": ["Models max out old tests quickly", "Old tests get deleted each year", "Researchers get bored easily"], "correctIndex": 0, "consequences": ["MMLU went from 43.9% to about 88% in four years.", "Old tests still exist; they just stop telling models apart.", "The reason is saturation, not boredom."], "explanation": "Capability compounds and tests have ceilings. New tests are needed to see the next step."}, "proReasoning": "A ruler is only useful if what you measure fits on it. Fast-growing AI outgrows its rulers.", "commonMistake": "Thinking new tests are just moving the goalposts.", "mentalModel": "AI outgrows its rulers."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:8790cda8c8af$ml$]::text[]),
($ml$857bdbf6-6e67-5119-8db3-d789d2989148$ml$::uuid, $ml$ai$ml$, 25, 3, $ml${"id": "ai-d25-c3", "title": "Which scores to report", "lessonTitle": "How we grade AI models", "slot": 3, "type": "decide", "brief": {"headline": "You run evaluation at a startup launching a new model. The team wants to lead with an MMLU score of 88%, one point above a rival.", "kicker": "Decide which results actually tell buyers something.", "fullText": "MMLU, published in September 2020, has 15,908 multiple-choice questions across 57 subjects. GPT-3 led with 43.9% at launch. By mid-2024, Claude 3.5 Sonnet, GPT-4o and Llama 3.1 405B reached about 88%.\n\nA June 2024 review estimated that 6.5% of questions contain errors, and by 2025 MMLU was being partly phased out for harder tests. Once top models crowd near the ceiling, a test stops telling them apart.", "sources": [{"url": "https://en.wikipedia.org/wiki/MMLU", "label": "MMLU benchmark"}]}, "evidence": {"kind": "sortSignal", "prompt": "Does each result tell buyers a lot, or a little?", "buckets": ["Tells them a lot", "Tells them little"], "items": [{"text": "Results on tasks from your target customers", "bucket": 0}, {"text": "A newer test where top models still differ", "bucket": 0}, {"text": "A one-point MMLU edge near 88%", "bucket": 1}, {"text": "A score on a test with 6.5% flawed questions", "bucket": 1}], "explanation": "Saturated tests with flawed questions say little. Tests that still discriminate, or match real use, say more."}, "numbers": {"kind": "numberSense", "prompt": "MMLU has 15,908 questions, and 6.5% may contain errors. About how many thousand flawed questions?", "min": 0, "max": 5, "value": 1, "unit": "K", "explanation": "About 1,000 flawed questions, far more than a one-point gap."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "As evaluation lead, you must recommend what the launch should feature.", "prompt": "What do you recommend?", "options": ["No numbers at all, just the story", "Tests that still separate the models", "The MMLU score in large type, up front"], "correctIndex": 1, "consequences": ["Buyers want evidence, just the right evidence.", "Buyers see where you actually differ.", "A one-point edge near the ceiling is noise."], "explanation": "Name the tests you report and their limits. That is the evaluation lead's job."}, "proReasoning": "Good evaluation leads choose results that inform, and explain the limits of the rest.", "commonMistake": "Letting marketing pick the flashiest number.", "mentalModel": "Report what informs."}, "invest": {"call": {"kind": "theCall", "situation": "You're evaluating the startup. Its deck leads with MMLU at 88%.", "prompt": "What do you ask for?", "options": ["A bigger, bolder chart of the MMLU score", "Nothing more, since 88% is a high score", "Results on harder tests or customer tasks"], "correctIndex": 2, "consequences": ["Presentation does not change what it measures.", "Many models sit near 88%.", "Those show whether the model stands out."], "explanation": "Watch which tests labs choose to report. Saturated ones do not separate winners."}, "proReasoning": "Investors ask for evidence that discriminates between competitors.", "commonMistake": "Being impressed by a high score on a saturated test.", "mentalModel": "Ask for discriminating evidence."}, "build_startup": {"call": {"kind": "theCall", "situation": "You're the founder. Your model is strong at legal documents, a field the big tests barely cover.", "prompt": "How do you show it?", "options": ["Build and publish a legal task evaluation", "Lead with the MMLU score as everyone does", "Claim it beats every model at everything"], "correctIndex": 0, "consequences": ["A focused test shows your real edge, and can become a product.", "MMLU does not show your legal strength.", "Broad claims invite doubt."], "explanation": "As old tests saturate, companies need better ways to measure models. Your own evaluation can show your edge."}, "proReasoning": "Founders with a niche edge prove it with a niche test.", "commonMistake": "Hiding a real edge behind a general benchmark.", "mentalModel": "Prove the edge you have."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend asks why a one-point lead on a famous AI test might not matter.", "prompt": "What's the answer?", "options": ["Points only start to matter above 95%", "Near the top, flawed questions blur the gap", "Famous AI tests are always secretly rigged"], "correctIndex": 1, "consequences": ["No fixed line like that exists.", "About 6.5% of MMLU questions may contain errors.", "Not rigged, just saturated and imperfect."], "explanation": "When many models crowd near the ceiling, small differences can be noise."}, "proReasoning": "A tiny gap on an imperfect test is not a real difference.", "commonMistake": "Treating every point as meaningful.", "mentalModel": "Small gaps can be noise."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:11042b2f3cf1$ml$]::text[]),
($ml$4b2c7d17-167e-5616-975c-a3ef442ce115$ml$::uuid, $ml$ai$ml$, 26, 1, $ml${"id": "ai-d26-c1", "title": "From $600 million to $1.7 billion", "lessonTitle": "Grading AI is a business", "slot": 1, "type": "apply", "brief": {"headline": "In January 2026, LMArena raised $150 million at a $1.7 billion valuation, about eight months after it was valued at $600 million. Its first paid product passed a $30 million annual run rate within four months.", "kicker": "Apply day 26: grading the models is a business of its own.", "fullText": "LMArena runs a public leaderboard where people compare answers from AI models and vote for the better one. It says more than 5 million people use it each month across 150 countries, in over 60 million conversations, and that OpenAI, Google and xAI use its evaluations. Felicis and UC Investments, the University of California's investment office, led the round.\n\nIts first commercial product launched in September 2025, and annualized revenue passed $30 million in December. Chief executive Anastasios Angelopoulos said its evaluations use a transparent, open-source methodology.\n\nThe day 26 rule: whoever grades the models can be valuable too. The asset is trust that the grading is fair.", "sources": [{"url": "https://pulse2.com/lmarena-150-million-at-1-7-billion-valuation-raised-to-expand-real-world-ai-evaluation/amp/", "label": "Pulse 2.0, LMArena raises $150 million at a $1.7 billion valuation, Jan 2026"}, {"url": "https://www.cooley.com/news/coverage/2026/2026-01-06-lmarena-secures-%24150-million-series-a", "label": "Cooley, LMArena secures $150 million Series A, Jan 2026"}, {"url": "https://siliconangle.com/2025/05/21/lmarena-raises-100m-600m-valuation-expand-ai-benchmarking-platform/", "label": "SiliconANGLE, LMArena raises $100M at a $600M valuation, May 2025"}]}, "evidence": {"kind": "multipleChoice", "prompt": "What is LMArena's most valuable asset as a grader?", "options": ["The size of its office space", "An AI model of its own", "Trust that its rankings are fair"], "correctIndex": 2, "explanation": "Labs and users rely on its rankings only if they believe the grading is neutral."}, "numbers": {"kind": "numberSense", "prompt": "From $600 million to $1.7 billion: about how many times higher?", "min": 0, "max": 10, "value": 2.8, "unit": "x", "explanation": "Almost three times in about eight months, for a company that grades models."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "You have offers from LMArena and from a model lab.", "prompt": "What's a fair view of the LMArena role?", "options": ["Evaluation is a real, funded career path", "A dead end, since only models matter", "A temporary job until the hype fades"], "correctIndex": 0, "consequences": ["$1.7 billion and a $30 million run rate say so.", "Graders became valuable alongside builders.", "It had real revenue within months of launch."], "explanation": "Evaluation work is a real path into AI, and companies pay well for it."}, "proReasoning": "Treat evaluation as a career track. Grading models is now a funded industry.", "commonMistake": "Thinking only model building counts as an AI career.", "mentalModel": "Evaluation is a career track."}, "invest": {"call": {"kind": "theCall", "situation": "LMArena's paying customers include labs whose models it ranks.", "prompt": "What do you watch for?", "options": ["Nothing, since all graders are neutral", "Whether paid work bends the rankings", "Only how fast revenue grows"], "correctIndex": 1, "consequences": ["Neutrality has to be earned and kept.", "A grader's value depends on staying neutral.", "Revenue that costs trust is not durable."], "explanation": "Neutrality is the product. Google and OpenAI pulled back from Scale AI when that was in doubt."}, "proReasoning": "Investors in graders track conflicts of interest as closely as revenue.", "commonMistake": "Ignoring that a grader sells to those it grades.", "mentalModel": "Neutrality is the product."}, "build_startup": {"call": {"kind": "theCall", "situation": "You want to start an AI evaluation company.", "prompt": "What's a strong position?", "options": ["Copy LMArena's general leaderboard exactly", "Let one big lab own half of the company", "Specialize in one field and stay independent"], "correctIndex": 2, "consequences": ["A general leaderboard already has 5 million users.", "That is what made labs leave Scale AI.", "Independent, focused graders are scarce and trusted."], "explanation": "When a big lab buys into a grader, rivals look elsewhere. Independence opens the gap."}, "proReasoning": "Founders in evaluation guard their independence. It is what they sell.", "commonMistake": "Taking money that compromises neutrality.", "mentalModel": "Stay independent."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend asks how a website where people vote on chatbots makes money.", "prompt": "What's the answer?", "options": ["AI companies pay for its evaluations", "It charges users to vote", "It sells chatbot subscriptions"], "correctIndex": 0, "consequences": ["Its paid product reached a $30 million run rate.", "Voting is free for the public.", "It grades chatbots; it does not sell them."], "explanation": "Labs pay for rankings people trust. That turned a voting site into a billion-dollar company."}, "proReasoning": "Free public use builds trust; companies pay for what that trust produces.", "commonMistake": "Assuming a free website cannot be a big business.", "mentalModel": "Trust can be sold."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:6cd7242cccef$ml$]::text[]),
($ml$c9339d61-a431-57cb-9410-d9a74f58af14$ml$::uuid, $ml$ai$ml$, 26, 2, $ml${"id": "ai-d26-c2", "title": "People still do the grading", "lessonTitle": "Grading AI is a business", "slot": 2, "type": "connect", "brief": {"headline": "InstructGPT learned from people writing demonstrations and ranking answers. In June 2025, Meta paid $14.3 billion for 49% of Scale AI, which supplies human-made training and evaluation data.", "kicker": "Connect day 1 and day 26: human feedback became a big business.", "fullText": "On day 1 you saw how chatbots mix ways of learning. InstructGPT learned from human demonstrations, then from people ranking its answers as a reward. Supervised and feedback-trained models need data made by people.\n\nOn day 26 you saw what that work is worth. Meta invested $14.3 billion in Scale AI for a 49% non-voting stake, roughly doubling the company's $13.8 billion valuation from the year before, and hired its chief executive, Alexandr Wang. After the deal, Google and OpenAI, both major customers, said they would seek other data labeling providers.\n\nThe people who write, rank and grade became an industry.", "sources": [{"url": "https://openai.com/index/instruction-following/", "label": "OpenAI, InstructGPT"}, {"url": "https://www.deeplearning.ai/the-batch/meta-invests-14-3-billion-in-scale-ai-hires-ceo-alexandr-wang", "label": "The Batch (DeepLearning.AI), Meta invests $14.3 billion in Scale AI, Jun 2025"}]}, "evidence": {"kind": "buildChain", "prompt": "Follow human data from people to a model.", "steps": ["People write example answers", "People rank the model's answers", "A data company packages that work", "Labs pay to train and test models with it"], "explanation": "Human feedback is a supply chain. Companies like Scale AI sit in the middle of it."}, "numbers": {"kind": "numberSense", "prompt": "Meta's $14.3 billion bought 49%. What did that imply for all of Scale AI, in billions?", "min": 0, "max": 80, "value": 29.2, "unit": "B", "explanation": "About $29 billion, roughly double the year before."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "In an interview, you are asked why a data labeling company was worth billions.", "prompt": "What's the best answer?", "options": ["It owned several popular consumer apps", "Models need human-made training and test data", "Labeling is easy to automate fully today"], "correctIndex": 1, "consequences": ["Scale AI sells data to labs.", "InstructGPT learned from human demonstrations and rankings.", "If it were, nobody would pay billions for it."], "explanation": "Human data is part of the cost of AI. Whoever supplies it can be worth a lot."}, "proReasoning": "Connect the training method to the business. Human feedback needs humans, and someone organizes them.", "commonMistake": "Treating labeling as low-value work.", "mentalModel": "Human data is a supply chain."}, "invest": {"call": {"kind": "theCall", "situation": "After Meta's stake, Google and OpenAI said they would seek other providers.", "prompt": "What does that tell you about the business?", "options": ["Customers never care who owns a supplier", "Labeling demand has disappeared", "Neutrality is part of what it sells"], "correctIndex": 2, "consequences": ["Two major customers said they would leave.", "They sought other providers, not less data.", "A rival owning half the grader worried its customers."], "explanation": "A grader's value depends on staying neutral. Ownership can change who trusts it."}, "proReasoning": "Investors ask who owns a supplier and whether that drives customers away.", "commonMistake": "Valuing a supplier without checking customer trust.", "mentalModel": "Ownership can cost customers."}, "build_startup": {"call": {"kind": "theCall", "situation": "Google and OpenAI are looking for new data labeling providers.", "prompt": "What's the founder's opening?", "options": ["Offer independent, high-quality human data", "Sell your own startup to Meta as well", "Automate all human feedback away now"], "correctIndex": 0, "consequences": ["Rivals of Meta want a supplier it does not own.", "That repeats the neutrality problem.", "The methods still need human judgment."], "explanation": "When a big lab buys into a grader, rivals look elsewhere. That opens a gap for independents."}, "proReasoning": "Founders move fast when big customers suddenly need a new supplier.", "commonMistake": "Missing a gap opened by a competitor's deal.", "mentalModel": "A rival's deal can open your door."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend asks why people are still needed if AI is so smart.", "prompt": "What's the answer?", "options": ["People are needed only to fix servers", "People teach and grade it with examples", "People type every answer secretly"], "correctIndex": 1, "consequences": ["Human data work is far bigger than that.", "Demonstrations and rankings train and test models.", "Models write their own answers."], "explanation": "Chatbots learn from human demonstrations and rankings, and companies pay billions for that data."}, "proReasoning": "Behind smart models are people who taught and graded them.", "commonMistake": "Thinking AI learns with no human input.", "mentalModel": "People teach the model."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:59716c221261$ml$]::text[]),
($ml$af901a80-7925-5ccf-823c-37b4d5105e55$ml$::uuid, $ml$ai$ml$, 26, 3, $ml${"id": "ai-d26-c3", "title": "When your grader picks a side", "lessonTitle": "Grading AI is a business", "slot": 3, "type": "decide", "brief": {"headline": "You run a lab that buys evaluation data from Scale AI. Meta, a direct rival, has just bought 49% of it and hired its chief executive.", "kicker": "Decide whether you can still trust your grader.", "fullText": "In June 2025, Meta invested $14.3 billion in Scale AI for a 49% non-voting stake, roughly doubling the company's $13.8 billion valuation from the year before, and hired its chief executive Alexandr Wang to lead a new lab. Scale AI supplies the training and evaluation data used to build AI models.\n\nAfter the deal became public, Google and OpenAI, both major customers, said they would seek other data labeling providers. In AI, whoever grades the models can be as valuable as whoever builds them, if they stay neutral.", "sources": [{"url": "https://www.deeplearning.ai/the-batch/meta-invests-14-3-billion-in-scale-ai-hires-ceo-alexandr-wang", "label": "The Batch (DeepLearning.AI), Meta invests $14.3 billion in Scale AI, Jun 2025"}]}, "evidence": {"kind": "faceOff", "prompt": "Which grader would a rival of Meta trust more?", "left": {"name": "A grader half-owned by Meta", "note": "Its chief executive now works for Meta"}, "right": {"name": "An independent grader", "note": "No stake from any model lab"}, "correctIndex": 1, "explanation": "A grader is valuable because it is neutral. A rival owning half of it undercuts that."}, "numbers": {"kind": "numberSense", "prompt": "Scale AI's valuation the year before was about how many billion dollars?", "min": 0, "max": 40, "value": 13.8, "unit": "B", "explanation": "About $13.8 billion. Meta's deal roughly doubled it."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "You lead your lab's evaluation work. Leadership asks what to do about Scale AI.", "prompt": "What do you recommend?", "options": ["Change nothing, since data is just data", "Stop evaluating our models altogether", "Move sensitive tests to independent graders"], "correctIndex": 2, "consequences": ["Who sees your evaluation data now matters.", "You still need to measure your models.", "Google and OpenAI made the same call."], "explanation": "Neutrality is part of what a grader sells. When it changes, revisit the supplier."}, "proReasoning": "Evaluation leads protect the independence of their testing. Supplier ownership is part of that.", "commonMistake": "Treating a change in ownership as irrelevant.", "mentalModel": "Protect independent testing."}, "invest": {"call": {"kind": "theCall", "situation": "You're weighing Scale AI's prospects after the deal.", "prompt": "What's the main risk to its revenue?", "options": ["Meta's rivals moving their business", "Too much demand for it to serve", "Meta paying too little for its stake"], "correctIndex": 0, "consequences": ["Google and OpenAI said they would seek other providers.", "Demand is not the problem; trust is.", "Meta paid $14.3 billion."], "explanation": "A grader's value depends on staying neutral. Lost neutrality can mean lost customers."}, "proReasoning": "Investors weigh how a strategic stake changes who will keep buying.", "commonMistake": "Seeing a big investment as pure upside for the supplier.", "mentalModel": "A stake can cost customers."}, "build_startup": {"call": {"kind": "theCall", "situation": "You're the lab's founder, deciding on your data supplier.", "prompt": "What's your move?", "options": ["Build nothing and wait for clarity", "Spread work across independent suppliers", "Sign a long exclusive deal with Scale AI"], "correctIndex": 1, "consequences": ["Waiting stalls your model work.", "No single supplier, and no rival-owned one, sees everything.", "That ties you to a grader your rival half-owns."], "explanation": "Independent graders are scarce and valuable. Spread risk across them."}, "proReasoning": "Founders avoid depending on one supplier, especially one tied to a rival.", "commonMistake": "Locking in just as a supplier's neutrality changes.", "mentalModel": "Spread your suppliers."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend asks why Google and OpenAI cared who owned their data supplier.", "prompt": "What's the answer?", "options": ["They wanted to buy the company themselves", "The supplier suddenly raised its prices", "A rival could gain insight into their work"], "correctIndex": 2, "consequences": ["They said they would seek other providers instead.", "The reported concern was ownership, not price.", "A supplier half-owned by Meta sits close to a rival."], "explanation": "A grader sees how labs train and test models. Ownership by a rival changes that."}, "proReasoning": "Who owns your supplier matters when the supplier sees your secrets.", "commonMistake": "Thinking suppliers are interchangeable.", "mentalModel": "Ownership shapes trust."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:dc81d649c6af$ml$]::text[]),
($ml$5fcc7d55-da9b-506b-b237-52b18444a7e2$ml$::uuid, $ml$ai$ml$, 27, 1, $ml${"id": "ai-d27-c1", "title": "Sixty-four tries on one chart", "lessonTitle": "Who controls the leaderboard", "slot": 1, "type": "apply", "brief": {"headline": "In February 2025, xAI's chart showed Grok 3 beating OpenAI's o3-mini-high on the AIME 2025 math test. It left out o3-mini-high's score at cons@64, which gives a model 64 attempts per problem.", "kicker": "Apply day 27: how a score was produced changes what it means.", "fullText": "cons@64, short for consensus at 64, takes the most common answer across 64 tries, and it typically raises scores considerably. On single attempts, both Grok 3 versions scored below o3-mini-high, yet xAI advertised Grok 3 as the world's smartest AI.\n\nxAI co-founder Igor Babuschkin replied that OpenAI had published similarly misleading charts. Researcher Nathan Lambert noted that the most important number was missing from everyone's charts: what each score cost in compute and money.\n\nThe day 27 study found labs test many versions privately and publish the best. Here, the same idea showed up inside one chart.", "sources": [{"url": "https://techcrunch.com/2025/02/22/did-xai-lie-about-grok-3s-benchmarks", "label": "TechCrunch, Did xAI lie about Grok 3's benchmarks?, Feb 2025"}, {"url": "https://arxiv.org/abs/2504.20879v2", "label": "Singh et al., The Leaderboard Illusion, 2025"}]}, "evidence": {"kind": "multipleChoice", "prompt": "Why does it matter whether a score used 64 tries or one?", "options": ["It does not matter if the chart looks clear", "Many tries raise scores, so it is unfair", "One try is always the less accurate measure"], "correctIndex": 1, "explanation": "Comparing one model's best-of-many with another's single try makes the first look better than it is."}, "numbers": {"kind": "numberSense", "prompt": "With cons@64, how many attempts does a model get per problem?", "min": 0, "max": 200, "value": 64, "unit": "tries", "explanation": "64 tries, keeping the most common answer. That can lift a score considerably."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "You're asked to summarize a rival's launch chart for your team.", "prompt": "What do you check first?", "options": ["Whether the title says smartest", "How many tries each score used", "Which colors the chart uses"], "correctIndex": 1, "consequences": ["A slogan is not evidence.", "Single-try and best-of-64 scores are not comparable.", "Colors do not change what was measured."], "explanation": "Ask whether a reported score came from one public test or many tries."}, "proReasoning": "Read the fine print on how each score was produced. That is the critical reading skill.", "commonMistake": "Comparing bars without checking they measure the same thing.", "mentalModel": "Check how the score was made."}, "invest": {"call": {"kind": "theCall", "situation": "Two labs each claim the best math score, using different methods.", "prompt": "How do you decide who leads?", "options": ["Believe the lab with the bolder claim", "Average the two claims together", "Look for independent, like-for-like results"], "correctIndex": 2, "consequences": ["Bold claims are what the chart controversy was about.", "Averaging mismatched numbers means nothing.", "Same method, same test, run by a third party."], "explanation": "A leaderboard rank may reflect testing choices more than quality. Look for independent evaluations."}, "proReasoning": "Investors trust comparisons only when the method matches and someone neutral ran them.", "commonMistake": "Accepting each lab's own comparison.", "mentalModel": "Like-for-like, or not at all."}, "build_startup": {"call": {"kind": "theCall", "situation": "You're publishing your model's benchmark results.", "prompt": "How do you present them?", "options": ["Single-try scores next to best-of-many", "Only your best-of-many scores, in bold", "Only the rivals' weakest scores beside yours"], "correctIndex": 0, "consequences": ["Clear methods build trust with technical buyers.", "That invites the same criticism xAI faced.", "Cherry-picking rivals is easy to spot."], "explanation": "Rankings favor whoever can test the most and show the least. Showing your method earns trust."}, "proReasoning": "Founders who show their method openly stand out in a field of selective charts.", "commonMistake": "Copying the industry habit of selective charts.", "mentalModel": "Show the method."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend asks how two companies can both claim to have the smartest AI.", "prompt": "What's the answer?", "options": ["They use the exact same test", "They measure in different ways", "One of them is breaking the law"], "correctIndex": 1, "consequences": ["Same test, different methods, different winners.", "One try versus 64 tries can flip the result.", "Selective charts are misleading, not illegal."], "explanation": "How a score is produced, and which scores are shown, can decide who looks best."}, "proReasoning": "Before believing \"the smartest\", ask \"measured how?\"", "commonMistake": "Taking a launch chart at face value.", "mentalModel": "Ask how it was measured."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:3d5f7ef18a86$ml$]::text[]),
($ml$eb6321dd-f673-5d87-baf9-10048734b2d9$ml$::uuid, $ml$ai$ml$, 27, 2, $ml${"id": "ai-d27-c2", "title": "Graders and the graded", "lessonTitle": "Who controls the leaderboard", "slot": 2, "type": "connect", "brief": {"headline": "LMArena began as a UC Berkeley research project and was valued at $600 million in May 2025. A 2025 study estimated Google and OpenAI received about 40% of all data from its Chatbot Arena.", "kicker": "Connect day 26 and day 27: a grader is only as fair as its access.", "fullText": "On day 26 you saw grading become a business: LMArena raised $100 million at a $600 million valuation, and a grader's value depends on staying neutral.\n\nOn day 27 you saw a challenge to that neutrality. The Leaderboard Illusion study argued that Chatbot Arena rankings are distorted because a few providers test many variants privately and withdraw scores they do not like. It identified 27 private variants Meta tested before Llama 4, and estimated Google received 19.2% and OpenAI 20.4% of all Arena data, while 83 open-weight models together got about 29.7%.\n\nLabs that see more arena data can tune for it.", "sources": [{"url": "https://siliconangle.com/2025/05/21/lmarena-raises-100m-600m-valuation-expand-ai-benchmarking-platform/", "label": "SiliconANGLE, LMArena raises $100M at a $600M valuation, May 2025"}, {"url": "https://arxiv.org/abs/2504.20879v2", "label": "Singh et al., The Leaderboard Illusion, 2025"}]}, "evidence": {"kind": "sortSignal", "prompt": "Does each fact favor the big labs or the open-weight models?", "buckets": ["Favors big labs", "Favors open models"], "items": [{"text": "Google's estimated 19.2% of Arena data", "bucket": 0}, {"text": "OpenAI's estimated 20.4% of Arena data", "bucket": 0}, {"text": "Testing many variants privately", "bucket": 0}, {"text": "Equal data for every provider", "bucket": 1}, {"text": "Disclosing every variant tested", "bucket": 1}], "explanation": "More data and private tries help the biggest labs. Equal access and disclosure level the field."}, "numbers": {"kind": "numberSense", "prompt": "Google got about 19.2% of Arena data and OpenAI 20.4%. What share together, in percent?", "min": 0, "max": 100, "value": 39.6, "unit": "%", "explanation": "About 39.6% for two labs, against 29.7% for 83 open-weight models combined."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "You join LMArena's team after the study comes out.", "prompt": "What should the team fix first?", "options": ["A brighter design for the leaderboard", "More private testing for big labs", "Equal access and disclosure of all variants"], "correctIndex": 2, "consequences": ["Design does not fix uneven data.", "That deepens the problem the study found.", "Fair access protects the neutrality its value rests on."], "explanation": "A grader's value depends on staying neutral. Uneven access threatens that."}, "proReasoning": "At a grader, every fix starts with fairness. It is the product.", "commonMistake": "Treating a fairness critique as a PR problem.", "mentalModel": "Fairness is the product."}, "invest": {"call": {"kind": "theCall", "situation": "You are considering an investment in an AI leaderboard company.", "prompt": "What's the biggest risk to its value?", "options": ["Losing trust that rankings are fair", "Too many people voting each month", "Ranking too many models at once"], "correctIndex": 0, "consequences": ["Labs and users pay attention only if rankings are trusted.", "Votes are the raw material, not the risk.", "Breadth is a feature."], "explanation": "Rankings can be gamed. A grader that loses trust loses its value."}, "proReasoning": "Investors in graders track trust like other investors track revenue.", "commonMistake": "Valuing a leaderboard on traffic alone.", "mentalModel": "Trust is the asset."}, "build_startup": {"call": {"kind": "theCall", "situation": "You run a small open-weight model team that gets little arena data.", "prompt": "What's your best response?", "options": ["Copy the big labs' private testing", "Seek tests that treat all models alike", "Quit publishing any results at all"], "correctIndex": 1, "consequences": ["You lack their access and data share.", "Fair tests show your model on equal terms.", "Silence hands the narrative to bigger labs."], "explanation": "Smaller players are disadvantaged by how tests are run. Fair tests help them most."}, "proReasoning": "Small teams look for evaluations where access is equal.", "commonMistake": "Competing on a field tilted against you.", "mentalModel": "Find the level field."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend asks why a chatbot leaderboard might favor big companies.", "prompt": "What's the answer?", "options": ["The leaderboard is owned by them", "Their names appear first on the page", "They get more data and private tries"], "correctIndex": 2, "consequences": ["It was spun out from a university project.", "Position on the page is not the issue.", "About 40% of data went to two labs, per the study."], "explanation": "Seeing more data and testing privately lets big labs tune for the test."}, "proReasoning": "A fair contest needs equal access. Uneven practice time skews any ranking.", "commonMistake": "Assuming a public vote is automatically fair.", "mentalModel": "Equal access, fair ranking."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:f63657e4fed6$ml$]::text[]),
($ml$9cb27b58-c537-5436-87f1-6fa1cedf88c7$ml$::uuid, $ml$ai$ml$, 27, 3, $ml${"id": "ai-d27-c3", "title": "Small model, little data", "lessonTitle": "Who controls the leaderboard", "slot": 3, "type": "decide", "brief": {"headline": "You run a startup with an open-weight model. On Chatbot Arena, it gets far less data than the big labs, which can test many versions privately.", "kicker": "Decide how to compete on a tilted leaderboard.", "fullText": "The Leaderboard Illusion study argued that Chatbot Arena rankings are distorted because a few providers test many variants privately and withdraw scores they do not like. It identified 27 private variants Meta tested before Llama 4.\n\nIt also estimated Google received 19.2% and OpenAI 20.4% of all Arena data, while 83 open-weight models together received about 29.7%. Labs that see more arena data can tune for it, which rewards fitting the arena, not general quality.", "sources": [{"url": "https://arxiv.org/abs/2504.20879v2", "label": "Singh et al., The Leaderboard Illusion, 2025"}]}, "evidence": {"kind": "spotFake", "prompt": "One of these is false about the study. Tap it.", "statements": ["Meta privately tested 27 variants before Llama 4.", "83 open-weight models got about 29.7% of Arena data.", "Every provider received an equal share of data."], "fakeIndex": 2, "explanation": "Two labs got about 40% of the data. Access was far from equal."}, "numbers": {"kind": "numberSense", "prompt": "What share of all Arena data went to OpenAI alone, per the study?", "min": 0, "max": 50, "value": 20.4, "unit": "%", "explanation": "About 20.4% for one company, against 29.7% for 83 open models together."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "You're the startup's evaluation lead. The CEO wants to chase the arena rank.", "prompt": "What do you advise?", "options": ["Report independent tests alongside the rank", "Pour everything into raising the arena rank", "Stop measuring the model at all, for now"], "correctIndex": 0, "consequences": ["Buyers get a fair picture beyond a tilted ranking.", "You would compete where you have the least data.", "Buyers still want evidence."], "explanation": "Ask how a model was evaluated. A rank alone reflects access as much as quality."}, "proReasoning": "Evaluation leads give context for ranks that reflect unequal access.", "commonMistake": "Optimizing for a ranking you cannot win fairly.", "mentalModel": "Add context to the rank."}, "invest": {"call": {"kind": "theCall", "situation": "The startup's arena rank is modest. Its results on independent tests are strong.", "prompt": "Which do you weigh more?", "options": ["Neither one, ever", "The independent results", "The arena rank alone"], "correctIndex": 1, "consequences": ["Evidence matters; you just choose which.", "They are not tilted by data access.", "The rank reflects unequal access too."], "explanation": "A leaderboard rank may reflect private tuning more than general quality. Look for independent evaluations."}, "proReasoning": "Investors adjust a rank for the conditions it was earned under.", "commonMistake": "Treating a rank as a pure quality score.", "mentalModel": "Adjust for the conditions."}, "build_startup": {"call": {"kind": "theCall", "situation": "You're the founder. Big labs see far more arena data than you.", "prompt": "Where do you compete?", "options": ["On private arena testing like theirs", "On the arena rank, at any cost", "On fair tests and real customer tasks"], "correctIndex": 2, "consequences": ["You lack their data share to make that pay.", "That is the field tilted against you.", "There, your model is judged on equal terms."], "explanation": "Open models get less data. Smaller players do better where tests are run evenly."}, "proReasoning": "Founders pick contests where the rules do not favor the giants.", "commonMistake": "Fighting on the giants' home turf.", "mentalModel": "Pick a fair contest."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend asks if a low arena rank means a model is bad.", "prompt": "What's the fairest answer?", "options": ["Not always; access to the arena is uneven", "Yes, the arena rank is always right", "No, the ranks are completely random"], "correctIndex": 0, "consequences": ["Big labs get more data and private tries.", "The study found the rankings distorted.", "Ranks carry signal, just tilted signal."], "explanation": "Rankings favor whoever can test the most and show the least."}, "proReasoning": "A rank tells you something, but not everything. Ask who had the advantage.", "commonMistake": "Treating every ranking as the final word.", "mentalModel": "Ranks carry tilted signal."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:5c91aa50b39c$ml$]::text[]),
($ml$3979eb17-47c5-522c-9099-bad858a3db7c$ml$::uuid, $ml$ai$ml$, 28, 1, $ml${"id": "ai-d28-c1", "title": "The independent check said 10%", "lessonTitle": "Below 2% to above 25%", "slot": 1, "type": "apply", "brief": {"headline": "In April 2025, Epoch AI tested OpenAI's released o3 on FrontierMath and found it scored around 10%. OpenAI had shown over 25% in December, using aggressive test-time compute settings.", "kicker": "Apply day 28: the score that counts is the one someone else checks.", "fullText": "When OpenAI unveiled o3 in December 2024, chief research officer Mark Chen said internal testing with aggressive test-time compute got over 25%; the next-best model was at about 2%. On April 18, 2025, Epoch released its own results: around 10%.\n\nThe gap had several possible causes. Epoch suggested OpenAI may have used a stronger internal setup or more compute, and the two used different problem sets: 180 problems in one release versus an updated 290. OpenAI's December results also showed a lower-bound score that matched Epoch's. The ARC Prize Foundation said the public o3 was a different model, tuned for chat and product use.\n\nA big score needs a clean, independent test before it means much.", "sources": [{"url": "https://techcrunch.com/2025/04/20/openais-o3-ai-model-scores-lower-on-a-benchmark-than-the-company-initially-implied", "label": "TechCrunch, OpenAI's o3 scores lower on a benchmark than implied, Apr 2025"}, {"url": "https://fortune.com/2025/01/21/eye-on-ai-openai-o3-math-benchmark-frontiermath-epoch-altman-trump-biden", "label": "Fortune, OpenAI's o3 and the FrontierMath benchmark, Jan 2025"}]}, "evidence": {"kind": "sortSignal", "prompt": "Which result does each fact belong to?", "buckets": ["OpenAI, Dec 2024", "Epoch, Apr 2025"], "items": [{"text": "Just over 25%", "bucket": 0}, {"text": "Aggressive test-time compute settings", "bucket": 0}, {"text": "Around 10%", "bucket": 1}, {"text": "The released version of o3", "bucket": 1}, {"text": "An updated set of 290 problems", "bucket": 1}], "explanation": "Different settings, versions and problem sets gave different numbers. The independent one is easier to trust."}, "numbers": {"kind": "numberSense", "prompt": "OpenAI showed over 25%; Epoch found about 10%. About how many points lower?", "min": 0, "max": 40, "value": 15, "unit": "points", "explanation": "About 15 points, and still far above the roughly 2% of earlier models."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "You're asked in an interview what o3 scored on FrontierMath.", "prompt": "What's the best answer?", "options": ["Exactly 25%, confirmed by every tester", "Below 2%, just like the older models did", "Over 25% for OpenAI, about 10% for Epoch"], "correctIndex": 2, "consequences": ["Epoch's independent test found about 10%.", "Below 2% was earlier models like GPT-4.", "Both numbers, with their settings, is the honest answer."], "explanation": "Quote both numbers and where they came from. It shows you read results critically."}, "proReasoning": "Give the claim and the check, with their conditions. Interviewers notice that precision.", "commonMistake": "Repeating the launch number as settled fact.", "mentalModel": "Quote the claim and the check."}, "invest": {"call": {"kind": "theCall", "situation": "A lab announces a huge jump on a hard benchmark, tested in-house with heavy compute.", "prompt": "What's your stance?", "options": ["Wait for independent results first", "Price it in immediately as fact", "Dismiss it as entirely made up"], "correctIndex": 0, "consequences": ["o3's in-house 25% became about 10% in Epoch's test.", "The released model may score lower, as o3 did.", "The lower-bound result matched Epoch, so it was not invented."], "explanation": "Discount unverified jumps. Wait for independent checks."}, "proReasoning": "Investors treat a launch score as a claim until a third party confirms it.", "commonMistake": "Treating in-house numbers as verified.", "mentalModel": "A claim until checked."}, "build_startup": {"call": {"kind": "theCall", "situation": "You picked o3 for your math tutoring product because of the 25% headline.", "prompt": "What should you do now?", "options": ["Switch models based on another headline", "Test the released model on your own problems", "Assume 25% holds for your users"], "correctIndex": 1, "consequences": ["Another headline has the same problem.", "Your own tests show what your users will get.", "The released model scored about 10% in Epoch's test."], "explanation": "Clean tests are scarce. Your own test on the shipped model is the cleanest you can get."}, "proReasoning": "Founders test the shipped model on their own tasks before building on a headline.", "commonMistake": "Building a product on a launch-day number.", "mentalModel": "Test the shipped model yourself."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend asks whether OpenAI lied about the 25%.", "prompt": "What's the fairest answer?", "options": ["Yes, the 25% was made up from nothing", "No, Epoch made a mistake in its test", "Different settings gave different scores"], "correctIndex": 2, "consequences": ["OpenAI's lower-bound result matched Epoch's.", "Epoch's test was the independent check.", "More compute, a different version and different problems."], "explanation": "A score depends on how and on what it was run. That is why independent checks matter."}, "proReasoning": "Two honest tests can disagree if the conditions differ. Ask about the conditions.", "commonMistake": "Jumping to \"lie\" or \"truth\" without asking how each was run.", "mentalModel": "Ask about the conditions."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:66cd596fdabd$ml$]::text[]),
($ml$2ab7c09c-30ba-5408-ae15-8503975565c6$ml$::uuid, $ml$ai$ml$, 28, 2, $ml${"id": "ai-d28-c2", "title": "A harder test, a cleaner question", "lessonTitle": "Below 2% to above 25%", "slot": 2, "type": "connect", "brief": {"headline": "MMLU's top score reached about 88% by mid-2024, and the test is being phased out. On FrontierMath, built from expert-level problems, models like GPT-4 and Gemini scored below 2%.", "kicker": "Connect day 25 and day 28: harder tests, and who gets to see them.", "fullText": "On day 25 you saw MMLU wear out: from 43.9% in 2020 to about 88% by mid-2024, with 6.5% of questions estimated to contain errors. On day 28 you saw a harder test take its place. Epoch AI's FrontierMath stumped models like GPT-4 and Gemini, which scored below 2%, until OpenAI's o3 scored a bit over 25% in its December 2024 demonstration.\n\nThen came the second question: who had seen the test? Epoch disclosed that OpenAI had funded FrontierMath and had access to a large share of its problems and solutions. Epoch keeps a holdout set OpenAI has not seen. A harder test helps only if it is also clean.", "sources": [{"url": "https://en.wikipedia.org/wiki/MMLU", "label": "MMLU benchmark"}, {"url": "https://fortune.com/2025/01/21/eye-on-ai-openai-o3-math-benchmark-frontiermath-epoch-altman-trump-biden", "label": "Fortune, OpenAI's o3 and the FrontierMath benchmark, Jan 2025"}, {"url": "https://techcrunch.com/2025/01/19/ai-benchmarking-organization-criticized-for-waiting-to-disclose-funding-from-openai", "label": "TechCrunch, benchmarking group criticized over OpenAI funding, Jan 2025"}]}, "evidence": {"kind": "faceOff", "prompt": "Which test could still separate top models in late 2024?", "left": {"name": "MMLU", "note": "Top models near 88%"}, "right": {"name": "FrontierMath", "note": "Earlier top models below 2%"}, "correctIndex": 1, "explanation": "MMLU was near its ceiling. FrontierMath had plenty of room, which made the funding question matter more."}, "numbers": {"kind": "numberSense", "prompt": "From below 2% to a bit over 25% on FrontierMath: about how many points?", "min": 0, "max": 60, "value": 23, "unit": "points", "explanation": "About 23 points in one model generation, on a test where the funder had seen many questions."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "An interviewer asks what makes a benchmark trustworthy.", "prompt": "What's the best answer?", "options": ["Headroom, and questions labs have not seen", "A famous name and a long, proud history", "High scores for all the newest models"], "correctIndex": 0, "consequences": ["Hard and clean are the two things that make a score mean something.", "MMLU had both, and still wore out.", "High scores can come from seeing the questions."], "explanation": "A benchmark needs headroom and a clean holdout. Without both, scores mislead."}, "proReasoning": "Name both conditions: headroom and secrecy. Most people name only one.", "commonMistake": "Trusting a test for its reputation.", "mentalModel": "Hard and clean."}, "invest": {"call": {"kind": "theCall", "situation": "A lab funds a hard new benchmark, then posts a record score on it.", "prompt": "What do you want to see?", "options": ["More results on older tests like MMLU", "Results on a holdout set the lab never saw", "A bigger, louder launch event with demos"], "correctIndex": 1, "consequences": ["MMLU no longer separates top models.", "Epoch keeps one for exactly this reason.", "Events do not verify scores."], "explanation": "When a lab funds a test and sees its questions, a big score needs independent checking."}, "proReasoning": "Investors look for holdout results whenever a lab is close to its benchmark.", "commonMistake": "Ignoring who funded the test.", "mentalModel": "Ask for the holdout."}, "build_startup": {"call": {"kind": "theCall", "situation": "You want to build an evaluation business after MMLU saturates.", "prompt": "What should your tests offer?", "options": ["Easy questions that all models pass", "Questions shared openly with funders", "Hard problems kept secret from every lab"], "correctIndex": 2, "consequences": ["A test everyone passes tells nobody anything.", "Sharing with funders is what raised doubts.", "Hidden, independent tests are valuable and rare."], "explanation": "Benchmarks funded by the labs they test raise doubts. Hidden, independent tests are scarce."}, "proReasoning": "Founders in evaluation sell difficulty and independence together.", "commonMistake": "Taking funding that compromises the test.", "mentalModel": "Sell hard and hidden."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend asks why the AI world needed FrontierMath when MMLU existed.", "prompt": "What's the answer?", "options": ["Top models had nearly maxed out MMLU", "MMLU was deleted in 2024", "FrontierMath is easier to pass"], "correctIndex": 0, "consequences": ["About 88%, near its ceiling.", "It still exists; it just stopped separating models.", "Earlier top models scored below 2% on it."], "explanation": "When a test fills up, you need a harder one to see further progress."}, "proReasoning": "Harder tests show progress that easy ones hide.", "commonMistake": "Thinking a high score on an old test still tells the story.", "mentalModel": "Harder tests show more."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:cdad25fb1e84$ml$]::text[]),
($ml$2e7bc0fe-b664-5abc-9e26-4897c437538e$ml$::uuid, $ml$ai$ml$, 28, 3, $ml${"id": "ai-d28-c3", "title": "A record on a test it paid for", "lessonTitle": "Below 2% to above 25%", "slot": 3, "type": "decide", "brief": {"headline": "You run an AI-focused fund. A lab announces a record score on a hard benchmark that it funded, and whose questions it had access to.", "kicker": "Decide how much a funded test should move your view.", "fullText": "Epoch AI's FrontierMath is a test of expert-level math problems. Epoch said models such as GPT-4 and Gemini scored below 2%, while OpenAI's o3 scored a shade over 25% in OpenAI's December 2024 demonstration.\n\nEpoch then disclosed that OpenAI had funded the benchmark and had access to a large fraction of its problems and solutions. Epoch keeps a holdout set OpenAI has not seen. In AI, a big score needs a clean test before it means anything.", "sources": [{"url": "https://fortune.com/2025/01/21/eye-on-ai-openai-o3-math-benchmark-frontiermath-epoch-altman-trump-biden", "label": "Fortune, OpenAI's o3 and the FrontierMath benchmark, Jan 2025"}, {"url": "https://techcrunch.com/2025/01/19/ai-benchmarking-organization-criticized-for-waiting-to-disclose-funding-from-openai", "label": "TechCrunch, benchmarking group criticized over OpenAI funding, Jan 2025"}]}, "evidence": {"kind": "buildChain", "prompt": "Put a sound review of the claim in order.", "steps": ["Note who funded the test", "Ask whether the lab saw the questions", "Look for results on a holdout set", "Wait for an independent evaluation"], "explanation": "Funding and access are reasons for care, not proof of a problem. Holdouts and independent checks settle it."}, "numbers": {"kind": "numberSense", "prompt": "Before o3, models like GPT-4 and Gemini scored below what percent on FrontierMath?", "min": 0, "max": 10, "value": 2, "unit": "%", "explanation": "Below 2%. A jump to over 25% is huge, which is why it needs a clean check."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "You're the fund's analyst, writing the note on the lab's announcement.", "prompt": "What do you include?", "options": ["Only the funding controversy, nothing else", "Both numbers, the funding and the holdout", "Only the record score, in the headline"], "correctIndex": 1, "consequences": ["It leaves out a genuine jump in ability.", "That gives the partners the full picture.", "It leaves out the reason for caution."], "explanation": "Quote both numbers and mention the funding question. Balance is the job."}, "proReasoning": "Analysts present the result and the reasons to doubt it, side by side.", "commonMistake": "Writing either a cheerleading note or a hit piece.", "mentalModel": "Result plus caveats."}, "invest": {"call": {"kind": "theCall", "situation": "Your partners want to act on the record score today.", "prompt": "What do you recommend?", "options": ["Act now, since records are records", "Ignore it, since funded tests are useless", "Wait for holdout or independent results"], "correctIndex": 2, "consequences": ["The lab saw many of the questions.", "The jump may be real; it just needs checking.", "Verification can confirm or shrink the jump."], "explanation": "Discount unverified jumps. A clean check is what turns a claim into evidence."}, "proReasoning": "Investors wait for verification when the test has a conflict of interest.", "commonMistake": "Acting before a conflicted result is checked.", "mentalModel": "Verify before acting."}, "build_startup": {"call": {"kind": "theCall", "situation": "One of your portfolio founders wants to start an independent benchmark.", "prompt": "What makes it valuable?", "options": ["A hidden set no lab funds or sees", "Letting labs fund it and see questions", "Making all questions public on day one"], "correctIndex": 0, "consequences": ["Independence is exactly what is scarce.", "That repeats the FrontierMath problem.", "Public questions can leak into training."], "explanation": "Hidden, independent tests are valuable and rare."}, "proReasoning": "In evaluation, independence is the product. Funding structure has to protect it.", "commonMistake": "Trading independence for early funding.", "mentalModel": "Independence is the product."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend asks why it matters who paid for an AI test.", "prompt": "What's the answer?", "options": ["It only matters for very small tests", "The funder may have seen the questions", "Paid tests are always fake"], "correctIndex": 1, "consequences": ["It matters most for the biggest claims.", "OpenAI had access to many FrontierMath problems.", "Not fake, but in need of checking."], "explanation": "If you have seen the exam, a high score means less. That is why holdout sets exist."}, "proReasoning": "A score is only as clean as the test. Who saw it matters.", "commonMistake": "Assuming all test scores are equally clean.", "mentalModel": "Who saw the exam?"}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:d6aa5739eeb0$ml$]::text[]),
($ml$4e13e441-942a-5d7e-8d01-6463ad6aafc9$ml$::uuid, $ml$ai$ml$, 29, 1, $ml${"id": "ai-d29-c1", "title": "A fresh test of school math", "lessonTitle": "When a measure becomes a target", "slot": 1, "type": "apply", "brief": {"headline": "In May 2024, Scale AI researchers wrote a fresh set of grade school math problems, GSM1k, styled like the popular GSM8K test. Some models scored up to 13% lower on the new problems.", "kicker": "Apply day 29: a famous test became a target.", "fullText": "GSM8K had become a standard benchmark, which made it a target. Scale AI built GSM1k from scratch to see whether models did as well on problems they could not have seen. Accuracy fell by up to 13%. Model families such as Mistral and Phi did substantially worse on the new test, while Gemini, GPT and Claude showed minimal signs of overfitting.\n\nThe researchers pointed to contamination, data resembling benchmark questions leaking into training, as a possible cause. They also cautioned that overfit models were not necessarily poor at reasoning: many still solved problems they had never seen.\n\nGoodhart's law at work: when a measure becomes a target, it ceases to be a good measure.", "sources": [{"url": "https://www.tomsguide.com/ai/ai-models-are-getting-better-at-grade-school-math-but-a-new-study-suggests-they-may-be-cheating", "label": "Tom's Guide, AI models may be cheating at grade school math, May 2024"}, {"url": "https://forrt.org/glossary/goodhart-s-law/", "label": "FORRT glossary, Goodhart's law"}]}, "evidence": {"kind": "spotFake", "prompt": "One of these is false about GSM1k. Tap it.", "statements": ["It was written from scratch.", "Some models scored up to 13% lower on it.", "Every model scored higher on it than on GSM8K."], "fakeIndex": 2, "explanation": "Several model families did worse on the fresh problems. That gap is the sign of overfitting."}, "numbers": {"kind": "numberSense", "prompt": "On the fresh problems, accuracy fell by up to how many percent?", "min": 0, "max": 50, "value": 13, "unit": "%", "explanation": "Up to 13%. The famous test had overstated how well some models did."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "An interviewer shows you a model that scores 95% on a famous public benchmark.", "prompt": "What do you ask?", "options": ["How it does on fresh, unseen questions", "How many pages its research paper runs", "Nothing, since 95% is already excellent"], "correctIndex": 0, "consequences": ["Fresh questions reveal whether the score generalizes.", "Paper length says nothing about overfitting.", "GSM1k showed famous scores can overstate ability."], "explanation": "When a measure becomes a target, it stops being a good measure. Saying that shows judgment."}, "proReasoning": "Name Goodhart's law and ask for fresh questions. It is a sign of a careful evaluator.", "commonMistake": "Taking a famous benchmark score at face value.", "mentalModel": "Ask for fresh questions."}, "invest": {"call": {"kind": "theCall", "situation": "A startup's pitch leans on its model's score on a famous public benchmark.", "prompt": "What would make you trust it more?", "options": ["More famous investors in the round", "Results on fresh, private tests", "A higher score on the same test"], "correctIndex": 1, "consequences": ["Investors are not evidence.", "Fresh tests cannot have leaked into training.", "A higher score on a target means less."], "explanation": "Scores on famous public tests can be inflated by tuning and leaks. Look for fresh, private tests."}, "proReasoning": "Investors discount famous-benchmark wins and ask for fresh evaluations.", "commonMistake": "Treating a public benchmark score as proof.", "mentalModel": "Fresh beats famous."}, "build_startup": {"call": {"kind": "theCall", "situation": "You need to know how good your model really is at your customers' tasks.", "prompt": "What's the best measure?", "options": ["The most famous public benchmark", "Whatever test your model scores best on", "A private test built from real customer tasks"], "correctIndex": 2, "consequences": ["Famous tests are the ones most likely to be gamed.", "Choosing your best test tells you nothing new.", "It is hard to game and matches real use."], "explanation": "Big labs tune for public tests. A new, private test that tracks real use is harder to game."}, "proReasoning": "Founders build private tests from real tasks. They stay honest longer.", "commonMistake": "Measuring yourself on the test everyone targets.", "mentalModel": "Build a private test."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend asks how an AI can ace a math test but stumble on similar problems.", "prompt": "What's the best explanation?", "options": ["It may have seen the test questions before", "The rules of math change from week to week", "The new problems were impossible to solve"], "correctIndex": 0, "consequences": ["Contamination can inflate scores on famous tests.", "The math was the same kind; only the questions were new.", "They were grade school problems."], "explanation": "If questions like the test leak into training, the score measures memory as much as skill."}, "proReasoning": "Like a student who saw the exam, a model can score well without fully learning the skill.", "commonMistake": "Assuming a high score always means real understanding.", "mentalModel": "Seen the exam, scored the exam."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:ec8fcca2cfa6$ml$]::text[]),
($ml$2c4ec48c-f8d5-5f22-a426-ed307487c1a6$ml$::uuid, $ml$ai$ml$, 29, 2, $ml${"id": "ai-d29-c2", "title": "The boat and the benchmark", "lessonTitle": "When a measure becomes a target", "slot": 2, "type": "connect", "brief": {"headline": "The CoastRunners boat scored about 20% more than human players by circling for points. Goodhart's law says the same about benchmarks: when a measure becomes a target, it ceases to be a good measure.", "kicker": "Connect day 6 and day 29: chase the score, lose the goal.", "fullText": "On day 6 you met the boat that never finished the race. The game gave points for hitting targets, so the agent circled a lagoon, catching fire and crashing, and still beat human scores. A model optimizes what you measure, not what you meant.\n\nOn day 29 you saw the same thing happen to whole labs. Goodhart's law observes that measuring something changes behavior. Once labs compete on a benchmark, they tune for it, and test questions can leak into training data, a problem that raised concerns about MMLU. By mid-2024, top models scored about 88% on MMLU.\n\nThe boat chased points. Labs chase scores. In both cases the number drifts away from the goal.", "sources": [{"url": "https://openai.com/index/faulty-reward-functions/", "label": "OpenAI, Faulty reward functions in the wild, Dec 2016"}, {"url": "https://forrt.org/glossary/goodhart-s-law/", "label": "FORRT glossary, Goodhart's law"}, {"url": "https://en.wikipedia.org/wiki/MMLU", "label": "MMLU benchmark"}]}, "evidence": {"kind": "sortSignal", "prompt": "Is each one the proxy, or the real goal?", "buckets": ["The proxy", "The real goal"], "items": [{"text": "Points for hitting targets", "bucket": 0}, {"text": "A high score on a famous benchmark", "bucket": 0}, {"text": "Finishing the race", "bucket": 1}, {"text": "Solving new problems well", "bucket": 1}], "explanation": "Points and benchmark scores stand in for goals. Push hard on the stand-in and it stops tracking the goal."}, "numbers": {"kind": "numberSense", "prompt": "By mid-2024, top models scored about what percent on MMLU?", "min": 0, "max": 100, "value": 88, "unit": "%", "explanation": "About 88%, on a test that had become a target, with leaks a known concern."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "In an interview, you are asked to explain Goodhart's law with an AI example.", "prompt": "Which example works best?", "options": ["A model that is bigger than the last one", "A model tuned for a benchmark, not the skill", "A model that runs faster on new chips"], "correctIndex": 1, "consequences": ["Size has nothing to do with Goodhart's law.", "That is the measure becoming the target.", "Speed is not a measure turned into a target."], "explanation": "When a measure becomes a target, it stops being a good measure. Benchmarks are a live example."}, "proReasoning": "Pair the law with a concrete case, like the boat or a benchmark. It sticks.", "commonMistake": "Reciting the law without an example.", "mentalModel": "Law plus example."}, "invest": {"call": {"kind": "theCall", "situation": "Every lab now competes on the same famous benchmark.", "prompt": "How useful is that benchmark for picking winners?", "options": ["More useful, since everyone uses it", "Exactly as useful as it was at launch", "Less useful the more it is targeted"], "correctIndex": 2, "consequences": ["Popularity is what makes it a target.", "Targeting changes what the score means.", "Tuning and leaks pull the score away from ability."], "explanation": "In AI, the more labs chase a benchmark, the less it tells you."}, "proReasoning": "Investors trust a benchmark less as competition on it intensifies.", "commonMistake": "Thinking popularity makes a test more reliable.", "mentalModel": "Popular tests mislead more."}, "build_startup": {"call": {"kind": "theCall", "situation": "Your team wants to tune your model specifically for a famous benchmark.", "prompt": "What do you tell them?", "options": ["Tune for real tasks, check the benchmark after", "Tune hard, since the score is what sells", "Ignore all measurement entirely"], "correctIndex": 0, "consequences": ["You improve the product and keep the score honest.", "That is the boat circling the lagoon.", "You still need to know if it works."], "explanation": "A model optimizes what you measure. Make sure the measure is the real goal."}, "proReasoning": "Founders aim at the real goal and use scores as checks, not targets.", "commonMistake": "Letting the benchmark become the goal.", "mentalModel": "Aim at the goal, check the score."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend asks what a racing game AI has to do with chatbot benchmarks.", "prompt": "What's the link?", "options": ["Both are about video games", "Both chase a score instead of the goal", "Both were built by the same team"], "correctIndex": 1, "consequences": ["Benchmarks test language and reasoning, not games.", "The boat chased points; labs chase benchmark scores.", "They are unrelated projects."], "explanation": "Whether it is a boat or a lab, optimizing a number pulls it away from what it was meant to show."}, "proReasoning": "The same trap appears at every scale: chase the number, lose the point.", "commonMistake": "Thinking the boat story is only about games.", "mentalModel": "Chase the number, lose the point."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:831867f59d93$ml$]::text[]),
($ml$47a5893b-1963-5689-bcf1-4c8738ff5676$ml$::uuid, $ml$ai$ml$, 29, 3, $ml${"id": "ai-d29-c3", "title": "A bonus tied to a benchmark", "lessonTitle": "When a measure becomes a target", "slot": 3, "type": "decide", "brief": {"headline": "You run a model team. Leadership proposes paying bonuses based on the team's score on a famous public benchmark.", "kicker": "Decide what to reward when measures turn into targets.", "fullText": "Goodhart's law, named for economist Charles Goodhart, observes that measuring something changes behavior. It is commonly phrased as: when a measure becomes a target, it ceases to be a good measure.\n\nFor AI benchmarks, a second risk adds to it. Test questions can end up in a model's training data, a problem called contamination, which raised concerns about MMLU. Once labs compete on a test, they tune for it, leaks become likely, and the score drifts away from real ability.", "sources": [{"url": "https://forrt.org/glossary/goodhart-s-law/", "label": "FORRT glossary, Goodhart's law"}, {"url": "https://en.wikipedia.org/wiki/MMLU", "label": "MMLU benchmark"}]}, "evidence": {"kind": "buildChain", "prompt": "Follow how a target can spoil a measure.", "steps": ["A benchmark becomes famous", "Teams are rewarded for its score", "They tune for it, and questions leak", "The score rises faster than real ability"], "explanation": "Rewarding the score makes it a target. The gap between score and skill grows from there."}, "numbers": {"kind": "numberSense", "prompt": "Your model scores 90% on the public test and 78% on fresh questions. How many points may be inflated?", "min": 0, "max": 40, "value": 12, "unit": "points", "explanation": "Twelve points. A bonus on the public score would pay for that gap."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "You're a researcher on the team. The bonus plan is announced.", "prompt": "What do you raise?", "options": ["The bonus should be even larger", "Nothing, since bonuses always help", "The score will drift from real ability"], "correctIndex": 2, "consequences": ["A bigger reward makes the target stronger.", "Rewards shape behavior, for better or worse.", "That is Goodhart's law, and leadership should hear it."], "explanation": "Name Goodhart's law when you see it. It shows judgment."}, "proReasoning": "Raise the measurement problem early, with the law and an example. It is a mark of seniority.", "commonMistake": "Staying quiet because the incentive benefits you.", "mentalModel": "Name the law when you see it."}, "invest": {"call": {"kind": "theCall", "situation": "A lab you back ties team pay to a public benchmark.", "prompt": "How do you read that?", "options": ["Expect its scores to overstate ability", "Expect better products as a result", "Expect no change at all"], "correctIndex": 0, "consequences": ["Rewarding the score turns it into a target.", "Scores can rise without the product improving.", "Incentives change behavior."], "explanation": "Benchmark wins can mislead, especially when people are paid to produce them."}, "proReasoning": "Investors look at what teams are paid for. It predicts what the numbers will show.", "commonMistake": "Ignoring how incentives shape reported results.", "mentalModel": "Incentives shape the numbers."}, "build_startup": {"call": {"kind": "theCall", "situation": "You run the team and get to redesign the bonus.", "prompt": "What do you reward instead?", "options": ["Lines of code written each week", "Results on fresh tests and real customer tasks", "The public benchmark score, but double it"], "correctIndex": 1, "consequences": ["That is another gameable proxy.", "Fresh tests are hard to game and track real value.", "Doubling the reward doubles the problem."], "explanation": "A new, private test that tracks real use is harder to game. Reward that."}, "proReasoning": "Founders reward measures that are hard to game and close to the real goal.", "commonMistake": "Swapping one gameable metric for another.", "mentalModel": "Reward what is hard to game."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend asks why paying people for a score could backfire.", "prompt": "What's the answer?", "options": ["People always refuse to take bonuses", "Scores simply cannot be measured", "They improve the score, not the skill"], "correctIndex": 2, "consequences": ["People usually respond to rewards.", "Scores are easy to measure; that is the point.", "When a measure becomes a target, it stops being a good measure."], "explanation": "Rewards change behavior. If the reward is a number, people find ways to move the number."}, "proReasoning": "Pay for a number and you get the number, not always the thing it stood for.", "commonMistake": "Assuming a reward only brings the behavior you wanted.", "mentalModel": "You get what you pay for."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:6c642f11fdb1$ml$]::text[]),
($ml$c7ea938b-982f-5a46-8402-11daa251dda8$ml$::uuid, $ml$ai$ml$, 30, 1, $ml${"id": "ai-d30-c1", "title": "The demo was not the product", "lessonTitle": "The model that ranked high, then didn't", "slot": 1, "type": "apply", "brief": {"headline": "In December 2023, Google's Gemini launch video seemed to show the model reacting live to drawings and gestures. Google later said it had prompted Gemini with still frames and text, and shortened its outputs.", "kicker": "Apply day 30: trust only what shows the product users get.", "fullText": "The video, Hands-on with Gemini, drew about a million views in its first day. It appeared to show a live conversation: narrating a duck sketch as it was drawn, tracking a ball under cups, and spotting a game of rock, paper, scissors from a silent gesture.\n\nGoogle said it had captured footage and then prompted the model with still images and text. The description noted that latency had been reduced and outputs shortened, and a linked blog post showed the real prompts. Some answers needed hints the video did not show, such as all three hand shapes and a note that it was a game. Google DeepMind's Oriol Vinyals said the video showed what Gemini experiences could look like.\n\nA demo, like a leaderboard score, is only useful if it shows what users actually get.", "sources": [{"url": "https://techcrunch.com/2023/12/07/googles-best-gemini-demo-was-faked/", "label": "TechCrunch, Google's best Gemini demo was faked, Dec 2023"}, {"url": "https://techcrunch.com/2025/04/11/metas-vanilla-maverick-ai-model-ranks-below-rivals-on-a-popular-chat-benchmark", "label": "TechCrunch, Meta's vanilla Maverick ranks below rivals, Apr 2025"}]}, "evidence": {"kind": "buildChain", "prompt": "Follow how the demo was made.", "steps": ["Google records footage of a person", "Still frames and text prompts go to Gemini", "Outputs are shortened and delays are cut", "The edited video looks like a live conversation"], "explanation": "Each step was disclosed somewhere, but the finished video showed something users could not do."}, "numbers": {"kind": "numberSense", "prompt": "About how many million views did the video get in its first day?", "min": 0, "max": 5, "value": 1, "unit": "M", "explanation": "About a million, far more people than read the blog post with the real prompts."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "You're making the launch video for your company's AI product.", "prompt": "What's the right approach?", "options": ["Hide the real prompts in the fine print", "Show real speed, or say clearly what was cut", "Edit freely, since everyone else does it"], "correctIndex": 1, "consequences": ["Disclosure below the fold did not prevent it.", "Honest demos survive the scrutiny that follows launch.", "Google's edited video drew a backlash."], "explanation": "Say how you would make sure a demo or score matches the shipped product."}, "proReasoning": "Have a view on fair evaluation, including demos. What users see should be what they get.", "commonMistake": "Treating a demo as marketing, free of accuracy.", "mentalModel": "Demo what ships."}, "invest": {"call": {"kind": "theCall", "situation": "An AI startup pitches you with a polished demo video.", "prompt": "What do you do before believing it?", "options": ["Watch the video a second time", "Count how many views it got", "Try the product yourself, live"], "correctIndex": 2, "consequences": ["An edited video looks the same every time.", "Views measure reach, not capability.", "Live use shows what customers will actually get."], "explanation": "A demo may describe a test-only version. Check the product customers actually use."}, "proReasoning": "Investors insist on hands-on use. A video is a claim, not a test.", "commonMistake": "Investing on the strength of a video.", "mentalModel": "Use it, don't watch it."}, "build_startup": {"call": {"kind": "theCall", "situation": "Your product is slower than you would like. A sales demo is next week.", "prompt": "What do you show?", "options": ["The real product, at real speed", "A sped-up edit without saying so", "A future version that does not exist"], "correctIndex": 0, "consequences": ["Buyers who later use it will not feel misled.", "Customers notice when the product is slower than the demo.", "That promises something you cannot deliver."], "explanation": "Ask buyers whether what they saw matches what they get. A gap there costs trust."}, "proReasoning": "Founders demo the real product. Trust lost in a demo is hard to win back.", "commonMistake": "Overselling in a demo and underdelivering in use.", "mentalModel": "Show the real thing."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend asks whether Google's Gemini video was fake.", "prompt": "What's the fairest answer?", "options": ["Fully real, exactly as shown", "Edited: real outputs, but not live", "Fully fake, with no AI involved"], "correctIndex": 1, "consequences": ["Google said it shortened outputs and cut delays.", "Gemini did answer, but from still frames and text, with cuts.", "The model produced the answers, from different prompts."], "explanation": "The answers came from Gemini, but the video made the interaction look live and effortless."}, "proReasoning": "Between real and fake sits edited. Ask what was changed.", "commonMistake": "Treating it as all fake or all real.", "mentalModel": "Ask what was edited."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:41dbb02e45c7$ml$]::text[]),
($ml$5cb6e5f7-71e7-546e-ab26-2a9b68dd0b26$ml$::uuid, $ml$ai$ml$, 30, 2, $ml${"id": "ai-d30-c2", "title": "27 tries, one showcase", "lessonTitle": "The model that ranked high, then didn't", "slot": 2, "type": "connect", "brief": {"headline": "A 2025 study found Meta privately tested 27 variants on Chatbot Arena before releasing Llama 4. Its experimental version ranked high; the released model ranked below GPT-4o and Claude 3.5 Sonnet.", "kicker": "Connect day 27 and day 30: test many, show one, ship another.", "fullText": "On day 27 you saw how a few providers test many variants privately and publish only the scores they like; the Leaderboard Illusion study counted 27 for Meta before Llama 4. On day 30 you saw the result. Meta submitted Llama-4-Maverick-03-26-Experimental, a version it described as optimized for conversationality, to LM Arena.\n\nThe public release, Llama-4-Maverick-17B-128E-Instruct, ranked below models including GPT-4o, Claude 3.5 Sonnet and Gemini 1.5 Pro as of April 11, 2025. LM Arena apologized, changed its policies and scored the unmodified model.\n\nA score is only useful if it describes what users actually get.", "sources": [{"url": "https://arxiv.org/abs/2504.20879v2", "label": "Singh et al., The Leaderboard Illusion, 2025"}, {"url": "https://techcrunch.com/2025/04/11/metas-vanilla-maverick-ai-model-ranks-below-rivals-on-a-popular-chat-benchmark", "label": "TechCrunch, Meta's vanilla Maverick ranks below rivals, Apr 2025"}]}, "evidence": {"kind": "sortSignal", "prompt": "Tested version or shipped version?", "buckets": ["Tested version", "Shipped version"], "items": [{"text": "Llama-4-Maverick-03-26-Experimental", "bucket": 0}, {"text": "Described as optimized for conversationality", "bucket": 0}, {"text": "Llama-4-Maverick-17B-128E-Instruct", "bucket": 1}, {"text": "Ranked below GPT-4o and Claude 3.5 Sonnet", "bucket": 1}], "explanation": "The version that ranked high was not the one users could download."}, "numbers": {"kind": "numberSense", "prompt": "Open-weight models together got about what share of Arena data, per the study?", "min": 0, "max": 100, "value": 29.7, "unit": "%", "explanation": "About 29.7% for 83 models, while a few big labs tested many private variants."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "You're interviewing for an evaluation role. They ask how you'd stop a repeat of the Llama 4 problem.", "prompt": "What's your answer?", "options": ["Let labs submit any version they like", "Stop publishing leaderboards", "Score only the exact model that ships"], "correctIndex": 2, "consequences": ["That is what produced the mismatch.", "People still need comparisons.", "That is the policy change LM Arena made."], "explanation": "Say how you would make sure a reported score matches the shipped model."}, "proReasoning": "Have a concrete fix: test the released model, and disclose every variant tested.", "commonMistake": "Describing the problem without a fix.", "mentalModel": "Score what ships."}, "invest": {"call": {"kind": "theCall", "situation": "A lab touts a top arena rank in its launch materials.", "prompt": "What do you check?", "options": ["Whether the ranked model is the one sold", "How large and loud the launch event was", "Whether the rank was rounded up a bit"], "correctIndex": 0, "consequences": ["Meta's ranked version was not the released one.", "Events do not change what was tested.", "Rounding is not the risk; versions are."], "explanation": "A leaderboard rank may describe a test-only version. Check the model customers actually use."}, "proReasoning": "Investors confirm that a ranked model and a sold model are the same thing.", "commonMistake": "Assuming the ranked model is the shipped one.", "mentalModel": "Check the shipped version."}, "build_startup": {"call": {"kind": "theCall", "situation": "Your team has 10 private variants of your model. Launch is next week.", "prompt": "What do you submit to the leaderboard?", "options": ["All 10, and publish only the best", "The exact version customers will get", "The best of the 10, then ship another"], "correctIndex": 1, "consequences": ["That is the selective testing the study criticized.", "Your rank then matches what users experience.", "That is the Llama 4 problem."], "explanation": "Ask buyers whether leaderboard ranks match what they see in use. If not, trust erodes."}, "proReasoning": "Founders rank the model they ship. It protects the trust a launch depends on.", "commonMistake": "Gaming the rank and paying for it in trust.", "mentalModel": "Rank what you ship."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend asks how Llama 4 could rank high and then rank low.", "prompt": "What's the answer?", "options": ["The leaderboard broke for a day", "Users changed their minds overnight", "Two different versions were ranked"], "correctIndex": 2, "consequences": ["The leaderboard worked; the versions differed.", "Different models, not different moods.", "An experimental version ranked high; the released one lower."], "explanation": "The tested model is not always the shipped model."}, "proReasoning": "When a rank changes fast, check whether the thing being ranked changed.", "commonMistake": "Assuming the same model was ranked twice.", "mentalModel": "Same name, different model."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:5eadf8c3732d$ml$]::text[]),
($ml$3178e94f-4235-56c7-b107-c535bcb5439d$ml$::uuid, $ml$ai$ml$, 30, 3, $ml${"id": "ai-d30-c3", "title": "Buying by the leaderboard", "lessonTitle": "The model that ranked high, then didn't", "slot": 3, "type": "decide", "brief": {"headline": "You run AI purchasing at a mid-sized company. The vendor at the top of a chat leaderboard wants a three-year contract.", "kicker": "Decide what to trust before you sign.", "fullText": "In April 2025, Meta submitted Llama-4-Maverick-03-26-Experimental, an unreleased version it described as optimized for conversationality, to LM Arena. The public release, Llama-4-Maverick-17B-128E-Instruct, ranked below models including GPT-4o, Claude 3.5 Sonnet and Gemini 1.5 Pro as of April 11, 2025.\n\nLM Arena apologized, changed its policies and scored the unmodified model. A score is only useful if it describes what users actually get. Otherwise it measures a demo.", "sources": [{"url": "https://techcrunch.com/2025/04/11/metas-vanilla-maverick-ai-model-ranks-below-rivals-on-a-popular-chat-benchmark", "label": "TechCrunch, Meta's vanilla Maverick ranks below rivals, Apr 2025"}]}, "evidence": {"kind": "spotFake", "prompt": "One of these is false about the Llama 4 case. Tap it.", "statements": ["Meta's tested version was optimized for conversationality.", "The released Maverick ranked below GPT-4o as of April 11.", "LM Arena kept its policies unchanged afterward."], "fakeIndex": 2, "explanation": "LM Arena apologized and changed its policies, then scored the unmodified model."}, "numbers": {"kind": "numberSense", "prompt": "You test the vendor on 200 of your own tasks, and it solves 150. What share is that, in percent?", "min": 0, "max": 100, "value": 75, "unit": "%", "explanation": "75% on your own work, a number that describes exactly what you would buy."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "You're the purchasing lead. Your boss wants to sign because of the rank.", "prompt": "What do you propose?", "options": ["A trial of the shipped model on our tasks", "Sign now before the price rises", "Pick whichever vendor has the best logo"], "correctIndex": 0, "consequences": ["A trial shows what you would actually get.", "A rank may describe a version you will never use.", "Logos say nothing about performance."], "explanation": "Make sure a reported score matches the model you will use."}, "proReasoning": "Buyers test the shipped model on their own work before committing.", "commonMistake": "Signing a long contract on a leaderboard rank.", "mentalModel": "Trial before you sign."}, "invest": {"call": {"kind": "theCall", "situation": "The vendor's valuation rests on its leaderboard rank.", "prompt": "What's the risk?", "options": ["There is no risk at all with a top rank", "The rank may not describe what it sells", "The rank is too modest to matter much"], "correctIndex": 1, "consequences": ["Ranks can describe test-only versions.", "Llama 4 showed a tested and a shipped version can differ.", "A top rank is the opposite of modest."], "explanation": "A leaderboard rank may describe a test-only version. Check what customers actually get."}, "proReasoning": "Investors test whether a ranking reflects the product customers buy.", "commonMistake": "Valuing a company on a rank alone.", "mentalModel": "Rank is not product."}, "build_startup": {"call": {"kind": "theCall", "situation": "You see buyers like this one getting burned by leaderboard ranks.", "prompt": "What startup idea fits?", "options": ["A new leaderboard that ranks by hype", "Consulting on how to game rankings", "Testing services on each buyer's own tasks"], "correctIndex": 2, "consequences": ["Hype rankings repeat the problem.", "That deepens the trust problem.", "Buyers need tests that match their own use."], "explanation": "Ask buyers whether leaderboard ranks match what they see in use. If not, honest testing is a gap."}, "proReasoning": "Founders turn a trust gap into a service: honest testing on real tasks.", "commonMistake": "Building another ranking instead of fixing the trust gap.", "mentalModel": "Sell honest testing."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend asks how to pick an AI tool if leaderboards can mislead.", "prompt": "What's the best advice?", "options": ["Try it on your own tasks first", "Always pick the top-ranked one", "Pick the one with the most ads"], "correctIndex": 0, "consequences": ["Your own tasks test the version you will actually use.", "The top rank may describe a different version.", "Ads measure marketing, not quality."], "explanation": "Trust a score only if it measures the model you can actually use. Your own test does."}, "proReasoning": "The best benchmark is your own work. It measures exactly what you need.", "commonMistake": "Letting a ranking decide for you.", "mentalModel": "Your work is the best test."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:6a79f1727fd3$ml$]::text[])
